        {id:'bw_yardsale',title:'Town-wide yard-sale weekend',description:'Garages open, old possessions circulate and neighbors learn what others are getting rid of.',dueTurn:520,repeatEveryTurns:2688,locationId:'bw_crossroads',conditionOnTrigger:'yard-sale weekend',conditionDurationTurns:40}
