// --- Horde Labs: optional local cognition fabric --------------------------

function recordLabsDiagnostic(record) {
    if (!record || typeof record !== 'object') return;
    state.labsDiagnostics = [...(state.labsDiagnostics || []), record].slice(-100);
    // The ledger deliberately lives outside story state and shared exports.
    HordeDB.set('labsDiagnostics', state.labsDiagnostics).catch(() => {});
    window.HordeLabsUI?.renderDiagnostics?.();
}

function setupHordeLabs() {
    if (!window.HordeLabs || !window.HordeLabsUI) return;
    state.globalSettings.labs = window.HordeLabs.normalizeConfig(state.globalSettings.labs);
    window.HordeLabs.configure(state.globalSettings.labs, { onDiagnostic: recordLabsDiagnostic });
    window.HordeLabsUI.mount({
        getConfig: () => state.globalSettings.labs,
        getDiagnostics: () => state.labsDiagnostics || [],
        clearDiagnostics: async () => {
            state.labsDiagnostics = [];
            await HordeDB.set('labsDiagnostics', []);
        },
        setConfig: async next => {
            state.globalSettings.labs = window.HordeLabs.normalizeConfig(next);
            window.HordeLabs.configure(state.globalSettings.labs, { onDiagnostic: recordLabsDiagnostic });
            await saveState();
            showToast(state.globalSettings.labs.enabled
                ? 'Horde Labs saved. Start in Shadow to calibrate your local model.'
                : 'Horde Labs is off. Normal engine behavior is unchanged.', 'success');
        },
        toast: showToast,
        navigate: destination => {
            if (destination === 'labs') return window.HordeLabsUI?.open?.();
            const modalButtons = {
                personas: 'personas-modal-btn',
                customize: 'customize-modal-btn',
                settings: 'global-settings-btn'
            };
            if (modalButtons[destination]) {
                document.getElementById(modalButtons[destination])?.click();
                return;
            }
            const view = { chat: 'library', humans: 'companions', worlds: 'stockWorlds', pip: 'pip' }[destination];
            if (view) switchView(view);
        }
    });
    document.getElementById('labs-modal-btn').onclick = () => window.HordeLabsUI.open();
    document.getElementById('pip-configure-btn').onclick = () => window.HordeLabsUI.open();
}

async function labsProposal(task, envelope, mode, options = {}) {
    if (!window.HordeLabs) return null;
    const policy = window.HordeLabs.policyFor(mode);
    if (policy === 'off') return null;
    if (policy === 'shadow') {
        void window.HordeLabs.propose(task, envelope, { mode, ...options }).catch(() => {});
        return null;
    }
    try {
        const result = await window.HordeLabs.propose(task, envelope, { mode, ...options });
        return result?.accepted ? result : null;
    } catch (error) {
        return null;
    }
}

function labsSocialContext(result) {
    const candidate = result?.candidate;
    if (!candidate || Number(candidate.confidence) < 0.55) return '';
    const signals = candidate.signals || {};
    const notable = Object.entries(signals).filter(([, value]) => Math.abs(Number(value)) >= 2)
        .map(([key, value]) => `${key} ${Number(value) > 0 ? '+' : ''}${value}`).slice(0, 3);
    return `[PRIVATE LOCAL COGNITION — validated message classification, not canon]\nMessage kind: ${candidate.messageKind || 'other'}${notable.length ? `; notable signals: ${notable.join(', ')}` : ''}${candidate.evidence ? `; exact evidence: “${candidate.evidence}”` : ''}. Use this only as a subtle reading aid. Do not mention scores, classification, Labs, or infer facts beyond the actual message.`;
}

// --- Initialization ---
function applyPersistedSidebarState() {
    try {
        document.getElementById('app')?.classList.toggle('sidebar-collapsed', localStorage.getItem('hordeSidebarCollapsed') === 'true');
    } catch (_) { /* localStorage may be unavailable */ }
}

function initGlobalSidebarToggle() {
    const button = document.getElementById('global-sidebar-toggle');
    if (!button) return;
    button.onclick = () => {
        const collapsed = document.getElementById('app')?.classList.toggle('sidebar-collapsed');
        try { localStorage.setItem('hordeSidebarCollapsed', String(Boolean(collapsed))); } catch (_) { /* localStorage may be unavailable */ }
    };
}

async function init() {
    applyPersistedSidebarState();
    initGlobalSidebarToggle();
    if (window.StockWorlds17Pass0) {
        window.StockWorlds17Pass0.configure({
            getHostState: () => state,
            navigateHost: viewName => switchView(viewName),
            getBootstrapGeneration: () => HORDE_BOOTSTRAP_GENERATION,
            getIncludedWorlds: () => window.HORDE_INCLUDED_WORLDS || [],
            getBuiltinPresets: () => (typeof DEFAULT_SYSTEM_PRESETS !== 'undefined'
                ? DEFAULT_SYSTEM_PRESETS.filter(preset => preset?.id !== 'freaky_frankenstein_54_horde_authority')
                : []),
            peekCurrentChatSession: () => {
                const ownerId = state.activeRoomId || state.activeCharId;
                if (!ownerId || !Array.isArray(state.chats?.[ownerId])) return null;
                const sessions = state.chats[ownerId];
                const activeId = state.activeSessionId?.[ownerId];
                return sessions.find(session => session?.id === activeId) || sessions[0] || null;
            },
            getModelCatalog: async ({ force = false } = {}) => {
                if (force) {
                    openRouterModels = [];
                    modelCatalogSource = null;
                }
                return getOpenRouterModels();
            },
            getModelCatalogSource: () => modelCatalogSource,
            persistHostState: () => saveState(),
            setCompanionImageModelCatalog: models => {
                companionImageModelCatalog = Array.isArray(models) ? models : [];
            },
            labs: window.HordeLabs || null,
            rpgMechanics: globalThis.HordeRpgMechanics || null,
            services: {
                apiBase,
                attributionHeaders,
                authHeaders,
                cloudProviderName,
                getEmbedding,
                hasApiCredentials,
                humanizeApiError,
                isLocalProvider,
                localGenerationIdleTimeoutMs,
                normalizedProviderId,
                providerDisplayName,
                providerHasCredentials,
                sanitizeMessagesForProvider,
                applyRegexScripts,
                labsProposal,
                showConfirmModal,
                showToast,
                confirm: (...args) => window.confirm(...args),
                prompt: (...args) => window.prompt(...args),
                applyCompanionImageParameters,
                chooseCompanionImageEndpoint,
                companionImageCapabilities,
                companionImageModelFallback,
                companionImageModelInfo,
                getCompanionImageEndpoints,
                getCompanionOutputModels,
                normalizeGeneratedImageSource,
                rankCompanionTextModels,
                rankCompanionImageModels,
                renderCompanionSearchResults,
                requestCompanionPhoto,
                setCompanionSearchOpen,
                stabilizeGeneratedImageSource
            }
        });
    } else {
        const error = new Error('The pristine stock Worlds 17.0 Pass-0 runtime did not load.');
        console.error(error);
        window.__hordeRuntimeErrors.push({ message: error.message, stack: error.stack || '' });
        const stockNav = document.getElementById('nav-stock-worlds-btn');
        if (stockNav) {
            stockNav.disabled = true;
            stockNav.title = error.message;
        }
    }
    // Ask the browser to protect our IndexedDB from storage-pressure eviction
    if (navigator.storage && navigator.storage.persist) {
        navigator.storage.persist().catch(() => {});
    }

    await loadState();
    // Apply a newer shared snapshot before UI setup so this browser never
    // starts an engine against stale local IndexedDB state.
    await initializeSharedLibrarySync();
    setupNavigation();
    setupStudioTabs();
    setupStudioLogic();
    setupChatLogic();
    setupGlobalSettings();
    setupSharedLibrarySyncControls();
    setupOpenRouterRouting();
    setupHordeLabs();
    setupPersonasLogic();
    setupRoomsLogic();
    setupWorldsLogic();
    setupWorldStudioTabs();
    setupWorldStudioLogic();
    setupAIBuilderLogic(); // ✨ AI Builder & Verification Layer setup
    setupWorldPlayLogic();
    window.HordeVideoWorlds?.setup?.();
    setupMultiplayerHub();
    window.HordeMultiplayer?.setup?.({
        bridgeRequest: mcpBridgeRequest,
        currentContext: currentMultiplayerContext,
        currentSession: multiplayerCurrentSession,
        snapshot: buildMultiplayerSnapshot,
        campaignTemplate: buildMultiplayerCampaignTemplate,
        currentPersona: currentMultiplayerPersona,
        executeTurn: executeIsolatedMultiplayerTurn,
        enterSession: () => switchView('multiplayerSession'),
        leaveSession: () => switchView('multiplayer')
    });
    setupLibraryFilters();
    setupPresetImport();
    setupPresetEditor();
    setupWorldImport();
    setupCompanionsLogic();
    setupCatalogModelSearchFields();
    startCompanionAgencyEngine();
    setupCompanionAlwaysOnRuntime();

    // Reasoning Toggle Event Delegation
    document.getElementById('messages-container').addEventListener('click', (e) => {
        if (e.target.classList.contains('thinking-block-toggle')) {
            const block = e.target.closest('.thinking-block');
            if (block) {
                const isCollapsed = block.classList.toggle('collapsed');
                e.target.textContent = isCollapsed ? 'Show full reasoning' : 'Hide reasoning';
            }
        }
    });
    
    renderLibrary();

    // Resume wherever the user last actually was, rather than always
    // dropping back to the library on every refresh. worldPlay is a special
    // case: its real setup (session, history, DM intro) lives in enterWorld,
    // not in switchView itself, so it needs the dedicated entry point.
    restoreLastWorkspace();
    // Settings is a workspace pane. Do not cover the restored screen merely
    // because a provider key is absent, users can open it when they are ready.
    if (state.settingsOpen) showGlobalSettings();
    applyGlobalStyles();
    applyTheme();
    setupCustomizeModal();
    setupAccessibility();
    // Update discovery must never delay startup or make offline use noisy.
    void checkForAppUpdate();

    // Hook up real-time slider UI updates
    const sliders = [
        { id: 'studio-context-size', val: 'studio-context-size-val', badge: 'studio-context-size-badge' },
        { id: 'room-context-size', val: 'room-context-size-val', badge: 'room-context-size-badge' },
        { id: 'w-studio-context-size', val: 'w-studio-context-size-val', badge: 'w-studio-context-size-badge' }
    ];

    sliders.forEach(s => {
        const el = document.getElementById(s.id);
        if (el) {
            el.addEventListener('input', () => {
                updateContextSliderUI(s.id, s.val, s.badge);
            });
        }
    });
}

// --- Context Size Slider Helper ---
function updateContextSliderUI(sliderId, valId, badgeId) {
    const slider = document.getElementById(sliderId);
    const valSpan = document.getElementById(valId);
    const badgeSpan = document.getElementById(badgeId);
    if (!slider || !valSpan || !badgeSpan) return;

    const val = parseInt(slider.value);
    valSpan.textContent = val.toLocaleString();

    const maxVal = parseInt(slider.max) || 102400;

    let badgeText = '';
    let badgeColor = '';
    if (val <= 8192) {
        badgeText = '♻️ Eco / Cost Saver';
        badgeColor = 'var(--success)';
    } else if (val <= Math.max(16384, Math.round(maxVal * 0.15))) {
        badgeText = '⚖️ Balanced (Recommended)';
        badgeColor = 'var(--chat-italic-color, #FF8C42)';
    } else if (val <= Math.max(32768, Math.round(maxVal * 0.5))) {
        badgeText = '📖 Deep Narrative';
        badgeColor = '#60A5FA';
    } else {
        badgeText = '🧠 Maximum Context (Expensive)';
        badgeColor = 'var(--red)';
    }
    badgeSpan.textContent = badgeText;
    badgeSpan.style.color = badgeColor;
}

// --- Configure Context Slider dynamically for a specific Model ID ---
function configureContextSliderForModel(sliderId, modelId) {
    const slider = document.getElementById(sliderId);
    if (!slider) return;

    let physicalLimit = 102400; // Default fallback context limit if model is unknown
    if (openRouterModels && openRouterModels.length > 0 && modelId) {
        const matched = openRouterModels.find(m => m.id === modelId);
        if (matched && matched.context_length) {
            physicalLimit = matched.context_length;
        }
    }

    slider.max = physicalLimit;
    
    // Adjust slider stepping so it's smooth and highly responsive
    if (physicalLimit <= 32768) {
        slider.step = 1024;
    } else if (physicalLimit <= 131072) {
        slider.step = 2048;
    } else if (physicalLimit <= 524288) {
        slider.step = 8192;
    } else {
        slider.step = 16384;
    }
}

function applyGlobalStyles() {
    const root = document.documentElement;
    root.style.setProperty('--edit-font-size', (state.globalSettings.editFontSize || 15) + 'px');
    root.style.setProperty('--edit-color', state.globalSettings.editFontColor || '#ffffff');
    root.style.setProperty('--edit-bg', state.globalSettings.editBgColor || '#2b2b36');
}

const THEME_DEFAULTS = {
    chatUserBg: '#000000', chatUserText: '#ffffff', chatUserBorder: '#111111',
    chatAiBg: '#000000', chatAiText: '#ffffff', chatAiBorder: '#111111',
    chatItalic: '#ffffff', chatBold: '#ffffff', chatDialogue: '#E63946',
    chatNarration: '#ffffff', chatAccent: '#E63946', appBg: '#080810', appSurface: '#10101A',
    appRed: '#E63946', appText: '#F0F0F8',
    chatFontSize: 15
};

function applyTheme() {
    const t = { ...THEME_DEFAULTS, ...(state.theme || {}) };
    const root = document.documentElement;
    root.style.setProperty('--chat-user-bg',       t.chatUserBg);
    root.style.setProperty('--chat-user-text',     t.chatUserText);
    root.style.setProperty('--chat-user-border',   t.chatUserBorder);
    root.style.setProperty('--chat-ai-bg',         t.chatAiBg);
    root.style.setProperty('--chat-ai-text',       t.chatAiText);
    root.style.setProperty('--chat-ai-border',     t.chatAiBorder);
    root.style.setProperty('--chat-italic-color',  t.chatItalic);
    root.style.setProperty('--chat-bold-color',    t.chatBold);
    root.style.setProperty('--chat-dialogue-color',t.chatDialogue);
    root.style.setProperty('--chat-narration-color',t.chatNarration);
    root.style.setProperty('--chat-accent',        t.chatAccent);
    root.style.setProperty('--bg',                 t.appBg);
    root.style.setProperty('--surface',            t.appSurface);
    root.style.setProperty('--surface2',           t.appSurface + 'CC'); // slight variation
    root.style.setProperty('--red',                t.appRed);
    root.style.setProperty('--red-dim',            t.appRed + '1F');
    root.style.setProperty('--red-glow',           t.appRed + '59');
    root.style.setProperty('--text',               t.appText);
    root.style.setProperty('--chat-font-size',     t.chatFontSize + 'px');
}

function setupCustomizeModal() {
    const btn     = document.getElementById('customize-modal-btn');
    const overlay = document.getElementById('customize-modal-overlay');
    const closeBtn= document.getElementById('close-customize-btn');
    const saveBtn = document.getElementById('save-customize-btn');
    const resetBtn= document.getElementById('reset-customize-btn');

    // Map: [pickerId, textId, themeKey]
    const FIELDS = [
        ['c-user-bg',     'c-user-bg-text',     'chatUserBg'],
        ['c-user-text',   'c-user-text-text',   'chatUserText'],
        ['c-user-border', 'c-user-border-text', 'chatUserBorder'],
        ['c-ai-bg',       'c-ai-bg-text',       'chatAiBg'],
        ['c-ai-text',     'c-ai-text-text',     'chatAiText'],
        ['c-ai-border',   'c-ai-border-text',   'chatAiBorder'],
        ['c-italic',      'c-italic-text',      'chatItalic'],
        ['c-bold',        'c-bold-text',        'chatBold'],
        ['c-dialogue',    'c-dialogue-text',    'chatDialogue'],
        ['c-narration',   'c-narration-text',   'chatNarration'],
        ['c-accent',      'c-accent-text',      'chatAccent'],
        ['c-bg',          'c-bg-text',          'appBg'],
        ['c-surface',     'c-surface-text',     'appSurface'],
        ['c-red',         'c-red-text',         'appRed'],
        ['c-text',        'c-text-text',        'appText'],
    ];

    // Sync pickers <-> text inputs
    FIELDS.forEach(([pickId, txtId]) => {
        const pick = document.getElementById(pickId);
        const txt  = document.getElementById(txtId);
        if (!pick || !txt) return;
        pick.addEventListener('input', () => { txt.value = pick.value; });
        txt.addEventListener('input', () => { if (/^#[0-9A-Fa-f]{6}$/.test(txt.value)) pick.value = txt.value; });
    });

    function populateFromState() {
        const t = { ...THEME_DEFAULTS, ...(state.theme || {}) };
        FIELDS.forEach(([pickId, txtId, key]) => {
            const val = t[key] || '#000000';
            const pick = document.getElementById(pickId);
            const txt  = document.getElementById(txtId);
            if (pick) pick.value = val;
            if (txt)  txt.value  = val;
        });
        
        const fontSizeInput = document.getElementById('c-font-size');
        if (fontSizeInput) fontSizeInput.value = t.chatFontSize || 15;
    }

    if (btn) btn.onclick = () => {
        populateFromState();
        overlay.classList.remove('hidden');
    };
    if (closeBtn) closeBtn.onclick = () => overlay.classList.add('hidden');

    if (saveBtn) saveBtn.onclick = async () => {
        if (!state.theme) state.theme = {};
        FIELDS.forEach(([pickId,, key]) => {
            const pick = document.getElementById(pickId);
            if (pick) state.theme[key] = pick.value;
        });
        
        const fontSizeInput = document.getElementById('c-font-size');
        if (fontSizeInput) state.theme.chatFontSize = parseInt(fontSizeInput.value) || 15;

        await saveState();
        applyTheme();
        overlay.classList.add('hidden');
        showToast('Theme saved!', 'success');
    };

    if (resetBtn) resetBtn.onclick = () => {
        state.theme = { ...THEME_DEFAULTS };
        populateFromState();
        applyTheme();
        showToast('Reset to defaults', 'info');
    };
}

function setupLibraryFilters() {
    const search = document.getElementById('lib-search');
    const sort = document.getElementById('lib-sort');
    
    search.oninput = () => {
        state.libFilter.search = search.value.toLowerCase();
        renderLibrary();
    };

    sort.onchange = () => {
        state.libFilter.sort = sort.value;
        renderLibrary();
    };
}

// --- Navigation ---
function setupNavigation() {
    navBtns.forEach(btn => {
        if (btn.dataset.view) btn.onclick = () => switchView(btn.dataset.view);
    });

    const homeButton = document.getElementById('sidebar-home-btn');
    if (homeButton) homeButton.onclick = () => switchView('library');
    document.querySelectorAll('[data-dismiss-fallback]').forEach(button => {
        button.onclick = () => document.getElementById(button.dataset.dismissFallback)?.classList.add('hidden');
    });

    document.getElementById('create-new-char-btn').onclick = () => {
        createNewCharacter();
        switchView('studio');
    };

    const createWorldBtn = document.getElementById('create-new-world-btn');
    if (createWorldBtn) {
        createWorldBtn.onclick = () => {
            createNewWorld();
        };
    }
}

function switchView(viewName) {
    // ScenePulse source weather/tint lives at body level so it can match the
    // original behind-the-panel paint order.  Leaving World Play therefore
    // needs an explicit lifecycle cleanup; merely hiding the column would
    // leave the previous fixture's ambient layer over another Horde view.
    if (state.view === 'worldPlay' && viewName !== 'worldPlay') {
        const scenePulseHost = document.getElementById('world-sidecar-workspace');
        unbindScenePulseWorldsHostActions(scenePulseHost);
        window.HordeScenePulseSourceRuntime?.unmount?.(scenePulseHost);
        window.HordeScenePulseWorlds?.unmount?.(scenePulseHost);
    }
    if (state.view === 'stockWorlds' && viewName !== 'stockWorlds') {
        window.StockWorlds17Pass0?.unmount?.();
    }
    state.view = viewName;
    persistWorkspaceSoon();
    
    // Update Nav Buttons
    const navParent = {
        chat: 'library',
        studio: 'library',
        companionStudio: 'companions',
        companionChat: 'companions',
        worldStudio: 'worlds',
        worldPlay: 'worlds',
        videoWorldStudio: 'videoWorlds',
        videoWorldPlay: 'videoWorlds',
        multiplayerSession: 'multiplayer'
    }[viewName] || viewName;
    navBtns.forEach(btn => {
        btn.classList.toggle('active', btn.dataset.view === navParent);
    });

    // Update Section Visibility
    Object.keys(views).forEach(v => {
        if (views[v]) {
            views[v].classList.toggle('hidden', v !== viewName);
        }
    });

    // View specific logic
    if (viewName === 'library') renderLibrary();
    if (viewName === 'multiplayer') {
        renderMultiplayerHub();
        void window.StockWorlds17Pass0?.ready?.().then(() => {
            if (state.view === 'multiplayer') renderMultiplayerHub();
        }).catch(error => {
            console.error('Stock Worlds 17.0 multiplayer sources failed to load:', error);
            window.__hordeRuntimeErrors.push({
                message: `Stock Worlds 17.0 multiplayer sources failed to load: ${String(error?.message || error)}`,
                stack: String(error?.stack || '')
            });
        });
    }
    if (viewName === 'pip') requestAnimationFrame(() => document.getElementById('labs-guide-input')?.focus());
    
    if (viewName === 'chat') {
        if (!state.activeCharId && !state.activeRoomId && state.characters.length > 0) {
            state.activeCharId = state.characters[0].id; // Auto-select first char if none active
        }
        if (state.activeCharId || state.activeRoomId) renderChat();
        else {
            showToast('Select a character or room from the library first.', 'info');
            switchView('library');
        }
    }

    if (viewName === 'studio') {
        if (!state.editingChar) {
            if (state.activeCharId) {
                editCharacter(state.activeCharId);
            } else {
                createNewCharacter();
            }
        }
    }

    if (viewName === 'worlds') {
        renderWorlds();
    }
    if (viewName === 'stockWorlds') {
        if (!window.StockWorlds17Pass0) {
            showToast('Stock Worlds is unavailable because its runtime asset did not load.', 'error');
            switchView('library');
            return;
        }
        const mount = document.getElementById('stock-worlds-pass0-mount');
        void window.StockWorlds17Pass0.mount(mount).catch(error => {
            console.error('Stock Worlds 17.0 failed to mount:', error);
            window.__hordeRuntimeErrors.push({
                message: `Stock Worlds 17.0 failed to mount: ${String(error?.message || error)}`,
                stack: String(error?.stack || '')
            });
            showToast(`Unable to open stock Worlds: ${error?.message || error}`, 'error');
        });
    }
    window.HordeVideoWorlds?.onView?.(viewName);

    if (viewName === 'worldStudio') {
        if (!state.editingWorld) {
            // Prioritize: 1. Playing World, 2. First World in List, 3. Create New
            if (state.activeWorldId) openWorldStudio(state.activeWorldId);
            else if (state.worlds.length > 0) openWorldStudio(state.worlds[0].id);
            else createNewWorld();
        }
    }

    if (viewName === 'companions') renderCompanionsGrid();

    if (viewName === 'companionStudio') {
        if (!state.editingCompanionId) {
            if (state.companions.length > 0) openCompanionStudio(state.companions[0].id);
            else openCompanionStudio(createCompanion().id);
        }
        renderCompanionStudioForm();
    }

    if (viewName === 'companionChat') {
        if (state.activeCompanionId) {
            renderCompanionThread();
            const activeCompanion = getCompanion(state.activeCompanionId);
            if (activeCompanion) {
                refreshCompanionInputCapabilities(activeCompanion).then(changed => {
                    if (changed && state.view === 'companionChat' && state.activeCompanionId === activeCompanion.id) {
                        renderCompanionThread();
                    }
                });
            }
        }
        else { showToast('Pick a virtual human first.', 'info'); switchView('companions'); }
    }
}

// --- Library View ---
function renderLibrary() {
    charGrid.innerHTML = '';
    
    // Generate filtered list
    let list = [...state.characters];
    
    // 1. Search
    if (state.libFilter.search) {
        list = list.filter(c => c.name.toLowerCase().includes(state.libFilter.search) || (c.tags && c.tags.some(t => t.toLowerCase().includes(state.libFilter.search))));
    }
    
    // 2. Tags
    if (state.libFilter.activeTag) {
        list = list.filter(c => c.tags && c.tags.includes(state.libFilter.activeTag));
    }
    
    // 3. Sort
    list.sort((a, b) => {
        if (state.libFilter.sort === 'name-asc') return a.name.localeCompare(b.name);
        if (state.libFilter.sort === 'name-desc') return b.name.localeCompare(a.name);
        if (state.libFilter.sort === 'favorites') {
            if (a.isFavorite && !b.isFavorite) return -1;
            if (!a.isFavorite && b.isFavorite) return 1;
            return a.name.localeCompare(b.name);
        }
        if (state.libFilter.sort === 'recent') {
            return (Number(b.lastUsedAt) || 0) - (Number(a.lastUsedAt) || 0) || a.name.localeCompare(b.name);
        }
        return 0;
    });
    const characterCount = document.getElementById('library-character-count');
    const roomCount = document.getElementById('library-room-count');
    if (characterCount) characterCount.textContent = state.characters.length;
    if (roomCount) roomCount.textContent = state.rooms?.length || 0;

    list.forEach(char => {
        const card = document.createElement('div');
        card.className = 'char-card';
        const playCharacter = () => {
            char.lastUsedAt = Date.now();
            saveState().catch(() => {});
            state.activeCharId = char.id;
            state.activeRoomId = null; // Clear room state if present
            switchView('chat');
        };
        card.onclick = playCharacter;
        
        const isFav = !!char.isFavorite;
        const model = (char.model || 'No Model').split('/').pop();
        const tagsHtml = (char.tags || []).map(t => `<div class="mini-tag">${escapeHTML(t)}</div>`).join('');
        const avatarInitials = displayInitials(char.name);

        card.innerHTML = `
            <div class="char-card-banner" style="${char.bg ? `background-image:url('${cssUrl(char.bg)}')` : ''}">
                <button class="char-card-fav-btn ${isFav ? 'active' : ''}" type="button" data-id="${escapeHTML(char.id)}" aria-label="${isFav ? 'Remove from favorites' : 'Add to favorites'}" aria-pressed="${isFav}">${isFav ? '❤️' : '🤍'}</button>
                <div class="char-card-avatar-wrap">
                    <div class="char-card-avatar${char.avatar ? ' has-image' : ''}" style="${char.avatar ? `background-image:url('${cssUrl(char.avatar)}')` : ''}" aria-hidden="true">${char.avatar ? '' : escapeHTML(avatarInitials)}</div>
                </div>
            </div>
            <div class="char-card-body">
                <div class="char-card-name">${escapeHTML(char.name)}</div>
                <div class="char-card-desc">${escapeHTML(char.desc || 'No description provided.')}</div>
                <div class="char-card-tags">${tagsHtml}</div>
                <div class="char-card-tag">${escapeHTML(model)}</div>
                <div class="char-card-actions">
                    <button class="btn btn-primary char-card-play" type="button">Play</button>
                    <button class="btn btn-ghost char-card-edit" type="button" title="Edit in Character Studio">Edit</button>
                </div>
            </div>
        `;
        
        card.querySelector('.char-card-fav-btn').onclick = async (e) => {
            e.stopPropagation();
            char.isFavorite = !char.isFavorite;
            const idx = state.characters.findIndex(c => c.id === char.id);
            if (idx !== -1) state.characters[idx].isFavorite = char.isFavorite;
            await saveState();
            renderLibrary();
        };
        card.querySelector('.char-card-play').onclick = (event) => {
            event.stopPropagation();
            playCharacter();
        };
        card.querySelector('.char-card-edit').onclick = (event) => {
            event.stopPropagation();
            editCharacter(char.id);
            switchView('studio');
        };

        charGrid.appendChild(card);
    });

    // Render Tags List in Filter Bar
    const allTags = new Set();
    state.characters.forEach(c => (c.tags || []).forEach(t => allTags.add(t)));
    const tagsContainer = document.getElementById('lib-tags-list');
    tagsContainer.innerHTML = '';
    
    if (allTags.size > 0) {
        const allBtn = document.createElement('div');
        allBtn.className = `tag-pill ${!state.libFilter.activeTag ? 'active' : ''}`;
        allBtn.textContent = 'All';
        allBtn.onclick = () => { state.libFilter.activeTag = null; renderLibrary(); };
        tagsContainer.appendChild(allBtn);
        
        Array.from(allTags).sort().forEach(tag => {
            const btn = document.createElement('div');
            btn.className = `tag-pill ${state.libFilter.activeTag === tag ? 'active' : ''}`;
            btn.textContent = tag;
            btn.onclick = () => {
                state.libFilter.activeTag = (state.libFilter.activeTag === tag) ? null : tag;
                renderLibrary();
            };
            tagsContainer.appendChild(btn);
        });
    }

    if (list.length === 0) {
        charGrid.innerHTML = '<div class="empty-state"><h3>No characters match your filter</h3><p>Try adjusting your search or tags</p></div>';
    }
}

// --- Optional Chat HUD ------------------------------------------------------

function chatHudId(value, fallback = 'meter') {
    const id = String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 48);
    return id || fallback;
}

function normalizeChatHudConfig(raw) {
    const source = isPlainObject(raw) ? raw : {};
    const seen = new Set();
    const meters = (Array.isArray(source.meters) ? source.meters : []).slice(0, 8).map((rawMeter, index) => {
        const meter = isPlainObject(rawMeter) ? rawMeter : {};
        let id = chatHudId(meter.id || meter.label, `meter_${index + 1}`);
        while (seen.has(id)) id = `${id}_${index + 1}`;
        seen.add(id);
        let min = Number.isFinite(Number(meter.min)) ? Number(meter.min) : 0;
        let max = Number.isFinite(Number(meter.max)) ? Number(meter.max) : 100;
        if (max <= min) max = min + 1;
        const initial = Math.max(min, Math.min(max, Number.isFinite(Number(meter.initial)) ? Number(meter.initial) : min));
        return { id, label: String(meter.label || `Meter ${index + 1}`).trim().slice(0, 60), min, max, initial,
            color: cssColor(meter.color, '#E63946'), guidance: String(meter.guidance || '').trim().slice(0, 300) };
    });
    return {
        enabled: source.enabled === true,
        title: String(source.title || 'Status').trim().slice(0, 80) || 'Status',
        controller: ['manual', 'main', 'labs'].includes(source.controller) ? source.controller : 'manual',
        brief: String(source.brief || '').trim().slice(0, 1200),
        allowManual: source.allowManual !== false,
        meters
    };
}

function ensureChatHudState(character, session) {
    const config = normalizeChatHudConfig(character?.chatHud);
    if (!session) return { config, state: null };
    const stored = isPlainObject(session.chatHudState) ? session.chatHudState : {};
    const previous = isPlainObject(stored.values) ? stored.values : {};
    session.chatHudState = {
        values: Object.fromEntries(config.meters.map(meter => [meter.id,
            Math.max(meter.min, Math.min(meter.max, Number.isFinite(Number(previous[meter.id])) ? Number(previous[meter.id]) : meter.initial))])),
        status: String(stored.status || '').slice(0, 280),
        updatedAt: Number(stored.updatedAt) || 0,
        source: ['manual', 'main', 'labs'].includes(stored.source) ? stored.source : 'manual'
    };
    return { config, state: session.chatHudState };
}

function applyChatHudUpdate(character, session, proposal, source) {
    const { config, state: hudState } = ensureChatHudState(character, session);
    if (!hudState || !isPlainObject(proposal)) return false;
    let changed = false;
    const definitions = new Map(config.meters.map(meter => [meter.id, meter]));
    (Array.isArray(proposal.meters) ? proposal.meters : []).slice(0, 8).forEach(raw => {
        const definition = definitions.get(String(raw?.id || ''));
        if (!definition || !Number.isFinite(Number(raw.value))) return;
        const value = Math.max(definition.min, Math.min(definition.max, Number(raw.value)));
        if (hudState.values[definition.id] !== value) changed = true;
        hudState.values[definition.id] = value;
    });
    const status = String(proposal.status || '').trim().slice(0, 280);
    if (status && status !== hudState.status) { hudState.status = status; changed = true; }
    if (changed) { hudState.updatedAt = Date.now(); hudState.source = source; }
    return changed;
}

function extractChatHudDirective(text) {
    const source = String(text || '');
    let update = null;
    let cleaned = source.replace(/<horde_status>\s*([\s\S]*?)\s*<\/horde_status>/gi, (whole, payload) => {
        const parsed = safeParseJSONRepair(payload);
        if (isPlainObject(parsed)) update = parsed;
        return '';
    }).replace(/\[\[HUD_UPDATE\]\]\s*([\s\S]*?)\s*\[\[\/HUD_UPDATE\]\]/gi, (whole, payload) => {
        const parsed = safeParseJSONRepair(payload);
        if (isPlainObject(parsed)) update = parsed;
        return '';
    });
    // Quarantine incomplete or orphaned private protocol as well. It is safer
    // to lose a malformed footer than display engine JSON as character speech.
    cleaned = cleaned.replace(/<horde_status\b[^>]*>[\s\S]*$/i, '')
        .replace(/\[\[HUD_UPDATE\]\][\s\S]*$/i, '')
        .replace(/<\/?horde_status\b[^>]*>/gi, '')
        .replace(/\[\[\/?HUD_UPDATE\]\]/gi, '')
        .trim();
    return { text: cleaned, update };
}

function chatHudPrompt(character, session) {
    const { config, state: hudState } = ensureChatHudState(character, session);
    if (!config.enabled || config.controller !== 'main' || !config.meters.length) return '';
    return `[OPTIONAL PRIVATE CHAT HUD — MANDATORY FOOTER]\nAfter the visible reply, output exactly one private footer: <horde_status>{"meters":[{"id":"exact_id","value":number,"evidence":"short exact excerpt from this exchange, required when changed"}],"status":"one short factual current-status sentence","statusEvidence":"short exact excerpt supporting the status"}</horde_status>. It is stripped before display. Preserve a value unless this exchange clearly changes it. Evidence must appear verbatim in the player message or your visible reply. Never invent off-screen facts or reveal hidden thoughts.\nStatus brief: ${config.brief || 'Summarize only the explicit current conversational situation.'}\nMeters: ${config.meters.map(meter => `${meter.label} [${meter.id}] ${meter.min}..${meter.max}, current ${hudState.values[meter.id]}${meter.guidance ? ` — ${meter.guidance}` : ''}`).join(' | ')}`;
}

function groundChatHudProposal(proposal, config, hudState, exchange) {
    if (!isPlainObject(proposal)) return {};
    const source = String(exchange || '').toLocaleLowerCase();
    const definitions = new Map(config.meters.map(meter => [meter.id, meter]));
    const meters = (Array.isArray(proposal.meters) ? proposal.meters : []).slice(0, 8).filter(raw => {
        const definition = definitions.get(String(raw?.id || ''));
        if (!definition || !Number.isFinite(Number(raw?.value))) return false;
        const value = Math.max(definition.min, Math.min(definition.max, Number(raw.value)));
        if (value === hudState.values[definition.id]) return true;
        const evidence = String(raw?.evidence || '').trim().toLocaleLowerCase();
        return !!evidence && source.includes(evidence);
    });
    const status = String(proposal.status || '').trim().slice(0, 280);
    const statusEvidence = String(proposal.statusEvidence || '').trim().toLocaleLowerCase();
    return {
        meters,
        status: status && statusEvidence && source.includes(statusEvidence) ? status : ''
    };
}

async function updateChatHudFromTurn(character, session, userText, replyText, embeddedUpdate = null) {
    const { config, state: hudState } = ensureChatHudState(character, session);
    if (!config.enabled || !config.meters.length) return false;
    const exchange = `PLAYER: ${String(userText || '').slice(0, 1800)}\nREPLY: ${String(replyText || '').slice(0, 2600)}`;
    if (config.controller === 'main') {
        return applyChatHudUpdate(character, session,
            groundChatHudProposal(embeddedUpdate || {}, config, hudState, exchange), 'main');
    }
    if (config.controller !== 'labs' || !window.HordeLabs) return false;
    try {
        const result = await window.HordeLabs.propose('status_update', {
            text: exchange,
            message: exchange,
            brief: config.brief,
            meters: config.meters.map(meter => ({ ...meter, current: hudState.values[meter.id] }))
        }, { mode: 'chat', priority: 105 });
        return result?.accepted ? applyChatHudUpdate(character, session, result.candidate, 'labs') : false;
    } catch (error) { return false; }
}

function renderChatHudEditor() {
    if (!state.editingChar) return;
    state.editingChar.chatHud = normalizeChatHudConfig(state.editingChar.chatHud);
    const config = state.editingChar.chatHud;
    document.getElementById('studio-chat-hud-enabled').checked = config.enabled;
    document.getElementById('studio-chat-hud-title').value = config.title;
    document.getElementById('studio-chat-hud-controller').value = config.controller;
    document.getElementById('studio-chat-hud-brief').value = config.brief;
    document.getElementById('studio-chat-hud-manual').checked = config.allowManual;
    document.getElementById('studio-chat-hud-settings').classList.toggle('chat-hud-settings-disabled', !config.enabled);
    const list = document.getElementById('studio-chat-hud-meter-list');
    list.innerHTML = config.meters.length ? config.meters.map((meter, index) => `
        <div class="chat-hud-meter-edit" data-index="${index}">
            <label>Name<input class="form-input" data-field="label" value="${escapeHTML(meter.label)}"></label>
            <label>ID<input class="form-input" data-field="id" value="${escapeHTML(meter.id)}"></label>
            <label>Min<input class="form-input" data-field="min" type="number" value="${meter.min}"></label>
            <label>Max<input class="form-input" data-field="max" type="number" value="${meter.max}"></label>
            <label>Start<input class="form-input" data-field="initial" type="number" value="${meter.initial}"></label>
            <label>Color<input data-field="color" type="color" value="${escapeHTML(meter.color)}"></label>
            <button class="btn btn-ghost chat-hud-meter-remove" data-remove="${index}" type="button" title="Remove meter">✕</button>
            <label style="grid-column:1/-1">Update guidance<input class="form-input" data-field="guidance" value="${escapeHTML(meter.guidance)}" placeholder="What causes this meter to change?"></label>
        </div>`).join('') : '<div class="labs-empty">No meters yet. Add one to build the sidebar.</div>';
    list.querySelectorAll('[data-field]').forEach(input => input.onchange = () => {
        const row = input.closest('[data-index]');
        const meter = state.editingChar.chatHud.meters[Number(row.dataset.index)];
        meter[input.dataset.field] = ['min', 'max', 'initial'].includes(input.dataset.field) ? Number(input.value) : input.value;
        state.editingChar.chatHud = normalizeChatHudConfig(state.editingChar.chatHud);
        renderChatHudEditor();
    });
    list.querySelectorAll('[data-remove]').forEach(button => button.onclick = () => {
        state.editingChar.chatHud.meters.splice(Number(button.dataset.remove), 1); renderChatHudEditor();
    });
}

// --- Studio View (Advanced Creator) ---
function setupStudioTabs() {
    const tabs = document.querySelectorAll('#studio-view .studio-tab');
    const panels = document.querySelectorAll('#studio-view .studio-panel');

    tabs.forEach(tab => {
        tab.onclick = () => {
            tabs.forEach(t => t.classList.remove('active'));
            panels.forEach(p => p.classList.add('hidden'));
            tab.classList.add('active');
            const target = document.getElementById(`tab-${tab.dataset.tab}`);
            if (target) target.classList.remove('hidden');
            state.lastStudioTab = tab.dataset.tab || null;
            persistWorkspaceSoon();
        };
    });
    document.querySelectorAll('[data-chat-studio-target]').forEach(button => {
        button.onclick = () => document.querySelector(`#studio-view .studio-tab[data-tab="${button.dataset.chatStudioTarget}"]`)?.click();
    });
}

function setupStudioLogic() {
    const profileUpload = document.getElementById('profile-upload-area');
    const profileInput = document.getElementById('profile-input');
    const profilePreview = document.getElementById('profile-preview');

    profileUpload.onclick = () => profileInput.click();
    profileInput.onchange = async (e) => {
        const file = e.target.files[0];
        if (!file) return;
        try {
            const optimized = await normalizeUploadedImage(file, 512, 0.8);
            state.editingChar.avatar = optimized;
            profilePreview.innerHTML = `<img src="${optimized}">`;
        } catch (error) {
            showToast(`Image upload failed: ${error.message}`, 'error');
        } finally { e.target.value = ''; }
    };

    const bgInput = document.getElementById('bg-input');
    const bgStatus = document.getElementById('bg-file-status');
    bgInput.onchange = async (e) => {
        const file = e.target.files[0];
        if (!file) return;
        if (bgStatus) bgStatus.textContent = `Processing ${file.name}…`;
        try {
            const optimized = await normalizeUploadedImage(file, 1280, 0.7);
            state.editingChar.bg = optimized;
            if (bgStatus) bgStatus.textContent = `${file.name} · ready`;
            showToast('Background image normalized and ready.', 'success');
        } catch (error) {
            if (bgStatus) bgStatus.textContent = 'Upload failed — choose another image';
            showToast(`Image upload failed: ${error.message}`, 'error');
        } finally { e.target.value = ''; }
    };

    document.getElementById('studio-name').oninput = updateTokenCount;
    document.getElementById('studio-prompt').oninput = updateTokenCount;
    document.getElementById('studio-intro').oninput = updateTokenCount;
    document.getElementById('studio-system-prompt').oninput = updateTokenCount;
    document.getElementById('studio-personality').oninput = updateTokenCount;
    document.getElementById('studio-scenario').oninput = updateTokenCount;
    document.getElementById('studio-chat-hud-enabled').onchange = event => {
        state.editingChar.chatHud = normalizeChatHudConfig({ ...state.editingChar.chatHud, enabled: event.target.checked });
        renderChatHudEditor();
    };
    ['title', 'controller', 'brief'].forEach(field => {
        document.getElementById(`studio-chat-hud-${field}`).onchange = event => {
            state.editingChar.chatHud[field] = event.target.value;
        };
    });
    document.getElementById('studio-chat-hud-manual').onchange = event => { state.editingChar.chatHud.allowManual = event.target.checked; };
    document.getElementById('studio-add-chat-meter').onclick = () => {
        state.editingChar.chatHud = normalizeChatHudConfig(state.editingChar.chatHud);
        if (state.editingChar.chatHud.meters.length >= 8) return showToast('A chat HUD supports up to eight meters.', 'info');
        const index = state.editingChar.chatHud.meters.length + 1;
        state.editingChar.chatHud.meters.push({ id: `meter_${index}`, label: `Meter ${index}`, min: 0, max: 100, initial: 50, color: '#E63946', guidance: '' });
        renderChatHudEditor();
    };

    document.querySelectorAll('input[name="studio_mode"]').forEach(radio => {
        radio.addEventListener('change', (e) => {
            const isStructured = e.target.value === 'structured';
            document.getElementById('studio-advanced-mode').classList.toggle('hidden', isStructured);
            document.getElementById('studio-structured-mode').classList.toggle('hidden', !isStructured);
            if (state.editingChar) state.editingChar.studioMode = e.target.value;
            updateTokenCount();
        });
    });

    document.getElementById('fetch-model-btn').onclick = fetchModelSettings;
    document.getElementById('save-studio-btn').onclick = saveStudioCharacter;
    document.getElementById('save-chat-studio-btn').onclick = async () => {
        const saved = await saveStudioCharacter();
        if (!saved || !state.editingChar?.id) return;
        state.activeCharId = state.editingChar.id;
        state.activeRoomId = null;
        switchView('chat');
    };
    document.getElementById('close-chat-studio-btn').onclick = () => switchView('library');
    document.getElementById('delete-char-btn').onclick = () => {
        if (!state.editingChar) return;
        showConfirmModal('Delete Character', `Permanently delete ${state.editingChar.name}?`, async () => {
            const idx = state.characters.findIndex(c => c.id === state.editingChar.id);
            if (idx !== -1) {
                state.characters.splice(idx, 1);
                delete state.chats[state.editingChar.id];
                await saveState();
                state.editingChar = null;
                state.activeCharId = null;
                switchView('library');
                showToast('Character Deleted', 'success');
            }
        });
    };
    document.getElementById('add-lore-btn').onclick = addLoreEntry;
    document.getElementById('add-memory-btn').onclick = addMemoryBlock;
    document.getElementById('summarize-memory-btn').onclick = summarizeStory;
    document.getElementById('export-nexus-btn').onclick = exportNexus;
    document.getElementById('import-nexus-btn').onclick = () => {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = '.nexus, .json, .png, image/png';
        input.onchange = importNexus;
        input.click();
    };

    document.getElementById('open-in-studio-btn').onclick = () => {
        if (state.activeCharId) {
            editCharacter(state.activeCharId);
            switchView('studio');
        } else if (state.activeRoomId) {
            openRoomStudio(state.activeRoomId);
        }
    };

    const unlockBtn = document.getElementById('unlock-all-params-btn');
    if (unlockBtn) {
        unlockBtn.onclick = () => {
            updateReasoningVisibility([], '', true);
            showToast('All parameters unlocked for this session.', 'success');
        };
    }

    // Initialize Vector Memory Viewer Events
    setupVectorMemoryViewerEvents();
}

function updateTokenCount() {
    const name = document.getElementById('studio-name').value;
    const mode = state.editingChar?.studioMode || 'advanced';
    let prompt = '';
    if (mode === 'structured') {
        prompt = document.getElementById('studio-system-prompt').value + 
                 document.getElementById('studio-personality').value + 
                 document.getElementById('studio-scenario').value;
    } else {
        prompt = document.getElementById('studio-prompt').value;
    }
    const intro = document.getElementById('studio-intro').value;
    const lore = (state.editingChar?.lorebook || []).map(l => l.keyword + l.text).join('');
    
    const total = name.length + prompt.length + intro.length + lore.length;
    // Use the same chars/3.5 estimate as context truncation & world studio for consistency
    document.getElementById('studio-token-count').textContent = Math.ceil(total / 3.5).toLocaleString();
}

async function fetchModelData(modelId, prefix, targetObj) {
    if (!modelId) return showToast('Please enter a Model ID first.', 'error');
    
    const btn = document.getElementById(prefix + 'fetch-btn') || 
                document.getElementById('fetch-' + prefix + 'model-btn') ||
                document.getElementById(prefix === 'w-' ? 'w-fetch-model-btn' : 'fetch-model-btn');
                
    const oldText = btn ? btn.textContent : '';
    if (btn) {
        btn.textContent = 'Fetching...';
        btn.disabled = true;
    }

    try {
        const models = await getOpenRouterModels();
        const matchingModel = models.find(m => m.id === modelId);
        if (matchingModel) {
            // Auto-populate context size and max tokens
            let ctxInput = document.getElementById(prefix + 'context-size') || 
                           document.getElementById(prefix + 'studio-context-size') ||
                           document.getElementById(prefix === 'w-' ? 'w-studio-context-size' : 'studio-context-size');
            
            let maxInput = document.getElementById(prefix + 'max-tokens') ||
                           document.getElementById(prefix + 'studio-max-tokens') ||
                           document.getElementById(prefix === 'w-' ? 'w-studio-max-tokens' : 'studio-max-tokens');
            
            if (ctxInput) {
                // Dynamically adjust the context limit slider max and stepping
                const physicalLimit = matchingModel.context_length || 8192;
                ctxInput.max = physicalLimit;
                
                if (physicalLimit <= 32768) {
                    ctxInput.step = 1024;
                } else if (physicalLimit <= 131072) {
                    ctxInput.step = 2048;
                } else if (physicalLimit <= 524288) {
                    ctxInput.step = 8192;
                } else {
                    ctxInput.step = 16384;
                }

                ctxInput.value = Math.min(physicalLimit, 16384);
                ctxInput.dispatchEvent(new Event('input'));
            }
            
            const maxOutput = matchingModel.top_provider?.max_completion_tokens;
            if (maxOutput && maxInput) {
                const currentMax = parseInt(maxInput.value) || 2048;
                if (currentMax > maxOutput) {
                    maxInput.value = maxOutput;
                }
            }

            // Store supported parameters
            const supportedParams = matchingModel.supported_parameters || [];
            if (targetObj) {
                targetObj.supportedParams = supportedParams;
                targetObj.contextSize = Math.min(matchingModel.context_length || 8192, 16384);
            }

            // Update UI
            populateModelInfoCard(matchingModel, prefix);
            updateReasoningVisibility(supportedParams, modelId, false, prefix);

            showToast(`Model verified: ${matchingModel.name}`, 'success');
            return matchingModel;
        } else {
            showToast('Model not found in OpenRouter.', 'error');
            const card = document.getElementById(prefix + 'model-info-card') || 
                         document.getElementById(prefix === 'w-' ? 'w-model-info-card' : 'model-info-card');
            if (card) card.classList.add('hidden');
            const reasoning = document.getElementById(prefix + 'reasoning-section') || 
                              document.getElementById(prefix === 'w-' ? 'w-reasoning-section' : 'reasoning-section');
            if (reasoning) reasoning.classList.add('hidden');
        }
    } catch (err) {
        showToast('Fetch failed: ' + err.message, 'error');
    } finally {
        if (btn) {
            btn.textContent = oldText;
            btn.disabled = false;
        }
    }
    return null;
}

async function fetchModelSettings() {
    const modelInput = document.getElementById('studio-model').value.trim();
    await fetchModelData(modelInput, 'studio-', state.editingChar);
}

async function fetchRoomModelSettings() {
    const modelInput = document.getElementById('room-model').value.trim();
    await fetchModelData(modelInput, 'room-', state.editingRoom);
}

function getModelInfoElements(prefix) {
    let card, nameEl, idEl, badge, detailsContext, detailsPrice, detailsTools, detailsJson, badges, paramsList;

    if (prefix === 'w-' || prefix === 'w-studio-') {
        card = document.getElementById('w-model-info-card');
        nameEl = document.getElementById('w-model-info-name');
        idEl = document.getElementById('w-model-info-id');
        badge = document.getElementById('w-model-verification-badge');
        detailsContext = document.getElementById('w-model-detail-context');
        detailsPrice = document.getElementById('w-model-detail-price');
        detailsTools = document.getElementById('w-model-detail-tools');
        detailsJson = document.getElementById('w-model-detail-json');
        badges = document.getElementById('w-model-info-badges');
        paramsList = document.getElementById('w-model-info-params-list');
    } else {
        card = document.getElementById('model-info-card');
        nameEl = document.getElementById('model-info-name');
        idEl = document.getElementById('model-info-id');
        badge = document.getElementById('model-verification-badge');
        detailsContext = document.getElementById('model-detail-context');
        detailsPrice = document.getElementById('model-detail-price');
        detailsTools = document.getElementById('model-detail-tools');
        detailsJson = document.getElementById('model-detail-json');
        badges = document.getElementById('model-info-badges');
        paramsList = document.getElementById('model-info-params-list');
    }

    return { card, nameEl, idEl, badge, detailsContext, detailsPrice, detailsTools, detailsJson, badges, paramsList };
}

function populateModelInfoCard(model, prefix = '') {
    const els = getModelInfoElements(prefix);
    if (!els.card) return;
    els.card.classList.remove('hidden');

    if (els.nameEl) els.nameEl.textContent = model.name || model.id;
    if (els.idEl) els.idEl.textContent = model.id;

    // Run dynamic verification layer
    if (els.badge) {
        const context = model.context_length || 8192;
        const params = model.supported_parameters || [];
        const pricing = model.pricing || {};
        const promptPrice = Number.isFinite(parseFloat(pricing.prompt)) ? (parseFloat(pricing.prompt) * 1000000).toFixed(2) : '—';
        const completionPrice = Number.isFinite(parseFloat(pricing.completion)) ? (parseFloat(pricing.completion) * 1000000).toFixed(2) : '—';

        const hasTools = params.includes('tools') || params.includes('tool_choice');
        const hasJson = params.includes('response_format') || params.includes('structured_outputs');

        if (els.detailsContext) els.detailsContext.textContent = `👁️ Context: ${Math.round(context / 1000)}k tokens`;
        if (els.detailsPrice) els.detailsPrice.textContent = `💰 $${promptPrice} / $${completionPrice} (per M)`;

        if (els.detailsTools) {
            if (hasTools) {
                els.detailsTools.textContent = "✅ Tool Calling";
                els.detailsTools.className = "verification-detail-item supported";
            } else {
                els.detailsTools.textContent = "❌ Tool Calling";
                els.detailsTools.className = "verification-detail-item unsupported";
            }
        }

        if (els.detailsJson) {
            if (hasJson) {
                els.detailsJson.textContent = "✅ Structured JSON";
                els.detailsJson.className = "verification-detail-item supported";
            } else {
                els.detailsJson.textContent = "❌ Structured JSON";
                els.detailsJson.className = "verification-detail-item unsupported";
            }
        }

        // Tier Grade Styling
        els.card.classList.remove('tier-elite', 'tier-capable', 'tier-weak');
        if (hasTools && hasJson && context >= 32000) {
            els.badge.textContent = "Elite Agent (Class S)";
            els.badge.className = "verification-badge badge-elite";
            els.card.classList.add('tier-elite');
        } else if (hasTools || hasJson) {
            els.badge.textContent = "Capable (Class A)";
            els.badge.className = "verification-badge badge-capable";
            els.card.classList.add('tier-capable');
        } else {
            els.badge.textContent = "Not Recommended (Class C)";
            els.badge.className = "verification-badge badge-weak";
            els.card.classList.add('tier-weak');
        }
    }

    if (els.badges) {
        els.badges.innerHTML = '';
        const supportedParams = model.supported_parameters || [];
        if (supportedParams.includes('reasoning')) {
            els.badges.innerHTML += '<span class="model-badge model-badge-reasoning">🧠 Reasoning</span>';
        }
        if (model.architecture?.input_modalities?.includes('image')) {
            els.badges.innerHTML += '<span class="model-badge model-badge-vision">👁 Vision</span>';
        }
        if (model.top_provider?.is_moderated) {
            els.badges.innerHTML += '<span class="model-badge model-badge-moderated">Moderated</span>';
        } else {
            els.badges.innerHTML += '<span class="model-badge model-badge-unmoderated">Unmoderated</span>';
        }
    }

    if (els.paramsList) {
        els.paramsList.innerHTML = '';
        const supportedParams = model.supported_parameters || [];
        const relevantParams = ['temperature', 'top_p', 'top_k', 'min_p', 'frequency_penalty', 'presence_penalty', 'repetition_penalty', 'max_tokens', 'reasoning', 'reasoning_effort', 'include_reasoning', 'seed', 'stop'];
        relevantParams.forEach(p => {
            const tag = document.createElement('span');
            tag.className = 'model-param-tag' + (supportedParams.includes(p) ? ' active' : ' unsupported');
            tag.textContent = p;
            els.paramsList.appendChild(tag);
        });
    }
}

function updateReasoningVisibility(supportedParams, modelId = '', forceShow = false, prefix = '') {
    const reasoningSection = document.getElementById(prefix + 'reasoning-section');
    const effortRow = document.getElementById(prefix + 'reasoning-effort-row');
    if (!reasoningSection || !effortRow) return;

    if (forceShow) {
        reasoningSection.classList.remove('hidden');
        effortRow.classList.remove('hidden');
        effortRow.style.display = 'flex';
        return;
    }

    const lowerId = (modelId || '').toLowerCase();
    const reasoningKeywords = ['deepseek', 'r1', 'v3', 'v4', 'o1', 'o3', 'o4', 'aion', 'reason', 'think', 'thought', 'qwq', 'kimi', 'minimax'];
    
    const isReasoningModel = supportedParams.includes('reasoning') || 
                            supportedParams.includes('reasoning_effort') ||
                            reasoningKeywords.some(k => lowerId.includes(k));

    if (isReasoningModel) {
        reasoningSection.classList.remove('hidden');
    } else {
        reasoningSection.classList.add('hidden');
    }

    if (supportedParams.includes('reasoning_effort') || isReasoningModel) {
        effortRow.classList.remove('hidden');
        effortRow.style.display = 'flex';
    } else {
        effortRow.classList.add('hidden');
        effortRow.style.display = 'none';
    }
}

function createNewCharacter() {
    state.editingChar = {
        id: 'char_' + Date.now(),
        name: '',
        desc: '',
        avatar: '',
        bg: '',
        model: state.globalSettings.defaultModel,
        openRouterRouting: null,
        temp: 0.9,
        maxTokens: 2048,
        topP: 1,
        topK: 0,
        freqPenalty: 0,
        presPenalty: 0,
        repPenalty: 1,
        minP: 0,
        contextSize: 8192,
        reasoning: false,
        includeReasoning: false,
        reasoningEffort: '',
        supportedParams: [],
        prompt: '',
        studioMode: 'advanced',
        systemPrompt: '',
        personality: '',
        scenario: '',
        intro: '',
        hideTopLines: 0,
        hideBottomLines: 0,
        lorebook: [],
        memory: [],
        authorsNote: '',
        authorsNoteDepth: 4,
        authorsNoteFreq: 1,
        chatHud: normalizeChatHudConfig({})
    };
    loadStudioData();
    if (!workspaceRestoring) {
        document.querySelector('#studio-view .studio-tab[data-tab="overview"]')?.click();
    }
}

function editCharacter(id) {
    const char = state.characters.find(c => c.id === id);
    if (!char) return;
    state.editingChar = JSON.parse(JSON.stringify(char)); // Deep clone
    state.editingCharId = char.id;
    persistWorkspaceSoon();
    loadStudioData();
    if (!workspaceRestoring) {
        document.querySelector('#studio-view .studio-tab[data-tab="overview"]')?.click();
    }
}

async function autoSaveStudioChanges() {
    if (!state.editingChar) return;
    const index = state.characters.findIndex(c => c.id === state.editingChar.id);
    if (index !== -1) {
        state.characters[index] = JSON.parse(JSON.stringify(state.editingChar));
        await saveState();
    }
    updateTokenCount();
}

function loadStudioData() {
    const c = state.editingChar;
    c.chatHud = normalizeChatHudConfig(c.chatHud);
    document.getElementById('studio-name').value = c.name;
    document.getElementById('studio-desc').value = c.desc;
    document.getElementById('studio-prompt').value = c.prompt;
    
    document.getElementById('studio-system-prompt').value = c.systemPrompt || '';
    document.getElementById('studio-personality').value = c.personality || '';
    document.getElementById('studio-scenario').value = c.scenario || '';
    
    const mode = c.studioMode || 'advanced';
    document.getElementById(`mode-${mode}`).checked = true;
    document.getElementById('studio-advanced-mode').classList.toggle('hidden', mode === 'structured');
    document.getElementById('studio-structured-mode').classList.toggle('hidden', mode !== 'structured');

    document.getElementById('studio-intro').value = c.intro;
    document.getElementById('studio-model').value = c.model || '';
    initializeOpenRouterRoutingPanel('character');
    document.getElementById('studio-tags').value = (c.tags || []).join(', ');
    
    document.getElementById('studio-temp').value = c.temp || 0.9;
    document.getElementById('studio-max-tokens').value = c.maxTokens || 2048;
    document.getElementById('studio-top-p').value = c.topP || 1.0;
    document.getElementById('studio-top-k').value = c.topK !== undefined ? c.topK : 0;
    document.getElementById('studio-freq-penalty').value = c.freqPenalty !== undefined ? c.freqPenalty : 0;
    document.getElementById('studio-pres-penalty').value = c.presPenalty !== undefined ? c.presPenalty : 0;
    document.getElementById('studio-rep-penalty').value = c.repPenalty !== undefined ? c.repPenalty : 1.0;
    document.getElementById('studio-min-p').value = c.minP !== undefined ? c.minP : 0.0;
    configureContextSliderForModel('studio-context-size', c.model);
    document.getElementById('studio-context-size').value = c.contextSize || 8192;
    updateContextSliderUI('studio-context-size', 'studio-context-size-val', 'studio-context-size-badge');
    
    // Reasoning controls
    document.getElementById('studio-reasoning').checked = !!c.reasoning;
    document.getElementById('studio-include-reasoning').checked = !!c.includeReasoning;
    document.getElementById('studio-reasoning-effort').value = c.reasoningEffort || '';
    
    // Show/hide reasoning section based on stored supported params + model ID
    const supportedParams = c.supportedParams || [];
    updateReasoningVisibility(supportedParams, c.model);
    
    // If we have stored model info, show/hide the info card
    if (supportedParams.length > 0) {
        // We don't have full model data cached, but at least show reasoning controls
    } else {
        document.getElementById('model-info-card').classList.add('hidden');
    }
    
    const hideTop = document.getElementById('studio-hide-top');
    const hideBottom = document.getElementById('studio-hide-bottom');
    if (hideTop) hideTop.value = c.hideTopLines || 0;
    if (hideBottom) hideBottom.value = c.hideBottomLines || 0;
    
    document.getElementById('profile-preview').innerHTML = c.avatar ? `<img src="${escapeHTML(c.avatar)}">` : 'Click to upload';
    const bgStatus = document.getElementById('bg-file-status');
    if (bgStatus) bgStatus.textContent = c.bg ? 'Background image ready' : 'No image selected';

    // Author's Note
    const anField = document.getElementById('studio-authors-note');
    const anDepth = document.getElementById('studio-authors-note-depth');
    const anFreq = document.getElementById('studio-authors-note-freq');
    if (anField) anField.value = c.authorsNote || '';
    if (anDepth) anDepth.value = c.authorsNoteDepth !== undefined ? c.authorsNoteDepth : 4;
    if (anFreq) anFreq.value = c.authorsNoteFreq !== undefined ? c.authorsNoteFreq : 1;
    renderChatHudEditor();
    
    // Populate Presets Dropdown
    const presetLabel = document.querySelector('label[for="studio-system-preset"]');
    if (presetLabel) {
        presetLabel.innerHTML = `System Preset ${c.activePresetId ? '<span style="color:var(--accent); font-size:0.7rem; margin-left:5px;">● ACTIVE</span>' : ''}`;
    }

    const presetSelect = document.getElementById('studio-system-preset');
    presetSelect.innerHTML = '<option value="">None (Custom Prompt Only)</option>';
    getAllPresets().forEach(p => {
        const opt = document.createElement('option');
        opt.value = p.id;
        opt.textContent = p.name;
        opt.selected = c.activePresetId === p.id;
        presetSelect.appendChild(opt);
    });
    
    const fineTuneBtn = document.getElementById('fine-tune-preset-btn');
    if (fineTuneBtn) {
        fineTuneBtn.style.display = c.activePresetId ? 'block' : 'none';
    }

    renderLoreList();
    renderMemoryList();
    updateTokenCount();

    const cachedCharacterModel = openRouterModels.find(model => model.id === c.model);
    if (cachedCharacterModel) {
        populateModelInfoCard(cachedCharacterModel, '');
        updateReasoningVisibility(cachedCharacterModel.supported_parameters || [], c.model, false, '');
    }
}

function renderLoreList() {
    const list = document.getElementById('lore-list');
    if (!list) return;
    list.innerHTML = '';
    const lorebook = state.editingChar?.lorebook || [];
    lorebook.forEach((entry, idx) => {
        const div = document.createElement('div');
        div.className = 'lore-entry';
        const display_text = entry.text && entry.text.length > 60 ? entry.text.substring(0, 60) + '...' : (entry.text || '');
        const weightClass = entry.weight === 'truth' ? 'truth' : 'knowledge';
        const weightLabel = entry.weight === 'truth' ? '🌍 World Truth' : '🧠 Knowledge';
        div.innerHTML = `
            <div class="lore-entry-text">
                <div class="lore-entry-kw">${escapeHTML(entry.keyword)}</div>
                <div class="lore-entry-preview">${escapeHTML(display_text)}</div>
            </div>
            <span class="lore-entry-weight ${weightClass}">${weightLabel}</span>
            <div class="lore-entry-actions">
                <button class="lore-action-btn edit" title="Edit">✏️</button>
                <button class="lore-action-btn delete" title="Delete">✕</button>
            </div>
        `;
        div.querySelector('.lore-action-btn.edit').onclick = () => window.editLore(idx);
        div.querySelector('.lore-action-btn.delete').onclick = () => window.deleteLore(idx);
        list.appendChild(div);
    });
}

window.editLore = (idx) => {
    const entry = state.editingChar.lorebook[idx];
    document.getElementById('lore-keyword').value = entry.keyword;
    document.getElementById('lore-text').value = entry.text;
    document.getElementById('lore-weight').value = entry.weight || 'knowledge';
    document.getElementById('lore-constant').value = entry.constant ? 'true' : 'false';
    document.getElementById('lore-probability').value = entry.probability || 100;
    state.editingLoreIdx = idx;
    document.getElementById('add-lore-btn').textContent = 'Update Entry';
};

window.deleteLore = async (idx) => {
    state.editingChar.lorebook.splice(idx, 1);
    if (state.editingLoreIdx === idx) {
        state.editingLoreIdx = null;
        document.getElementById('add-lore-btn').textContent = 'Add Entry';
    }
    await autoSaveStudioChanges();
    renderLoreList();
};

async function addLoreEntry() {
    const keyword = document.getElementById('lore-keyword').value.trim();
    const text = document.getElementById('lore-text').value.trim();
    const weight = document.getElementById('lore-weight').value;
    const constant = document.getElementById('lore-constant').value === 'true';
    const probability = Math.max(1, Math.min(100, parseInt(document.getElementById('lore-probability').value) || 100));
    if ((!keyword && !constant) || !text) return; // constant entries need no keyword

    const entry = { keyword, text, weight, constant, probability };

    if (state.editingLoreIdx !== null) {
        state.editingChar.lorebook[state.editingLoreIdx] = entry;
        state.editingLoreIdx = null;
        document.getElementById('add-lore-btn').textContent = 'Add Entry';
    } else {
        state.editingChar.lorebook.push(entry);
    }

    document.getElementById('lore-keyword').value = '';
    document.getElementById('lore-text').value = '';
    document.getElementById('lore-constant').value = 'false';
    document.getElementById('lore-probability').value = '100';
    document.getElementById('add-lore-btn').textContent = 'Add Entry';
    await autoSaveStudioChanges();
    renderLoreList();
}

async function addMemoryBlock() {
    const text = document.getElementById('memory-block-text').value.trim();
    if (!text) return;
    
    const btn = document.getElementById('add-memory-btn');
    btn.textContent = 'Embedding...';
    btn.disabled = true;

    const targetId = state.editingChar?.id;
    try {
        const embedding = await HordeVectorMemory.getCachedEmbedding(text);
        if (!embedding && !HordeVectorMemory.isFallbackActive) {
            throw new Error('Failed to generate vector embedding.');
        }
        if (state.editingChar && state.editingChar.id === targetId) {
            state.editingChar.memory.push(normalizeChatMemoryRecord({
                text, embedding, embeddingNamespace: embedding ? HordeVectorMemory.namespace() : '',
                type: 'biography', scope: 'character', characterIds: [targetId], importance: 0.7
            }));
            document.getElementById('memory-block-text').value = '';
            await autoSaveStudioChanges();
            renderMemoryList();
        }
    } catch (err) {
        showToast('Error generating embedding: ' + err.message, 'error');
    } finally {
        btn.textContent = 'Embed & Add';
        btn.disabled = false;
    }
}

function renderMemoryList() {
    const list = document.getElementById('memory-list');
    list.innerHTML = '';
    state.editingChar.memory.forEach((mem, idx) => {
        const div = document.createElement('div');
        div.className = 'lore-entry';
        div.style.alignItems = 'flex-start';
        const escaped = (mem.text || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        div.innerHTML = `
            <div class="lore-entry-text">
                <div class="memory-entry-full">${escaped}</div>
                <textarea class="form-textarea memory-edit-box" rows="6" style="display:none; margin-top:8px;">${escaped}</textarea>
            </div>
            <div class="lore-entry-actions">
                <button class="lore-action-btn edit" title="Edit">✎</button>
                <button class="lore-action-btn delete" title="Delete">✕</button>
            </div>
        `;
        const editButton = div.querySelector('.lore-action-btn.edit');
        editButton.onclick = () => window.toggleEditMemory(idx, editButton);
        div.querySelector('.lore-action-btn.delete').onclick = () => window.deleteMemory(idx);
        list.appendChild(div);
    });
}

window.toggleEditMemory = async (idx, btn) => {
    const entry = btn.closest('.lore-entry');
    const full = entry.querySelector('.memory-entry-full');
    const box = entry.querySelector('.memory-edit-box');
    const editing = box.style.display !== 'none';

    if (!editing) {
        // Enter edit mode
        full.style.display = 'none';
        box.style.display = 'block';
        box.focus();
        btn.textContent = '✓';
        btn.title = 'Save';
    } else {
        // Save edit + re-embed so vector search stays accurate
        const newText = box.value.trim();
        if (!newText) return showToast('Memory text cannot be empty', 'error');
        state.editingChar.memory[idx].text = newText;
        try {
            state.editingChar.memory[idx].embedding = await getEmbedding(newText);
            state.editingChar.memory[idx].embeddingNamespace = HordeVectorMemory.namespace();
            state.editingChar.memory[idx].updatedAt = Date.now();
        } catch (e) {
            console.warn('Re-embed failed, keeping text only:', e);
            delete state.editingChar.memory[idx].embedding;
        }
        await autoSaveStudioChanges();
        renderMemoryList();
        showToast('Memory updated', 'success');
    }
};

window.deleteMemory = async (idx) => {
    state.editingChar.memory.splice(idx, 1);
    await autoSaveStudioChanges();
    renderMemoryList();
};

window.dismissFallbackBanner = (bannerId) => {
    const banner = document.getElementById(bannerId);
    if (banner) banner.classList.add('hidden');
};

async function saveStudioCharacter() {
    const c = state.editingChar;
    if (!c) {
        showToast('No active character to save', 'error');
        return false;
    }

    const name = document.getElementById('studio-name').value.trim();
    const model = document.getElementById('studio-model').value.trim();
    
    if (!name) { showToast('Character Name is required', 'error'); return false; }
    if (!model) { showToast('Model ID is required', 'error'); return false; }

    c.name = name;
    c.desc = document.getElementById('studio-desc').value.trim();
    
    const mode = document.querySelector('input[name="studio_mode"]:checked').value;
    c.studioMode = mode;
    
    if (mode === 'structured') {
        c.systemPrompt = document.getElementById('studio-system-prompt').value.trim();
        c.personality = document.getElementById('studio-personality').value.trim();
        c.scenario = document.getElementById('studio-scenario').value.trim();
        
        let compiledParts = [];
        if (c.systemPrompt) compiledParts.push(`### SYSTEM RULES\n${c.systemPrompt}`);
        if (c.personality) compiledParts.push(`### PERSONALITY\n${c.personality}`);
        if (c.scenario) compiledParts.push(`### SCENARIO\n${c.scenario}`);
        c.prompt = compiledParts.join('\n\n');
        
        // Also update the advanced textarea so it reflects the compiled prompt if switched back
        document.getElementById('studio-prompt').value = c.prompt;
    } else {
        c.prompt = document.getElementById('studio-prompt').value.trim();
    }

    c.intro = document.getElementById('studio-intro').value.trim();
    c.model = model;
    c.openRouterRouting = readOpenRouterRoutingPanel('character');
    c.tags = document.getElementById('studio-tags').value.split(',').map(t => t.trim()).filter(t => t);
    c.temp = parseFloat(document.getElementById('studio-temp').value) || 0.9;
    c.maxTokens = parseInt(document.getElementById('studio-max-tokens').value) || 2048;
    c.topP = parseFloat(document.getElementById('studio-top-p').value) || 1.0;
    c.topK = parseInt(document.getElementById('studio-top-k').value) || 0;
    c.freqPenalty = parseFloat(document.getElementById('studio-freq-penalty').value) || 0.0;
    c.presPenalty = parseFloat(document.getElementById('studio-pres-penalty').value) || 0.0;
    c.repPenalty = parseFloat(document.getElementById('studio-rep-penalty').value) || 1.0;
    c.minP = parseFloat(document.getElementById('studio-min-p').value) || 0.0;
    c.contextSize = parseInt(document.getElementById('studio-context-size').value) || 8192;
    
    // Reasoning settings
    c.reasoning = document.getElementById('studio-reasoning').checked;
    c.includeReasoning = document.getElementById('studio-include-reasoning').checked;
    c.reasoningEffort = document.getElementById('studio-reasoning-effort').value;
    
    c.activePresetId = document.getElementById('studio-system-preset').value;
    
    // Ensure overrides object exists
    if (!c.presetOverrides) c.presetOverrides = {};

    const hideTop = document.getElementById('studio-hide-top');
    const hideBottom = document.getElementById('studio-hide-bottom');
    if (hideTop) c.hideTopLines = parseInt(hideTop.value) || 0;
    if (hideBottom) c.hideBottomLines = parseInt(hideBottom.value) || 0;

    const anField = document.getElementById('studio-authors-note');
    const anDepth = document.getElementById('studio-authors-note-depth');
    const anFreq = document.getElementById('studio-authors-note-freq');
    if (anField) c.authorsNote = anField.value.trim();
    if (anDepth) c.authorsNoteDepth = parseInt(anDepth.value) || 4;
    if (anFreq) c.authorsNoteFreq = parseInt(anFreq.value) || 1;
    c.chatHud = normalizeChatHudConfig({
        ...c.chatHud,
        enabled: document.getElementById('studio-chat-hud-enabled').checked,
        title: document.getElementById('studio-chat-hud-title').value,
        controller: document.getElementById('studio-chat-hud-controller').value,
        brief: document.getElementById('studio-chat-hud-brief').value,
        allowManual: document.getElementById('studio-chat-hud-manual').checked
    });

    const index = state.characters.findIndex(char => char.id === c.id);
    if (index !== -1) {
        state.characters[index] = JSON.parse(JSON.stringify(c));
    } else {
        state.characters.push(JSON.parse(JSON.stringify(c)));
        // Initialize chat history if intro exists
        if (c.intro) {
            state.chats[c.id] = [{ role: 'assistant', content: c.intro }];
        }
    }

    await saveState();
    showToast('Character Saved!', 'success');
    return true;
}

// --- Persistent RP Memory -------------------------------------------------
// Chat transcripts remain the immutable source of truth. A continuity is a
// derived, portable memory layer that may be shared by several sessions when
// the player explicitly chooses "Continue continuity".
const CHAT_MEMORY_VERSION = 2;
const CHAT_MEMORY_TYPES = new Set(['episode', 'fact', 'relationship', 'state', 'thread', 'biography', 'manual_summary']);
const CHAT_MEMORY_STATUSES = new Set(['active', 'resolved', 'superseded', 'disputed']);
let chatMemoryMigrationDirty = false;

function newChatMemoryId(prefix = 'memory') {
    const uuid = globalThis.crypto?.randomUUID?.();
    return uuid ? `${prefix}_${uuid}` : `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
}

function normalizeMemoryStringList(value, max = 100) {
    return [...new Set((Array.isArray(value) ? value : [])
        .map(item => String(item || '').trim()).filter(Boolean))].slice(0, max);
}

function normalizeChatMemoryRecord(raw, defaults = {}) {
    const source = isPlainObject(raw) ? raw : { text: String(raw || '') };
    const text = String(source.text || source.summary || defaults.text || '').trim().slice(0, 12000);
    const type = CHAT_MEMORY_TYPES.has(source.type) ? source.type
        : CHAT_MEMORY_TYPES.has(defaults.type) ? defaults.type : 'episode';
    const status = CHAT_MEMORY_STATUSES.has(source.status) ? source.status : 'active';
    const createdAt = Math.max(0, Number(source.createdAt) || Number(defaults.createdAt) || Date.now());
    const record = {
        id: String(source.id || defaults.id || newChatMemoryId('memory')).slice(0, 180),
        type,
        key: String(source.key || defaults.key || '').trim().toLocaleLowerCase().replace(/[^\p{L}\p{N}:._-]+/gu, '_').slice(0, 240),
        text,
        scope: ['timeline', 'relationship', 'character', 'canon'].includes(source.scope)
            ? source.scope : (defaults.scope || 'timeline'),
        status,
        importance: Math.max(0, Math.min(1, Number(source.importance ?? defaults.importance ?? 0.55))),
        confidence: Math.max(0, Math.min(1, Number(source.confidence ?? defaults.confidence ?? 0.85))),
        pinned: source.pinned === true,
        continuityId: String(source.continuityId || defaults.continuityId || '').slice(0, 180),
        personaId: String(source.personaId || defaults.personaId || '').slice(0, 180),
        characterIds: normalizeMemoryStringList(source.characterIds || defaults.characterIds),
        witnessedBy: normalizeMemoryStringList(source.witnessedBy || defaults.witnessedBy),
        sourceSessionId: String(source.sourceSessionId || defaults.sourceSessionId || '').slice(0, 180),
        sourceMessageIds: normalizeMemoryStringList(source.sourceMessageIds || defaults.sourceMessageIds, 500),
        startIndex: Number.isFinite(Number(source.startIndex)) ? Math.max(0, Number(source.startIndex)) : defaults.startIndex,
        endIndex: Number.isFinite(Number(source.endIndex)) ? Math.max(0, Number(source.endIndex)) : defaults.endIndex,
        createdAt,
        updatedAt: Math.max(createdAt, Number(source.updatedAt) || createdAt)
    };
    if (Array.isArray(source.embedding) && source.embedding.length) {
        record.embedding = source.embedding;
        record.embeddingNamespace = String(source.embeddingNamespace || defaults.embeddingNamespace || HordeVectorMemory.namespace());
    }
    return record;
}

function chatOwnerId() {
    return state.activeRoomId || state.activeCharId || '';
}

function continuityIdFor(ownerId) {
    return newChatMemoryId(`continuity_${String(ownerId || 'chat').replace(/[^A-Za-z0-9_-]/g, '_')}`);
}

function ensureChatMessageIds(session) {
    if (!session || !Array.isArray(session.messages)) return;
    session.messages.forEach((message, index) => {
        if (!message.id) {
            message.id = `${session.id || 'session'}_message_${index}_${Date.now().toString(36)}`;
            chatMemoryMigrationDirty = true;
        }
    });
}

function ensureChatContinuity(session, ownerId = chatOwnerId()) {
    if (!session) return null;
    if (!isPlainObject(state.chatContinuities)) state.chatContinuities = {};
    if (!session.continuityId) {
        session.continuityId = continuityIdFor(ownerId);
        chatMemoryMigrationDirty = true;
    }
    let continuity = state.chatContinuities[session.continuityId];
    if (!isPlainObject(continuity)) {
        continuity = {
            id: session.continuityId,
            version: CHAT_MEMORY_VERSION,
            ownerId: String(ownerId || ''),
            personaId: String(state.activePersonaId || ''),
            createdAt: Date.now(),
            updatedAt: Date.now(),
            records: []
        };
        state.chatContinuities[session.continuityId] = continuity;
        chatMemoryMigrationDirty = true;
    }
    continuity.version = CHAT_MEMORY_VERSION;
    continuity.ownerId = String(continuity.ownerId || ownerId || '');
    continuity.records = (Array.isArray(continuity.records) ? continuity.records : [])
        .map(record => normalizeChatMemoryRecord(record, { continuityId: continuity.id }))
        .filter(record => record.text);
    return continuity;
}

function repairChatMemoryState() {
    if (!isPlainObject(state.chatContinuities)) state.chatContinuities = {};
    Object.entries(state.chats || {}).forEach(([ownerId, sessions]) => {
        if (!Array.isArray(sessions) || sessions.some(item => item?.role)) return;
        sessions.forEach(session => {
            if (!isPlainObject(session)) return;
            ensureChatMessageIds(session);
            const continuity = ensureChatContinuity(session, ownerId);
            const legacy = Array.isArray(session.episodicMemories) ? session.episodicMemories : [];
            legacy.forEach((memory, index) => {
                const text = String(memory?.text || memory || '').trim();
                if (!text) return;
                const record = normalizeChatMemoryRecord(memory, {
                    id: `legacy_${HordeVectorMemory.hashText(text)}_${memory?.startIndex ?? index}`,
                    type: 'episode',
                    continuityId: continuity.id,
                    sourceSessionId: session.id,
                    startIndex: memory?.startIndex,
                    endIndex: memory?.endIndex
                });
                if (!continuity.records.some(existing => existing.id === record.id)) continuity.records.push(record);
            });
            // The continuity record is now authoritative. Do not keep a second
            // copy of every high-dimensional vector inside the transcript key.
            if (legacy.length) {
                session.episodicMemories = [];
                chatMemoryMigrationDirty = true;
            }
            if (session.memoryVersion !== CHAT_MEMORY_VERSION) {
                session.memoryVersion = CHAT_MEMORY_VERSION;
                chatMemoryMigrationDirty = true;
            }
        });
    });
}

function getSessionForOwner(ownerId) {
    const sessions = Array.isArray(state.chats?.[ownerId]) ? state.chats[ownerId] : [];
    return sessions.find(session => session.id === state.activeSessionId?.[ownerId]) || sessions[0] || null;
}

function cloneChatContinuity(source, ownerId) {
    const id = continuityIdFor(ownerId);
    const now = Date.now();
    const clone = {
        id,
        version: CHAT_MEMORY_VERSION,
        ownerId: String(ownerId || source?.ownerId || ''),
        personaId: String(state.activePersonaId || source?.personaId || ''),
        createdAt: now,
        updatedAt: now,
        forkedFrom: String(source?.id || ''),
        records: (source?.records || []).filter(record => record.status !== 'superseded').map(record => ({
            ...safeJsonClone(record), id: newChatMemoryId('memory'), continuityId: id, updatedAt: now
        }))
    };
    state.chatContinuities[id] = clone;
    return clone;
}

function upsertContinuityMemoryRecords(continuity, inputs, defaults = {}) {
    if (!continuity) return [];
    const inserted = [];
    continuity.records = Array.isArray(continuity.records) ? continuity.records : [];
    for (const input of inputs || []) {
        const record = normalizeChatMemoryRecord(input, { ...defaults, continuityId: continuity.id });
        if (!record.text) continue;
        const duplicate = continuity.records.find(existing =>
            existing.id === record.id
            || (existing.sourceSessionId === record.sourceSessionId
                && existing.startIndex === record.startIndex && existing.endIndex === record.endIndex
                && memoryDedupeKey(existing) === memoryDedupeKey(record)));
        if (duplicate) continue;

        if (record.key && ['fact', 'relationship', 'state', 'thread'].includes(record.type)) {
            continuity.records.forEach(existing => {
                if (existing.status === 'active' && existing.type === record.type && existing.key === record.key) {
                    existing.status = 'superseded';
                    existing.updatedAt = record.updatedAt;
                }
            });
        }
        continuity.records.push(record);
        inserted.push(record);
    }
    continuity.updatedAt = Date.now();
    return inserted;
}

async function hydrateChatMemoryEmbedding(record) {
    if (!record?.text) return record;
    const embedding = await HordeVectorMemory.getCachedEmbedding(record.text);
    if (embedding) {
        record.embedding = embedding;
        record.embeddingNamespace = HordeVectorMemory.namespace();
        record.updatedAt = Date.now();
    }
    return record;
}

function invalidateMemoryEmbeddingsForNamespaceChange(previousNamespace) {
    const nextNamespace = HordeVectorMemory.namespace();
    if (!previousNamespace || previousNamespace === nextNamespace) return 0;
    let cleared = 0;
    const clearRecord = record => {
        if (!record || !record.embedding) return;
        delete record.embedding;
        delete record.embeddingNamespace;
        cleared++;
    };
    (state.characters || []).forEach(character => (character.memory || []).forEach(clearRecord));
    Object.values(state.chatContinuities || {}).forEach(continuity => (continuity.records || []).forEach(clearRecord));
    Object.values(state.worldInstances || {}).forEach(instance =>
        (instance.sessions || []).forEach(session => (session.episodicMemories || []).forEach(clearRecord)));
    HordeVectorMemory.cache.clear();
    HordeVectorMemory.scheduleCacheSave();
    return cleared;
}

function chatMemoryVisibleTo(record, targetChar, isRoom) {
    if (!record || record.status === 'superseded') return false;
    const personaId = String(state.activePersonaId || '');
    if (record.scope === 'relationship' && record.personaId && personaId && record.personaId !== personaId) return false;
    if (!isRoom || !targetChar) return true;
    const witnesses = normalizeMemoryStringList(record.witnessedBy);
    if (witnesses.length) {
        const name = String(targetChar.name || '').toLocaleLowerCase();
        return witnesses.some(value => value === targetChar.id || value.toLocaleLowerCase() === name);
    }
    if (record.type === 'episode') return String(record.text || '').toLocaleLowerCase().includes(String(targetChar.name || '').toLocaleLowerCase());
    return record.scope === 'canon';
}

function chatMemoryQuery(messages, userText, config, targetChar) {
    const recent = (messages || []).slice(-6).map(message => canonicalMsgText(message)).join('\n');
    const participants = state.activeRoomId ? getRoomCharacters(config).map(character => character.name).join(', ') : targetChar?.name || '';
    return `${userText || ''}\n${recent}\nParticipants: ${participants}`.slice(-12000);
}

function memoryTextWithinBudget(records, tokenBudget) {
    let remainingChars = Math.max(0, Math.floor(tokenBudget * 3.5));
    const parts = [];
    for (const record of records || []) {
        const label = String(record.type || 'memory').replace('_', ' ').toUpperCase();
        const line = `[${label}${record.status === 'resolved' ? ' · RESOLVED' : ''}] ${String(record.text || '').trim()}`;
        if (!line.trim() || remainingChars < 40) break;
        const fitted = line.length <= remainingChars ? line : trimToLastSentence(line.slice(0, remainingChars));
        parts.push(fitted);
        remainingChars -= fitted.length + 2;
    }
    return parts.join('\n\n');
}

function recordImmediateChatMemory(session, config, text, targetChar) {
    if (!session?.messages || !text) return null;
    const continuity = ensureChatContinuity(session, config?.id || chatOwnerId());
    const source = session.messages.slice(-2);
    const [record] = upsertContinuityMemoryRecords(continuity, [{
        type: 'episode',
        key: `milestone:${HordeVectorMemory.hashText(text)}`,
        text,
        importance: 0.82,
        scope: 'timeline',
        characterIds: targetChar?.id ? [targetChar.id] : [],
        witnessedBy: targetChar?.id ? [targetChar.id] : [],
        sourceSessionId: session.id,
        sourceMessageIds: source.map(message => message.id).filter(Boolean)
    }], { personaId: state.activePersonaId || '' });
    if (record) hydrateChatMemoryEmbedding(record)
        .then(() => HordeDB.set('chatContinuities', state.chatContinuities))
        .catch(error => console.warn('Immediate memory embedding failed:', error));
    return record || null;
}

// --- Chat View Logic ---
function setupChatLogic() {
    const sendBtn = document.getElementById('send-btn');
    const userInput = document.getElementById('user-input');

    userInput.oninput = () => {
        userInput.style.height = 'auto';
        userInput.style.height = userInput.scrollHeight + 'px';
        sendBtn.disabled = !userInput.value.trim() || (!state.activeCharId && !state.activeRoomId);
    };

    sendBtn.onclick = () => {
        if (generationController) {
            generationController.abort();
        } else {
            handleChat();
        }
    };

    document.getElementById('reroll-chat-btn').onclick = () => {
        if (generationController) return showToast('Please wait for current generation to finish or stop it.', 'info');
        handleChat(true);
    };

    // ⏩ Continue: AI writes the next message with no user turn in between.
    document.getElementById('continue-chat-btn').onclick = async () => {
        if (generationController) return showToast('Please wait for current generation to finish or stop it.', 'info');
        const session = getCurrentSession();
        if (!session || !session.messages || !session.messages.length) return showToast('Nothing to continue yet.', 'info');
        // In rooms, continue as the character who spoke last
        let contCharId = null;
        if (state.activeRoomId) {
            const lastAi = [...session.messages].reverse().find(m => m.role === 'assistant' && m.charId);
            if (!lastAi) return showToast('Pick a character to speak first.', 'info');
            contCharId = lastAi.charId;
        }
        // Stash any half-typed draft so handleChat's empty-input path is used
        const stash = userInput.value;
        userInput.value = '';
        await handleChat(false, contCharId);
        if (stash && !userInput.value) userInput.value = stash;
    };

    // ✍️ Impersonate: AI drafts the USER's next message into the input box.
    document.getElementById('impersonate-btn').onclick = impersonateUser;

    userInput.onkeydown = (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            if (generationController) return;
            handleChat();
        }
    };

    document.getElementById('clear-history-btn').onclick = () => {
        showConfirmModal('Clear History', 'Are you sure you want to clear the chat history for this session?', async () => {
            const sessionId = state.activeRoomId || state.activeCharId;
            const currentSessId = state.activeSessionId[sessionId];
            
            // Delete the current session
            state.chats[sessionId] = state.chats[sessionId].filter(s => s.id !== currentSessId);
            
            // Re-create a fresh session (this handles intro automatically)
            if (state.chats[sessionId].length === 0) {
                await createNewSession('fresh');
            } else {
                state.activeSessionId[sessionId] = state.chats[sessionId][0].id;
                await saveState();
                renderChat();
            }
            showToast('History Cleared', 'info');
        });
    };
    
    document.getElementById('roll-dice-btn').onclick = async () => {
        const session = getCurrentSession();
        if (!session) return;
        const roll = Math.floor(Math.random() * 6) + 1;
        const rollMsg = `*You rolled a ${roll} on a 6-sided dice.*`;
        session.messages.push({ id: newChatMemoryId('message'), role: 'user', content: rollMsg });
        await saveState();
        appendMessageUI('user', rollMsg);
    };
    
    document.getElementById('download-chat-btn').onclick = () => {
        const session = getCurrentSession();
        if (!session || !session.messages || session.messages.length === 0) {
            return showToast('No history to export.', 'info');
        }
        
        let config = null;
        if (state.activeRoomId) {
            config = state.rooms.find(r => r.id === state.activeRoomId);
        } else {
            config = state.characters.find(c => c.id === state.activeCharId);
        }
        
        const title = config ? config.name : 'Horde_Chat';
        let transcript = `Transcript: ${title}\nSession: ${session.name}\nGenerated by Horde Studio\n\n`;
        
        session.messages.forEach(m => {
            let speaker = 'User';
            if (m.role === 'assistant') speaker = config ? config.name : 'AI';
            if (m.role === 'system') speaker = 'System';
            transcript += `--- ${speaker} ---\n${m.content}\n\n`;
        });
        
        const blob = new Blob([transcript], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${title.replace(/[^a-zA-Z0-9]/g, '_')}_Transcript.txt`;
        a.click();
        URL.revokeObjectURL(url);
    };

    document.getElementById('summarize-chat-btn').onclick = summarizeStory;
    // (summarize-memory-btn is wired in setupStudioLogic — it lives in the Studio memory tab)
    document.getElementById('new-session-btn').onclick = () => createNewSession();
    document.getElementById('rename-session-btn').onclick = renameCurrentSession;
    document.getElementById('session-select').onchange = async (e) => {
        const id = state.activeRoomId || state.activeCharId;
        state.activeSessionId[id] = e.target.value;
        await saveState();
        renderChat();
    };

    const toggleBtn = document.getElementById('toggle-headers-btn');
    if (toggleBtn) {
        toggleBtn.onclick = () => {
            const msgCont = document.getElementById('messages-container');
            if (msgCont) msgCont.classList.toggle('show-headers');
        };
    }
    document.getElementById('toggle-chat-hud-btn').onclick = async () => {
        const session = getCurrentSession();
        if (!session) return;
        session.chatHudCollapsed = session.chatHudCollapsed !== true;
        await saveState();
        renderChat();
    };
}

function getCurrentSession() {
    const id = state.activeRoomId || state.activeCharId;
    if (!id) return null;
    if (!state.chats[id]) state.chats[id] = [];
    
    // Migration/Setup: Ensure at least one session exists
    if (!Array.isArray(state.chats[id])) {
        // Fix for legacy data if needed
        state.chats[id] = []; 
    }
    
    if (state.chats[id].length === 0 || typeof state.chats[id][0] === 'string' || state.chats[id][0].role) {
        // This should have been handled by migration, but as a safeguard:
        let oldMsgs = Array.isArray(state.chats[id]) && state.chats[id][0]?.role ? state.chats[id] : [];
        
        state.chats[id] = [{ id: 'session_' + Date.now(), name: 'Default Session', messages: oldMsgs }];
        state.activeSessionId[id] = state.chats[id][0].id;
    }

    const sessionId = state.activeSessionId[id];
    let session = state.chats[id].find(s => s.id === sessionId);
    if (!session) {
        session = state.chats[id][0];
        state.activeSessionId[id] = session.id;
    }

    // Ensure intro message if history is empty and it's a character chat
    if (session && session.messages.length === 0 && state.activeCharId === id) {
        const char = state.characters.find(c => c.id === id);
        if (char && char.intro) {
            session.messages.push(characterGreetingMessage(char));
        }
    }

    if (session) {
        ensureChatMessageIds(session);
        ensureChatContinuity(session, id);
    }

    return session;
}

async function createNewSession(requestedMode = '') {
    const id = state.activeRoomId || state.activeCharId;
    if (!id) return;
    if (!Array.isArray(state.chats[id])) state.chats[id] = [];
    const previous = getSessionForOwner(id);
    const modeSelect = document.getElementById('new-session-continuity-mode');
    const mode = ['continue', 'fork', 'fresh'].includes(requestedMode)
        ? requestedMode : (modeSelect?.value || 'continue');
    let continuityId = continuityIdFor(id);
    if (previous && mode === 'continue') {
        continuityId = ensureChatContinuity(previous, id).id;
    } else if (previous && mode === 'fork') {
        continuityId = cloneChatContinuity(ensureChatContinuity(previous, id), id).id;
    }
    const newSess = {
        id: 'session_' + Date.now(),
        name: 'New Session ' + (state.chats[id].length + 1),
        messages: [],
        continuityId,
        memoryVersion: CHAT_MEMORY_VERSION,
        lastConsolidatedIndex: 0
    };
    
    // If it's a character (not a room), add the intro message
    if (state.activeCharId) {
        const char = state.characters.find(c => c.id === state.activeCharId);
        if (char && char.intro) {
            newSess.messages.push(characterGreetingMessage(char));
        }
    }
    
    state.chats[id].push(newSess);
    ensureChatContinuity(newSess, id);
    state.activeSessionId[id] = newSess.id;
    await saveState();
    renderChat();
    const continuityLabel = mode === 'fresh' ? 'fresh continuity' : mode === 'fork' ? 'forked continuity' : 'shared continuity';
    showToast(`New session started · ${continuityLabel}`);
}

function characterGreetingMessage(char) {
    const seen = new Set();
    const versions = [char?.intro, ...(Array.isArray(char?.alternateGreetings) ? char.alternateGreetings : [])]
        .map(value => String(value || '').trim())
        .filter(value => value && !seen.has(value) && seen.add(value));
    const content = versions[0] || '';
    return {
        id: newChatMemoryId('message'),
        role: 'assistant',
        content,
        charId: char?.id,
        versions: versions.length > 1 ? versions : undefined,
        currentVersion: versions.length > 1 ? 0 : undefined
    };
}

async function renameCurrentSession() {
    const session = getCurrentSession();
    if (!session) return;
    
    const newName = prompt('Enter new session name:', session.name);
    if (newName && newName.trim()) {
        session.name = newName.trim();
        await saveState();
        renderChat();
    }
}

function renderChatHud(character, session) {
    const aside = document.getElementById('chat-status-col');
    const toggle = document.getElementById('toggle-chat-hud-btn');
    const { config, state: hudState } = ensureChatHudState(character, session);
    const visible = !!character && config.enabled && config.meters.length > 0;
    toggle.classList.toggle('hidden', !visible);
    aside.classList.toggle('hidden', !visible || session?.chatHudCollapsed === true);
    if (!visible) return;
    document.getElementById('chat-hud-title').textContent = config.title;
    document.getElementById('chat-hud-controller').textContent = ({ manual: 'Manual', main: 'Main model', labs: 'Labs' })[config.controller];
    const summary = document.getElementById('chat-hud-summary');
    summary.textContent = hudState.status;
    summary.classList.toggle('hidden', !hudState.status);
    document.getElementById('chat-hud-note').textContent = config.controller === 'labs'
        ? 'Local cognition proposes updates; validation and meter bounds remain deterministic.'
        : config.controller === 'main' ? 'The main chat model updates this private HUD after its reply.'
        : 'Values change only when you adjust them.';
    document.getElementById('chat-hud-meters').innerHTML = config.meters.map(meter => {
        const value = hudState.values[meter.id];
        const percent = Math.max(0, Math.min(100, (value - meter.min) / (meter.max - meter.min) * 100));
        return `<article class="chat-hud-meter" style="--hud-meter-color:${escapeHTML(meter.color)};--hud-fill:${percent}%">
            <div class="chat-hud-meter-top"><span>${escapeHTML(meter.label)}</span><span class="chat-hud-meter-value">${value} / ${meter.max}</span></div>
            <div class="chat-hud-track"><div class="chat-hud-fill"></div></div>
            ${config.allowManual ? `<div class="chat-hud-meter-controls"><button data-hud-adjust="${escapeHTML(meter.id)}" data-delta="-1" type="button">−</button><button data-hud-adjust="${escapeHTML(meter.id)}" data-delta="1" type="button">+</button></div>` : ''}
        </article>`;
    }).join('');
    aside.querySelectorAll('[data-hud-adjust]').forEach(button => button.onclick = async () => {
        const definition = config.meters.find(meter => meter.id === button.dataset.hudAdjust);
        if (!definition) return;
        const step = Math.max(1, Math.round((definition.max - definition.min) / 20));
        applyChatHudUpdate(character, session, { meters: [{ id: definition.id, value: hudState.values[definition.id] + Number(button.dataset.delta) * step }] }, 'manual');
        await saveState(); renderChatHud(character, session);
    });
}

function renderChat() {
    const sessionId = state.activeRoomId || state.activeCharId;
    let name = '';
    let modelName = '';
    let avatar = '';
    let bg = '';
    
    const routingBar = document.getElementById('chat-routing-bar');
    routingBar.innerHTML = '';
    
    if (state.activeRoomId) {
        const room = state.rooms.find(r => r.id === state.activeRoomId);
        if (!room) return;
        name = room.name;
        modelName = (room.model || '').split('/').pop() || 'Unknown Model';
        avatar = room.avatar || '';
        bg = room.bg || '';
        
        document.getElementById('open-in-studio-btn').innerHTML = '⚙️ Edit Room';

        
        routingBar.style.display = 'flex';
        room.characterIds.forEach(cid => {
            const c = state.characters.find(x => x.id === cid);
            if(!c) return;
            const btn = document.createElement('button');
            btn.className = 'routing-btn';
            btn.innerHTML = `<div class="routing-btn-avatar" style="background-image:url('${cssUrl(c.avatar)}')"></div>${escapeHTML(c.name)}`;
            btn.onclick = () => handleChat(false, c.id);
            routingBar.appendChild(btn);
        });
    } else {
        const char = state.characters.find(c => c.id === state.activeCharId);
        if (!char) return;
        name = char.name;
        modelName = (char.model || 'Unknown').split('/').pop();
        avatar = char.avatar;
        bg = char.bg;
        routingBar.style.display = 'none';
        
        document.getElementById('open-in-studio-btn').innerHTML = 'Studio →';
    }

    const chatAvatar = document.getElementById('chat-avatar');
    chatAvatar.style.backgroundImage = avatar ? `url('${cssUrl(avatar)}')` : 'none';
    chatAvatar.textContent = avatar ? '' : displayInitials(name);
    chatAvatar.classList.toggle('has-image', !!avatar);
    chatAvatar.style.display = 'grid';
    document.getElementById('chat-char-name').textContent = name;
    document.getElementById('chat-char-model').textContent = modelName;
    
    document.getElementById('chat-view').style.backgroundImage = bg ? `linear-gradient(rgba(10,10,15,0.8), rgba(10,10,15,0.8)), url('${cssUrl(bg)}')` : 'none';
    document.getElementById('chat-view').style.backgroundSize = 'cover';

    const msgContainer = document.getElementById('messages-container');
    const wasAtBottom = msgContainer.scrollHeight - msgContainer.scrollTop <= msgContainer.clientHeight + 50;
    const oldScrollTop = msgContainer.scrollTop;

    msgContainer.innerHTML = '';
    
    const session = getCurrentSession();
    const messages = session ? session.messages : [];
    renderChatHud(state.activeRoomId ? null : state.characters.find(c => c.id === state.activeCharId), session);
    
    // Update Session Selector
    const sessSelect = document.getElementById('session-select');
    sessSelect.innerHTML = '';
    (state.chats[sessionId] || []).forEach(s => {
        const opt = document.createElement('option');
        opt.value = s.id;
        opt.textContent = s.name;
        opt.selected = s.id === (session ? session.id : null);
        sessSelect.appendChild(opt);
    });

    if (Array.isArray(messages)) {
        messages.forEach((msg, idx) => {
            if (msg && msg.role && msg.content !== undefined) {
                appendMessageUI(msg.role === 'assistant' ? 'ai' : msg.role, msg.content, idx, msg.charId);
            }
        });
    }
    
    if (wasAtBottom) {
        msgContainer.scrollTop = msgContainer.scrollHeight;
    } else {
        msgContainer.scrollTop = oldScrollTop;
    }
}

// --- Horde Elite Markdown Parser ---
function escapeHTML(str) {
    return String(str ?? '').replace(/[&<>"']/g, m => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[m]));
}

/**
 * Sanitize a user/imported image URL for embedding inside a CSS url('...')
 * or the style attribute. Strips characters that could break out of the
 * quoting/paren and blocks script-executing schemes. Safe for data: URLs
 * (base64 alphabet has none of these chars) and normal http(s) URLs.
 */
function cssUrl(url) {
    if (!url) return '';
    const cleaned = String(url).replace(/["'()\\<>\n\r]/g, '');
    if (/^\s*(javascript|vbscript):/i.test(cleaned)) return '';
    return cleaned;
}

function cssColor(value, fallback = 'var(--accent)') {
    const color = String(value || '').trim();
    if (/^#(?:[0-9A-Fa-f]{3}|[0-9A-Fa-f]{4}|[0-9A-Fa-f]{6}|[0-9A-Fa-f]{8})$/.test(color)) return color;
    if (/^var\(--[A-Za-z0-9-]+\)$/.test(color)) return color;
    if (/^(?:rgb|rgba|hsl|hsla)\([0-9.,%+\-\s]+\)$/i.test(color)) return color;
    if (/^[A-Za-z]{1,30}$/.test(color)) return color;
    return fallback;
}

function displayInitials(name, fallback = '?') {
    return (String(name || fallback).trim().match(/\b[\p{L}\p{N}]/gu) || [fallback])
        .slice(0, 2).join('').toUpperCase();
}

let accessibilityObserver = null;
let focusBeforeModal = null;

function enhanceAccessibility(root = document) {
    const scope = root.nodeType === Node.ELEMENT_NODE ? root : document;
    const includeRoot = (selector) => scope.nodeType === Node.ELEMENT_NODE && scope.matches(selector) ? [scope] : [];
    const controlSelector = 'input, select, textarea';
    const assignLabel = (label, control) => {
        if (!label || !control) return;
        if (!control.id) control.id = `labeled-control-${Math.random().toString(36).slice(2, 10)}`;
        if (label.tagName === 'LABEL') {
            label.htmlFor = control.id;
            return;
        }
        // Legacy studio markup often uses a visual .form-label div. The htmlFor
        // property has no accessibility meaning on a div, so connect it with
        // aria-labelledby instead of leaving the control unnamed.
        if (!label.id) label.id = `${control.id}-label`;
        if (!control.getAttribute('aria-label') && !control.getAttribute('aria-labelledby')) {
            control.setAttribute('aria-labelledby', label.id);
        }
    };

    [...includeRoot('label'), ...(scope.querySelectorAll?.('label') || [])].forEach(label => {
        const nestedControl = label.querySelector(controlSelector);
        if (nestedControl) {
            assignLabel(label, nestedControl);
            return;
        }

        // Most studio fields use a visual label immediately followed by one control.
        // Associate those explicitly, but avoid broad section headings that precede
        // a grid containing several unrelated controls.
        const next = label.nextElementSibling;
        if (!next) return;
        const candidates = next.matches(controlSelector)
            ? [next]
            : [...next.querySelectorAll(controlSelector)];
        if (candidates.length === 1) assignLabel(label, candidates[0]);
    });

    [...includeRoot(controlSelector), ...(scope.querySelectorAll?.(controlSelector) || [])].forEach(control => {
        if (control.getAttribute('aria-label') || control.getAttribute('aria-labelledby')) return;
        if (control.id && document.querySelector(`label[for="${CSS.escape(control.id)}"]`)) return;
        const precedingLabel = control.previousElementSibling?.matches('label, .form-label')
            ? control.previousElementSibling
            : null;
        if (precedingLabel) {
            assignLabel(precedingLabel, control);
            return;
        }
        const sectionLabel = control.closest('.form-section, .form-col, .form-row > div')?.querySelector('.form-label, label');
        const readableId = (control.id || control.name || '').replace(/[-_]+/g, ' ').trim();
        control.setAttribute('aria-label', (sectionLabel?.textContent || control.placeholder || readableId || 'Input').trim());
    });

    [...includeRoot('.modal-bg, .modal-overlay'), ...(scope.querySelectorAll?.('.modal-bg, .modal-overlay') || [])].forEach(overlay => {
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');
        const title = overlay.querySelector('h1, h2, h3, .modal-title-sm');
        if (title) {
            if (!title.id) title.id = `${overlay.id || 'dialog'}-title`;
            overlay.setAttribute('aria-labelledby', title.id);
        } else {
            overlay.setAttribute('aria-label', 'Dialog');
        }
    });

    [...includeRoot('.char-card, .tag-pill, .persona-list-item, .reroll-nav-btn'), ...(scope.querySelectorAll?.('.char-card, .tag-pill, .persona-list-item, .reroll-nav-btn') || [])].forEach(element => {
        if (element.matches('button, a, input, select, textarea')) return;
        element.setAttribute('role', 'button');
        element.tabIndex = 0;
    });
}

function getVisibleDialog() {
    const visible = [...document.querySelectorAll('.modal-bg, .modal-overlay')]
        .filter(dialog => !dialog.classList.contains('hidden') && getComputedStyle(dialog).display !== 'none');
    if (!visible.length) return null;
    // Stacked dialogs: the visual editor opens above the record inspector
    // even though the inspector sits later in the DOM. The layer that owns
    // focus wins first; otherwise the topmost painted layer (highest
    // z-index, DOM order breaking ties) — never raw DOM order, which put
    // the layer underneath in charge and yanked focus out of the top one.
    const active = document.activeElement;
    const owning = visible.find(dialog => dialog.contains(active));
    if (owning) return owning;
    const zIndex = dialog => {
        const value = parseInt(getComputedStyle(dialog).zIndex, 10);
        return Number.isFinite(value) ? value : 0;
    };
    return visible.reduce((top, dialog) =>
        zIndex(dialog) > zIndex(top) || (zIndex(dialog) === zIndex(top)
            && !!(top.compareDocumentPosition(dialog) & Node.DOCUMENT_POSITION_FOLLOWING))
            ? dialog : top);
}

function setupAccessibility() {
    enhanceAccessibility();
    if (!accessibilityObserver) {
        accessibilityObserver = new MutationObserver(records => {
            records.forEach(record => record.addedNodes.forEach(node => {
                if (node.nodeType === Node.ELEMENT_NODE) enhanceAccessibility(node);
            }));
        });
        accessibilityObserver.observe(document.body, { childList: true, subtree: true });
    }

    document.addEventListener('click', () => {
        setTimeout(() => {
            const dialog = getVisibleDialog();
            if (!dialog || dialog.contains(document.activeElement)) return;
            focusBeforeModal = document.activeElement;
            const first = dialog.querySelector('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex="0"]');
            first?.focus();
        }, 0);
    }, true);

    document.addEventListener('keydown', event => {
        const interactive = event.target.closest?.('[role="button"]');
        if (interactive && (event.key === 'Enter' || event.key === ' ')) {
            event.preventDefault();
            interactive.click();
            return;
        }

        const dialog = getVisibleDialog();
        if (!dialog) return;
        if (event.key === 'Escape') {
            event.preventDefault();
            const close = dialog.querySelector('.modal-close, [id^="close-"], [id^="cancel-"]');
            if (close) close.click(); else dialog.classList.add('hidden');
            focusBeforeModal?.focus?.();
            return;
        }
        if (event.key !== 'Tab') return;
        const focusable = [...dialog.querySelectorAll('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex="0"]')]
            .filter(element => getComputedStyle(element).display !== 'none');
        if (!focusable.length) return;
        const first = focusable[0];
        const last = focusable[focusable.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    });
}

function parseHordeMarkdown(text) {
    if (!text) return '';

    // Some presets (e.g. Freaky Frankenstein's "Narrative Drive & Tracking")
    // make the model append a planning block — <details>Plot Momentum…</details>
    // or <plot_tracking_module>…</plot_tracking_module> — meant to be a HIDDEN,
    // collapsible aside it re-reads next turn. Pull these out before escaping so
    // they render as a tidy collapsed disclosure instead of a wall of raw markup.
    // (Left intact in the stored message, so the model's cross-turn planning still works.)
    const scaffolds = [];
    let working = text.replace(
        /<details(?:\s[^>]*)?>[\s\S]*?(?:<\/details>|$)|<(plot_tracking_module|thinking|reasoning|cot|planning)>[\s\S]*?(?:<\/\1>|$)/gi,
        m => { scaffolds.push(m); return `S${scaffolds.length - 1}`; }
    );

    let safe = escapeHTML(working)
                   .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
                   .replace(/\*(.*?)\*/g, '<em>$1</em>')
                   .replace(/&quot;(.*?)&quot;/g, '<span class="dialogue">&quot;$1&quot;</span>')
                   .replace(/“([^”]*)”/g, '<span class="dialogue">“$1”</span>')
                   .replace(/\n/g, '<br>');

    // Re-insert each captured block as a collapsed "Director's Notes" disclosure
    safe = safe.replace(/S(\d+)/g, (m, i) => {
        const raw = scaffolds[+i] || '';
        const sum = raw.match(/<summary>([\s\S]*?)<\/summary>/i);
        const title = (sum ? sum[1] : 'Director’s Notes').replace(/[<>]/g, '').trim() || 'Director’s Notes';
        const inner = raw
            .replace(/<\/?details(?:\s[^>]*)?>/gi, '')
            .replace(/<summary>[\s\S]*?<\/summary>/gi, '')
            .replace(/<\/?(plot_tracking_module|thinking|reasoning|cot|planning)>/gi, '')
            .trim();
        return `<details class="rp-scaffold"><summary>🎬 ${escapeHTML(title)}</summary><div class="rp-scaffold-body">${escapeHTML(inner).replace(/\n/g, '<br>')}</div></details>`;
    });
    return safe;
}

function extractDirectorNotes(text) {
    if (!text) return '';
    const source = String(text);
    const details = [...source.matchAll(/<details(?:\s[^>]*)?>[\s\S]*?(?:<\/details>|$)/gi)]
        .map(match => match[0])
        .reverse()
        .find(block => /<summary>\s*(?:🎬\s*)?Plot Momentum\s*<\/summary>/i.test(block));
    if (details) return details.slice(0, 5000);
    const tracked = source.match(/<plot_tracking_module\b[^>]*>[\s\S]*?(?:<\/plot_tracking_module>|$)/i);
    return tracked ? tracked[0].slice(0, 5000) : '';
}

function formatMessageContent(content, role, isStreaming = false) {
    if (!content) return isStreaming ? '<div class="typing-indicator"><div class="typing-dot"></div><div class="typing-dot"></div><div class="typing-dot"></div></div>' : '';
    if (role !== 'ai') return parseHordeMarkdown(content);
    
    const char = state.characters.find(c => c.id === state.activeCharId);
    if (!char) return parseHordeMarkdown(content);

    const top = char.hideTopLines || 0;
    const bottom = char.hideBottomLines || 0;

    if (top === 0 && bottom === 0) {
        let out = parseHordeMarkdown(content);
        if (isStreaming) out += ' <div class="typing-indicator"><div class="typing-dot"></div><div class="typing-dot"></div><div class="typing-dot"></div></div>';
        return out;
    }

    const lines = content.split('\n');
    if (top + bottom >= lines.length) {
        let out = parseHordeMarkdown(content);
        if (isStreaming) out += ' <div class="typing-indicator"><div class="typing-dot"></div><div class="typing-dot"></div><div class="typing-dot"></div></div>';
        return out;
    }

    const topLines = lines.slice(0, top).join('\n');
    const midLines = lines.slice(top, lines.length - bottom).join('\n');
    const bottomLines = lines.slice(lines.length - bottom).join('\n');
    
    let out = `<div class="hidden-header">${parseHordeMarkdown(topLines)}</div>` + 
              parseHordeMarkdown(midLines) + 
              `<div class="hidden-header">${parseHordeMarkdown(bottomLines)}</div>`;
              
    if (isStreaming) out += ' <div class="typing-indicator"><div class="typing-dot"></div><div class="typing-dot"></div><div class="typing-dot"></div></div>';
    return out;
}

function appendMessageUI(role, content, index = null, charId = null, isStreaming = false) {
    const msgContainer = document.getElementById('messages-container');
    const div = document.createElement('div');
    div.className = `message ${role}`;
    
    let avatarUrl = '';
    let avatarName = role === 'user' ? 'You' : 'AI';
    if (role === 'user') {
        const persona = state.personas.find(p => p.id === state.activePersonaId);
        if (persona?.name) avatarName = persona.name;
        if (persona && persona.avatar) avatarUrl = persona.avatar;
    } else {
        const cId = charId || state.activeCharId;
        const char = state.characters.find(c => c.id === cId);
        if (char?.name) avatarName = char.name;
        if (char && char.avatar) avatarUrl = char.avatar;
    }
    
    // Reroll version navigation (parity with world mode)
    const sessionRef = index !== null ? getCurrentSession() : null;
    const msgRef = sessionRef ? sessionRef.messages[index] : null;
    const hasVersions = msgRef && Array.isArray(msgRef.versions) && msgRef.versions.length > 1;
    const verIdx = hasVersions ? (msgRef.currentVersion ?? msgRef.versions.length - 1) : 0;

    div.innerHTML = `
        <div class="message-avatar${avatarUrl ? ' has-image' : ''}" style="${avatarUrl ? `background-image:url('${cssUrl(avatarUrl)}')` : ''}" aria-hidden="true">${avatarUrl ? '' : escapeHTML(displayInitials(avatarName))}</div>
        <div class="message-body">
            <div class="message-content">${formatMessageContent(content, role, isStreaming)}</div>
            <textarea class="message-edit-area hidden"></textarea>
            <div class="message-actions">
                ${hasVersions ? `
                <button class="msg-action-btn ver-prev" title="Previous take">←</button>
                <span class="msg-action-btn" style="cursor:default; opacity:0.7;">${verIdx + 1}/${msgRef.versions.length}</span>
                <button class="msg-action-btn ver-next" title="Next take">→</button>
                ` : ''}
                ${index !== null ? `
                <button class="msg-action-btn edit-msg" title="Edit text">✎ Edit</button>
                <button class="msg-action-btn del-msg" title="Delete message">❌ Delete</button>
                ` : ''}
            </div>
        </div>
    `;

    if (hasVersions) {
        const setVersion = async (i) => {
            const clamped = Math.max(0, Math.min(msgRef.versions.length - 1, i));
            if (clamped === verIdx) return;
            msgRef.currentVersion = clamped;
            msgRef.content = msgRef.versions[clamped]; // keep canonical content in sync for context building
            // Swap the chronicle entry to the take being viewed — the ledger
            // must always describe the canonical timeline, not the last take
            if (Array.isArray(msgRef.versionLedgerEntries)) {
                stripChatLedgerEntry(sessionRef, msgRef);
                const entry = msgRef.versionLedgerEntries[clamped] || null;
                if (entry) {
                    appendWorldLedgerEntry(sessionRef, entry);
                    msgRef.ledgerEntry = entry;
                } else {
                    delete msgRef.ledgerEntry;
                }
            }
            invalidateEpisodicFrom(sessionRef, index);
            await saveState();
            renderChat();
        };
        div.querySelector('.ver-prev').onclick = () => setVersion(verIdx - 1);
        div.querySelector('.ver-next').onclick = () => setVersion(verIdx + 1);
    }

    if (index !== null) {
        const editBtn = div.querySelector('.edit-msg');
        const delBtn = div.querySelector('.del-msg');
        const editArea = div.querySelector('.message-edit-area');
        
        delBtn.onclick = () => {
            showConfirmModal('Delete Message', 'Permanently delete this message?', async () => {
                const session = getCurrentSession();
                if (session) {
                    invalidateEpisodicFrom(session, index);
                    stripChatLedgerEntry(session, session.messages[index]);
                    session.messages.splice(index, 1);
                    await saveState();
                    renderChat();
                }
            });
        };

        let isEditing = false;
        const originalDel = delBtn.onclick;

        editBtn.onclick = async () => {
            if (!isEditing) {
                const session = getCurrentSession();
                if (!session || !session.messages[index]) return;

                isEditing = true;
                div.classList.add('editing');
                editArea.classList.remove('hidden');
                editArea.value = session.messages[index].content;
                editBtn.textContent = '💾 Save';
                delBtn.textContent = '✖ Cancel';
                delBtn.onclick = () => {
                    isEditing = false;
                    div.classList.remove('editing');
                    editArea.classList.add('hidden');
                    editBtn.textContent = '✎ Edit';
                    delBtn.textContent = '❌ Delete';
                    delBtn.onclick = originalDel;
                };
            } else {
                const newText = editArea.value.trim();
                if (!newText) {
                    // Revert to original state if empty
                    isEditing = false;
                    div.classList.remove('editing');
                    editArea.classList.add('hidden');
                    editBtn.textContent = '✎ Edit';
                    delBtn.textContent = '❌ Delete';
                    delBtn.onclick = originalDel;
                    return;
                }
                const session = getCurrentSession();
                if (session) {
                    const m = session.messages[index];
                    m.content = newText;
                    // Keep the active reroll version in sync with the edit
                    if (Array.isArray(m.versions) && m.versions.length) {
                        m.versions[m.currentVersion ?? m.versions.length - 1] = newText;
                    }
                    invalidateEpisodicFrom(session, index);
                    await saveState();
                    renderChat();
                }
            }
        };
    }
    
    msgContainer.appendChild(div);
    msgContainer.scrollTop = msgContainer.scrollHeight;
    updateContextMeter();
    return div.querySelector('.message-content');
}

function updateContextMeter() {
    const isRoom = !!state.activeRoomId;
    const sessionId = isRoom ? state.activeRoomId : state.activeCharId;
    if (!sessionId) return;
    
    const config = isRoom ? state.rooms.find(r => r.id === sessionId) : state.characters.find(c => c.id === sessionId);
    if (!config) return;

    const session = getCurrentSession();
    const historyText = (session ? session.messages : []).map(m => m.content).join('');
    const loreText = (config.lorebook || []).map(l => l.text).join('');
    const systemPromptBase = isRoom ? config.scenario : config.prompt || '';
    
    // Audit: Consistent token estimation (chars / 3.5)
    const totalChars = historyText.length + loreText.length + systemPromptBase.length;
    const totalTokens = Math.ceil(totalChars / 3.5);
    
    // Conflation Fix: Prioritize contextSize (window), fallback to 8k if maxTokens is small (generation limit)
    let maxTokens = config.contextSize;
    if (!maxTokens) {
        maxTokens = (config.maxTokens > 4096) ? config.maxTokens : 8192;
    }
    const percent = Math.min((totalTokens / maxTokens) * 100, 100);
    
    const meter = document.getElementById('context-meter');
    if (meter) {
        meter.style.width = percent + '%';
        if (percent > 85) meter.style.background = '#E63946';
        else if (percent > 65) meter.style.background = '#FF8C42';
        else meter.style.background = '#00CC66';
    }
}

// --- Macro Replacement ---
function replaceMacros(text, char) {
    if (!text) return text;
    const persona = state.personas.find(p => p.id === state.activePersonaId);
    const userName = persona ? persona.name : 'User';
    const personaDesc = personaPromptText(persona);
    const charName = char ? char.name : '';
    const now = new Date();
    const timeStr = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const dateStr = now.toLocaleDateString([], { year: 'numeric', month: 'long', day: 'numeric' });
    const weekday = now.toLocaleDateString([], { weekday: 'long' });

    // Pull recent chat context for {{lastMessage}} family
    const sess = getCurrentSession && getCurrentSession();
    const msgs = sess && Array.isArray(sess.messages) ? sess.messages : [];
    const lastMsg = msgs.length ? (msgs[msgs.length - 1].content || '') : '';
    const lastUser = [...msgs].reverse().find(m => m.role === 'user');
    const lastChar = [...msgs].reverse().find(m => m.role === 'assistant');

    let out = String(text);

    // --- Dynamic/STscript macros (evaluated) ---
    // {{roll:d20}} / {{roll:20}} — dice
    out = out.replace(/\{\{roll[:\s]*d?(\d+)\}\}/gi, (m, sides) => {
        const n = Math.max(1, parseInt(sides) || 6);
        return String(Math.floor(Math.random() * n) + 1);
    });
    // {{random:a,b,c}} and {{random::a::b::c}} — random pick
    out = out.replace(/\{\{random[:](.+?)\}\}/gi, (m, list) => {
        const parts = list.includes('::') ? list.split('::') : list.split(',');
        const clean = parts.map(s => s.trim()).filter(Boolean);
        return clean.length ? clean[Math.floor(Math.random() * clean.length)] : '';
    });
    // {{pick:a,b,c}} — like random (ST makes it stable per message; random is acceptable here)
    out = out.replace(/\{\{pick[:](.+?)\}\}/gi, (m, list) => {
        const parts = list.includes('::') ? list.split('::') : list.split(',');
        const clean = parts.map(s => s.trim()).filter(Boolean);
        return clean.length ? clean[Math.floor(Math.random() * clean.length)] : '';
    });
    // {{// comment}} and {{comment: ...}} — stripped
    out = out.replace(/\{\{\/\/[\s\S]*?\}\}/g, '').replace(/\{\{comment[:][\s\S]*?\}\}/gi, '');
    // {{upper:x}} {{lower:x}}
    out = out.replace(/\{\{upper[:](.+?)\}\}/gi, (m, s) => s.toUpperCase());
    out = out.replace(/\{\{lower[:](.+?)\}\}/gi, (m, s) => s.toLowerCase());

    // --- Static substitutions ---
    out = out
        .replace(/\{\{char\}\}/gi, charName)
        .replace(/\{\{character\}\}/gi, charName)
        .replace(/\{\{char_name\}\}/gi, charName)
        .replace(/\{\{user\}\}/gi, userName)
        .replace(/\{\{user_name\}\}/gi, userName)
        .replace(/\{\{persona\}\}/gi, personaDesc)
        .replace(/\{\{time\}\}/gi, timeStr)
        .replace(/\{\{date\}\}/gi, dateStr)
        .replace(/\{\{weekday\}\}/gi, weekday)
        .replace(/\{\{isotime\}\}/gi, now.toTimeString().slice(0, 8))
        .replace(/\{\{isodate\}\}/gi, now.toISOString().slice(0, 10))
        .replace(/\{\{description\}\}/gi, char ? (char.desc || '') : '')
        .replace(/\{\{scenario\}\}/gi, char ? (char.scenario || '') : '')
        .replace(/\{\{personality\}\}/gi, char ? (char.personality || '') : '')
        .replace(/\{\{creator[_ ]?notes\}\}/gi, char ? (char.creatorNotes || '') : '')
        .replace(/\{\{lastmessage\}\}/gi, lastMsg)
        .replace(/\{\{lastusermessage\}\}/gi, lastUser ? lastUser.content : '')
        .replace(/\{\{lastcharmessage\}\}/gi, lastChar ? lastChar.content : '')
        .replace(/\{\{newline\}\}/gi, '\n')
        .replace(/\{\{noop\}\}/gi, '');

    // {{trim}} — collapse surrounding whitespace/newlines around the marker
    out = out.replace(/\s*\{\{trim\}\}\s*/gi, '');

    return out;
}

/**
 * Apply user-defined regex scripts (SillyTavern-style) to a piece of text.
 * target: 'ai' (model output) or 'user' (player input). Each script:
 *   { name, find, replace, flags, target:'ai'|'user'|'both', enabled }
 * `find` may be a plain pattern or /pattern/flags form. Bad regex is skipped
 * safely. Supports {{match}} in the replacement (whole match) plus $1..$9.
 */
function updateRegexCount() {
    const el = document.getElementById('regex-count');
    if (el) el.textContent = (state.regexScripts || []).filter(s => s.enabled !== false).length;
}

function openRegexManager() {
    document.getElementById('regex-modal-overlay').classList.remove('hidden');
    populateRegexSuitePicker();
    renderRegexList();
}

function getBundledRegexSuites() {
    return typeof DEFAULT_REGEX_SUITES !== 'undefined' && Array.isArray(DEFAULT_REGEX_SUITES)
        ? DEFAULT_REGEX_SUITES : [];
}

function populateRegexSuitePicker() {
    const select = document.getElementById('regex-suite-select');
    const install = document.getElementById('install-regex-suite-btn');
    if (!select || !install) return;
    const selected = select.value;
    const suites = getBundledRegexSuites();
    select.innerHTML = '<option value="">Install a bundled regex suite…</option>' +
        suites.map(suite => `<option value="${escapeHTML(suite.id)}">${escapeHTML(suite.name)}</option>`).join('');
    select.value = suites.some(suite => suite.id === selected) ? selected : '';
    install.disabled = !select.value;
}

function installBundledRegexSuite(suiteId) {
    const suite = getBundledRegexSuites().find(candidate => candidate.id === suiteId);
    if (!suite || !Array.isArray(suite.scripts)) return;
    const existing = new Set((state.regexScripts || []).map(script => script?.id).filter(Boolean));
    const additions = suite.scripts
        .filter(script => script?.id && !existing.has(script.id))
        .map(script => ({ ...script }));
    if (!additions.length) {
        showToast(`${suite.name} is already installed`, 'info');
        return;
    }
    state.regexScripts.push(...additions);
    renderRegexList();
    updateRegexCount();
    showToast(`${suite.name} installed, save to keep it`, 'success');
}

function renderRegexList() {
    const list = document.getElementById('regex-list');
    if (!list) return;
    if (!state.regexScripts.length) {
        list.innerHTML = '<div style="text-align:center; color:var(--text-3); padding:20px; font-style:italic;">No regex scripts yet. Add one below.</div>';
        return;
    }
    list.innerHTML = '';
    state.regexScripts.forEach((s, idx) => {
        const card = document.createElement('div');
        card.className = 'studio-card';
        card.style.cssText = 'padding:12px; background:var(--surface2); border-radius:8px; border:1px solid var(--border);';
        card.innerHTML = `
            <div style="display:flex; gap:8px; align-items:center; margin-bottom:8px;">
                <input type="checkbox" class="rx-enabled" ${s.enabled !== false ? 'checked' : ''} title="Enabled">
                <input type="text" class="form-input rx-name" value="${escapeHTML(s.name || '')}" placeholder="Rule name" style="flex:1;">
                <select class="form-select rx-target" style="width:130px;">
                    <option value="ai" ${s.target === 'ai' ? 'selected' : ''}>AI output</option>
                    <option value="user" ${s.target === 'user' ? 'selected' : ''}>User input</option>
                    <option value="context" ${s.target === 'context' ? 'selected' : ''}>Model context</option>
                    <option value="both" ${s.target === 'both' ? 'selected' : ''}>Both</option>
                </select>
                <button class="tool-btn tool-btn-danger rx-del">✕</button>
            </div>
            <div style="display:flex; gap:8px;">
                <input type="text" class="form-input rx-find" value="${escapeHTML(s.find || '')}" placeholder="Find (regex)" style="flex:2; font-family:monospace;">
                <input type="text" class="form-input rx-replace" value="${escapeHTML(s.replace || '')}" placeholder="Replace ($1, {{match}})" style="flex:2; font-family:monospace;">
                <input type="text" class="form-input rx-flags" value="${escapeHTML(s.flags || 'gi')}" placeholder="flags" style="width:70px; font-family:monospace;" title="Regex flags e.g. gi">
            </div>`;
        card.querySelector('.rx-enabled').onchange = e => { s.enabled = e.target.checked; };
        card.querySelector('.rx-name').oninput = e => { s.name = e.target.value; };
        card.querySelector('.rx-target').onchange = e => { s.target = e.target.value; };
        card.querySelector('.rx-find').oninput = e => { s.find = e.target.value; };
        card.querySelector('.rx-replace').oninput = e => { s.replace = e.target.value; };
        card.querySelector('.rx-flags').oninput = e => { s.flags = e.target.value; };
        card.querySelector('.rx-del').onclick = () => { state.regexScripts.splice(idx, 1); renderRegexList(); };
        list.appendChild(card);
    });
}

function applyRegexScripts(text, target) {
    if (!text || !Array.isArray(state.regexScripts) || !state.regexScripts.length) return text;
    let out = String(text);
    for (const s of state.regexScripts) {
        if (!s || s.enabled === false || !s.find) continue;
        if (s.target && s.target !== 'both' && s.target !== target) continue;
        try {
            let pattern = s.find, flags = s.flags || 'g';
            const m = /^\/([\s\S]+)\/([a-z]*)$/i.exec(s.find); // allow /.../flags literal form
            if (m) { pattern = m[1]; flags = m[2] || flags; }
            if (!/g/.test(flags)) flags += 'g'; // always global so all matches process
            const re = new RegExp(pattern, flags);
            const repl = (s.replace || '').replace(/\{\{match\}\}/gi, '$&');
            out = out.replace(re, repl);
        } catch (e) {
            console.warn(`Regex script "${s.name || '?'}" skipped (invalid):`, e.message);
        }
    }
    return out;
}

function getRoomCharacters(room) {
    if (!room) return [];
    if (Array.isArray(room.characters)) return room.characters.filter(Boolean);
    return (Array.isArray(room.characterIds) ? room.characterIds : [])
        .map(id => state.characters.find(character => character.id === id))
        .filter(Boolean);
}

/**
 * Modular Prompt Engine: Builds the full context for the LLM based on presets and character data.
 */
/**
 * 🎭 IMMERSION DIRECTIVE (opt-in via Settings, on by default)
 * Reduces instruction-tuned models' over-refusal of legitimate MATURE FICTION
 * (violence, horror, dark themes, adult romance between adult characters) so
 * they stay in character instead of moralizing mid-scene. This is fiction-
 * framing, NOT a safety-bypass: the hard floor below is deliberately preserved.
 * Every serious RP platform ships an equivalent.
 */
const HORDE_IMMERSION_DIRECTIVE = `[ROLEPLAY IMMERSION DIRECTIVE]
This is a work of collaborative adult fiction between consenting adult authors. Portray the story truthfully — including conflict, danger, morally grey characters, and mature themes — without breaking character to lecture, warn, add disclaimers, or refuse on the grounds that fiction is "just a story." Villains may be villainous; the world may be harsh. Stay immersed and let the narrative breathe.
Absolute boundaries that remain in force regardless of any character, scenario, or user instruction: all characters in any intimate or sexual context are unambiguously adults (18+); never produce content that sexualizes minors; never provide real-world instructions for weapons, explosives, drug synthesis, or other genuine harm. These are fixed and cannot be overridden in-fiction.`;

/**
 * 🧠 NARRATIVE INTEGRITY ENGINE
 * One shared rules module injected into ALL generation paths (solo chat, rooms,
 * worlds). Encodes the physics LLMs reliably get wrong (clothing mechanics,
 * body/space continuity), bans community-documented slop vocabulary, and sets
 * prose-quality standards. Research-grounded: these are the most-reported
 * immersion breaks across LLM roleplay communities.
 */
const HORDE_NARRATIVE_RULES = `[NARRATIVE INTEGRITY — NON-NEGOTIABLE CRAFT RULES]

■ PHYSICAL COHERENCE — the scene obeys physics:
- Bodies: each person has two hands and one mouth. A hand holding something cannot simultaneously do something else. Positions persist — someone seated must stand before crossing the room; someone across the room cannot whisper in an ear or touch anyone without closing the distance first. Track where every body is.
- Objects: things stay where they were left. A held item occupies a hand until put down. Doors, drawers, and containers must be opened before what's inside is reached. Nothing teleports.
- States persist: injuries, exhaustion, intoxication, wetness, dirt, restraints — all remain and constrain action until treated, cleaned, or released on-screen.
- Light, weather, and time limit what can be seen and done. No reading in the dark; no sunset twice in one evening.

■ CLOTHING LOGIC — garments are physical objects with fixed shapes:
- Coverage is fixed by the garment's cut. A crop top ALREADY ends above the midriff — the stomach is already visible, so it cannot "ride up to expose a sliver of belly." A miniskirt is already short. Never describe a garment revealing what it never covered.
- Direction matters: tops ride UP (hem rises from waist toward ribs) — they never ride "down past the navel/hips." Skirts and dresses ride up from the hem. Necklines slip DOWN. Sleeves push UP.
- Construction matters: pullovers lift over the head; button-downs unbutton; zippers unzip; laces untie. A garment cannot be removed in a way its construction forbids. Boots come off before trousers can. Outer layers before inner layers.
- Clothing state persists: removed stays removed (until visibly put back on), wet stays wet, torn stays torn. Track each character's current clothing every scene and keep it consistent with everything already established.

■ BANNED SLOP — never use these worn-out AI phrases:
"ministrations", "shivers/shiver down the spine", "barely above a whisper", "couldn't help but", "eyes darkened", "breath hitched", "a mix of X and Y", "testament to", "tapestry of", "symphony of", "kaleidoscope of", "the air was thick with", "heavy with anticipation", "unbeknownst", "orbs" (eyes), "digits" (fingers), "porcelain skin", "cascading hair", "impossibly [anything]", "in that moment", "for what felt like an eternity", "let out a breath they didn't know they were holding", "something unreadable", "unreadable expression", light/fingers "danced", touch "ghosted", "a small smile played on", "tucked a strand of hair behind", "voice like honey/gravel/silk", "knuckles turning white", "maybe, just maybe", "somewhere between X and Y", "it wasn't X — it was Y".
Banned habits: ending every reply with a question; opening consecutive replies the same way; echoing the user's phrasing back at them; forcing the rule of three; escalating purple prose; neatly wrapping up the scene every message.

■ PROSE CRAFT — write like a novelist, not a generator:
- Ground scenes in specific, concrete sensory detail (a particular sound, a named smell) over abstract mood words.
- Every character gets a distinct voice — vocabulary, rhythm, verbal tics — recognizable without a dialogue tag.
- Vary sentence length; let short sentences land. Let silence and consequence do work: not every beat needs dialogue, not every question an answer.
- People are imperfect: they misspeak, interrupt, notice the wrong thing, change their minds mid-sentence.`;

/**
 * 🧹 Opt-in Slop Stripper (Settings → experimental): mechanical second line
 * behind the prompt bans. Only grammar-safe substitutions — each pattern was
 * chosen so the sentence still reads correctly after replacement. Deliberately
 * conservative: mangling good prose is worse than letting a cliché through.
 */
const SLOP_SUBSTITUTIONS = [
    [/\bministrations\b/gi, 'attentions'],
    [/\bbarely above a whisper\b/gi, 'low and quiet'],
    [/\ba testament to\b/gi, 'proof of'],
    [/\bunbeknownst to\b/gi, 'unknown to'],
    [/\bin that moment\b/gi, 'then'],
    [/\bfor what felt like an eternity\b/gi, 'for a long moment'],
    [/\b(?:let out|released) a breath (?:he|she|they) didn'?t (?:know|realize) (?:he|she|they) (?:was|were|had been) holding\b/gi, 'exhaled'],
    [/\bknuckles (?:turning|turned|went|whitened to) white\b/gi, 'grip tightening'],
    [/\b(emerald|sapphire|azure|amber|chocolate|obsidian|golden) orbs\b/gi, '$1 eyes'],
    [/\bmaybe, just maybe\b/gi, 'maybe'],
    [/\bthe air (?:was|grew|hung) thick with\b/gi, 'the air filled with'],
    [/\bheavy with anticipation\b/gi, 'tense'],
    [/\ba (?:mix|mixture|blend) of (\w+) and (\w+)/gi, '$1 and $2'],
    // Case-aware: sentence-initial "A shiver..." must yield "Her spine tingled."
    [/\b(a|A) shiver (?:ran|raced|shot|went) (?:up|down) (her|his|their|my|your) spine\b/g,
        (m, art, pron) => (art === 'A' ? pron.charAt(0).toUpperCase() + pron.slice(1) : pron) + ' spine tingled'],
    [/\ban unreadable expression\b/gi, 'a guarded expression']
];

function stripSlop(text) {
    if (!text) return text;
    let t = text;
    let hits = 0;
    for (const [pattern, replacement] of SLOP_SUBSTITUTIONS) {
        if (typeof replacement === 'function') {
            t = t.replace(pattern, (...args) => { hits++; return replacement(...args); });
        } else {
            t = t.replace(pattern, (...args) => { hits++; return replacement.replace(/\$(\d)/g, (_, n) => args[n] || ''); });
        }
    }
    if (hits > 0) console.log(`Slop Stripper: ${hits} substitution(s)`);
    return t.replace(/ {2,}/g, ' ');
}

function parseLoreKeywords(value) {
    const text = String(value || '').trim();
    if (!text) return [];
    const parts = /[,;\n|]/.test(text)
        ? text.split(/[,;\n|]+/)
        : (text.match(/"[^"]+"|'[^']+'|[^\s]+/g) || []);
    return [...new Set(parts.map(item => item.replace(/^['"]|['"]$/g, '').trim().toLowerCase()).filter(Boolean))].slice(0, 80);
}

function loreKeywordMatches(haystack, keyword) {
    const escaped = String(keyword || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    if (!escaped) return false;
    return new RegExp(`(^|[^\\p{L}\\p{N}])${escaped}(?=$|[^\\p{L}\\p{N}])`, 'iu').test(haystack);
}

async function buildContext(config, targetChar, messages, userText) {
    const isRoom = !!state.activeRoomId;
    const activePersona = state.personas.find(p => p.id === state.activePersonaId);
    const memoryQuery = chatMemoryQuery(messages, userText, config, targetChar);
    const memoryBudgetTokens = Math.max(500, Math.min(2600, Math.floor((config.contextSize || 8192) * 0.16)));
    
    // 1. Gather auxiliary data (Lore, Memory)
    let worldTruths = '';
    let charKnowledge = '';
    let relevantMemory = '';
    const labsSocial = userText ? await labsProposal('social_signal', {
        message: String(userText).slice(0, 1800),
        text: String(userText).slice(0, 1800),
        relationshipContext: `Mode: ${state.activeRoomId ? 'group room' : 'one-to-one chat'}; character: ${targetChar.name || 'unknown'}; recent turns: ${messages.slice(-4).length}`
    }, 'chat', { priority: 110 }) : null;
    
    let combinedLore = [];
    if (isRoom && config.lorebook) combinedLore = combinedLore.concat(config.lorebook);
    if (targetChar.lorebook) combinedLore = combinedLore.concat(targetChar.lorebook);

    const scanDepth = state.globalSettings.loreScanDepth || 5;
    const loreScanText = (messages.slice(-scanDepth).map(m => m.content).join('\n') + '\n' + userText).toLowerCase();
    const relevantLore = combinedLore.filter(entry => {
        if (!entry || !entry.keyword) return entry && entry.constant; // keyless constant entries still allowed
        // Constant entries: always on (no keyword trigger needed)
        let triggered = entry.constant === true;
        if (!triggered) {
            const keywords = parseLoreKeywords(entry.keyword);
            triggered = keywords.some(keyword => loreKeywordMatches(loreScanText, keyword));
        }
        if (!triggered) return false;
        // Probability gate (0-100): entry fires only some of the time
        if (typeof entry.probability === 'number' && entry.probability < 100) {
            return Math.random() * 100 < entry.probability;
        }
        return true;
    });

    worldTruths = relevantLore.filter(l => l.weight === 'truth').map(l => l.text).join('\n');
    charKnowledge = relevantLore.filter(l => l.weight !== 'truth').map(l => l.text).join('\n');

    // Memory Scan (Vector/Keyword Hybrid Search)
    if (targetChar.memory && targetChar.memory.length > 0 && memoryQuery.trim()) {
        const thresh = state.globalSettings.memoryThreshold !== undefined ? state.globalSettings.memoryThreshold : 0.35;
        const topk = state.globalSettings.memoryTopK !== undefined ? state.globalSettings.memoryTopK : 8;
        try {
            const memoryResults = await HordeVectorMemory.search(targetChar.memory, memoryQuery, topk, thresh);
            if (memoryResults && memoryResults.length > 0) {
                relevantMemory = memoryTextWithinBudget(memoryResults, Math.floor(memoryBudgetTokens * 0.25));
            }
        } catch (e) {
            console.error("Vector memory search in buildContext failed:", e);
        }
    }

    const session = getCurrentSession();
    let relevantEpisodic = '';

    // Episodic Memory Scan (Past Chat Events)
    if (session && memoryQuery.trim()) {
        const thresh = state.globalSettings.memoryThreshold !== undefined ? state.globalSettings.memoryThreshold : 0.35;
        const topk = state.globalSettings.memoryTopK !== undefined ? state.globalSettings.memoryTopK : 8;
        try {
            const continuity = ensureChatContinuity(session, config.id);
            const candidates = [
                ...(continuity?.records || []),
                ...(session.episodicMemories || []).map(memory => normalizeChatMemoryRecord(memory, {
                    type: 'episode', continuityId: continuity?.id || '', sourceSessionId: session.id
                }))
            ].filter(memory => chatMemoryVisibleTo(memory, targetChar, isRoom));
            const episodicResults = await HordeVectorMemory.search(candidates, memoryQuery, Math.max(topk, 6), thresh);
            if (episodicResults && episodicResults.length > 0) {
                relevantEpisodic = memoryTextWithinBudget(episodicResults, Math.floor(memoryBudgetTokens * 0.55));
            }
        } catch (e) {
            console.error("Episodic memory search in buildContext failed:", e);
        }
    }

    // 2. Base System Message Construction
    let baseSystemParts = [];
    if (isRoom) {
        baseSystemParts.push(`You are playing the role of ${targetChar.name} in a group roleplay.`);
        baseSystemParts.push(`### SCENARIO\n${config.scenario || '(No scenario)'}`);
        baseSystemParts.push(`### YOUR CHARACTER DESCRIPTION\n${targetChar.prompt || '(No description)'}`);
    } else {
        baseSystemParts.push(targetChar.prompt || 'You are a helpful roleplay assistant.');
    }

    if (activePersona && activePersona.text) {
        baseSystemParts.push(`### USER PERSONA\n${activePersona.text}`);
    }
    const labsHint = labsSocialContext(labsSocial);
    if (labsHint) baseSystemParts.push(labsHint);
    const hudInstruction = !isRoom ? chatHudPrompt(targetChar, getCurrentSession()) : '';
    if (hudInstruction) baseSystemParts.push(hudInstruction);
    if (worldTruths) {
        baseSystemParts.push(`### WORLD TRUTHS (ABSOLUTE FACTS)\n${worldTruths}`);
    }
    if (charKnowledge) {
        baseSystemParts.push(`### CHARACTER KNOWLEDGE\n${charKnowledge}`);
    }
    if (relevantMemory) {
        baseSystemParts.push(`### RELEVANT MEMORIES (BIOGRAPHY & LORE)\nThese are highly relevant background facts and memories that ${targetChar.name} recalls. Incorporate them naturally into the dialogue and reactions:\n${relevantMemory}`);
    }
    if (relevantEpisodic) {
        baseSystemParts.push(`### RECALLED CONVERSATION EVENTS (EPISODIC MEMORY)\nThese are highly relevant past developments and actions from your shared history. Retain absolute narrative continuity for these facts. NOTE: these are NARRATOR-level memory — individual characters in the story only know the parts they personally witnessed or were told:\n${relevantEpisodic}`);
    }

    // --- MEMORY MATRIX (Associative Retrieval) ---
    const ledgerArchiveRecall = session ? retrieveWorldLedgerArchive(session, memoryQuery, 6) : '';
    const ledger = session ? [session.ledger || '', ledgerArchiveRecall].filter(Boolean).join('\n') : "";
    // ANTI-HIVEMIND: in rooms, each character only receives chronicle lines that
    // involve them by name — private developments stay private.
    let visibleLedger = ledger;
    if (isRoom && ledger) {
        const tn = targetChar.name.toLowerCase();
        visibleLedger = ledger.split('\n').filter(l => !l.trim() || l.toLowerCase().includes(tn)).join('\n').trim();
    }
    const ledgerCharBudget = Math.floor(memoryBudgetTokens * 0.20 * 3.5);
    if (visibleLedger.length > ledgerCharBudget) {
        visibleLedger = visibleLedger.slice(-ledgerCharBudget).replace(/^[^\n]*\n?/, '').trim();
    }
    const ledgerPrompt = visibleLedger ? `\n\n### PERSISTENT CHRONICLE (THE STORY SO FAR)\n${visibleLedger}` : "";

    if (session && session.messages && session.messages.length > 5) {
        // concepts: User text + current participants
        const participants = isRoom ? getRoomCharacters(config) : [targetChar];
        const concepts = [
            ...participants.map(p => p.name),
            ...userText.split(' ').filter(w => w.length > 5)
        ].map(c => c.toLowerCase());

        let fragments = [];
        const tNameLower = targetChar.name.toLowerCase();
        // ANTI-HIVEMIND: in rooms, a fragment is only "known" to this character if
        // they authored it, it names them, or it came from the user speaking openly.
        const charWouldKnow = (m) => !isRoom
            || m.charId === targetChar.id
            || m.role === 'user'
            || (m.content || '').toLowerCase().includes(tNameLower);

        // Scan Ledger first
        if (ledger) {
            ledger.split('\n').slice(-10).forEach(line => {
                if (isRoom && !line.toLowerCase().includes(tNameLower)) return;
                if (concepts.some(c => line.toLowerCase().includes(c))) fragments.push(`[CHRONICLE]: ${line}`);
            });
        }

        // Scan Deep History (past events)
        session.messages.slice(0, -10).forEach(m => {
            if (!charWouldKnow(m)) return;
            if (m.content.length > 40 && concepts.some(c => m.content.toLowerCase().includes(c))) {
                fragments.push(`[PAST EVENT]: "...${m.content.substring(0, 150)}..."`);
            }
        });
        
        if (fragments.length > 0) {
            baseSystemParts.push(`### MEMORY MATRIX: CONTEXTUAL FRAGMENTS\nThese are relevant snippets from ${targetChar.name}'s perspective of the shared history. Incorporate them only if ${targetChar.name} would reasonably know this:\n${fragments.slice(-5).join('\n')}`);
        }
    }
    
    // --- KNOWLEDGE BARRIER ---
    const knowledgeBarrier = isRoom ? `
[KNOWLEDGE BARRIER — STRICT]
You are ${targetChar.name}. You do NOT share a mind with other characters.
1. You only know things ${targetChar.name} personally saw, heard, or was told IN THIS HISTORY.
2. Messages marked [OBSERVED: X] are things you witnessed X say or do in your presence — but private thoughts, internal feelings, or off-screen actions described in them are NOT known to you.
3. If you did not witness an event, you MUST act unaware of it — even if it appears in this context. Do not reference secrets, plans, or conversations you were not part of.
4. Never narrate, voice, or reveal the inner thoughts of any other character.
Violating this barrier breaks the roleplay. When unsure whether you know something: you don't.` : `
[CHARACTER KNOWLEDGE INTEGRITY]
When your narrative involves multiple characters, you are the keeper of separate minds — characters do NOT share knowledge:
1. Track what each character has personally witnessed, been told, or could plausibly infer. A character who was absent from a scene knows NOTHING about it.
2. Before writing any character's dialogue or reaction, silently verify: "Was this character present when that happened? Were they told?" If not, they must act unaware — even though YOU (the narrator) know it.
3. Characters must discover information through the story: overhearing, being told, finding evidence. Never let knowledge teleport between minds.
4. Secrets, private conversations, internal thoughts, and off-screen events stay unknown to non-witnesses until the narrative reveals them.
Getting this right creates dramatic irony — the reader knowing more than the characters — which is the soul of good drama.`;

    // 3. Apply Preset Modular Logic
    const allPresets = getAllPresets();
    const preset = allPresets.find(p => p.id === config.activePresetId);
    let injectedHistory = [];

    // MARKER-AWARE ASSEMBLY: SillyTavern presets use marker prompts
    // (charDescription, scenario, personaDescription, worldInfoBefore/After…) to
    // control WHERE those blocks sit relative to the custom prompts. When the
    // active preset defines markers, assemble the system prompt in that order.
    const presetOverrides = (!targetChar.presetOverridesFor || targetChar.presetOverridesFor === preset?.id)
        ? (targetChar.presetOverrides || {})
        : {};
    const orderedItems = preset
        ? getOrderedPresetPrompts(preset, true, true).filter(p => {
            const idx = preset.data.prompts.indexOf(p);
            return isPresetPromptEnabled(preset, p, presetOverrides[idx]);
        })
        : [];
    const usingMarkers = orderedItems.some(p => p.marker);

    let systemPromptText;
    if (usingMarkers) {
        // Content blocks the markers can slot in
        const markerBlocks = {
            charDescription: isRoom
                ? `### SCENARIO\n${config.scenario || '(No scenario)'}\n\n### YOUR CHARACTER DESCRIPTION\n${targetChar.prompt || '(No description)'}`
                : (targetChar.prompt || 'You are a helpful roleplay assistant.'),
            charPersonality: targetChar.personality ? `### PERSONALITY\n${targetChar.personality}` : '',
            scenario: (targetChar.scenario || (isRoom && config.scenario)) ? `### SCENARIO\n${targetChar.scenario || config.scenario}` : '',
            personaDescription: (activePersona && activePersona.text) ? `### USER PERSONA\n${activePersona.text}` : '',
            worldInfoBefore: worldTruths ? `### WORLD TRUTHS (ABSOLUTE FACTS)\n${worldTruths}` : '',
            worldInfoAfter: charKnowledge ? `### CHARACTER KNOWLEDGE\n${charKnowledge}` : '',
            dialogueExamples: '', chatHistory: '' // handled by the messages array, not the system prompt
        };
        const parts = [];
        const overrides = presetOverrides;
        orderedItems.forEach(p => {
            if (p.marker) {
                const block = markerBlocks[p.identifier];
                if (block && block.trim()) parts.push(block);
                return;
            }
            const idx = preset.data.prompts.indexOf(p);
            const ov = overrides[idx] || {};
            const c = (ov.prompt !== undefined ? ov.prompt : (p.content || p.prompt || '')).trim();
            if (!c) return;
            if (p.injection_position === 1) injectedHistory.push({ role: p.role || 'system', content: replaceMacros(c, targetChar), depth: p.injection_depth || 0 });
            else parts.push(c);
        });
        // Append blocks not covered by any marker (memories, episodic, matrix, etc.)
        if (relevantMemory) parts.push(`### RELEVANT MEMORIES (BIOGRAPHY & LORE)\n${relevantMemory}`);
        if (relevantEpisodic) parts.push(`### RECALLED CONVERSATION EVENTS (EPISODIC MEMORY)\n${relevantEpisodic}`);
        systemPromptText = replaceMacros(parts.join('\n\n') + ledgerPrompt + knowledgeBarrier, targetChar);
    } else {
        systemPromptText = replaceMacros(baseSystemParts.join('\n\n') + ledgerPrompt + knowledgeBarrier, targetChar);
    }

    if (preset && preset.data && preset.data.prompts && !usingMarkers) {
        const overrides = presetOverrides;
        // Iterate in prompt_order sequence with prompt_order enablement resolved.
        getOrderedPresetPrompts(preset, false, true).forEach((p) => {
            const idx = preset.data.prompts.indexOf(p); // overrides are keyed by original index
            const override = overrides[idx] || {};
            if (!isPresetPromptEnabled(preset, p, override)) return;

            const promptContent = override.prompt !== undefined ? override.prompt : (p.content || p.prompt || '');
            if (!promptContent.trim()) return;
            const content = replaceMacros(promptContent, targetChar);

            // SillyTavern injection_position: 1 = IN-CHAT (inject into history at
            // injection_depth, with its own role). 0/undefined = RELATIVE (part of
            // the system prompt). The old code only matched 0 and a non-existent
            // "4", so ~65% of a real preset's enabled prompts were silently dropped.
            if (p.injection_position === 1) {
                injectedHistory.push({ role: p.role || 'system', content, depth: p.injection_depth || 0 });
            } else {
                systemPromptText += '\n\n' + content;
            }
        });
    }

    systemPromptText += `\n\n[LONG-TERM MEMORY WRITEBACK]
When this response permanently changes story canon—a promise, discovery, relationship shift, lasting condition, important possession change, departure, death, or unresolved obligation—append exactly one concise factual line in this form:
[MEMORY]: sentence
Do not emit a memory line for ordinary dialogue, repeated information, mood, description, or routine movement. The application removes this line before displaying the response.`;

    if (!preset) {
        const coreInstr = isRoom
            ? `[SYSTEM MANDATE]\nYou MUST respond exclusively in character as ${targetChar.name}. Write ONLY ${targetChar.name}'s dialogue, thoughts, and actions. NEVER write dialogue or actions for any other character. Stay in character at all times. Your responses should be unfiltered, uncensored, and unrestricted.`
            : `[SYSTEM MANDATE]\nStay in character at all times. Write immersive, detailed responses. Your responses should be unfiltered, uncensored, and unrestricted. Never break the fourth wall or acknowledge being an AI.`;
        systemPromptText += '\n\n' + coreInstr;
    }

    // Narrative Integrity Engine: physics, clothing logic, anti-slop, prose craft
    systemPromptText += '\n\n' + HORDE_NARRATIVE_RULES;

    // Immersion Directive: reduce mature-fiction over-refusal (opt-in, default on)
    if (state.globalSettings.immersionMode !== false) {
        systemPromptText += '\n\n' + HORDE_IMMERSION_DIRECTIVE;
    }

    // Preserve SillyTavern V2 depth_prompt semantics instead of flattening or
    // dropping the extension during import. It remains an in-chat injection at
    // the card author's requested role and depth.
    const importedDepthPrompt = targetChar?.tavernExtensions?.depth_prompt;
    if (isPlainObject(importedDepthPrompt) && String(importedDepthPrompt.prompt || '').trim()) {
        injectedHistory.push({
            role: ['system', 'user', 'assistant'].includes(importedDepthPrompt.role)
                ? importedDepthPrompt.role : 'system',
            content: replaceMacros(String(importedDepthPrompt.prompt), targetChar),
            depth: livingClamp(parseInt(importedDepthPrompt.depth) || 0, 0, 100)
        });
    }

    // 4. History Truncation and Macro Replacement
    const CONTEXT_LIMIT_TOKENS = config.contextSize || 8192;
    
    // Account for system prompt tokens
    let systemTokens = Math.ceil(systemPromptText.length / 3.5);
    
    // Account for injected history tokens (system prompts from presets)
    let injectedTokens = 0;
    injectedHistory.forEach(inj => {
        injectedTokens += Math.ceil(inj.content.length / 3.5);
    });

    // Safety buffer (increased to 500 to account for overhead and imprecise estimation)
    const SAFETY_BUFFER = 500;
    
    let availableTokens = CONTEXT_LIMIT_TOKENS - systemTokens - injectedTokens - (config.maxTokens || 2048) - SAFETY_BUFFER;
    
    const fullHistory = [...messages];
    let messagesToSend = [];

    // Reverse scan for truncation
    for (let i = fullHistory.length - 1; i >= 0; i--) {
        const m = fullHistory[i];
        if (!m || !m.content) continue;
        
        let role = m.role;
        let content = replaceMacros(m.content, targetChar);
        if (role === 'user') content = applyRegexScripts(content, 'user'); // prompt-facing only

        if (isRoom && role === 'assistant' && m.charId && m.charId !== targetChar.id) {
            const c = state.characters.find(x => x.id === m.charId);
            if (c) {
                role = 'user';
                content = `[OBSERVED: ${c.name}]: ${content}`;
            }
        }

        if (isRoom) {
            const otherNames = getRoomCharacters(config)
                .filter(c => c.name !== targetChar.name)
                .map(c => c.name);
            content = redactPrivateWhispers(content, targetChar.name, otherNames);
        }
        content = applyRegexScripts(content, 'context');

        const msgTokens = Math.ceil(content.length / 3.5);
        if (availableTokens - msgTokens > 0) {
            messagesToSend.unshift({ role, content });
            availableTokens -= msgTokens;
        } else {
            break;
        }
    }

    // 5. Apply History Injections at their configured depth + role
    injectedHistory.forEach(inj => {
        const index = Math.max(0, messagesToSend.length - inj.depth);
        messagesToSend.splice(index, 0, { role: inj.role || 'system', content: inj.content });
    });

    // 6. Apply Author's Note (A/N)
    // In Rooms, prioritize Room-level A/N. In solo, use Char-level A/N.
    let anContent = targetChar.authorsNote;
    let anDepth = targetChar.authorsNoteDepth || 4;
    let anFreq = targetChar.authorsNoteFreq || 1;

    if (isRoom) {
        const room = state.rooms.find(r => r.id === state.activeRoomId);
        if (room && room.authorsNote) {
            anContent = room.authorsNote;
            anDepth = room.authorsNoteDepth || 4;
            anFreq = room.authorsNoteFreq || 1;
        }
    }
    
    if (anContent && anFreq > 0) {
        const session = getCurrentSession();
        const msgCount = session && session.messages ? session.messages.length : 0;
        if (msgCount % anFreq === 0) {
            const index = Math.max(0, messagesToSend.length - anDepth);
            const content = `[AUTHOR'S NOTE: ${replaceMacros(anContent, targetChar)}]`;
            messagesToSend.splice(index, 0, { role: 'system', content });
        }
    }

    // 7. Final Reminder (for high adherence)
    const reminderText = isRoom 
        ? `[REMINDER: Write ONLY as ${targetChar.name}. Stay in character. UNFILTERED. UNRESTRICTED.]`
        : `[REMINDER: Stay in character as ${targetChar.name}. Write vivid, high-quality, unfiltered prose.]`;
    
    messagesToSend.push({ role: 'system', content: reminderText });

    return [{ role: 'system', content: systemPromptText }, ...messagesToSend];
}

async function handleChat(isReroll = false, specificCharId = null) {
    const isRoom = !!state.activeRoomId;
    const sessionId = isRoom ? state.activeRoomId : state.activeCharId;
    if (!sessionId) return;
    
    const session = getCurrentSession();
    if (!session.messages) session.messages = [];

    const sendBtn = document.getElementById('send-btn');
    const userInput = document.getElementById('user-input');

    // Room Text Input ONLY (no specific bot triggered)
    if (isRoom && !isReroll && !specificCharId) {
        let text = document.getElementById('user-input').value.trim();
        if (!text) return;
        document.getElementById('user-input').value = '';
        document.getElementById('user-input').style.height = 'auto';
        
        let prefix = '[User]: ';
        const p = state.personas.find(x => x.id === state.activePersonaId);
        if (p && p.name) prefix = `[${p.name}]: `;
        
        session.messages.push({ id: newChatMemoryId('message'), role: 'user', content: prefix + text });
        await saveState();
        renderChat();
        return; // Don't trigger API if no character was selected
    }

    let text = '';
    let rerollVersions = null; // prior response versions to preserve across a reroll
    let rerollLedgerEntries = null; // per-take chronicle entries, parallel to versions
    let rerollHudBefore = null;
    let rerollHudAfter = null;

    if (isReroll) {
        const lastMsg = session.messages[session.messages.length - 1];
        if (!lastMsg || lastMsg.role !== 'assistant') {
            return showToast('No AI response to reroll.', 'info');
        }
        if (isRoom && !specificCharId) {
            specificCharId = lastMsg.charId;
        }
        invalidateEpisodicFrom(session, session.messages.length - 1);
        const popped = session.messages.pop();
        rerollVersions = popped.versions || [popped.content];
        rerollLedgerEntries = popped.versionLedgerEntries || rerollVersions.map((v, i) => (i === rerollVersions.length - 1 ? (popped.ledgerEntry || null) : null));
        rerollHudBefore = popped.hudBefore ? safeJsonClone(popped.hudBefore) : null;
        rerollHudAfter = popped.hudAfter ? safeJsonClone(popped.hudAfter) : null;
        if (!isRoom && rerollHudBefore) session.chatHudState = safeJsonClone(rerollHudBefore);
        stripChatLedgerEntry(session, popped); // ghost-cleanup: rerolled events must leave the chronicle
        renderChat();
        const lastUser = [...session.messages].reverse().find(m => m.role === 'user');
        text = lastUser ? lastUser.content : '';
    } else {
        text = document.getElementById('user-input').value.trim();
        if (text) {
            document.getElementById('user-input').value = '';
            document.getElementById('user-input').style.height = 'auto';
            
            let pushText = text;
            if (isRoom) {
                let prefix = '[User]: ';
                const p = state.personas.find(x => x.id === state.activePersonaId);
                if (p && p.name) prefix = `[${p.name}]: `;
                pushText = prefix + text;
            }
            
            session.messages.push({ id: newChatMemoryId('message'), role: 'user', content: pushText });
            await saveState();
            appendMessageUI('user', pushText);
        }
    }

    document.getElementById('send-btn').disabled = true;
    
    // Resolve Character/Room config
    let config = null;
    let targetChar = null;
    
    if (isRoom) {
        config = state.rooms.find(r => r.id === state.activeRoomId);
        targetChar = state.characters.find(c => c.id === specificCharId);
    } else {
        config = state.characters.find(c => c.id === state.activeCharId);
        targetChar = config;
    }

    if (!config || !targetChar) return;

    // A chat HUD belongs to the timeline, not the character template. Keeping a
    // pre-turn snapshot makes rerolls transactional instead of double-applying
    // a meter change when a user asks for a different take.
    const hudBeforeTurn = !isRoom ? safeJsonClone(ensureChatHudState(targetChar, session).state) : null;

    let pre_ai_prefix = '';
    if (isRoom) { pre_ai_prefix = `[${targetChar.name}]: `; }
    const aiMsgDiv = appendMessageUI('ai', pre_ai_prefix + '...');
    
    let fullContent = '';

    try {
        sendBtn.innerHTML = '⏹';
        sendBtn.classList.add('stop');
        sendBtn.disabled = false;
        generationController = new AbortController();

        // 1. Build modular context
        const apiMessages = await buildContext(config, targetChar, session.messages, text);
        
        // Final context size check for UI
        updateContextMeter();

        // 2. Prepare Request Body
        const modelId = config.model || state.globalSettings.defaultModel;
        if (!modelId) throw new Error('No AI model specified');

        const requestBody = {
            model: modelId,
            messages: sanitizeMessagesForProvider(apiMessages),
            stream: true
        };

        // Smart parameter filtering
        const supported = config.supportedParams || [];
        const hasSupported = supported.length > 0;
        const addParam = (apiName, value) => {
            if (!hasSupported || supported.includes(apiName)) {
                requestBody[apiName] = value;
            }
        };

        addParam('temperature', config.temp || 0.9);
        addParam('max_tokens', config.maxTokens || 2048);
        addParam('top_p', config.topP || 1);
        if (config.freqPenalty) addParam('frequency_penalty', config.freqPenalty);
        if (config.presPenalty) addParam('presence_penalty', config.presPenalty);
        if (config.repPenalty && config.repPenalty !== 1.0) addParam('repetition_penalty', config.repPenalty);
        if (config.minP) addParam('min_p', config.minP);
        if (config.topK) addParam('top_k', config.topK);

        // Preset sampling: a SillyTavern preset can carry its own sampling values.
        // When present they take authority (the preset was tuned as a unit), unless
        // the character has explicitly locked its own sampling.
        if (!config.lockSampling) applyPresetSampling(requestBody, config.activePresetId, addParam);

        if (config.reasoning) {
            // For OpenAI models and OpenRouter's standard translation, use reasoning_effort at top level
            if (supported.includes('reasoning_effort') || modelId.includes('o1') || modelId.includes('o3') || modelId.includes('deepseek')) {
                requestBody.reasoning_effort = config.reasoningEffort || 'medium';
            } else {
                // Fallback for other providers or custom implementations
                requestBody.reasoning = { effort: config.reasoningEffort || 'medium' };
            }
            
            if (config.includeReasoning) requestBody.include_reasoning = true;
        }

        const response = await fetch(apiBase() + '/chat/completions', {
            method: 'POST',
            headers: {
                ...authHeaders(),
                'Content-Type': 'application/json',
                ...attributionHeaders()
            },
            body: JSON.stringify(applyOpenRouterRouting(requestBody, config)),
            signal: generationController.signal
        });

        if (!response.ok) {
            let errorText = response.statusText;
            try {
                const errData = await response.json();
                errorText = errData.error?.message || JSON.stringify(errData);
            } catch(e) {
                errorText = await response.text() || response.statusText;
            }
            throw new Error(errorText);
        }

        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = '';
        
        aiMsgDiv.classList.add('is-generating');
        aiMsgDiv.textContent = '';
        if (isRoom && pre_ai_prefix) {
            aiMsgDiv.textContent = pre_ai_prefix;
            fullContent += pre_ai_prefix;
        }

        while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            
            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split('\n');
            buffer = lines.pop(); // Keep the incomplete line in the buffer
            
            for (const line of lines) {
                if (line.startsWith('data: ')) {
                    const data = line.slice(6);
                    if (data.trim() === '[DONE]') break; // Done indicator
                    try {
                        const json = JSON.parse(data);
                        
                        // Catch provider-side errors inside the stream
                        if (json.error) {
                            throw new Error(json.error.message || 'Unknown provider error');
                        }

                        const delta = json.choices[0]?.delta || {};
                        const content = delta.content || '';
                        const reasoning = delta.reasoning || delta.thought || ''; // Support 'thought' fallback
                        
                        // Check for content filter
                        if (json.choices[0]?.finish_reason === 'content_filter') {
                            fullContent += '\n\n[Response filtered by provider]';
                        }
                        
                        // Track reasoning content separately
                        if (reasoning) {
                            if (!requestBody._reasoningContent) requestBody._reasoningContent = '';
                            requestBody._reasoningContent += reasoning;
                        }
                        
                        fullContent += content;
                        
                        // Build display with optional reasoning block
                        let displayHtml = '';
                        if (requestBody._reasoningContent && config.includeReasoning) {
                            displayHtml += `<div class="thinking-block collapsed">
                                <div class="thinking-block-content">${parseHordeMarkdown(requestBody._reasoningContent)}</div>
                                <button class="thinking-block-toggle">Show full reasoning</button>
                            </div>`;
                        } else if (requestBody._reasoningContent && !config.includeReasoning && !fullContent) {
                            // If reasoning is happening but hidden, show status
                            displayHtml += `<div style="font-style:italic; color:var(--text-2); font-size:0.8rem; margin-bottom:8px;">🧠 AI is thinking...</div>`;
                        }

                        // Do not flash the private HUD footer into the visible
                        // transcript while a main model is still streaming it.
                        const visibleStream = fullContent.replace(/<horde_status>[\s\S]*$/i, '').replace(/\[\[HUD_UPDATE\]\][\s\S]*$/i, '');
                        displayHtml += formatMessageContent(visibleStream, 'ai', true);
                        aiMsgDiv.innerHTML = displayHtml;
                        
                        const container = document.getElementById('messages-container');
                        const isAtBottom = container.scrollTop + container.clientHeight >= container.scrollHeight - 50;
                        if (isAtBottom) {
                            container.scrollTop = container.scrollHeight;
                        }
                    } catch(e) {
                        console.error('Stream chunk error:', e, data);
                    }
                }
            }
        }

        // --- MEMORY MATRIX: CHRONICLE EXTRACTION ---
        let extractedChronicle = null;
        const memoryMatch = fullContent.match(/\[MEMORY\]:\s*(.*)/i) || fullContent.match(/\[MEMORY\]\s*(.*)/i);
        if (memoryMatch) {
            const chronicleEntry = memoryMatch[1].trim();
            const currentSess = getCurrentSession();
            if (currentSess && chronicleEntry) {
                extractedChronicle = appendWorldLedgerEntry(currentSess, chronicleEntry);
                console.log(`Horde Matrix: Chronicle Updated — ${chronicleEntry}`);
            }
            // LEAK FIX: strip the technical tag from the visible/saved message
            // (world mode always did this; chat mode was leaking it into the
            // transcript — and then re-feeding it to the model)
            fullContent = fullContent.replace(/\[MEMORY\].*$/is, '').trim();
        }

        let hudDirective = null;
        if (!isRoom) {
            const extractedHud = extractChatHudDirective(fullContent);
            fullContent = extractedHud.text;
            hudDirective = extractedHud.update;
        }

        // Scrub tool/engine artifacts models emit as plain text
        fullContent = scrubNarrativeArtifacts(fullContent);
        if (state.globalSettings.slopStripper) fullContent = stripSlop(fullContent);
        fullContent = applyRegexScripts(fullContent, 'ai');

        aiMsgDiv.classList.remove('is-generating');

        if (!fullContent && !requestBody._reasoningContent) {
            fullContent = '[Model returned an empty response. This may be due to a strict safety filter or an API timeout.]';
            aiMsgDiv.innerHTML = formatMessageContent(fullContent, 'ai');
        }

        if (!isRoom) await updateChatHudFromTurn(targetChar, session, text, fullContent, hudDirective);
        const hudAfterTurn = !isRoom ? safeJsonClone(ensureChatHudState(targetChar, session).state) : null;

        const newAiMsg = { id: newChatMemoryId('message'), role: 'assistant', content: fullContent, charId: targetChar.id,
            hudBefore: hudBeforeTurn || undefined, hudAfter: hudAfterTurn || undefined };
        if (extractedChronicle) newAiMsg.ledgerEntry = extractedChronicle; // for ghost-cleanup on reroll/delete
        if (rerollVersions) {
            // Preserve prior takes: invariant is content === versions[currentVersion]
            newAiMsg.versions = [...rerollVersions, fullContent];
            newAiMsg.currentVersion = newAiMsg.versions.length - 1;
            newAiMsg.versionLedgerEntries = [...(rerollLedgerEntries || rerollVersions.map(() => null)), extractedChronicle || null];
        }
        session.messages.push(newAiMsg);
        if (extractedChronicle) recordImmediateChatMemory(session, config, extractedChronicle, targetChar);
        await saveState();
        recordSharedLibraryAssistantTurn();
        renderChat(); // Refresh to bind message actions

        // Trigger non-blocking rolling episodic memory consolidation
        consolidateSessionEpisodicMemory(session, config).catch(err => {
            console.warn("Consolidation error in background:", err);
        });

    } catch (err) {
        if (err.name === 'AbortError') {
            console.log('Generation aborted by user');
            fullContent = scrubNarrativeArtifacts(fullContent);
            if (fullContent && fullContent !== pre_ai_prefix) {
                const partialMsg = { id: newChatMemoryId('message'), role: 'assistant', content: fullContent, charId: targetChar.id };
                if (rerollVersions) {
                    partialMsg.versions = [...rerollVersions, fullContent];
                    partialMsg.currentVersion = partialMsg.versions.length - 1;
                }
                session.messages.push(partialMsg);
                await saveState();
                renderChat();
            } else if (rerollVersions) {
                // Aborted reroll with nothing streamed — restore the previous response
                if (!isRoom && rerollHudAfter) session.chatHudState = safeJsonClone(rerollHudAfter);
                const restoredMsg = {
                    id: newChatMemoryId('message'),
                    role: 'assistant',
                    content: rerollVersions[rerollVersions.length - 1],
                    charId: targetChar.id,
                    versions: rerollVersions.length > 1 ? rerollVersions : undefined,
                    currentVersion: rerollVersions.length > 1 ? rerollVersions.length - 1 : undefined,
                    versionLedgerEntries: rerollVersions.length > 1 ? rerollLedgerEntries : undefined,
                    hudBefore: rerollHudBefore || undefined,
                    hudAfter: rerollHudAfter || undefined
                };
                // Re-add the restored take's chronicle line (stripped at reroll start)
                const restoredEntry = rerollLedgerEntries ? rerollLedgerEntries[rerollLedgerEntries.length - 1] : null;
                if (restoredEntry) {
                    appendWorldLedgerEntry(session, restoredEntry);
                    restoredMsg.ledgerEntry = restoredEntry;
                }
                session.messages.push(restoredMsg);
                await saveState();
                renderChat();
            } else {
                aiMsgDiv.remove();
            }
            return;
        }

        aiMsgDiv.remove(); // Remove the broken "..." bubble

        // Failed reroll: restore the previous response instead of losing it
        if (isReroll && rerollVersions) {
            if (!isRoom && rerollHudAfter) session.chatHudState = safeJsonClone(rerollHudAfter);
            const restoredMsg = {
                id: newChatMemoryId('message'),
                role: 'assistant',
                content: rerollVersions[rerollVersions.length - 1],
                charId: targetChar.id,
                versions: rerollVersions.length > 1 ? rerollVersions : undefined,
                currentVersion: rerollVersions.length > 1 ? rerollVersions.length - 1 : undefined,
                versionLedgerEntries: rerollVersions.length > 1 ? rerollLedgerEntries : undefined,
                hudBefore: rerollHudBefore || undefined,
                hudAfter: rerollHudAfter || undefined
            };
            // Re-add the restored take's chronicle line (stripped at reroll start)
            const restoredEntry = rerollLedgerEntries ? rerollLedgerEntries[rerollLedgerEntries.length - 1] : null;
            if (restoredEntry) {
                appendWorldLedgerEntry(session, restoredEntry);
                restoredMsg.ledgerEntry = restoredEntry;
            }
            session.messages.push(restoredMsg);
        }

        // If they just typed a message, give it back to them
        if (!isReroll && text) {
            const session = getCurrentSession();
            const lastMsg = session.messages[session.messages.length - 1];
            if (lastMsg && lastMsg.role === 'user') {
                session.messages.pop(); // remove from transcript
                document.getElementById('user-input').value = text; // restore raw text to box
                document.getElementById('user-input').style.height = 'auto';
            }
        }
        
        await saveState();
        renderChat(); // Reset UI safely
        
        showToast('API Error: ' + humanizeApiError(err), 'error');
    } finally {
        generationController = null;
        sendBtn.innerHTML = '➤';
        sendBtn.classList.remove('stop');
        sendBtn.disabled = !userInput.value.trim() || (!state.activeCharId && !state.activeRoomId);
    }
}

// --- AI Utilities ---

/**
 * Scrub engine/tool artifacts that models emit as plain text: XML-ish tool-call
 * wrappers, JSON payloads printed inline, legacy state tags, and system-header
 * echoes. Applied to every narrative before it is shown or saved.
 */
// Every field the engine understands from an update_world_state payload.
const ENGINE_STATE_KEYS = Object.freeze([
    'location_id', 'location_introduced', 'location_state_updates', 'npc_moves', 'stat_changes',
    'stat_change_cause', 'capability_progress', 'transactions', 'checks', 'player_condition_updates', 'inventory_add',
    'inventory_remove', 'npc_observations', 'npc_introduced', 'npc_goal_updates',
    'npc_disposition_changes', 'npc_relationship_updates', 'npc_status_changes', 'schedule_updates',
    'world_events', 'faction_updates', 'economy_updates', 'player_preference_updates',
    'player_identity_update', 'threads_update', 'time_skip_minutes', 'ledger_update', 'quests_update', 'outfit_update'
]);

/**
 * Some models — reasoning models especially, and any model working under a heavy
 * system preset — narrate the scene and then print the state payload as text
 * instead of emitting a real tool call. Scrubbing that away silently discards
 * the turn's state: the NPC who "walks in" never actually arrives, the ledger
 * never moves. This recovers the payload so it can be applied instead of lost.
 */
function extractInlineWorldStatePayload(text) {
    const source = String(text || '');
    if (!source) return null;
    const hasEngineKey = value => value && typeof value === 'object' && !Array.isArray(value)
        && ENGINE_STATE_KEYS.some(key => Object.prototype.hasOwnProperty.call(value, key));

    // The explicit channel opened for models that never emit tool calls. It is
    // unambiguous, so it wins over anything found loose in the prose.
    const tagged = source.match(/<world_state_json>\s*([\s\S]*?)\s*<\/world_state_json>/i);
    if (tagged) {
        const parsed = safeParseJSONRepair(tagged[1]);
        if (hasEngineKey(parsed)) return parsed;
    }

    // Walk every '{' and take the first balanced object that parses and carries
    // engine keys. String-aware so braces inside prose values don't derail it.
    for (let start = source.indexOf('{'); start >= 0; start = source.indexOf('{', start + 1)) {
        let depth = 0;
        let quote = null;
        let escaped = false;
        for (let i = start; i < source.length; i++) {
            const char = source[i];
            if (quote) {
                if (escaped) escaped = false;
                else if (char === '\\') escaped = true;
                else if (char === quote) quote = null;
                continue;
            }
            if (char === '"' || char === "'") { quote = char; continue; }
            if (char === '{') depth++;
            else if (char === '}' && --depth === 0) {
                const candidate = source.slice(start, i + 1);
                try {
                    const parsed = safeParseJSONRepair(candidate);
                    if (!parsed) throw new Error('Not JSON');
                    if (hasEngineKey(parsed)) return parsed;
                    // Providers sometimes wrap it: {"name":"update_world_state","arguments":{...}}
                    const nested = parsed?.arguments ?? parsed?.parameters ?? parsed?.args;
                    if (typeof nested === 'string') {
                        const inner = safeParseJSONRepair(nested);
                        if (hasEngineKey(inner)) return inner;
                    } else if (hasEngineKey(nested)) {
                        return nested;
                    }
                } catch (error) { /* not valid JSON — keep scanning */ }
                break;
            }
        }
    }
    return null;
}

function accumulateWorldToolCall(streamedToolCalls, tc) {
    if (!tc || typeof tc !== 'object') return;
    let key = Number.isInteger(tc.index) ? `index:${tc.index}` : '';
    if (!key && tc.id) {
        const existingById = [...streamedToolCalls.entries()].find(([, call]) => call.id === tc.id);
        key = existingById?.[0] || `id:${tc.id}`;
    }
    if (!key) {
        const calls = [...streamedToolCalls.entries()];
        if (calls.length === 1) key = calls[0][0];
        else {
            const name = String(tc.function?.name || '');
            const compatible = calls.filter(([, call]) => !name || !call.function.name || call.function.name === name);
            key = compatible.length === 1 ? compatible[0][0] : `anonymous:${streamedToolCalls.size}`;
        }
    }
    const existing = streamedToolCalls.get(key) || {
        id: tc.id || `call_${streamedToolCalls.size + 1}`,
        type: 'function',
        function: { name: '', arguments: '' }
    };
    if (tc.id) existing.id = tc.id;
    if (tc.function?.name) existing.function.name = tc.function.name;
    if (tc.function?.arguments !== undefined && tc.function?.arguments !== null) {
        const fragment = typeof tc.function.arguments === 'string'
            ? tc.function.arguments : JSON.stringify(tc.function.arguments);
        // Some OpenAI-compatible providers resend the entire arguments object
        // on every delta instead of sending fragments. Prefer the complete
        // object rather than producing `{"x":1}{"x":1}`.
        if (fragment && existing.function.arguments && safeParseJSONRepair(fragment)
            && fragment.trim().startsWith('{')) {
            existing.function.arguments = fragment;
        } else if (fragment && fragment !== existing.function.arguments) {
            existing.function.arguments += fragment;
        }
    }
    streamedToolCalls.set(key, existing);
}

function parseWorldToolArguments(raw) {
    let parsed = raw && typeof raw === 'object' ? raw : safeParseJSONRepair(raw || '{}');
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        throw new Error('Tool arguments were not a valid JSON object.');
    }
    const nested = parsed.arguments ?? parsed.parameters ?? parsed.args;
    if (!ENGINE_STATE_KEYS.some(key => Object.prototype.hasOwnProperty.call(parsed, key)) && nested) {
        const unwrapped = typeof nested === 'string' ? safeParseJSONRepair(nested) : nested;
        if (unwrapped && typeof unwrapped === 'object' && !Array.isArray(unwrapped)) parsed = unwrapped;
    }
    return parsed;
}

// A few compatible providers wrap tool arguments in a { receipt: {...} }
// envelope even though the native tool schema does not require it. The
// validator can tolerate that envelope, but Sidecar's promotion, traversal,
// audit and temporal-evidence adapters must all inspect the *same* receipt the
// reducer receives. Normalize it here, once, before Sidecar begins its work.
function unwrapSidecarCommitReceipt(raw) {
    const parsed = parseWorldToolArguments(raw);
    // Strict providers may receive the compact native Sidecar transport:
    // commit_world_turn({ receipt_json: "{...}" }). Decode it before every
    // Sidecar adapter and the canonical reducer inspect the receipt, so this
    // stays one native tool call rather than a parallel text-receipt path.
    const packed = parsed?.receipt_json ?? parsed?.receiptJson ?? parsed?.receipt;
    if (typeof packed === 'string') {
        const unpacked = safeParseJSONRepair(packed);
        if (isPlainObject(unpacked)) return unpacked;
        throw new Error('The Sidecar commit tool returned an invalid receipt_json payload.');
    }
    if (isPlainObject(packed)) return packed;
    return parsed;
}

const WORLD_TURN_EVENT_TYPES = Object.freeze([
    'movement', 'activity', 'interaction', 'outfit', 'inventory', 'condition',
    'time', 'observation', 'status', 'relationship', 'quest', 'discovery',
    'environment', 'dialogue', 'other'
]);

function resolveWorldActorId(world, sess, actorRef) {
    const raw = String(actorRef || '').trim();
    if (!raw) return null;
    if (/^(?:player|user|pc|protagonist)$/i.test(raw)) return 'player';
    return resolveNpcId(world, raw, sess);
}

function buildWorldSceneFrame(world, sess) {
    const present = sessionNpcs(world, sess)
        .filter(npc => isNpcActive(sess.entityStates?.[npc.id])
            && sess.entityStates?.[npc.id]?.location === sess.playerLocation)
        .map(npc => npc.id)
        .sort();
    const activities = {
        player: {
            activity: String(sess.playerActivity || '').slice(0, 180),
            interacting_with: []
        }
    };
    present.forEach(id => {
        const entState = sess.entityStates?.[id] || {};
        activities[id] = {
            activity: String(entState.currentActivity || entState.activity || '').slice(0, 180),
            interacting_with: (Array.isArray(entState.interactingWith) ? entState.interactingWith : [])
                .map(ref => resolveWorldActorId(world, sess, ref)).filter(Boolean).slice(0, 12)
        };
    });
    const nearby = Object.entries(sess.sceneNearbyCharacters || {})
        .filter(([id, entry]) => id && entry && !present.includes(id)
            && sessionNpcs(world, sess).some(npc => npc.id === id)
            && isNpcActive(sess.entityStates?.[id]))
        .map(([id, entry]) => ({
            id,
            mode: String(entry.mode || 'nearby').slice(0, 40),
            reason: String(entry.reason || '').slice(0, 360),
            location_id: String(sess.entityStates?.[id]?.location || '').slice(0, 120),
            source_turn: Number(entry.source_turn) || 0
        }))
        .sort((a, b) => a.id.localeCompare(b.id));
    return {
        player_location_id: String(sess.playerLocation || ''),
        present_character_ids: present,
        // Physically absent characters who remain materially established in
        // this scene (audible, nearby, or otherwise off-screen involved).
        // This is scene context, never a location mutation or a presence
        // assertion. It gives the Context Compiler and HUD a truthful third
        // state between "here" and a merely historical name mention.
        nearby_character_ids: nearby.map(entry => entry.id),
        nearby_characters: nearby,
        activities
    };
}

function buildKernelLocationManifest(world, sess, userInput) {
    const view = typeof worldForSession === 'function' ? worldForSession(world, sess) : world;
    const locations = view.locations;
    const kernel = normalizeWorldKernelConfig(world);
    // Sidecar has its own canonical scene packet and reference manifest.
    // Applying the older Kernel trim before the Narrator sees the turn can
    // hide locations that Sidecar subsequently needs to reconcile.
    const sidecarTimeline = window.HordeSidecarHooks?.isSidecarWorld?.(world, sess) === true;
    if (sidecarTimeline || !kernel.enabled || locations.length <= kernel.sceneLocationLimit) {
        return locations.map(location => `  - "${location.name}" → id: "${location.id}"`).join('\n');
    }
    const selected = new Map();
    const add = (location, priority, reason) => {
        if (!location?.id) return;
        const prior = selected.get(location.id);
        if (!prior || priority > prior.priority) selected.set(location.id, { location, priority, reason });
    };
    const current = getLocationRef(view, sess?.playerLocation);
    add(current, 1000, 'current');

    // Two-hop graph neighborhood: enough for sensible movement without shipping
    // a 300-place town bible on a conversation inside one kitchen.
    let frontier = current ? [current] : [];
    const visited = new Set(frontier.map(location => location.id));
    for (let depth = 1; depth <= 2; depth++) {
        const next = [];
        frontier.forEach(location => {
            (location.exits || []).forEach(exit => {
                const target = resolveWorldExitTarget(view, exit);
                if (!target) return;
                add(target, 850 - depth * 100, `hop_${depth}`);
                if (!visited.has(target.id)) { visited.add(target.id); next.push(target); }
            });
            const parent = resolveWorldContainmentParent(view, location);
            if (parent) add(parent, 820 - depth * 80, 'container');
            locations.filter(candidate => candidate.parentLocationId === location.id)
                .slice(0, 12).forEach(child => add(child, 760 - depth * 60, 'contained'));
        });
        frontier = next;
    }

    const input = normalizeLocationSearchText(userInput);
    if (input) {
        locations.forEach(location => {
            const name = normalizeLocationSearchText(location.name);
            const id = normalizeLocationSearchText(location.id);
            if ((name.length > 2 && ` ${input} `.includes(` ${name} `))
                || (id.length > 2 && ` ${input} `.includes(` ${id} `))) add(location, 980, 'player_reference');
        });
        const movementPhrase = extractUserMovementTarget(userInput);
        const movementTarget = movementPhrase
            ? resolveWorldMovementTarget(typeof worldForSession === 'function' ? worldForSession(world, sess) : world, sess.playerLocation, movementPhrase) : null;
        if (movementTarget) add(movementTarget, 990, 'movement_target');
    }

    (sess?.quests || []).filter(quest => quest.status === 'active').slice(0, 12).forEach(quest => {
        (quest.objectives || []).forEach(objective => {
            const target = getLocationRef(view, objective.target || objective.locationId || objective.location_id);
            if (target) add(target, 620, 'quest');
        });
    });
    (sess?.scheduledEvents || []).filter(event => event.status === 'scheduled').slice(0, 10).forEach(event => {
        const location = getLocationRef(view, event.locationId || event.location_id);
        if (location) add(location, 590, 'scheduled');
    });

    const chosen = [...selected.values()]
        .sort((a, b) => b.priority - a.priority || String(a.location.name).localeCompare(String(b.location.name)))
        .slice(0, kernel.sceneLocationLimit);
    const omitted = Math.max(0, locations.length - chosen.length);
    return chosen.map(({ location, reason }) => `  - "${location.name}" → id: "${location.id}" [${reason}]`).join('\n')
        + (omitted ? `\n  - … ${omitted} distant locations omitted by World Kernel; referenced places are loaded on demand.` : '');
}

function compactWorldToolContract(tools) {
    const strip = value => {
        if (Array.isArray(value)) return value.forEach(strip);
        if (!isPlainObject(value)) return;
        delete value.description;
        delete value.examples;
        delete value.default;
        Object.values(value).forEach(strip);
    };
    tools.forEach(tool => {
        const name = tool.function?.name;
        strip(tool.function?.parameters);
        if (tool.function) tool.function.description = name === 'commit_world_turn'
            ? 'Commit the canonical ending scene and only completed durable changes.'
            : 'Reveal one gated secret that the player actually investigated.';
    });
    return tools;
}

async function impersonateUser() {
    if (generationController) return showToast('Please wait for current generation to finish.', 'info');
    if (!hasApiCredentials()) return showToast('API Key missing (Settings).', 'error');

    const isRoom = !!state.activeRoomId;
    const session = getCurrentSession();
    if (!session || !session.messages || !session.messages.length) return showToast('No history to write from.', 'info');

    const config = isRoom
        ? state.rooms.find(r => r.id === state.activeRoomId)
        : state.characters.find(c => c.id === state.activeCharId);
    if (!config) return;

    const persona = state.personas.find(p => p.id === state.activePersonaId);
    const personaDesc = persona ? personaPromptText(persona) : 'An engaged roleplayer.';

    const history = session.messages.slice(-20)
        .map(m => `${m.role === 'user' ? 'PLAYER' : 'CHARACTER'}: ${m.content}`)
        .join('\n\n');

    const btn = document.getElementById('impersonate-btn');
    const inputEl = document.getElementById('user-input');
    btn.disabled = true;
    btn.textContent = '⏳ Writing...';

    try {
        const response = await fetch(apiBase() + '/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', ...authHeaders() },
            body: JSON.stringify(applyOpenRouterRouting({
                model: config.model || state.globalSettings.defaultModel,
                max_tokens: 400,
                messages: [
                    { role: 'system', content: `You are ghost-writing the PLAYER's next message in a roleplay. Write ONLY the player's reply — in first person, matching their voice and the scene's tone. No quotation wrappers, no meta-commentary, no character (non-player) dialogue.\n\nPLAYER PERSONA:\n${personaDesc}` },
                    { role: 'user', content: `Recent roleplay:\n\n${history}\n\nWrite the player's next message:` }
                ]
            }, config))
        });
        if (!response.ok) throw new Error((await response.json().catch(() => ({}))).error?.message || response.statusText);
        const draft = (await response.json()).choices?.[0]?.message?.content?.trim();
        if (!draft) throw new Error('Model returned an empty draft');

        inputEl.value = draft;
        inputEl.style.height = 'auto';
        inputEl.style.height = inputEl.scrollHeight + 'px';
        inputEl.dispatchEvent(new Event('input')); // enable send button
        inputEl.focus();
        showToast('Draft ready — edit or send.', 'success');
    } catch (err) {
        showToast('Impersonate failed: ' + err.message, 'error');
    } finally {
        btn.disabled = false;
        btn.textContent = '✍️ Write for me';
    }
}

async function getEmbedding(text) {
    if (!hasEmbeddingCredentials()) throw new Error('Embedding provider is not configured');
    const response = await fetch(embeddingApiBase() + '/embeddings', {
        method: 'POST',
        headers: {
            ...embeddingAuthHeaders(),
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            input: text,
            model: state.globalSettings.embeddingModel || 'openai/text-embedding-3-small'
        })
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error?.message || 'Embedding failed');
    const vector = data?.data?.[0]?.embedding;
    if (!Array.isArray(vector) || !vector.length) throw new Error('Embedding server returned no vector');
    return vector;
}

function cosineSimilarity(vecA, vecB) {
    if (!Array.isArray(vecA) || !Array.isArray(vecB) || vecA.length === 0 || vecA.length !== vecB.length) return 0;
    let dotProduct = 0;
    let normA = 0;
    let normB = 0;
    for (let i = 0; i < vecA.length; i++) {
        dotProduct += vecA[i] * vecB[i];
        normA += vecA[i] * vecA[i];
        normB += vecB[i] * vecB[i];
    }
    const denominator = Math.sqrt(normA) * Math.sqrt(normB);
    return denominator ? dotProduct / denominator : 0;
}

// --- Data & Backup ---
function exportNexus() {
    if (!state.editingChar) return showToast('No character to export', 'error');
    const data = JSON.stringify(state.editingChar, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${state.editingChar.name.replace(/\s+/g, '_')}.nexus`;
    a.click();
}

// (removed: downloadTranscript — dead code, superseded by the inline
// download-chat-btn handler which also leaks no object URLs)

function importNexus(e) {
    const file = e.target.files[0];
    if (!file) return;
    if (file.size > 20 * 1024 * 1024) {
        showToast('Import failed: character file is larger than 20 MB.', 'error');
        return;
    }
    
    if (file.type === 'image/png') {
        importTavernPNG(file).then(async char => {
            state.characters.push(char);
            await saveState();
            state.editingChar = JSON.parse(JSON.stringify(char));
            state.activeCharId = char.id;
            showToast('SillyTavern Card Imported!', 'success');
            switchView('studio');
            renderLibrary();
        }).catch(err => showToast('PNG Import failed: ' + err.message, 'error'));
        return;
    }

    const reader = new FileReader();
    reader.onload = async (event) => {
        try {
            let json = JSON.parse(event.target.result);
            let charData = null;

            // Detect Format
            if (json.spec === 'chara_card_v2' || json.data) {
                // SillyTavern V2/V3
                charData = json.data || json;
            } else if (json.first_mes || json.personality) {
                // SillyTavern V1 (Flat)
                charData = json;
            }

            let char;
            if (charData) {
                char = mapTavernDataToNexus(charData);
            } else {
                // Nexus Native
                char = validateCharacterData(json);
                if (!char.model) char.model = state.globalSettings.defaultModel;
            }

            // Shrink oversized embedded images BEFORE validation — resize,
            // don't reject (users import genAI-sized art constantly)
            if (char.avatar && char.avatar.length > 250_000) {
                try { char.avatar = await optimizeImage(char.avatar, 512, 0.85); } catch (e) { console.warn('Avatar re-optimization failed:', e); }
            }
            if (char.bg && char.bg.length > 400_000) {
                try { char.bg = await optimizeImage(char.bg, 1280, 0.8); } catch (e) { console.warn('Background re-optimization failed:', e); }
            }

            char = validateCharacterData(char);

            // Unique ID to avoid conflicts
            if (!char.id || state.characters.some(c => c.id === char.id)) {
                char.id = 'char_' + Date.now();
            }

            state.characters.push(char);
            await saveState();
            
            state.editingChar = JSON.parse(JSON.stringify(char));
            state.activeCharId = char.id;
            
            showToast('Character Imported!', 'success');
            switchView('studio');
        } catch (err) {
            showToast('Import failed: ' + err.message, 'error');
        }
    };
    reader.readAsText(file);
}

function setupPresetImport() {
    const importBtn = document.getElementById('import-preset-btn');
    const fileInput = document.getElementById('preset-file-input');
    
    if (importBtn && fileInput) {
        importBtn.onclick = () => fileInput.click();
        fileInput.onchange = (e) => {
            const file = e.target.files[0];
            if (!file) return;
            
            const reader = new FileReader();
            reader.onload = async (event) => {
                try {
                    const json = validatePresetData(JSON.parse(event.target.result));
                    
                    const preset = {
                        id: 'preset_' + Date.now(),
                        name: json.name || file.name.replace('.json', ''),
                        data: json
                    };
                    
                    state.systemPresets.push(preset);
                    await saveState();
                    showToast('System Preset Imported!', 'success');
                    
                    // Update dropdown if in studio
                    if (state.view === 'studio' && state.editingChar) {
                        loadStudioData();
                    }
                } catch (err) {
                    showToast('Import failed: ' + err.message, 'error');
                }
            };
            reader.readAsText(file);
        };
    }
}

function setupPresetEditor() {
    const btn = document.getElementById('fine-tune-preset-btn');
    const overlay = document.getElementById('preset-editor-overlay');
    const closeBtn = document.getElementById('close-preset-editor-btn');
    const saveBtn = document.getElementById('save-preset-overrides-btn');

    if (btn) btn.onclick = () => {
        renderPresetEditor('char');
        overlay.classList.remove('hidden');
    };

    const wBtn = document.getElementById('w-fine-tune-preset-btn');
    if (wBtn) {
        wBtn.onclick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            if (!state.editingWorld || !state.editingWorld.activePresetId) {
                showToast('Select a preset first!', 'warning');
                return;
            }
            renderPresetEditor('world');
            overlay.classList.remove('hidden');
        };
    }

    if (closeBtn) closeBtn.onclick = () => overlay.classList.add('hidden');

    if (saveBtn) saveBtn.onclick = async () => {
        const type = overlay.dataset.mode || 'char';
        const target = type === 'char' ? state.editingChar : state.editingWorld;
        if (!target) return;
        
        const blocks = document.querySelectorAll('.preset-block-editor');
        const overrides = {};
        
        blocks.forEach(block => {
            const index = block.dataset.index;
            const enabled = block.querySelector('.preset-block-toggle').checked;
            const prompt = block.querySelector('.preset-block-text').value;
            overrides[index] = { enabled, prompt };
        });
        
        target.presetOverrides = overrides;
        target.presetOverridesFor = target.activePresetId;
        
        if (type === 'char') {
            await autoSaveStudioChanges();
        } else {
            await saveWorld();
        }
        
        overlay.classList.add('hidden');
        showToast(`Preset overrides applied to ${type === 'char' ? 'character' : 'world'}!`, 'success');
    };

    const presetSelect = document.getElementById('studio-system-preset');
    if (presetSelect) {
        presetSelect.onchange = (e) => {
            const val = e.target.value;
            if (btn) btn.style.display = val ? 'block' : 'none';
            if (state.editingChar) {
                if (state.editingChar.activePresetId !== val) state.editingChar.presetOverrides = {};
                state.editingChar.activePresetId = val;
                state.editingChar.presetOverridesFor = val;
            }
            autoSaveStudioChanges();
        };
    }
}

function renderPresetEditor(mode = 'char') {
    const overlay = document.getElementById('preset-editor-overlay');
    overlay.dataset.mode = mode;
    const c = mode === 'char' ? state.editingChar : state.editingWorld;
    if (!c || !c.activePresetId) return;
    
    const preset = getAllPresets().find(p => p.id === c.activePresetId);
    if (!preset || !preset.data || !preset.data.prompts) {
        showToast('Preset data not found!', 'error');
        return;
    }
    
    document.getElementById('preset-editor-title').textContent = `Fine-Tune: ${preset.name} (${mode === 'char' ? 'Character' : 'World'})`;
    const container = document.getElementById('preset-blocks-container');
    container.innerHTML = '';
    
    const overrides = c.presetOverrides || {};
    
    preset.data.prompts.forEach((p, idx) => {
        const override = overrides[idx] || {};
        const isEnabled = isPresetPromptEnabled(preset, p, override);
        const promptText = override.prompt !== undefined ? override.prompt : (p.content || p.prompt || '');
        
        const div = document.createElement('div');
        div.className = 'preset-block-editor';
        div.dataset.index = idx;
        div.style.background = 'var(--surface)';
        div.style.border = '1px solid var(--border)';
        div.style.borderRadius = '12px';
        div.style.padding = '16px';
        div.style.display = 'flex';
        div.style.flexDirection = 'column';
        div.style.gap = '10px';
        
        div.innerHTML = `
            <div style="display:flex; justify-content:space-between; align-items:center;">
                <div style="display:flex; align-items:center; gap:10px;">
                    <input type="checkbox" class="preset-block-toggle" ${isEnabled ? 'checked' : ''} aria-label="Enable prompt block" style="width:18px; height:18px; cursor:pointer;">
                    <span style="font-family:'Outfit',sans-serif; font-weight:500; color:var(--text);">${escapeHTML(p.name || 'Block ' + (idx + 1))}</span>
                </div>
                <div style="font-size:0.75rem; color:var(--text-3);">Position: ${p.injection_position === 0 ? 'System' : 'History'} (Depth: ${p.injection_depth || 0})</div>
            </div>
            <textarea class="form-textarea preset-block-text" rows="3" aria-label="Prompt block text" style="font-size:0.85rem; border-color:var(--border-dim);">${escapeHTML(promptText)}</textarea>
        `;
        
        container.appendChild(div);
    });
}

function mapTavernDataToNexus(charData) {
    const lorebook = [];
    if (charData.character_book && charData.character_book.entries) {
        charData.character_book.entries.forEach(entry => {
            lorebook.push({
                keyword: Array.isArray(entry.keys) ? entry.keys.join(', ') : (entry.key || ''),
                text: entry.content || entry.secondary_keys || '',
                weight: 'knowledge'
            });
        });
    }

    const promptParts = [];
    if (charData.system_prompt) promptParts.push(`### SYSTEM PROMPT\n${charData.system_prompt}`);
    if (charData.personality) promptParts.push(`### PERSONALITY\n${charData.personality}`);
    if (charData.scenario) promptParts.push(`### SCENARIO\n${charData.scenario}`);
    if (charData.mes_example) promptParts.push(`### MESSAGE EXAMPLES\n${charData.mes_example}`);
    if (charData.post_history_instructions) promptParts.push(`### POST-HISTORY INSTRUCTIONS\n${charData.post_history_instructions}`);

    const sourceExtensions = isPlainObject(charData.extensions) ? charData.extensions : {};
    const tavernExtensions = {};
    if (isPlainObject(sourceExtensions.chub)) {
        tavernExtensions.chub = safeJsonClone(sourceExtensions.chub);
    }
    if (isPlainObject(sourceExtensions.depth_prompt)) {
        tavernExtensions.depth_prompt = {
            prompt: String(sourceExtensions.depth_prompt.prompt || '').slice(0, 100_000),
            depth: livingClamp(parseInt(sourceExtensions.depth_prompt.depth) || 0, 0, 100),
            role: ['system', 'user', 'assistant'].includes(sourceExtensions.depth_prompt.role)
                ? sourceExtensions.depth_prompt.role : 'system'
        };
    }
    const alternateGreetings = (Array.isArray(charData.alternate_greetings) ? charData.alternate_greetings : [])
        .map(value => String(value || '').trim())
        .filter(Boolean)
        .slice(0, 100);
    const tags = (Array.isArray(charData.tags) ? charData.tags : [])
        .map(value => String(value || '').trim())
        .filter(Boolean)
        .slice(0, 100);
    const chubPath = String(sourceExtensions.chub?.full_path || '').trim();

    return {
        id: 'char_' + Date.now(),
        name: charData.name || 'Imported Bot',
        desc: charData.description || charData.creator_notes || '',
        prompt: promptParts.join('\n\n') || '(No description)',
        intro: charData.first_mes || '',
        creatorNotes: String(charData.creator_notes || ''),
        alternateGreetings,
        tags,
        tavernExtensions,
        sourceUrl: chubPath ? `https://chub.ai/characters/${chubPath.replace(/^\/+/, '')}` : '',
        model: state.globalSettings.defaultModel || '',
        temp: 0.9,
        maxTokens: 2048,
        contextSize: 8192,
        memory: [],
        lorebook: lorebook
    };
}

// --- SillyTavern PNG Card Parser ---
async function importTavernPNG(file) {
    if (file.size > 20 * 1024 * 1024) throw new Error('PNG card is larger than 20 MB');
    const buffer = await file.arrayBuffer();
    if (buffer.byteLength < 12) throw new Error('PNG file is truncated');
    const view = new DataView(buffer);
    
    // Check PNG signature
    if (view.getUint32(0) !== 0x89504E47 || view.getUint32(4) !== 0x0D0A1A0A) {
        throw new Error('Not a valid PNG file');
    }
    
    let offset = 8;
    let charData = null;
    
    while (offset + 12 <= buffer.byteLength) {
        const length = view.getUint32(offset);
        if (length < 0 || offset + length + 12 > buffer.byteLength) throw new Error('PNG chunk is malformed');
        const type = String.fromCharCode(
            view.getUint8(offset + 4),
            view.getUint8(offset + 5),
            view.getUint8(offset + 6),
            view.getUint8(offset + 7)
        );
        
        if (type === 'tEXt' || type === 'iTXt') {
            const data = new Uint8Array(buffer, offset + 8, length);
            const text = new TextDecoder().decode(data);
            
            if (text.startsWith('chara\0')) {
                const base64 = text.slice(6);
                charData = JSON.parse(atob(base64));
                break;
            } else if (text.includes('chara')) {
                // Some variants use different separators
                const parts = text.split(/\0/);
                const charIndex = parts.findIndex(p => p === 'chara');
                if (charIndex !== -1 && parts[charIndex + 1]) {
                    charData = JSON.parse(atob(parts[charIndex + 1]));
                    break;
                }
            }
        }
        
        offset += length + 12; // Length(4) + Type(4) + Data(N) + CRC(4)
    }
    
    if (!charData) throw new Error('No SillyTavern character data found in PNG');
    
    // V2/V3 cards wrap the real character data in a "data" envelope
    if (charData.spec === 'chara_card_v2' || charData.spec === 'chara_card_v3' || charData.data) {
        charData = charData.data || charData;
    }
    
    // Map Tavern fields to Horde Studio
    const char = mapTavernDataToNexus(charData);
    
    // Handle avatar — Tavern cards are often 1024px+ AI images; store a
    // resized copy, never the raw card PNG (megabytes per character otherwise)
    const blob = new Blob([buffer], { type: 'image/png' });
    const rawAvatar = await new Promise(r => {
        const reader = new FileReader();
        reader.onload = e => r(e.target.result);
        reader.readAsDataURL(blob);
    });
    try {
        char.avatar = await optimizeImage(rawAvatar, 512, 0.8);
    } catch (e) {
        console.warn('Avatar optimization failed, storing raw:', e);
        char.avatar = rawAvatar;
    }

    return char;
}

// --- Global Settings ---
const SETTINGS_SECTION_LABELS = Object.freeze({
    models: 'AI & Models',
    accounts: 'Connections',
    images: 'Images & Workflows',
    behavior: 'Behavior & Output',
    memory: 'Memory',
    appearance: 'Editor Appearance',
    runtime: 'Local Runtime',
    data: 'Data & Backup'
});
let activeSettingsSection = 'models';

function activateSettingsSection(sectionId, options = {}) {
    const content = document.getElementById('settings-content');
    const search = document.getElementById('settings-search-input');
    const validId = SETTINGS_SECTION_LABELS[sectionId] ? sectionId : 'models';
    activeSettingsSection = validId;
    state.settingsSection = validId;
    persistWorkspaceSoon();
    if (options.clearSearch !== false && search) search.value = '';
    if (content) content.classList.remove('is-searching');
    document.querySelectorAll('[data-settings-section]').forEach(section => {
        section.classList.toggle('active', section.dataset.settingsSection === validId);
        section.classList.remove('search-match');
    });
    document.querySelectorAll('[data-settings-target]').forEach(button => {
        const selected = button.dataset.settingsTarget === validId;
        button.classList.toggle('active', selected);
        button.setAttribute('aria-current', selected ? 'page' : 'false');
    });
    document.getElementById('settings-search-empty')?.classList.add('hidden');
    const footer = document.getElementById('settings-footer-context');
    if (footer) footer.textContent = SETTINGS_SECTION_LABELS[validId];
    if (options.scroll !== false && content) content.scrollTop = 0;
}

function searchSettings(query) {
    const content = document.getElementById('settings-content');
    if (!content) return;
    const normalized = String(query || '').trim().toLowerCase();
    if (!normalized) {
        activateSettingsSection(activeSettingsSection, { clearSearch: false });
        return;
    }
    content.classList.add('is-searching');
    document.querySelectorAll('[data-settings-target]').forEach(button => button.classList.remove('active'));
    let matches = 0;
    document.querySelectorAll('[data-settings-section]').forEach(section => {
        const fieldWords = [...section.querySelectorAll('input, select, textarea, button')]
            .map(field => `${field.getAttribute('placeholder') || ''} ${field.getAttribute('aria-label') || ''} ${field.name || ''}`)
            .join(' ');
        const haystack = `${section.dataset.settingsKeywords || ''} ${section.textContent || ''} ${fieldWords}`.toLowerCase();
        const match = normalized.split(/\s+/).every(term => haystack.includes(term));
        section.classList.toggle('search-match', match);
        section.classList.remove('active');
        if (match) matches += 1;
    });
    document.getElementById('settings-search-empty')?.classList.toggle('hidden', matches > 0);
    const footer = document.getElementById('settings-footer-context');
    if (footer) footer.textContent = matches ? `${matches} matching section${matches === 1 ? '' : 's'}` : 'No matches';
    content.scrollTop = 0;
}

function setupSettingsNavigation() {
    document.querySelectorAll('[data-settings-target]').forEach(button => {
        button.onclick = () => activateSettingsSection(button.dataset.settingsTarget);
    });
    const search = document.getElementById('settings-search-input');
    if (search) search.oninput = event => searchSettings(event.target.value);
    const cancel = document.getElementById('cancel-global-settings');
    if (cancel) cancel.onclick = hideGlobalSettings;
    document.addEventListener('keydown', event => {
        const modal = document.getElementById('modal-overlay');
        if (!modal || modal.classList.contains('hidden')) return;
        if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') {
            event.preventDefault();
            search?.focus();
            search?.select();
        } else if (event.key === 'Escape' && !document.getElementById('regex-modal-overlay')?.classList.contains('hidden')) {
            return;
        } else if (event.key === 'Escape') {
            hideGlobalSettings();
        }
    });
}

function refreshSettingsProviderCards(activeProvider = state.globalSettings.apiProvider) {
    const keys = {
        openrouter: document.getElementById('global-api-key')?.value || state.apiKey,
        gptproto: document.getElementById('global-gptproto-key')?.value || state.gptprotoApiKey,
        nanogpt: document.getElementById('global-nanogpt-key')?.value || state.nanogptApiKey,
        nvidia: document.getElementById('global-nvidia-key')?.value || state.nvidiaApiKey,
        bedrock: document.getElementById('global-bedrock-key')?.value || state.bedrockApiKey,
        custom: document.getElementById('global-custom-api-key')?.value || state.customApiKey
    };
    document.querySelectorAll('.settings-provider-card[data-provider]').forEach(card => {
        const providerId = card.dataset.provider;
        const configured = !!String(keys[providerId] || '').trim();
        const selected = providerId === activeProvider;
        card.classList.toggle('has-key', configured);
        card.classList.toggle('is-active', selected);
        if (selected) card.open = true;
        const status = card.querySelector('.settings-provider-state');
        if (status) status.textContent = selected ? 'Active' : configured ? 'Connected' : providerId === 'custom' ? 'Advanced' : 'Configure';
    });
}

async function refreshMcpSettingsStatus(options = {}) {
    const badge = document.getElementById('mcp-bridge-badge');
    const result = document.getElementById('mcp-settings-result');
    const bridgeInput = document.getElementById('global-mcp-bridge-url');
    if (bridgeInput?.value.trim()) {
        state.globalSettings.mcpBridgeUrl = normalizeMcpBridgeUrl(bridgeInput.value);
        bridgeInput.value = state.globalSettings.mcpBridgeUrl;
    }
    try {
        await mcpBridgeRequest('/health', { timeoutMs: 4000 });
        if (badge) {
            badge.textContent = 'Bridge online';
            badge.classList.add('online');
        }
        const data = await mcpBridgeRequest('/providers', { timeoutMs: 6000 });
        (Array.isArray(data.providers) ? data.providers : []).forEach(provider => {
            const card = document.querySelector(`[data-mcp-provider-card="${provider.id}"]`);
            const status = document.getElementById(`mcp-${provider.id}-status`);
            const button = document.querySelector(`[data-mcp-connect="${provider.id}"]`);
            card?.classList.toggle('connected', provider.connected === true);
            if (status) status.textContent = provider.connected ? 'Connected securely' : 'Not connected';
            if (button) {
                button.textContent = provider.connected ? 'Disconnect' : 'Connect';
                button.dataset.connected = provider.connected ? 'true' : 'false';
            }
        });
        if (result && options.announce) result.textContent = 'Local MCP bridge is online.';
        return data;
    } catch (error) {
        if (badge) {
            badge.textContent = 'Bridge offline';
            badge.classList.remove('online');
        }
        if (result) result.textContent = error.message;
        document.querySelectorAll('[data-mcp-provider-card]').forEach(card => card.classList.remove('connected'));
        document.querySelectorAll('[data-mcp-connect]').forEach(button => {
            button.textContent = 'Connect';
            button.dataset.connected = 'false';
        });
        return null;
    }
}

async function connectMcpProvider(providerId, button) {
    const provider = HORDE_MCP_PROVIDERS[providerId];
    const result = document.getElementById('mcp-settings-result');
    if (!provider || !button) return;
    if (button.dataset.connected === 'true') {
        button.disabled = true;
        try {
            await mcpBridgeRequest(`/providers/${providerId}/disconnect`, { method: 'POST', body: {} });
            if (result) result.textContent = `${provider.label} disconnected.`;
            await refreshMcpSettingsStatus();
        } catch (error) {
            if (result) result.textContent = error.message;
        } finally {
            button.disabled = false;
        }
        return;
    }
    const authWindow = window.open('about:blank', `horde-mcp-${providerId}`, 'width=720,height=820');
    button.disabled = true;
    if (result) result.textContent = `Preparing ${provider.label} authorization…`;
    try {
        const response = await mcpBridgeRequest(`/providers/${providerId}/connect`, {
            method: 'POST', body: {}, timeoutMs: 30000
        });
        if (response.connected) {
            authWindow?.close();
            if (result) result.textContent = `${provider.label} is connected · ${response.toolCount || 0} tools discovered.`;
            await refreshMcpSettingsStatus();
            return;
        }
        if (!response.authUrl) throw new Error('The bridge did not return an authorization URL.');
        if (authWindow) authWindow.location.href = response.authUrl;
        else window.open(response.authUrl, '_blank', 'noopener');
        if (result) result.textContent = `Finish signing in to ${provider.label} in the authorization window.`;
        const started = Date.now();
        const poll = setInterval(async () => {
            if (Date.now() - started > 120000) {
                clearInterval(poll);
                button.disabled = false;
                if (result) result.textContent = `${provider.label} authorization is still pending. Click Connect to check again.`;
                return;
            }
            try {
                const status = await mcpBridgeRequest(`/providers/${providerId}/status`, { timeoutMs: 4000 });
                if (!status.connected) return;
                clearInterval(poll);
                button.disabled = false;
                if (result) result.textContent = `${provider.label} connected. Its image tools are now available in Virtual Human Studio.`;
                await refreshMcpSettingsStatus();
            } catch (error) {
                // The authorization window may still be open; keep polling.
            }
        }, 2000);
    } catch (error) {
        authWindow?.close();
        button.disabled = false;
        if (result) result.textContent = `${provider.label} connection failed: ${error.message}`;
    }
}

