// --- Feedback ---
function showToast(msg, type = 'info') {
    const toast = document.createElement('div');
    toast.className = `toast ${type}`;
    toast.textContent = msg;
    document.getElementById('toast-container').appendChild(toast);
    setTimeout(() => toast.remove(), 3000);
}

function numericVersionParts(value) {
    const match = String(value || '').match(/\d+(?:\.\d+){0,3}/);
    return match ? match[0].split('.').map(part => Number(part) || 0) : [];
}

function compareAppVersions(candidate, current) {
    const a = numericVersionParts(candidate);
    const b = numericVersionParts(current);
    if (!a.length || !b.length) return 0;
    const length = Math.max(a.length, b.length);
    for (let index = 0; index < length; index++) {
        const difference = (a[index] || 0) - (b[index] || 0);
        if (difference) return difference > 0 ? 1 : -1;
    }
    return 0;
}

function showAppUpdateNotice(release) {
    const tag = String(release?.tag_name || release?.name || 'new release').trim();
    let dismissed = '';
    try { dismissed = localStorage.getItem('horde_update_dismissed') || ''; } catch (_) {}
    if (!tag || dismissed === tag || document.querySelector('.app-update-notice')) return;

    const notice = document.createElement('aside');
    notice.className = 'app-update-notice';
    notice.setAttribute('role', 'status');
    notice.innerHTML = `
        <span class="app-update-icon" aria-hidden="true">↑</span>
        <span class="app-update-copy">
            <strong>Horde Studio ${escapeHTML(tag)} is available</strong>
            <small>You are using ${escapeHTML(HORDE_STUDIO_VERSION)}.</small>
        </span>
        <a class="app-update-link" href="${escapeHTML(release?.html_url || HORDE_STUDIO_RELEASES_URL)}" target="_blank" rel="noopener noreferrer">View update</a>
        <button class="app-update-dismiss" type="button" aria-label="Dismiss this update">Later</button>`;
    notice.querySelector('.app-update-dismiss').onclick = () => {
        try { localStorage.setItem('horde_update_dismissed', tag); } catch (_) {}
        notice.remove();
    };
    document.body.appendChild(notice);
}

async function checkForAppUpdate() {
    const cacheKey = 'horde_update_check_cache_v1';
    const cacheDuration = 24 * 60 * 60 * 1000;
    let cached = null;
    try { cached = JSON.parse(localStorage.getItem(cacheKey) || 'null'); } catch (_) {}

    let release = cached?.release || null;
    if (!cached?.checkedAt || Date.now() - Number(cached.checkedAt) > cacheDuration) {
        try {
            const response = await fetch(HORDE_STUDIO_RELEASE_API, {
                headers: { Accept: 'application/vnd.github+json' },
                cache: 'no-store',
                referrerPolicy: 'no-referrer'
            });
            if (!response.ok) {
                // Cache "no public release" and rate-limit responses too, so a
                // local-first app never retries GitHub on every launch.
                try { localStorage.setItem(cacheKey, JSON.stringify({ checkedAt: Date.now(), release: null })); } catch (_) {}
                return;
            }
            const result = await response.json();
            if (result?.draft || result?.prerelease || !result?.tag_name) return;
            release = {
                tag_name: String(result.tag_name).slice(0, 80),
                name: String(result.name || '').slice(0, 160),
                html_url: /^https:\/\/github\.com\/ddkhan24\/hordestudio\/releases\//i.test(result.html_url || '')
                    ? result.html_url : HORDE_STUDIO_RELEASES_URL,
                published_at: String(result.published_at || '')
            };
            try { localStorage.setItem(cacheKey, JSON.stringify({ checkedAt: Date.now(), release })); } catch (_) {}
        } catch (_) {
            return; // Offline is a normal supported state.
        }
    }
    if (!release) return;

    const versionOrder = compareAppVersions(release.tag_name, HORDE_STUDIO_VERSION);
    const publishedAfterThisBuild = !numericVersionParts(release.tag_name).length
        && Date.parse(release.published_at || '') > Date.parse(HORDE_STUDIO_RELEASED_AT);
    if (versionOrder > 0 || publishedAfterThisBuild) showAppUpdateNotice(release);
}

// --- Summarizer Utility ---
async function summarizeStory() {
    // World context path
    if (state.view === 'worldPlay') {
        const world = state.worlds.find(w => w.id === state.activeWorldId);
        const sess = getCurrentWorldSession();
        if (!world || !sess) return showToast('No active world session', 'error');
        if (!sess.history || sess.history.length < 2) return showToast('Not enough history to summarize', 'info');

        showToast('Generating world summary...', 'info');
        const history = sess.history
            .map(m => `${m.role === 'user' ? 'Player' : 'DM'}: ${m.content}`)
            .join('\n\n');

        try {
            const response = await fetch(apiBase() + '/chat/completions', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', ...authHeaders() },
                body: JSON.stringify(applyOpenRouterRouting({
                    model: world.model || state.globalSettings.defaultModel,
                    messages: [
                        { role: 'system', content: `You are "Horde Chronos", the world chronicle keeper. Summarize this adventure concisely and dramatically.\n\nStructure:\n### 📜 THE STORY SO FAR\n[2-3 sentence narrative overview]\n\n### 🔑 KEY DEVELOPMENTS\n- [3 most important events or changes]\n\n### 📍 CURRENT STATE\n- Location, active quests, key NPC status` },
                        { role: 'user', content: `Summarize this world session:\n\n${history}` }
                    ]
                }, world))
            });
            if (!response.ok) throw new Error((await response.json().catch(() => ({}))).error?.message || 'API error');
            const summary = (await response.json()).choices[0].message.content;
            showConfirmModal('World Summary', summary, null, 'Close', 'Dismiss');
        } catch (err) {
            showToast('Summarization failed: ' + err.message, 'error');
        }
        return;
    }

    // Regular chat path
    const invokedFromStudio = state.view === 'studio' && !!state.editingChar?.id;
    const isRoom = !invokedFromStudio && !!state.activeRoomId;
    const sessionId = invokedFromStudio ? state.editingChar.id : (isRoom ? state.activeRoomId : state.activeCharId);
    const session = getSessionForOwner(sessionId);

    if (!session || !session.messages || session.messages.length < 2) {
        return showToast('Not enough history to summarize', 'info');
    }

    const config = isRoom ? state.rooms.find(r => r.id === sessionId) : state.characters.find(c => c.id === sessionId);
    if (!config) return showToast('Context config missing', 'error');

    // --- SAFE TRUNCATION: respect model context limits ---
    // Budget: 80k tokens max for history (leaves ~80k for system + output on a 163k model)
    // Use 3 chars/token as a conservative estimate
    const MAX_HISTORY_CHARS = 80_000 * 3; // ~240,000 characters

    const allMessages = session.messages || [];
    // Walk backwards from newest, accumulating until we hit the budget
    let usedChars = 0;
    let startIdx = allMessages.length;
    for (let i = allMessages.length - 1; i >= 0; i--) {
        const line = `${allMessages[i].role === 'user' ? 'User' : config.name}: ${allMessages[i].content}`;
        usedChars += line.length + 2; // +2 for \n\n
        if (usedChars > MAX_HISTORY_CHARS) break;
        startIdx = i;
    }

    const trimmedMessages = allMessages.slice(startIdx);
    const includedCount = trimmedMessages.length;
    const totalCount = allMessages.length;
    const wasTruncated = startIdx > 0;

    const history = trimmedMessages
        .map(m => `${m.role === 'user' ? 'User' : config.name}: ${m.content}`)
        .join('\n\n');
    
    if (!history) return showToast('No history to summarize', 'info');

    if (wasTruncated) {
        showToast(`Summarizing last ${includedCount} of ${totalCount} messages (context limit)...`, 'info');
    } else {
        showToast('Generating summary...', 'info');
    }

    try {
        const response = await fetch(apiBase() + '/chat/completions', {
            method: 'POST',
            headers: {
                ...authHeaders(),
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(applyOpenRouterRouting({
                model: config.model || state.globalSettings.defaultModel,
                max_tokens: 900,
                messages: [
                    { 
                        role: 'system', 
                        content: `You are the "Horde Chronos" - the ultimate story summarizer. 
                        Analyze the roleplay history and provide a high-fidelity, professional summary.
                        
                        Structure your response as follows:
                        ### 📜 THE STORY SO FAR
                        [A gripping 2-3 sentence narrative overview of the current plot arc]
                        
                        ### 🔑 KEY DEVELOPMENTS
                        - [A bullet point list of the 3 most important world or character changes]
                        
                        ### 🎭 CHARACTER STATUS
                        - **${config.name}**: [Current mood, goals, and position]
                        
                        Maintain the tone of the roleplay. Be concise, dramatic, and elite.` 
                    },
                    { role: 'user', content: `Summarize the following journey:\n\n${history}` }
                ]
            }, config))
        });

        if (!response.ok) {
            const errData = await response.json().catch(() => ({}));
            throw new Error(errData.error?.message || 'API error during summary');
        }

        const data = await response.json();
        const summary = data.choices[0].message.content;
        
        // Show in a modal first (reusing confirm modal with different behavior)
        showConfirmModal('Story Summary', summary, async () => {
            // "Confirm" in this context will save to memory
            showToast('Embedding summary...', 'info');
            try {
                const blocks = summaryToMemoryRecords(summary);
                if (invokedFromStudio) {
                    const index = state.characters.findIndex(character => character.id === config.id);
                    if (index === -1) throw new Error('The character being edited no longer exists');
                    const additions = [];
                    for (const block of blocks) {
                        const record = normalizeChatMemoryRecord(block, {
                            type: 'biography', scope: 'character', characterIds: [config.id], importance: 0.72
                        });
                        await hydrateChatMemoryEmbedding(record);
                        additions.push(record);
                    }
                    state.characters[index].memory = [...(state.characters[index].memory || []), ...additions];
                    if (state.editingChar?.id === config.id) state.editingChar.memory = safeJsonClone(state.characters[index].memory);
                } else {
                    const continuity = ensureChatContinuity(session, config.id);
                    const inserted = upsertContinuityMemoryRecords(continuity, blocks, {
                        type: 'manual_summary', scope: 'timeline', sourceSessionId: session.id,
                        sourceMessageIds: trimmedMessages.map(message => message.id).filter(Boolean),
                        startIndex: startIdx, endIndex: allMessages.length,
                        personaId: state.activePersonaId || ''
                    });
                    for (const record of inserted) await hydrateChatMemoryEmbedding(record);
                }
                await saveState();
                showToast('Summary added to memory!', 'success');
                if (state.view === 'studio') renderMemoryList();
            } catch (err) {
                showToast('Failed to save summary: ' + err.message, 'error');
            }
        }, 'Add to Memory', 'Close');

    } catch (err) {
        showToast('Summarization failed: ' + err.message, 'error');
    }
}

function summaryToMemoryRecords(summary) {
    const raw = String(summary || '').trim();
    const lines = raw.split('\n').map(line => line.replace(/^\s*(?:[-*•]|\d+[.)])\s*/, '').trim())
        .filter(line => line && !/^#{1,6}\s/.test(line));
    const records = [{
        type: 'manual_summary', key: `manual:${HordeVectorMemory.hashText(raw)}`,
        text: raw.slice(0, 6000), importance: 0.78, confidence: 0.9, pinned: true
    }];
    lines.filter(line => line.length >= 25 && line.length <= 1200).slice(0, 12).forEach((line, index) => {
        records.push({
            type: /promise|goal|must|owe|unresolved|seek|plan/i.test(line) ? 'thread' : 'fact',
            key: `manual_detail:${HordeVectorMemory.hashText(line)}:${index}`,
            text: line, importance: 0.68, confidence: 0.85
        });
    });
    return records;
}

// --- Custom Modal Helper ---
function showConfirmModal(title, msg, onConfirm, okText = 'Confirm', cancelText = 'Cancel') {
    const overlay = document.getElementById('confirm-modal-overlay');
    document.getElementById('confirm-title').textContent = title;
    document.getElementById('confirm-msg').textContent = msg;
    
    const okBtn = document.getElementById('confirm-ok-btn');
    const cancelBtn = document.getElementById('confirm-cancel-btn');

    okBtn.textContent = okText;
    cancelBtn.textContent = cancelText;

    // Widen the modal for long-form content (e.g. story summaries) so it's readable
    const modalEl = overlay.querySelector('.modal');
    if (modalEl) modalEl.classList.toggle('modal-confirm-wide', (msg || '').length > 280);

    overlay.classList.remove('hidden');

    okBtn.onclick = () => {
        overlay.classList.add('hidden');
        if (onConfirm) onConfirm();
    };

    cancelBtn.onclick = () => {
        overlay.classList.add('hidden');
    };
}

// --- Personas System ---
function normalizePersona(persona = {}) {
    return {
        ...persona,
        id: String(persona.id || `persona_${Date.now()}`).slice(0, 100),
        name: String(persona.name || 'Unnamed Persona').slice(0, 120),
        text: String(persona.text || '').slice(0, 12000),
        age: String(persona.age || '').slice(0, 40),
        pronouns: String(persona.pronouns || '').slice(0, 80),
        appearance: String(persona.appearance || '').slice(0, 2000),
        publicIdentity: String(persona.publicIdentity || '').slice(0, 2000),
        reputation: String(persona.reputation || '').slice(0, 2000),
        color: /^#[0-9a-f]{6}$/i.test(String(persona.color || ''))
            ? String(persona.color).toUpperCase() : '#4A90E2'
    };
}

function personaPromptText(persona) {
    if (!persona) return '';
    const p = normalizePersona(persona);
    return [
        `Name: ${p.name}`,
        p.age ? `Age: ${p.age}` : '',
        p.pronouns ? `Pronouns: ${p.pronouns}` : '',
        p.appearance ? `Visible appearance: ${p.appearance}` : '',
        p.publicIdentity ? `Public identity: ${p.publicIdentity}` : '',
        p.reputation ? `Reputation and what others may have heard: ${p.reputation}` : '',
        p.text ? `Additional roleplay notes: ${p.text}` : ''
    ].filter(Boolean).join('\n');
}

function setupPersonasLogic() {
    const btn = document.getElementById('personas-modal-btn');
    const overlay = document.getElementById('personas-modal-overlay');
    const closeBtn = document.getElementById('close-personas-btn');
    const nameInput = document.getElementById('persona-name');
    const descInput = document.getElementById('persona-desc');
    const colorInput = document.getElementById('persona-color');
    const structuredInputs = {
        age: document.getElementById('persona-age'),
        pronouns: document.getElementById('persona-pronouns'),
        appearance: document.getElementById('persona-appearance'),
        publicIdentity: document.getElementById('persona-public-identity'),
        reputation: document.getElementById('persona-reputation')
    };
    
    if (btn) btn.onclick = () => {
        renderPersonasList();
        overlay.classList.remove('hidden');
    };
    if (closeBtn) closeBtn.onclick = () => overlay.classList.add('hidden');

    document.getElementById('add-persona-btn').onclick = async () => {
        const p = normalizePersona({ id: 'persona_' + Date.now(), name: 'New Persona', text: '', color: '#4A90E2' });
        state.personas.push(p);
        state.activePersonaId = p.id;
        await saveState();
        renderPersonasList();
    };

    nameInput.oninput = () => {
        const p = state.personas.find(x => x.id === (document.getElementById('persona-edit-pane').dataset.id));
        if (p) p.name = nameInput.value;
    };
    nameInput.onblur = renderPersonasList;

    descInput.oninput = () => {
        const p = state.personas.find(x => x.id === (document.getElementById('persona-edit-pane').dataset.id));
        if (p) p.text = descInput.value;
    };
    colorInput.oninput = () => {
        const p = state.personas.find(x => x.id === document.getElementById('persona-edit-pane').dataset.id);
        if (p) p.color = /^#[0-9a-f]{6}$/i.test(colorInput.value) ? colorInput.value.toUpperCase() : '#4A90E2';
    };
    Object.entries(structuredInputs).forEach(([field, input]) => {
        if (!input) return;
        input.oninput = () => {
            const p = state.personas.find(x => x.id === document.getElementById('persona-edit-pane').dataset.id);
            if (p) p[field] = input.value.slice(0, field === 'age' ? 40 : field === 'pronouns' ? 80 : 2000);
        };
    });

    const generatePersonaBtn = document.getElementById('persona-generate-btn');
    if (generatePersonaBtn) generatePersonaBtn.onclick = async () => {
        const personaId = document.getElementById('persona-edit-pane').dataset.id;
        const persona = state.personas.find(item => item.id === personaId);
        if (!persona) return;
        if (!hasApiCredentials()) return showToast(`API Key is missing. Add your ${cloudProviderName()} key in Settings.`, 'error');
        const world = state.worlds.find(item => item.id === state.activeWorldId) || state.editingWorld;
        const session = world ? getCurrentWorldSession() : null;
        const selectedPersonaProvider = document.getElementById('persona-generation-provider')?.value || 'inherit';
        const personaProvider = selectedPersonaProvider === 'inherit' ? normalizedProviderId(state.globalSettings.apiProvider) : normalizedProviderId(selectedPersonaProvider);
        const model = document.getElementById('persona-generation-model').value.trim() || state.globalSettings.defaultModel;
        const maxTokens = Math.max(500, Math.min(5000, parseInt(document.getElementById('persona-generation-max-tokens').value, 10) || 5000));
        const reasoningEnabled = document.getElementById('persona-generation-reasoning')?.checked === true;
        const status = document.getElementById('persona-generation-status');
        const desc = document.getElementById('persona-desc');
        generatePersonaBtn.disabled = true;
        generatePersonaBtn.textContent = '⏳ Drafting persona…';
        if (status) status.textContent = `${personaProvider} · ${model} · streaming one complete draft (up to ${maxTokens} tokens)…`;
        const context = {
            persona: normalizePersona(persona),
            world: world ? { name: world.name, description: world.description, authorNote: world.authorNote } : null,
            controlledCharacter: session?.controlledEntityId ? (world?.entities || []).find(entity => entity.id === session.controlledEntityId) : null,
            recentTurns: (session?.history || []).slice(-24).map(message => ({ role: message.role, content: String(message.content || message.text || '').slice(0, 1200) }))
        };
        const prompt = `[PERSONA DRAFTING]\nWrite a single rich, usable player persona description from the supplied world and conversation evidence. This is a portrayal brief for the narrator, not a JSON object and not a transcript. Use concrete voice, values, habits, boundaries, appearance, history, motivations, relationships, and speech patterns where supported. Clearly mark uncertainty instead of inventing biography. Keep the persona internally coherent and written as direct authorial notes. Return only the final persona text; do not include headings such as "draft", analysis, or a closing note. One complete draft is required.\n\nSOURCE CONTEXT:\n${JSON.stringify(context)}`;
        try {
            const personaWorld = { ...(world || {}), model, provider: personaProvider, openRouterRouting: personaProvider === normalizedProviderId(state.globalSettings.apiProvider) ? (world?.openRouterRouting || state.globalSettings.openRouterRouting) : null };
            const response = await fetch(providerApiBase(personaProvider) + '/chat/completions', {
                method: 'POST', headers: { ...providerAuthHeaders(personaProvider), 'Content-Type': 'application/json', ...providerAttributionHeaders(personaProvider) },
                body: JSON.stringify(applyOpenRouterRouting({ model, max_tokens: maxTokens, temperature: 0.35, stream: true,
                    ...(reasoningEnabled ? { reasoning_effort: 'low' } : {}),
                    messages: [{ role: 'system', content: prompt }, { role: 'user', content: 'Produce the complete persona draft now.' }] }, personaWorld, { scope: 'persona' }))
            });
            if (!response.ok) throw new Error((await response.text()).slice(0, 600) || `Persona generation failed (${response.status})`);
            const reader = response.body?.getReader();
            if (!reader) throw new Error('Persona provider did not return a stream.');
            const decoder = new TextDecoder(); let buffer = ''; let output = ''; let reasoning = '';
            const consume = raw => {
                buffer += raw;
                const rows = buffer.split('\n'); buffer = rows.pop() || '';
                rows.forEach(row => {
                    if (!row.startsWith('data:')) return;
                    const payload = row.slice(5).trim(); if (!payload || payload === '[DONE]') return;
                    try {
                        const delta = JSON.parse(payload).choices?.[0]?.delta || {};
                        const thought = delta.reasoning || delta.thought || '';
                        if (thought) { reasoning += thought; if (status) status.innerHTML = `<em>Thinking:</em> ${escapeHTML(reasoning.slice(-600))}`; }
                        const token = delta.content || '';
                        if (token) { output += token; desc.value = output; if (status) status.textContent = `Streaming persona draft… ${output.length.toLocaleString()} characters`; }
                    } catch (_) { /* provider may split JSON across chunks */ }
                });
            };
            while (true) { const { done, value } = await reader.read(); if (done) break; consume(decoder.decode(value, { stream: true })); }
            if (!output.trim()) throw new Error('Persona generation returned no usable draft.');
            persona.text = output.trim().slice(0, 12000);
            persona.personaGeneration = { provider: personaProvider, model, maxTokens, reasoning: reasoningEnabled, routing: personaWorld.openRouterRouting || null, generatedAt: new Date().toISOString(), source: 'world_and_recent_history', draftRequired: true };
            await saveState();
            if (status) status.textContent = `Draft complete · ${output.trim().split(/\s+/).length.toLocaleString()} words · saved with generation provenance.`;
            showToast('Persona draft generated and saved.', 'success');
        } catch (error) {
            if (status) status.textContent = `Generation failed: ${error.message}`;
            showToast(`Persona generation failed: ${error.message}`, 'error');
        } finally { generatePersonaBtn.disabled = false; generatePersonaBtn.textContent = '✨ Generate from current world'; }
    };

    document.getElementById('save-persona-btn').onclick = async () => {
        await saveState();
        renderPersonasList();
        showToast('Persona saved', 'success');
    };

    document.getElementById('set-active-persona-btn').onclick = async () => {
        const id = document.getElementById('persona-edit-pane').dataset.id;
        state.activePersonaId = id;
        const persona = state.personas.find(item => item.id === id) || null;
        // When this editor was opened from a World, “active” means active for
        // the current timeline as well. This is an explicit binding, unlike
        // the old implicit global-persona fallback.
        if (!document.getElementById('world-play-view')?.classList.contains('hidden')) {
            await bindPersonaToCurrentWorldTimeline(persona, { source: 'persona_editor_set_active' });
        }
        await saveState();
        renderPersonasList();
        showToast(persona ? 'Persona activated for this timeline.' : 'Persona activated', 'success');
    };

    const pUpload = document.getElementById('persona-upload-area');
    const pInput = document.getElementById('persona-input');
    if (pUpload && pInput) {
        pUpload.onclick = () => pInput.click();
        pInput.onchange = async (e) => {
            const file = e.target.files[0];
            if (!file) return;
            try {
                const optimized = await normalizeUploadedImage(file, 256, 0.8);
                const p = state.personas.find(x => x.id === document.getElementById('persona-edit-pane').dataset.id);
                if (p) {
                    p.avatar = optimized;
                    document.getElementById('persona-preview').innerHTML = `<img src="${optimized}" style="width:100%;height:100%;object-fit:cover;border-radius:12px;">`;
                }
            } catch (error) {
                showToast(`Image upload failed: ${error.message}`, 'error');
            } finally { e.target.value = ''; }
        };
    }

    document.getElementById('delete-persona-btn').onclick = () => {
        showConfirmModal('Delete Persona', 'Are you sure?', async () => {
            const id = document.getElementById('persona-edit-pane').dataset.id;
            state.personas = state.personas.filter(p => p.id !== id);
            if (state.activePersonaId === id) state.activePersonaId = state.personas.length > 0 ? state.personas[0].id : null;
            await saveState();
            renderPersonasList();
        });
    };
}

function renderPersonasList() {
    const list = document.getElementById('personas-list');
    list.innerHTML = '';
    
    const editPane = document.getElementById('persona-edit-pane');
    const emptyPane = document.getElementById('persona-empty-pane');
    
    if (state.personas.length === 0) {
        editPane.style.display = 'none';
        emptyPane.style.display = 'flex';
        return;
    }

    state.personas.forEach(p => {
        const div = document.createElement('div');
        div.className = `persona-list-item`;
        const isActive = p.id === state.activePersonaId;
        if (isActive) div.style.borderLeft = `3px solid ${cssColor(p.color || '#4A90E2', '#4A90E2')}`;
        
        const avatarHtml = p.avatar
            ? `<div style="width:32px;height:32px;border-radius:50%;background-image:url('${cssUrl(p.avatar)}');background-size:cover;background-position:center;flex-shrink:0;border:1px solid var(--border2);"></div>`
            : `<div style="width:32px;height:32px;border-radius:50%;background:var(--surface3);flex-shrink:0;border:1px solid var(--border);display:flex;align-items:center;justify-content:center;font-size:0.75rem;color:var(--text-3);">👤</div>`;

        div.innerHTML = `
            <div style="display:flex;align-items:center;gap:10px;width:100%;">
                ${avatarHtml}
                <div style="flex:1;min-width:0;">
                    <div class="persona-list-item-name" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHTML(p.name || 'Unnamed Persona')}</div>
                    ${isActive ? '<div class="persona-list-item-badge">Active</div>' : ''}
                </div>
            </div>
        `;
        div.onclick = () => selectPersona(p.id);
        list.appendChild(div);
    });

    if (!editPane.dataset.id && state.personas.length > 0) {
        selectPersona(state.activePersonaId || state.personas[0].id);
    } else if (editPane.dataset.id) {
        selectPersona(editPane.dataset.id);
    }
}

function selectPersona(id) {
    const p = state.personas.find(x => x.id === id);
    if (!p) return;
    const editPane = document.getElementById('persona-edit-pane');
    const emptyPane = document.getElementById('persona-empty-pane');
    
    editPane.style.display = 'flex';
    emptyPane.style.display = 'none';
    editPane.dataset.id = id;
    
    const nameInput = document.getElementById('persona-name');
    const descInput = document.getElementById('persona-desc');
    const colorInput = document.getElementById('persona-color');
    if (document.activeElement !== nameInput) nameInput.value = p.name;
    if (document.activeElement !== descInput) descInput.value = p.text;
    const generationModel = document.getElementById('persona-generation-model');
    const generationProvider = document.getElementById('persona-generation-provider');
    const generationMaxTokens = document.getElementById('persona-generation-max-tokens');
    const generationReasoning = document.getElementById('persona-generation-reasoning');
    if (generationModel && document.activeElement !== generationModel) generationModel.value = p.personaGeneration?.model || '';
    if (generationProvider && document.activeElement !== generationProvider) generationProvider.value = p.personaGeneration?.provider || 'inherit';
    if (generationMaxTokens && document.activeElement !== generationMaxTokens) generationMaxTokens.value = Math.max(500, Math.min(5000, Number(p.personaGeneration?.maxTokens) || 5000));
    if (generationReasoning && document.activeElement !== generationReasoning) generationReasoning.checked = p.personaGeneration?.reasoning === true;
    if (colorInput) colorInput.value = /^#[0-9a-f]{6}$/i.test(p.color || '') ? p.color : '#4A90E2';
    const structuredInputs = {
        age: document.getElementById('persona-age'),
        pronouns: document.getElementById('persona-pronouns'),
        appearance: document.getElementById('persona-appearance'),
        publicIdentity: document.getElementById('persona-public-identity'),
        reputation: document.getElementById('persona-reputation')
    };
    Object.entries(structuredInputs).forEach(([field, input]) => {
        if (input && document.activeElement !== input) input.value = p[field] || '';
    });
    
    const preview = document.getElementById('persona-preview');
    if (preview) {
        if (p.avatar) {
            preview.innerHTML = `<img src="${escapeHTML(p.avatar)}" style="width:100%;height:100%;object-fit:cover;border-radius:12px;">`;
        } else {
            preview.innerHTML = '<span>Upload</span>';
        }
    }
    
    // update list highlighting
    Array.from(document.getElementById('personas-list').children).forEach(child => {
        child.classList.remove('active');
        if (child.querySelector('.persona-list-item-name').textContent === (p.name || 'Unnamed Persona')) {
            child.classList.add('active');
        }
    });
}

// (removed: updateActivePersona — dead debounced auto-save, superseded by the
// live oninput handlers + explicit Save button in setupPersonasLogic)

// --- Rooms System ---
function setupRoomsLogic() {
    // Library Tabs
    const tabs = document.querySelectorAll('#library-view .tab');
    tabs.forEach(tab => {
        tab.onclick = () => {
            tabs.forEach(t => t.classList.remove('active'));
            tab.classList.add('active');
            
            if (tab.dataset.tab === 'characters') {
                document.getElementById('lib-characters-pane').classList.remove('hidden');
                document.getElementById('lib-rooms-pane').classList.add('hidden');
                document.getElementById('create-new-char-btn').classList.remove('hidden');
                document.getElementById('create-new-room-btn').classList.add('hidden');
            } else {
                document.getElementById('lib-characters-pane').classList.add('hidden');
                document.getElementById('lib-rooms-pane').classList.remove('hidden');
                document.getElementById('create-new-char-btn').classList.add('hidden');
                document.getElementById('create-new-room-btn').classList.remove('hidden');
                renderRooms();
            }
        };
    });

    const roomOverlay = document.getElementById('room-studio-overlay');
    document.getElementById('create-new-room-btn').onclick = () => {
        state.editingRoom = {
            id: 'room_' + Date.now(),
            name: 'New Sequence',
            scenario: '',
            avatar: '',
            bg: '',
            lorebook: [],
            model: state.globalSettings.defaultModel,
            openRouterRouting: null,
            maxTokens: 2048,
            contextSize: 8192,
            temp: 0.9,
            topP: 1.0,
            topK: 0,
            repPenalty: 1.0,
            minP: 0.0,
            freqPenalty: 0.0,
            presPenalty: 0.0,
            reasoning: false,
            includeReasoning: false,
            reasoningEffort: '',
            characterIds: [],
            authorsNote: '',
            authorsNoteDepth: 4,
            authorsNoteFreq: 1
        };
        openRoomStudio();
    };

    document.getElementById('close-room-studio-btn').onclick = () => roomOverlay.classList.add('hidden');
    
    document.getElementById('add-room-lore-btn').onclick = () => {
        if (!state.editingRoom.lorebook) state.editingRoom.lorebook = [];
        state.editingRoom.lorebook.push({ keyword: 'New Keyword', text: 'description...', weight: 'knowledge' });
        renderRoomLoreList();
    };

    document.getElementById('fetch-room-model-btn').onclick = fetchRoomModelSettings;

    document.getElementById('save-room-btn').onclick = async () => {
        const r = state.editingRoom;
        if (!r) return;
        r.name = document.getElementById('room-name').value.trim() || 'Unnamed Room';
        r.scenario = document.getElementById('room-scenario').value.trim();
        r.avatar = document.getElementById('room-avatar').value.trim();
        r.bg = document.getElementById('room-bg').value.trim();
        r.model = document.getElementById('room-model').value.trim();
        r.openRouterRouting = readOpenRouterRoutingPanel('room');
        r.contextSize = parseInt(document.getElementById('room-context-size').value) || 8192;
        r.maxTokens = parseInt(document.getElementById('room-max-tokens').value) || 2048;
        r.temp = parseFloat(document.getElementById('room-temp').value) || 0.9;
        r.topP = parseFloat(document.getElementById('room-top-p').value) || 1.0;
        r.topK = parseInt(document.getElementById('room-top-k').value) || 0;
        r.repPenalty = parseFloat(document.getElementById('room-rep-penalty').value) || 1.0;
        r.minP = parseFloat(document.getElementById('room-min-p').value) || 0;
        r.freqPenalty = parseFloat(document.getElementById('room-freq-penalty').value) || 0;
        r.presPenalty = parseFloat(document.getElementById('room-pres-penalty').value) || 0;
        
        r.reasoning = document.getElementById('room-reasoning').checked;
        r.includeReasoning = document.getElementById('room-include-reasoning').checked;
        r.reasoningEffort = document.getElementById('room-reasoning-effort').value;

        r.authorsNote = document.getElementById('room-authors-note').value.trim();
        r.authorsNoteDepth = parseInt(document.getElementById('room-authors-note-depth').value) || 4;
        r.authorsNoteFreq = parseInt(document.getElementById('room-authors-note-freq').value) || 1;
        
        // Find checked chars
        const charBoxes = document.querySelectorAll('.room-char-checkbox input');
        r.characterIds = Array.from(charBoxes).filter(b => b.checked).map(b => b.value);
        if (r.characterIds.length === 0) {
            showToast('Choose at least one character for this room.', 'error');
            return;
        }

        const index = state.rooms.findIndex(room => room.id === r.id);
        if (index !== -1) {
            state.rooms[index] = JSON.parse(JSON.stringify(r));
        } else {
            state.rooms.push(JSON.parse(JSON.stringify(r)));
        }
        await saveState();
        roomOverlay.classList.add('hidden');
        renderRooms();
        showToast('Room Saved!', 'success');
    };

    document.getElementById('delete-room-btn').onclick = () => {
        showConfirmModal('Delete Room', 'Permanently destroy this scenario?', async () => {
            state.rooms = state.rooms.filter(room => room.id !== state.editingRoom.id);
            delete state.chats[state.editingRoom.id];
            await saveState();
            roomOverlay.classList.add('hidden');
            renderRooms();
        });
    };
}

function openRoomStudio(roomId = null) {
    if (roomId) {
        const room = state.rooms.find(r => r.id === roomId);
        if (!room) return;
        state.editingRoom = JSON.parse(JSON.stringify(room));
        document.getElementById('delete-room-btn').style.display = 'block';
    } else {
        document.getElementById('delete-room-btn').style.display = 'none';
    }

    const r = state.editingRoom;
    document.getElementById('room-name').value = r.name || '';
    document.getElementById('room-scenario').value = r.scenario || '';
    document.getElementById('room-avatar').value = r.avatar || '';
    document.getElementById('room-bg').value = r.bg || '';
    document.getElementById('room-model').value = r.model || '';
    initializeOpenRouterRoutingPanel('room');
    configureContextSliderForModel('room-context-size', r.model);
    document.getElementById('room-context-size').value = r.contextSize || 8192;
    updateContextSliderUI('room-context-size', 'room-context-size-val', 'room-context-size-badge');
    document.getElementById('room-max-tokens').value = r.maxTokens || 2048;
    document.getElementById('room-temp').value = r.temp || 0.9;
    document.getElementById('room-top-p').value = r.topP || 1.0;
    document.getElementById('room-top-k').value = r.topK || 0;
    document.getElementById('room-rep-penalty').value = r.repPenalty || 1.0;
    document.getElementById('room-min-p').value = r.minP || 0.0;
    document.getElementById('room-freq-penalty').value = r.freqPenalty || 0.0;
    document.getElementById('room-pres-penalty').value = r.presPenalty || 0.0;
    
    document.getElementById('room-reasoning').checked = !!r.reasoning;
    document.getElementById('room-include-reasoning').checked = !!r.includeReasoning;
    document.getElementById('room-reasoning-effort').value = r.reasoningEffort || '';

    document.getElementById('room-authors-note').value = r.authorsNote || '';
    document.getElementById('room-authors-note-depth').value = r.authorsNoteDepth !== undefined ? r.authorsNoteDepth : 4;
    document.getElementById('room-authors-note-freq').value = r.authorsNoteFreq !== undefined ? r.authorsNoteFreq : 1;
    
    renderRoomLoreList();
    
    const charSelect = document.getElementById('room-char-selection');
    charSelect.innerHTML = '';
    state.characters.forEach(c => {
        const label = document.createElement('label');
        label.className = `room-char-checkbox ${r.characterIds.includes(c.id) ? 'selected' : ''}`;
        label.innerHTML = `
            <div style="width:24px; height:24px; border-radius:6px; background:var(--surface3); background-size:cover; background-image:url('${cssUrl(c.avatar)}')"></div>
            <span>${escapeHTML(c.name)}</span>
            <input type="checkbox" value="${escapeHTML(c.id)}" ${r.characterIds.includes(c.id) ? 'checked' : ''}>
        `;
        label.querySelector('input').addEventListener('change', function() {
            if(this.checked) label.classList.add('selected');
            else label.classList.remove('selected');
        });
        charSelect.appendChild(label);
    });

    document.getElementById('room-studio-overlay').classList.remove('hidden');
}

function renderRoomLoreList() {
    const list = document.getElementById('room-lore-entries');
    if (!list) return;
    list.innerHTML = '';
    const lorebook = state.editingRoom?.lorebook || [];
    
    lorebook.forEach((entry, idx) => {
        const div = document.createElement('div');
        div.style.display = 'flex';
        div.style.flexDirection = 'column';
        div.style.gap = '8px';
        div.style.background = 'var(--surface2)';
        div.style.padding = '12px';
        div.style.borderRadius = '8px';
        div.style.border = '1px solid var(--border)';
        
        div.innerHTML = `
            <div style="display:flex; gap:8px;">
                <input type="text" class="form-input room-lore-kw" style="flex:1;" value="${escapeHTML(entry.keyword || '')}" placeholder="Keyword(s)">
                <select class="form-select room-lore-wt" style="width:120px;">
                    <option value="knowledge" ${entry.weight === 'knowledge' ? 'selected' : ''}>Knowledge</option>
                    <option value="truth" ${entry.weight === 'truth' ? 'selected' : ''}>Truth</option>
                </select>
                <button class="tool-btn tool-btn-danger room-lore-del">✕</button>
            </div>
            <textarea class="form-textarea room-lore-txt" rows="2" placeholder="Entry context...">${escapeHTML(entry.text || '')}</textarea>
        `;
        
        div.querySelector('.room-lore-kw').onchange = (e) => entry.keyword = e.target.value;
        div.querySelector('.room-lore-wt').onchange = (e) => entry.weight = e.target.value;
        div.querySelector('.room-lore-txt').onchange = (e) => entry.text = e.target.value;
        
        div.querySelector('.room-lore-del').onclick = () => {
            state.editingRoom.lorebook.splice(idx, 1);
            renderRoomLoreList();
        };
        list.appendChild(div);
    });
}

function renderRooms() {
    const grid = document.getElementById('room-grid');
    grid.innerHTML = '';
    state.rooms.forEach(room => {
        const card = document.createElement('div');
        card.className = 'char-card';
        card.innerHTML = `
            <div class="char-card-banner" style="height: 80px; ${room.bg ? `background-image:url('${cssUrl(room.bg)}')` : ''}; ${room.avatar ? `display:flex; justify-content:center; align-items:flex-end; padding-bottom:10px;` : ''}">
                ${room.avatar ? `<div class="char-card-avatar" style="background-image:url('${cssUrl(room.avatar)}'); width:50px; height:50px; border-radius:50%; border:2px solid var(--surface2); background-size:cover; margin-top:20px;"></div>` : ''}
            </div>
            <div class="char-card-body">
                <div class="char-card-name">${escapeHTML(room.name)}</div>
                <div class="char-card-desc" style="font-style: italic;">${room.characterIds.length} members engaged</div>
                <div class="char-card-desc" style="white-space: pre-wrap; font-size: 0.8rem; height:40px; overflow:hidden;">${escapeHTML(room.scenario || 'No scenario')}</div>
                <div class="char-card-actions"><button class="btn btn-primary char-card-play enter-room-btn">Play</button><button class="btn btn-ghost edit-room-bottom-btn">Edit</button></div>
            </div>
        `;
        card.querySelector('.edit-room-bottom-btn').onclick = (e) => {
            e.stopPropagation();
            openRoomStudio(room.id);
        };
        card.querySelector('.enter-room-btn').onclick = () => {
            state.activeRoomId = room.id;
            state.activeCharId = null;
            switchView('chat');
        };
        grid.appendChild(card);
    });

    if (state.rooms.length === 0) {
        grid.innerHTML = '<div class="empty-state"><h3>No Rooms Yet</h3><p>Click "+ New Room" to start a multi-character simulation</p></div>';
    }
}

