            lastErrorAt: Number.isFinite(c.socialFeedRuntime.lastErrorAt) ? c.socialFeedRuntime.lastErrorAt : 0,
            lastError: String(c.socialFeedRuntime.lastError || '').trim().slice(0, 500),
