        webAccess: c.webAccess === true,
        lastProactiveAt: Number.isFinite(c.lastProactiveAt) ? c.lastProactiveAt : 0,
        model: typeof c.model === 'string' ? c.model : '',
        temp: Number.isFinite(Number(c.temp)) ? livingClamp(Number(c.temp), 0, 2) : 0.75,
