/**
 * Capabilities are enforced at the request boundary, not just requested in a
 * prompt. A disabled paid medium is absent from the model's tools entirely.
 */
function companionToolsFor(companion, localProvider = false) {
    const tools = COMPANION_TOOLS.filter(tool => {
        const name = tool.function?.name;
        if (name === 'share_link' && !companion.webAccess) return false;
        if (name === 'send_photo' && !companion.allowPhotos) return false;
        if (name === 'send_voice_note' && !companion.allowVoiceNotes) return false;
        return true;
    });
    if (companion.webAccess && !localProvider) tools.push(COMPANION_WEB_SEARCH_TOOL);
    return tools;
}

function normalizeCompanionEmbeddedToolValue(value) {
    if (Array.isArray(value)) return value.map(normalizeCompanionEmbeddedToolValue);
    if (!isPlainObject(value)) return value;
    const keyMap = {
        valencechange: 'valence_change',
        arousalchange: 'arousal_change',
        moodlabel: 'mood_label',
        relationshipchange: 'relationship_change',
        trustchange: 'trust_change',
        warmthchange: 'warmth_change',
        attractionchange: 'attraction_change',
        resentmentchange: 'resentment_change',
        stabilitychange: 'stability_change',
        familiaritychange: 'familiarity_change',
        respectchange: 'respect_change',
        comfortchange: 'comfort_change',
        dependencechange: 'dependence_change',
        fearchange: 'fear_change',
        obligationchange: 'obligation_change',
        powerimbalancechange: 'power_imbalance_change',
        compatibilitychange: 'compatibility_change',
        emotionappraisal: 'emotion_appraisal',
        emotionchanges: 'emotion_changes',
        towardplayeremotions: 'toward_player_emotions',
        maskingchange: 'masking_change',
        delayedreactionminutes: 'delayed_reaction_minutes',
        emotionaltrigger: 'emotional_trigger',
        goalimpact: 'goal_impact',
        normviolation: 'norm_violation',
        socialsafety: 'social_safety',
        energychange: 'energy_change',
        stresschange: 'stress_change',
        socialneedchange: 'social_need_change',
        angerchange: 'anger_change',
        intoxicationchange: 'intoxication_change',
        desirechange: 'desire_change',
        sexualarousalchange: 'sexual_arousal_change',
        sexualfrustrationchange: 'sexual_frustration_change',
        intimacyoutcome: 'intimacy_outcome',
        sexualcooldownminutes: 'sexual_cooldown_minutes',
        cooloffminutes: 'cool_off_minutes',
        cooldownreason: 'cooldown_reason',
        voicenote: 'voice_note',
        relationshipevent: 'relationship_event',
        memorywrite: 'memory_write',
        personavisualmemory: 'persona_visual_memory',
        playermediamemory: 'player_media_memory',
        socialpost: 'social_post',
        conversationgoal: 'conversation_goal',
        playermodelupdates: 'player_model_updates',
        boundaryupdates: 'boundary_updates',
        truthupdates: 'truth_updates',
        toldplayer: 'told_player',
        coverstory: 'cover_story',
        discoveryrisk: 'discovery_risk',
        emotionalcost: 'emotional_cost',
        lifeevent: 'life_event',
        lifestate: 'life_state',
        locationdetail: 'location_detail',
        temporarysituation: 'temporary_situation',
        placelabel: 'place_label',
        withnames: 'with_names',
        durationminutes: 'duration_minutes',
        dueinminutes: 'due_in_minutes',
        mediatype: 'media_type'
    };
    const normalized = {};
    Object.entries(value).forEach(([key, nested]) => {
        const compact = String(key).replace(/[^a-z0-9]/gi, '').toLowerCase();
        normalized[keyMap[compact] || key] = normalizeCompanionEmbeddedToolValue(nested);
    });
    return normalized;
}

/**
 * Some models emulate function calls in content using compact XML-like tags
 * instead of returning the OpenAI `tool_calls` field. Recover those calls and
 * remove the private protocol before any text can become a visible bubble.
 */
function extractCompanionEmbeddedToolCalls(rawText) {
    const source = String(rawText || '');
    const calls = [];
    let visibleText = '';
    let cursor = 0;
    const startPattern = /<(?:uncensored[_-]?)?tool[_-]?call>/gi;
    let start;
    while ((start = startPattern.exec(source))) {
        visibleText += source.slice(cursor, start.index);
        const bodyStart = startPattern.lastIndex;
        const endPattern = /<\/(?:uncensored[_-]?)?tool[_-]?call>/gi;
        endPattern.lastIndex = bodyStart;
        const end = endPattern.exec(source);
        const bodyEnd = end ? end.index : source.length;
        const body = source.slice(bodyStart, bodyEnd).trim();
        cursor = end ? endPattern.lastIndex : source.length;
        startPattern.lastIndex = cursor;

        const firstArg = body.search(/<arg[_-]?key>/i);
        const rawName = (firstArg >= 0 ? body.slice(0, firstArg) : body)
            .replace(/<[^>]+>/g, '').trim();
        const compactName = rawName.replace(/[^a-z0-9]/gi, '').toLowerCase();
        const toolNames = {
            commithumanturn: 'commit_human_turn',
            companionstate: 'companion_state',
            sendphoto: 'send_photo',
            sendvoicenote: 'send_voice_note',
            sharelink: 'share_link',
            publishsocialpost: 'publish_social_post'
        };
        const name = toolNames[compactName];
        if (!name) continue;

        const args = {};
        const pairPattern = /<arg[_-]?key>([\s\S]*?)<\/arg[_-]?key>\s*<arg[_-]?value>([\s\S]*?)<\/arg[_-]?value>/gi;
        let pair;
        while ((pair = pairPattern.exec(body))) {
            const rawKey = pair[1].replace(/<[^>]+>/g, '').trim();
            const compactKey = rawKey.replace(/[^a-z0-9]/gi, '').toLowerCase();
            const topLevelKeys = {
                voicenote: 'voice_note',
                relationshipevent: 'relationship_event',
                memorywrite: 'memory_write',
                personavisualmemory: 'persona_visual_memory',
                playermediamemory: 'player_media_memory',
                socialpost: 'social_post',
                lifeevent: 'life_event',
                lifestate: 'life_state',
                dueinminutes: 'due_in_minutes',
                mediatype: 'media_type',
                capturetype: 'capture_type'
            };
            const key = topLevelKeys[compactKey] || rawKey;
            const rawValue = pair[2].trim();
            const parsed = safeParseJSONRepair(rawValue);
            args[key] = normalizeCompanionEmbeddedToolValue(parsed === null ? rawValue : parsed);
        }
        calls.push({
            id: livingId('vh_embedded_tool', `${name}|${body}|${calls.length}`),
            type: 'function',
            function: { name, arguments: JSON.stringify(args) }
        });
    }
    visibleText += source.slice(cursor);
    const danglingProtocol = visibleText.search(/<\/?(?:uncensored[_-]?)?tool[_-]?call>|<\/?arg[_-]?(?:key|value)>/i);
    if (danglingProtocol >= 0) visibleText = visibleText.slice(0, danglingProtocol);
    return { visibleText: visibleText.trim(), toolCalls: calls };
}

/**
 * Last-resort protocol firewall. A few providers print function calls using
 * Python/repr syntax instead of native tool_calls or XML. That text is never
 * safe to render. Remove balanced call expressions and duplicated prompt
 * timing headers, while preserving ordinary prose before or after them.
 */
function quarantineCompanionProtocolText(rawText) {
    let source = String(rawText || '')
        .replace(/(?:\[you sent this[^\]]*\]\s*){1,}/gi, '')
        .replace(/(?:\[player sent this[^\]]*\]\s*){1,}/gi, '');
    const objectPayload = safeParseJSONRepair(source);
    if (isPlainObject(objectPayload)
        && (objectPayload.state || objectPayload.life_state || objectPayload.photo || objectPayload.voice_note
            || objectPayload.memory_write || objectPayload.relationship_event)) {
        source = String(objectPayload.visible_reply || objectPayload.reply || objectPayload.message || '');
    }
    const marker = /\b(?:commit_?human_?turn|commithumanturn|companion_?state|send_?photo|send_?voice_?note|publish_?social_?post)\s*\(/ig;
    let match;
    let guard = 0;
    while ((match = marker.exec(source)) && guard++ < 12) {
        let depth = 0;
        let quote = '';
        let escaped = false;
        let end = -1;
        for (let index = source.indexOf('(', match.index); index < source.length; index += 1) {
            const char = source[index];
            if (escaped) { escaped = false; continue; }
            if (quote && char === '\\') { escaped = true; continue; }
            if (char === '"' || char === "'") {
                if (!quote) quote = char;
                else if (quote === char) quote = '';
                continue;
            }
            if (quote) continue;
            if (char === '(') depth += 1;
            if (char === ')' && --depth === 0) { end = index + 1; break; }
        }
        // If the model truncated inside the private call, discard from the
        // marker onward. Otherwise join any genuine visible suffix back on.
        source = `${source.slice(0, match.index)} ${end < 0 ? '' : source.slice(end)}`;
        marker.lastIndex = 0;
    }
    const dangling = source.search(/\b(?:valence_?change|relationship_?change|memory_?write|life_?state|emotion_?appraisal)\s*=/i);
    if (dangling >= 0) source = source.slice(0, dangling);
    return source.replace(/\s{2,}/g, ' ').trim();
}

function companionVisibleReplyLimit(text, companion) {
    const budget = Math.max(128, Number(companion?.maxTokens) || 1000);
    // This is deliberately conservative. It is a display firewall for
    // providers that ignore max_tokens, not a tokenizer replacement.
    const maxChars = Math.max(240, Math.floor(budget * 3.2));
    const source = String(text || '').trim();
    if (source.length <= maxChars) return source;
    const clipped = source.slice(0, maxChars);
    const boundary = Math.max(clipped.lastIndexOf('. '), clipped.lastIndexOf('? '), clipped.lastIndexOf('! '), clipped.lastIndexOf('\n'));
    return (boundary > maxChars * 0.55 ? clipped.slice(0, boundary + 1) : clipped).trim();
}

function companionProviderOutputBudget(companion) {
    const visible = Math.max(128, Number(companion?.maxTokens) || 1000);
    // The state receipt is private engine output and must not consume the
    // author's visible reply allowance. Thinking models also need headroom.
    const reserve = companion?.reasoning ? 3200 : 1800;
    const effectiveModel = String(companion?.model || state.globalSettings.defaultModel || '').trim();
    const catalogModel = Array.isArray(companionTextModelCatalog)
        ? companionTextModelCatalog.find(item => item.id === effectiveModel)
        : null;
    const physicalLimit = Math.max(256, Number(catalogModel?.maxOutput) || 32768);
    return Math.min(physicalLimit, visible + reserve);
}

function companionRequestTimeoutMs(companion, repair = false) {
    if (repair) return 180000;
    return companion?.reasoning ? 10 * 60 * 1000 : 3 * 60 * 1000;
}

async function fetchCompanionCompletion(url, init, companion, repair = false) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), companionRequestTimeoutMs(companion, repair));
    try {
        return await fetch(url, { ...init, signal: controller.signal });
    } catch (error) {
        if (error?.name === 'AbortError') {
            throw new Error(!repair && companion?.reasoning
                ? 'The thinking model exceeded the 10-minute generation window. Try lower reasoning effort or a faster model.'
                : 'The model did not respond within 3 minutes. Try again or choose a faster model.');
        }
        throw error;
    } finally {
        clearTimeout(timeout);
    }
}

/**
 * Turn a raw tool_calls array into the normalized actions the send loop
 * applies. Pure and separately testable — the actual fetch response shape
 * only needs to be trusted once, here.
 */
function extractCompanionToolCalls(toolCalls) {
    const calls = Array.isArray(toolCalls) ? toolCalls : [];
    const parse = (raw) => {
        try { return JSON.parse(raw || '{}'); }
        catch (error) { return safeParseJSONRepair(raw); }
    };
    const commitCall = calls.find(call => call.function?.name === 'commit_human_turn');
    const stateCall = calls.find(call => call.function?.name === 'companion_state');
    const photoCall = calls.find(call => call.function?.name === 'send_photo');
    const voiceCall = calls.find(call => call.function?.name === 'send_voice_note');
    const linkCall = calls.find(call => call.function?.name === 'share_link');
    const commit = commitCall ? parse(commitCall.function.arguments) : null;
    const committedPhoto = commit?.photo?.decision === 'send' ? commit.photo : null;
    const committedVoice = commit?.voice_note?.decision === 'send' ? commit.voice_note : null;
    return {
        commit,
        state: commit?.state || (stateCall ? parse(stateCall.function.arguments) : null),
        photo: committedPhoto || (photoCall ? parse(photoCall.function.arguments) : null),
        voice: committedVoice || (voiceCall ? parse(voiceCall.function.arguments) : null),
        link: linkCall ? parse(linkCall.function.arguments) : null
    };
}

/**
 * A model turn is not complete until it has something the player can actually
 * receive. OpenAI-compatible providers may legitimately return only tool_calls
 * with message.content=null; the private receipt is useful, but it is not a
 * chat reply and must not consume the player's pending message by itself.
 */
function companionHasDeliverableReply(replyText, actions, companion, links = []) {
    if (String(replyText || '').trim()) return true;
    if (Array.isArray(links) && links.length) return true;
    if (/^https?:\/\//i.test(String(actions?.link?.url || ''))) return true;
    if (companion?.allowVoiceNotes && String(actions?.voice?.text || '').trim()) return true;
    if (companion?.allowPhotos && String(actions?.photo?.scene || '').trim()) return true;
    return false;
}

// --- Persistence ------------------------------------------------------------

function captureCompanionRuntime(companion) {
    return safeJsonClone({
        mood: companion.mood,
        humanDynamics: companion.humanDynamics,
        emotionState: companion.emotionState,
        relationshipDynamics: companion.relationshipDynamics,
        lifeEvents: companion.lifeEvents,
        commitments: companion.commitments,
        lifeRuntime: companion.lifeRuntime,
        continuityRuntime: companion.continuityRuntime,
        currentOutfit: companion.currentOutfit,
        currentLocationDetail: companion.currentLocationDetail,
        usage: companion.usage,
        trauma: companion.trauma,
        memory: companion.memory,
        personaVisualMemory: companion.personaVisualMemory,
        socialPosts: companion.socialPosts,
        socialFeedRuntime: companion.socialFeedRuntime,
        socialRelationship: companion.socialRelationship,
        videoJobs: companion.videoJobs,
        lastProactiveAt: companion.lastProactiveAt || 0
    });
}

function materializeCompanionStartingSocialPosts(companion, nowMs = Date.now()) {
    const seeds = Array.isArray(companion?.startingSocialPosts) ? companion.startingSocialPosts : [];
    return seeds.map((seed, index) => normalizeCompanionSocialPost({
        ...safeJsonClone(seed),
        // Put the unique seed identity before the companion identity. livingId
        // intentionally caps slugs, so a long companion ID must never be able
        // to trim off the only distinguishing part of a post ID.
        id: livingId('vh_post', `seed_${seed.id || index}_${index}_${nowMs}_${companion.id}`),
        createdAt: nowMs - (Number(seed.seedAgeDays) || (seeds.length - index)) * 86400000
            - ((index * 73) % 600) * 60000,
        pending: false,
        generationError: '',
        likedByPlayer: false,
        likedAt: 0,
        source: 'manual'
    }));
}

function materializeCompanionStartingVideoClip(companion, seed, index, nowMs = Date.now()) {
    return normalizeCompanionVideoJob({
        ...safeJsonClone(seed),
        id: String(seed.id || livingId('vh_clip', `seed_${index}_${companion.id}`)).slice(0, 100),
        status: 'ready',
        progress: 100,
        createdAt: nowMs - (Number(seed.seedAgeDays) || index + 1) * 86400000,
        updatedAt: nowMs - (Number(seed.seedAgeDays) || index + 1) * 86400000,
        error: ''
    });
}

function freshCompanionRuntime(companion, nowMs = Date.now()) {
    const startingSocialPosts = materializeCompanionStartingSocialPosts(companion, nowMs);
    const startingVideoClips = (companion.startingVideoClips || [])
        .map((clip, index) => materializeCompanionStartingVideoClip(companion, clip, index, nowMs));
    return {
        mood: {
            valence: companion.moodBaseline.valence,
            arousal: companion.moodBaseline.arousal,
            label: 'content',
            relationship: companion.startingRelationship,
            lastUpdated: nowMs
        },
        humanDynamics: normalizeCompanionHumanDynamics({
            desire: companionSexualSystemActive(companion) ? companionSexualFactors(companion).baseline : 0,
            lastUpdated: nowMs
        }, nowMs),
        emotionState: normalizeCompanionEmotionState({}, {
            label: 'content', valence: companion.moodBaseline.valence,
            arousal: companion.moodBaseline.arousal
        }, nowMs),
        relationshipDynamics: {
            trust: Math.max(0, companion.startingRelationship),
            warmth: companion.startingRelationship,
            attraction: 0,
            resentment: Math.max(0, -companion.startingRelationship),
            stability: 50,
            familiarity: Math.min(100, Number(companion.knownBeforeDays || 0) * 2),
            respect: Math.max(0, companion.startingRelationship * 0.35),
            comfort: Math.max(0, companion.startingRelationship * 0.4),
            dependence: 0,
            fear: Math.max(0, -companion.startingRelationship * 0.2),
            obligation: 0,
            powerImbalance: 0,
            compatibility: 0
        },
        lifeEvents: [],
        commitments: [],
        lifeRuntime: normalizeCompanionLifeRuntime({ lastSimulatedAt: nowMs }, companion.lifeProfile?.socialCircle),
        continuityRuntime: normalizeCompanionContinuityRuntime({ lastAdvancedAt: nowMs }, nowMs),
        currentOutfit: '',
        currentLocationDetail: '',
        usage: { textTurns: 0, photosGenerated: 0, voiceNotesGenerated: 0, callsCompleted: 0, videosGenerated: 0 },
        trauma: [],
        memory: { longTerm: [], consolidatedThroughIndex: 0 },
        personaVisualMemory: { personaId: '', avatarFingerprint: '', description: '', seenAt: 0 },
        socialPosts: startingSocialPosts,
        socialFeedRuntime: {
            lastPostAt: startingSocialPosts.length ? Math.max(...startingSocialPosts.map(post => post.createdAt)) : 0,
            nextPostAt: 0,
            lastGateAt: 0
        },
        socialRelationship: {
            role: companion.socialPlayerRole || 'stranger',
            totalTips: 0,
            lastTipAt: 0,
            subscribedAt: ['subscriber', 'vip_subscriber'].includes(companion.socialPlayerRole) ? nowMs : 0,
            engagement: 0
        },
        videoJobs: startingVideoClips,
        lastProactiveAt: 0
    };
}

function normalizeCompanionRuntime(raw, companion) {
    const source = isPlainObject(raw) ? raw : captureCompanionRuntime(companion);
    const repaired = normalizeCompanion({
        ...companion,
        mood: source.mood,
        humanDynamics: source.humanDynamics,
        emotionState: source.emotionState,
        relationshipDynamics: source.relationshipDynamics,
        lifeEvents: source.lifeEvents,
        commitments: source.commitments,
        lifeRuntime: source.lifeRuntime,
        continuityRuntime: source.continuityRuntime,
        currentOutfit: source.currentOutfit,
        currentLocationDetail: source.currentLocationDetail,
        usage: source.usage,
        trauma: source.trauma,
        memory: source.memory,
        personaVisualMemory: source.personaVisualMemory,
        socialPosts: source.socialPosts,
        socialFeedRuntime: source.socialFeedRuntime,
        socialRelationship: source.socialRelationship,
        videoJobs: source.videoJobs,
        lastProactiveAt: source.lastProactiveAt
    });
    return captureCompanionRuntime(repaired);
}

function applyCompanionRuntime(companion, rawRuntime) {
    const runtime = normalizeCompanionRuntime(rawRuntime, companion);
    companion.mood = runtime.mood;
    companion.humanDynamics = runtime.humanDynamics;
    companion.emotionState = runtime.emotionState;
    companion.relationshipDynamics = runtime.relationshipDynamics;
    companion.lifeEvents = runtime.lifeEvents;
    companion.commitments = runtime.commitments;
    companion.lifeRuntime = runtime.lifeRuntime;
    companion.continuityRuntime = runtime.continuityRuntime;
    companion.currentOutfit = runtime.currentOutfit;
    companion.currentLocationDetail = runtime.currentLocationDetail;
    companion.usage = runtime.usage;
    companion.trauma = runtime.trauma;
    companion.memory = runtime.memory;
    companion.personaVisualMemory = runtime.personaVisualMemory;
    companion.socialPosts = runtime.socialPosts;
    companion.socialFeedRuntime = runtime.socialFeedRuntime;
    companion.socialRelationship = runtime.socialRelationship;
    companion.videoJobs = runtime.videoJobs;
    companion.lastProactiveAt = runtime.lastProactiveAt;
    return runtime;
}

function normalizeCompanionChatExperience(raw) {
    const source = isPlainObject(raw) ? raw : {};
    return {
        realTimeLife: source.realTimeLife !== false,
        replyDelays: source.replyDelays !== false,
        allowNoReply: source.allowNoReply !== false,
        silenceConsequences: source.silenceConsequences !== false,
        replyBursts: source.replyBursts !== false
    };
}

function normalizeCompanionSilenceState(raw) {
    const source = isPlainObject(raw) ? raw : {};
    return {
        anchorMessageId: String(source.anchorMessageId || '').slice(0, 100),
        appliedStage: ['noticed', 'concerned', 'hurt', 'detached'].includes(source.appliedStage)
            ? source.appliedStage : '',
        changedAt: Number.isFinite(source.changedAt) ? source.changedAt : 0
    };
}

function companionChatExperience(companionId = state.activeCompanionId) {
    const timeline = getActiveCompanionTimeline(companionId);
    return normalizeCompanionChatExperience(timeline?.experience);
}

function companionExperienceLevel(experience) {
    const value = normalizeCompanionChatExperience(experience);
    if (value.realTimeLife && value.replyDelays && value.allowNoReply && value.silenceConsequences && value.replyBursts) return 'Full';
    if (!value.realTimeLife && !value.replyDelays && !value.allowNoReply && !value.silenceConsequences && !value.replyBursts) return 'Instant';
    if (!value.replyDelays && !value.allowNoReply) return 'Responsive';
    return 'Custom';
}

function normalizeCompanionTimeline(raw, companion, fallbackMessages = []) {
    const source = isPlainObject(raw) ? raw : {};
    const createdAt = Number.isFinite(source.createdAt) ? source.createdAt : Date.now();
    const timeline = {
        id: String(source.id || livingId('vh_timeline', `${companion.id}|${createdAt}|${Math.random()}`)).slice(0, 100),
        name: String(source.name || 'Main Timeline').trim().slice(0, 100) || 'Main Timeline',
        createdAt,
        updatedAt: Number.isFinite(source.updatedAt) ? source.updatedAt : createdAt,
        lastViewedAt: Number.isFinite(source.lastViewedAt) ? source.lastViewedAt : 0,
        experience: normalizeCompanionChatExperience(source.experience),
        silence: normalizeCompanionSilenceState(source.silence),
        messages: (Array.isArray(source.messages) ? source.messages : fallbackMessages)
            .map(normalizeCompanionMessage).slice(-5000),
        runtime: normalizeCompanionRuntime(source.runtime, companion)
    };
    // Keep this runtime-only marker out of IndexedDB while avoiding repeated
    // normalization that would replace live message objects during async media work.
    Object.defineProperty(timeline, '__companionTimelineNormalized', {
        value: true,
        enumerable: false,
        configurable: true
    });
    return timeline;
}

function ensureCompanionTimelineStore(companionId) {
    const companion = getCompanion(companionId);
    if (!companion) return null;
    let store = state.companionTimelines[companionId];
    if (!isPlainObject(store)) store = { activeSessionId: '', sessions: [] };
    store.sessions = (Array.isArray(store.sessions) ? store.sessions : [])
        .map(session => session?.__companionTimelineNormalized
            ? session
            : normalizeCompanionTimeline(session, companion))
        .slice(0, 200);
    // Repair the short-lived v18 creation bug that could seed two identical,
    // empty "Main Timeline" records a few milliseconds apart.
    let emptyMain = null;
    store.sessions = store.sessions.filter(session => {
        if (session.name !== 'Main Timeline' || session.messages.length) return true;
        if (!emptyMain) {
            emptyMain = session;
            return true;
        }
        const createdTogether = Math.abs(session.createdAt - emptyMain.createdAt) < 10000;
        return !createdTogether;
    });
    if (!store.sessions.length) {
        store.sessions.push(normalizeCompanionTimeline({
            name: 'Main Timeline',
            messages: state.companionThreads[companionId] || [],
            runtime: captureCompanionRuntime(companion)
        }, companion));
    }
    if (!store.sessions.some(session => session.id === store.activeSessionId)) {
        store.activeSessionId = store.sessions[0].id;
    }
    state.companionTimelines[companionId] = store;
    return store;
}

function getActiveCompanionTimeline(companionId = state.activeCompanionId) {
    const store = ensureCompanionTimelineStore(companionId);
    return store?.sessions.find(session => session.id === store.activeSessionId) || store?.sessions[0] || null;
}

function persistCompanionRuntime(companion) {
    if (!companion) return;
    const timeline = getActiveCompanionTimeline(companion.id);
    if (!timeline) return;
    timeline.runtime = captureCompanionRuntime(companion);
    timeline.updatedAt = Date.now();
}

function activateCompanionTimeline(companionId, timelineId) {
    const companion = getCompanion(companionId);
    const store = ensureCompanionTimelineStore(companionId);
    const timeline = store?.sessions.find(session => session.id === timelineId);
    if (!companion || !store || !timeline) return null;
    persistCompanionRuntime(companion);
    store.activeSessionId = timeline.id;
    applyCompanionRuntime(companion, timeline.runtime);
    state.companionThreads[companionId] = timeline.messages;
    return timeline;
}

function getCompanionThread(companionId = state.activeCompanionId) {
    const timeline = getActiveCompanionTimeline(companionId);
    if (!timeline) return [];
    state.companionThreads[companionId] = timeline.messages;
    return timeline.messages;
}

function createCompanionTimeline(companion, options = {}) {
    const store = ensureCompanionTimelineStore(companion.id);
    if (!store) return null;
    persistCompanionRuntime(companion);
    const current = getActiveCompanionTimeline(companion.id);
    const fork = options.fork === true && current;
    const runtime = fork ? captureCompanionRuntime(companion) : freshCompanionRuntime(companion);
    const timeline = normalizeCompanionTimeline({
        name: options.name || (fork ? `Fork of ${current.name}` : `Timeline ${store.sessions.length + 1}`),
        messages: fork ? safeJsonClone(current.messages) : [],
        experience: fork ? current.experience : options.experience,
        runtime
    }, companion);
    store.sessions.unshift(timeline);
    store.activeSessionId = timeline.id;
    applyCompanionRuntime(companion, timeline.runtime);
    state.companionThreads[companion.id] = timeline.messages;
    return timeline;
}

function freshCompanionId(reservedIds = null) {
    const occupied = reservedIds instanceof Set
        ? reservedIds
        : new Set((state.companions || []).map(companion => String(companion?.id || '')));
    for (let attempt = 0; attempt < 20; attempt += 1) {
        const uuid = typeof globalThis.crypto?.randomUUID === 'function'
            ? globalThis.crypto.randomUUID().replace(/-/g, '')
            : `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 12)}${attempt.toString(36)}`;
        const id = `companion_${uuid}`.slice(0, 80);
        if (!occupied.has(id)) return id;
    }
    return `companion_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 14)}`.slice(0, 80);
}

async function loadCompanionsState() {
    const rawCompanions = await HordeDB.get('companions') || [];
    const rawThreads = await HordeDB.get('companionThreads') || {};
    const rawTimelines = await HordeDB.get('companionTimelines') || {};
    const occupiedIds = new Set();
    let repairedDuplicateIds = false;
    const loadRecords = rawCompanions.map(raw => {
        const companion = normalizeCompanion(raw);
        const sourceId = companion.id;
        const duplicate = occupiedIds.has(sourceId);
        if (duplicate) {
            companion.id = freshCompanionId(occupiedIds);
            repairedDuplicateIds = true;
        }
        occupiedIds.add(companion.id);
        return { companion, sourceId, duplicate };
    });
    state.companions = loadRecords.map(record => record.companion);
    state.companionThreads = {};
    state.companionTimelines = {};
    loadRecords.forEach(({ companion, sourceId, duplicate }) => {
        // A duplicate record becomes a genuinely independent human. Copying
        // the shared old timeline would preserve the very coupling this repair
        // is meant to remove, so only the first owner keeps that history.
        const stored = !duplicate && isPlainObject(rawTimelines[sourceId]) ? rawTimelines[sourceId] : {};
        const legacyMessages = (!duplicate && Array.isArray(rawThreads[sourceId]) ? rawThreads[sourceId] : [])
            .map(normalizeCompanionMessage).slice(-5000);
        const sessions = (Array.isArray(stored.sessions) ? stored.sessions : []).map(session =>
            normalizeCompanionTimeline(session, companion));
        if (!sessions.length) {
            sessions.push(normalizeCompanionTimeline({
                name: 'Main Timeline',
                messages: legacyMessages,
                runtime: captureCompanionRuntime(companion)
            }, companion));
        }
        sessions.forEach(session => {
            session.messages = repairCompanionProtocolLeaks(session.messages, companion.name);
            // Older builds could fire initiative immediately after installing a
            // never-met human. Remove only that unmistakable cold-open shape:
            // no player turn at all, and every conversational reply marked as
            // autonomous. Authored intros and real conversations are untouched.
            const conversational = session.messages.filter(message =>
                message.type !== 'system' && ['user', 'companion'].includes(message.role));
            if (companion.priorContact !== 'spoken_before'
                && !conversational.some(message => message.role === 'user')
                && conversational.length
                && conversational.every(message => message.role === 'companion' && message.autonomous)) {
                const removedIds = new Set(conversational.map(message => message.id));
                session.messages = session.messages.filter(message => !removedIds.has(message.id));
            }
            session.messages.forEach(message => {
                if (message.type !== 'photo' || !message.pending || message.photo) return;
                message.pending = false;
                message.generationError = message.generationError
                    || 'Photo generation was interrupted before it completed. Retry the photo.';
            });
        });
        const activeSessionId = sessions.some(session => session.id === stored.activeSessionId)
            ? stored.activeSessionId : sessions[0].id;
        state.companionTimelines[companion.id] = { activeSessionId, sessions };
        const active = sessions.find(session => session.id === activeSessionId) || sessions[0];
        applyCompanionRuntime(companion, active.runtime);
        state.companionThreads[companion.id] = active.messages;
    });
    state.activeCompanionId = await HordeDB.get('activeCompanionId') || null;
    if (state.activeCompanionId && !state.companions.some(companion => companion.id === state.activeCompanionId)) {
        state.activeCompanionId = null;
        repairedDuplicateIds = true;
    }
    return repairedDuplicateIds;
}

function createCompanion() {
    const companion = normalizeCompanion({
        id: freshCompanionId(),
        name: 'New Virtual Human'
    });
    state.companions.unshift(companion);
    state.companionTimelines[companion.id] = { activeSessionId: '', sessions: [] };
    ensureCompanionTimelineStore(companion.id);
    state.editingCompanionId = companion.id;
    return companion;
}

function deleteCompanion(id) {
    state.companions = state.companions.filter(c => c.id !== id);
    delete state.companionThreads[id];
    delete state.companionTimelines[id];
    if (state.activeCompanionId === id) state.activeCompanionId = null;
    if (state.editingCompanionId === id) state.editingCompanionId = null;
}

function getCompanion(id) {
    return state.companions.find(c => c.id === id) || null;
}

function buildCompanionShareData(companion, nowMs = Date.now()) {
    if (!companion) throw new Error('No Virtual Human selected');
    const shareable = normalizeCompanion(safeJsonClone(companion));
    // Character sharing carries authored identity, inner life, model/media
    // configuration and the generated Active Life blueprint. Everything
    // learned or experienced in conversation starts fresh for the recipient.
    applyCompanionRuntime(shareable, freshCompanionRuntime(shareable, nowMs));
    return safeJsonClone(shareable);
}

function blobToDataUrl(blob) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ''));
        reader.onerror = () => reject(reader.error || new Error('Could not encode media.'));
        reader.readAsDataURL(blob);
    });
}

function dataUrlToBlob(source) {
    const match = String(source || '').match(/^data:([^;,]+);base64,(.+)$/s);
    if (!match) throw new Error('Archive media is not valid base64 data.');
    const binary = atob(match[2]);
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index++) bytes[index] = binary.charCodeAt(index);
    return new Blob([bytes], { type: match[1] });
}

async function portableMediaSource(source, expectedPrefix, warnings) {
    const value = String(source || '').trim();
    if (!value) return '';
    if (value.startsWith(`data:${expectedPrefix}/`)) return value;
    try {
        const response = await fetch(value);
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const blob = await response.blob();
        if (!blob.type.startsWith(`${expectedPrefix}/`)) throw new Error(`received ${blob.type || 'unknown media'}`);
        return await blobToDataUrl(blob);
    } catch (error) {
        warnings.push(`${expectedPrefix} media could not be embedded (${error.message || error})`);
        return value;
    }
}

async function embedCompanionArchiveMedia(companion, timelines) {
    const warnings = [];
    const imageCache = new Map();
    const videoCache = new Map();
    const videos = [];
    const embedImageField = async (holder, key) => {
        if (!holder?.[key]) return;
        const source = String(holder[key]);
        if (!imageCache.has(source)) imageCache.set(source, portableMediaSource(source, 'image', warnings));
        holder[key] = await imageCache.get(source);
    };
    const embedPostList = async posts => {
        for (const post of Array.isArray(posts) ? posts : []) await embedImageField(post, 'photo');
    };
    const embedVideoJob = async job => {
        if (!job) return;
        await embedImageField(job, 'poster');
        const key = job.assetId ? `asset:${job.assetId}`
            : job.bundledSrc ? `bundled:${job.bundledSrc}`
                : job.outputUrl ? `url:${job.outputUrl}` : '';
        if (!key) return;
        if (!videoCache.has(key)) {
            videoCache.set(key, (async () => {
                try {
                    let blob = job.assetId ? await HordeDB.get(`companionVideoAsset:${job.assetId}`) : null;
                    if (!(blob instanceof Blob)) {
                        const source = job.bundledSrc || job.outputUrl;
                        const response = await fetch(source);
                        if (!response.ok) throw new Error(`HTTP ${response.status}`);
                        blob = await response.blob();
                    }
                    if (!blob.type.startsWith('video/')) throw new Error(`received ${blob.type || 'unknown media'}`);
                    const id = `video_${videos.length + 1}`;
                    videos.push({ id, data: await blobToDataUrl(blob) });
                    return id;
                } catch (error) {
                    warnings.push(`clip could not be embedded (${error.message || error})`);
                    return '';
                }
            })());
        }
        const mediaId = await videoCache.get(key);
        if (!mediaId) return;
        job.archiveMediaId = mediaId;
        job.assetId = '';
        job.outputUrl = '';
        job.bundledSrc = '';
    };
    const embedRuntime = async runtime => {
        if (!runtime) return;
        await embedPostList(runtime.socialPosts);
        for (const job of Array.isArray(runtime.videoJobs) ? runtime.videoJobs : []) await embedVideoJob(job);
    };

    await embedImageField(companion, 'profilePhoto');
    await embedImageField(companion, 'basePhoto');
    await embedPostList(companion.startingSocialPosts);
    await embedPostList(companion.socialPosts);
    for (const job of Array.isArray(companion.startingVideoClips) ? companion.startingVideoClips : []) await embedVideoJob(job);
    for (const job of Array.isArray(companion.videoJobs) ? companion.videoJobs : []) await embedVideoJob(job);
    for (const timeline of Array.isArray(timelines?.sessions) ? timelines.sessions : []) {
        await embedRuntime(timeline.runtime);
        for (const message of Array.isArray(timeline.messages) ? timeline.messages : []) {
            await embedImageField(message, 'photo');
            if (message.audio) message.audio = await portableMediaSource(message.audio, 'audio', warnings);
        }
    }
    return { videos, warnings: [...new Set(warnings)] };
}

async function buildCompanionArchivePayload(companion, kind = 'character-template', nowMs = Date.now()) {
    if (!companion) throw new Error('No Virtual Human selected');
    const portable = kind === 'portable-human';
    if (portable) persistCompanionRuntime(companion);
    const archivedCompanion = portable
        ? safeJsonClone(normalizeCompanion(companion))
        : buildCompanionShareData(companion, nowMs);
    const timelines = portable
        ? safeJsonClone(ensureCompanionTimelineStore(companion.id))
        : { activeSessionId: '', sessions: [] };
    const media = await embedCompanionArchiveMedia(archivedCompanion, timelines);
    return {
        _format: 'horde-studio-virtual-human',
        _version: 3,
        _kind: portable ? 'portable-human' : 'character-template',
        _exportedAt: new Date().toISOString(),
        companion: archivedCompanion,
        ...(portable ? { timelines } : {}),
        ...(media.videos.length ? { media: { videos: media.videos } } : {}),
        ...(media.warnings.length ? { _mediaWarnings: media.warnings } : {})
    };
}

function companionArchiveFileName(name) {
    const stem = String(name || 'virtual_human').trim()
        .replace(/[^A-Za-z0-9._-]+/g, '_')
        .replace(/^_+|_+$/g, '')
        .slice(0, 100) || 'virtual_human';
    return `${stem}.horde_human`;
}

let companionExportTargetId = '';

function closeCompanionExportModal() {
    const overlay = document.getElementById('companion-export-overlay');
    overlay?.classList.add('hidden');
    overlay?.setAttribute('aria-hidden', 'true');
    companionExportTargetId = '';
}

function exportCompanionArchive(companionId = state.editingCompanionId || state.activeCompanionId) {
    const companion = getCompanion(companionId);
    if (!companion) return showToast('No Virtual Human selected to export.', 'error');
    companionExportTargetId = companion.id;
    const title = document.getElementById('companion-export-title');
    const copy = document.getElementById('companion-export-copy');
    if (title) title.textContent = `Export ${companion.name || 'Virtual Human'}`;
    if (copy) copy.textContent = 'Choose a clean shareable template or preserve this person exactly as they are now.';
    const overlay = document.getElementById('companion-export-overlay');
    overlay?.classList.remove('hidden');
    overlay?.setAttribute('aria-hidden', 'false');
}

async function downloadCompanionArchive(kind) {
    const companion = getCompanion(companionExportTargetId);
    if (!companion) return showToast('No Virtual Human selected to export.', 'error');
    const progress = document.getElementById('companion-export-progress');
    const buttons = [document.getElementById('export-companion-template-btn'), document.getElementById('export-companion-portable-btn')];
    progress?.classList.remove('hidden');
    buttons.forEach(button => { if (button) button.disabled = true; });
    let payload;
    try {
        payload = await buildCompanionArchivePayload(companion, kind);
    } catch (error) {
        console.error('Virtual Human export failed:', error);
        showToast(`Virtual Human export failed: ${error.message}`, 'error');
        return;
    } finally {
        progress?.classList.add('hidden');
        buttons.forEach(button => { if (button) button.disabled = false; });
    }
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = companionArchiveFileName(`${companion.name}${kind === 'portable-human' ? '_portable' : '_template'}`);
    anchor.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    closeCompanionExportModal();
    const warningCount = payload._mediaWarnings?.length || 0;
    showToast(kind === 'portable-human'
        ? `Exported ${companion.name || 'this Virtual Human'} with timelines, social life and media${warningCount ? ` (${warningCount} external item${warningCount === 1 ? '' : 's'} remained linked)` : ''}.`
        : `Exported a clean template of ${companion.name || 'this Virtual Human'} with authored starter media.`, warningCount ? 'info' : 'success');
}

function restoreCompanionArchive(rawArchive, nowMs = Date.now()) {
    const archive = validateCompanionArchiveData(rawArchive);
    const sourceId = archive.companion.id || 'imported';
    let companionId = livingId('companion', `${sourceId}|${archive.companion.name}|${nowMs}|${Math.random()}`);
    while (state.companions.some(item => item.id === companionId)) {
        companionId = livingId('companion', `${companionId}|${Math.random()}`);
    }
    const companion = normalizeCompanion({
        ...archive.companion,
        id: companionId
    });
    if (archive._version === 2 || (archive._version === 3 && archive._kind === 'character-template')) {
        applyCompanionRuntime(companion, freshCompanionRuntime(companion, nowMs));
    }
    const sourceSessions = Array.isArray(archive.timelines.sessions)
        ? archive.timelines.sessions : [];
    const sessionIdMap = new Map();
    const sessions = sourceSessions.map((source, index) => {
        const nextId = livingId('vh_timeline', `${companionId}|${source.id || index}|${nowMs}|${index}`);
        sessionIdMap.set(source.id, nextId);
        return normalizeCompanionTimeline({ ...source, id: nextId }, companion);
    });
    if (!sessions.length) {
        sessions.push(normalizeCompanionTimeline({
            name: 'Main Timeline',
            runtime: captureCompanionRuntime(companion),
            messages: []
        }, companion));
    }
    const requestedActiveId = sessionIdMap.get(archive.timelines.activeSessionId);
    const activeSessionId = sessions.some(session => session.id === requestedActiveId)
        ? requestedActiveId : sessions[0].id;
    state.companions.unshift(companion);
    state.companionTimelines[companion.id] = { activeSessionId, sessions };
    const active = sessions.find(session => session.id === activeSessionId) || sessions[0];
    applyCompanionRuntime(companion, active.runtime);
    state.companionThreads[companion.id] = active.messages;
    state.editingCompanionId = companion.id;
    return companion;
}

async function hydrateCompanionArchiveMedia(companion, media) {
    const entries = Array.isArray(media?.videos) ? media.videos : [];
    if (!entries.length) return;
    const assetIds = new Map();
    for (const entry of entries) {
        const blob = dataUrlToBlob(entry.data);
        const assetId = livingId('vh_video_asset', `${companion.id}|${entry.id}|${Date.now()}`);
        await HordeDB.set(`companionVideoAsset:${assetId}`, blob);
        assetIds.set(entry.id, assetId);
    }
    const hydrateJobs = jobs => (Array.isArray(jobs) ? jobs : []).forEach(job => {
        const assetId = assetIds.get(job.archiveMediaId);
        if (!assetId) return;
        job.assetId = assetId;
        job.archiveMediaId = '';
        job.outputUrl = '';
        job.bundledSrc = '';
    });
    hydrateJobs(companion.startingVideoClips);
    hydrateJobs(companion.videoJobs);
    const store = state.companionTimelines[companion.id];
    (store?.sessions || []).forEach(timeline => hydrateJobs(timeline.runtime?.videoJobs));
    const active = getActiveCompanionTimeline(companion.id);
    if (active) applyCompanionRuntime(companion, active.runtime);
}

function importCompanionArchiveFile(file) {
    if (!file) return;
    if (file.size > 512 * 1024 * 1024) {
        showToast('Import failed: Virtual Human archive is larger than 512 MB.', 'error');
        return;
    }
    const reader = new FileReader();
    reader.onload = async event => {
        try {
            const rawArchive = JSON.parse(event.target.result);
            const archive = validateCompanionArchiveData(rawArchive);
            const companion = restoreCompanionArchive(archive);
            await hydrateCompanionArchiveMedia(companion, archive.media);
            await saveState();
            renderCompanionsGrid();
            openCompanionStudio(companion.id);
            switchView('companionStudio');
            showToast(`Imported ${companion.name || 'Virtual Human'} as a separate copy.`, 'success');
        } catch (error) {
            console.error('Virtual Human import failed:', error);
            showToast('Virtual Human import failed: ' + error.message, 'error');
        }
    };
    reader.onerror = () => showToast('Virtual Human import failed: the file could not be read.', 'error');
    reader.readAsText(file);
}

// --- Sending a message: the network loop ------------------------------------

/**
 * Split a reply into separate bubbles the way a real person sends a burst of
 * texts rather than one long paragraph — on blank lines first (paragraph
 * breaks), and if a single paragraph still runs long, on sentence boundaries.
 */
function splitCompanionReplyIntoBubbles(text, enabled = true) {
    const normalized = String(text || '').trim();
    if (!normalized) return [];
    if (!enabled) return [normalized.replace(/\n+/g, ' ').replace(/\s{2,}/g, ' ').trim()];
    const paragraphs = normalized.split(/\n{2,}/).map(p => p.replace(/\n+/g, ' ').trim()).filter(Boolean);
    const bubbles = [];
    paragraphs.forEach(paragraph => {
        if (paragraph.length <= 340) {
            const previous = bubbles[bubbles.length - 1];
            if (previous && previous.length > 100 && paragraph.length < 25 && previous.length + paragraph.length < 340) {
                bubbles[bubbles.length - 1] = `${previous}\n\n${paragraph}`;
            } else bubbles.push(paragraph);
            return;
        }
        const sentences = paragraph.match(/[^.!?]+(?:[.!?]+[”"']?)(?:\s+|$)|[^.!?]+$/g) || [paragraph];
        let current = '';
        sentences.forEach(sentence => {
            if ((current + sentence).length > 340 && current) { bubbles.push(current.trim()); current = ''; }
            current += sentence;
        });
        if (current.trim()) bubbles.push(current.trim());
    });
    return bubbles;
}

function sanitizeCompanionTextReply(text, companionName = '') {
    const actionCue = /^(?:smiles?|grins?|laughs?|giggles?|sighs?|nods?|shrugs?|blushes?|frowns?|cries?|weeps?|gasps?|pauses?|hesitates?|looks?|stares?|walks?|steps?|moves?|leans?|reaches?|touches?|hugs?|kisses?|waves?|sits?|stands?|turns?|rolls? (?:my|their|his|her) eyes|[a-z]+ing\b)/i;
    const escapedName = String(companionName || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    let cleaned = String(text || '')
        // Remove explicit RP actions while retaining ordinary emphasis:
        // "*really*?" becomes "really?", but "*smiles*" disappears.
        .replace(/\*([^*\n]{1,140})\*/g, (match, inner) =>
            actionCue.test(inner.trim()) ? '' : inner)
        .replace(/_([^_\n]{1,140})_/g, (match, inner) =>
            actionCue.test(inner.trim()) ? '' : inner)
        .split('\n')
        .map(line => {
            const trimmed = line.trim();
            if (!trimmed) return '';
            const bracketed = trimmed.match(/^[[(]([^)\]]{1,140})[\])]$/);
            if (bracketed && actionCue.test(bracketed[1].trim())) return '';
            const narrator = new RegExp(`^(?:she|he|they${escapedName ? `|${escapedName}` : ''})\\s+(.+)$`, 'i').exec(trimmed);
            if (narrator && actionCue.test(narrator[1])) return '';
            const dialogueTag = /^(?:she|he|they)\s+(?:says?|texts?|replies?)[,:]?\s*["“]([\s\S]+?)["”]$/i.exec(trimmed);
            return dialogueTag ? dialogueTag[1] : trimmed;
        })
        .filter(Boolean)
        .join('\n')
        .replace(/[ \t]{2,}/g, ' ')
        .trim();
    return cleaned;
}

function repairCompanionProtocolLeaks(messages, companionName = '') {
    const source = Array.isArray(messages) ? messages : [];
    const protocolPattern = /uncensored[_-]?tool[_-]?call|<\/?tool[_-]?call|<\/?arg[_-]?(?:key|value)>|\b(?:commit_?human_?turn|commithumanturn|companion_?state)\s*\(|\b(?:valence_?change|relationship_?change|memory_?write|life_?state)\s*=/i;
    const groups = new Map();
    source.forEach((message, index) => {
        if (message?.role !== 'companion' || message.type !== 'text') return;
        const key = message.responseGroupId || `single:${index}`;
        if (!groups.has(key)) groups.set(key, []);
        groups.get(key).push({ message, index });
    });
    const replacements = new Map();
    groups.forEach(entries => {
        const combined = entries.map(entry => String(entry.message.text || '')).join('\n');
        if (!protocolPattern.test(combined)) return;
        const embedded = extractCompanionEmbeddedToolCalls(combined);
        const cleaned = sanitizeCompanionTextReply(quarantineCompanionProtocolText(embedded.visibleText), companionName);
        const bubbles = splitCompanionReplyIntoBubbles(cleaned);
        const base = entries[0].message;
        replacements.set(entries[0].index, bubbles.map((text, bubbleIndex) => normalizeCompanionMessage({
            ...base,
            id: bubbleIndex ? livingId('vh_message', `${base.id}|protocol-repair|${bubbleIndex}`) : base.id,
            text,
            timestamp: base.timestamp + bubbleIndex * 400,
            links: bubbleIndex ? [] : base.links,
            turnSnapshot: bubbleIndex ? null : base.turnSnapshot,
            turnAudit: bubbleIndex ? null : base.turnAudit
        })));
        entries.slice(1).forEach(entry => replacements.set(entry.index, []));
    });
    return source.flatMap((message, index) => replacements.has(index) ? replacements.get(index) : [message]);
}

async function repairCompanionTurnCommit(companion, promptMessages, visibleReply, options = {}) {
    try {
        const textProvider = companionTextProviderId(companion);
        const recoverVisibleOnly = options.recoverVisible === true && options.preserveCommit === true;
        const repairMessages = [
            ...promptMessages,
            { role: 'assistant', content: visibleReply || '[No visible text; the response may consist only of media.]' },
            {
                role: 'user',
                content: recoverVisibleOnly
                    ? `[VISIBLE REPLY RECOVERY — PRIVATE INSTRUCTION, NOT A PLAYER MESSAGE]
The private commit_human_turn receipt was recorded successfully, but the completion contained no player-visible reply or deliverable media. Return only one clean, natural reply to the player's latest actual message. Do not call tools, output JSON, mention this recovery, add timing headers, or expose engine language.`
                    : `[PRIVATE SIMULATION RECEIPT REPAIR — DO NOT WRITE ANOTHER VISIBLE MESSAGE]
Call commit_human_turn once for the response immediately above. Preserve what it actually did. Explicitly decide photo, voice_note and video_clip; use video_clip=none unless the player explicitly sent a [CLIP REQUEST id]. Report the emotional state change. Do not invent media that the visible response did not agree to send. Choose one conversation_goal. Keep profile claims, direct statements and observed patterns distinct. Add no unsupported relationship jump, secret, boundary event or milestone.`
            }
        ];
        const body = applyCompanionGenerationConfig({
            model: companion.model || state.globalSettings.defaultModel,
            messages: sanitizeMessagesForProvider(repairMessages, textProvider),
            ...(recoverVisibleOnly ? {} : {
                tools: [COMPANION_TURN_COMMIT_TOOL],
                tool_choice: { type: 'function', function: { name: 'commit_human_turn' } }
            })
        }, companion, { maxTokens: Math.min(2400, companionProviderOutputBudget(companion)) });
        const response = await fetchCompanionCompletion(providerApiBase(textProvider) + '/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', ...providerAuthHeaders(textProvider), ...providerAttributionHeaders(textProvider) },
            body: JSON.stringify(applyOpenRouterRouting(body, null, { providerId: textProvider }))
        }, companion, true);
        if (!response.ok) return null;
        const message = (await response.json())?.choices?.[0]?.message || {};
        const embedded = extractCompanionEmbeddedToolCalls(message.content);
        const repaired = extractCompanionToolCalls([
            ...(Array.isArray(message.tool_calls) ? message.tool_calls : []),
            ...embedded.toolCalls
        ]);
        const recoveredVisible = companionVisibleReplyLimit(sanitizeCompanionTextReply(
            quarantineCompanionProtocolText(embedded.visibleText), companion.name), companion);
        if (recoverVisibleOnly) return recoveredVisible ? { visibleReply: recoveredVisible } : null;
        if (repaired.commit) return { ...repaired, visibleReply: recoveredVisible };
        const parsed = safeParseJSONRepair(embedded.visibleText);
        return isPlainObject(parsed) ? { ...extractCompanionToolCalls([{
            function: { name: 'commit_human_turn', arguments: JSON.stringify(parsed) }
        }]), visibleReply: recoveredVisible } : null;
    } catch (error) {
        console.warn('Virtual Human receipt repair failed:', error);
        return null;
    }
}

function applyCompanionAgencyCommit(companion, rawAgency, nowMs, sourceMessageIds = []) {
    const agency = isPlainObject(rawAgency) ? rawAgency : {};
    const runtime = companionContinuity(companion);
    const perceived = String(agency.perceived_event || '').trim().slice(0, 700);
    const interpretation = String(agency.interpretation || '').trim().slice(0, 700);
    const decision = String(agency.decision || '').trim().slice(0, 400);
    const pressures = (Array.isArray(agency.pressures) ? agency.pressures : [])
        .map(value => String(value).trim().slice(0, 240)).filter(Boolean).slice(0, 8);
    const goal = isPlainObject(agency.conversation_goal) ? agency.conversation_goal : {};
    const goalTypes = ['respond', 'learn', 'connect', 'impress', 'flirt', 'reassure', 'seek_reassurance',
        'entertain', 'sell', 'obtain_money', 'recruit', 'avoid_disclosure', 'change_subject', 'test_boundary',
        'enforce_boundary', 'repair', 'deescalate', 'delay_commitment', 'end_conversation', 'maintain_access',
        'practical', 'other'];
    runtime.conversationGoal = {
        type: goalTypes.includes(goal.type) ? goal.type : 'respond',
        objective: String(goal.objective || decision || 'Respond to what the player actually said.').trim().slice(0, 400),
        reason: String(goal.reason || interpretation || 'This is the most fitting immediate response.').trim().slice(0, 500),
        chosenAt: nowMs
    };
    if (decision || perceived || interpretation) {
        companionSetDecisionEvidence(companion, {
            decision: decision || 'Respond naturally', perceived, interpretation,
            pressures: pressures.length ? pressures : companionDecisionPressures(companion, nowMs),
            confidence: agency.confidence, source: 'model', createdAt: nowMs
        });
    }
    const decisionEvent = companionRecordContinuityEvent(companion, {
        type: decision ? 'response_sent' : 'system',
        summary: decision || perceived,
        interpretation,
        certainty: agency.confidence,
        sourceMessageIds,
        createdAt: nowMs,
        perceivedAt: nowMs,
        dedupeKey: sourceMessageIds.length ? `decision:${sourceMessageIds.join(',')}:${nowMs}` : ''
    });
    (Array.isArray(agency.belief_updates) ? agency.belief_updates : []).slice(0, 12)
        .forEach(raw => companionApplyBeliefUpdate(companion, raw, nowMs, decisionEvent?.id || ''));
    (Array.isArray(agency.player_model_updates) ? agency.player_model_updates : []).slice(0, 12)
        .forEach(raw => companionApplyPlayerModelUpdate(companion, raw, nowMs, decisionEvent?.id || ''));
    (Array.isArray(agency.boundary_updates) ? agency.boundary_updates : []).slice(0, 8)
        .forEach(raw => companionApplyBoundaryUpdate(companion, raw, nowMs));
    (Array.isArray(agency.truth_updates) ? agency.truth_updates : []).slice(0, 6)
        .forEach(raw => companionApplyTruthUpdate(companion, raw, nowMs));
    (Array.isArray(agency.milestones) ? agency.milestones : []).slice(0, 4)
        .forEach(raw => companionRecordMilestone(companion, raw, nowMs));
    (Array.isArray(agency.intention_updates) ? agency.intention_updates : []).slice(0, 12)
        .forEach(raw => companionApplyIntentionUpdate(companion, raw, nowMs, decisionEvent?.id || ''));
    (Array.isArray(agency.episode_updates) ? agency.episode_updates : []).slice(0, 6).forEach(raw => {
        const existing = runtime.episodes.find(item => item.id === raw?.id);
        if (existing && raw.operation === 'archive') {
            existing.status = 'archived'; existing.updatedAt = nowMs;
        } else if (existing && raw.operation === 'reinterpret') {
            existing.status = 'reinterpreted';
            existing.emotionalMeaning = String(raw.emotional_meaning || existing.emotionalMeaning).trim().slice(0, 700);
            existing.emotionalTone = String(raw.emotional_tone || existing.emotionalTone).trim().slice(0, 120);
            existing.relationshipImpact = livingClamp(Number.isFinite(Number(raw.relationship_impact)) ? Number(raw.relationship_impact) : existing.relationshipImpact, -100, 100);
            existing.updatedAt = nowMs;
        } else if (raw?.operation === 'remember' && String(raw?.summary || '').trim()) {
            companionRecordEpisode(companion, {
                title: raw.title, summary: raw.summary, emotionalMeaning: raw.emotional_meaning,
                participants: raw.participants, importance: raw.importance, emotionalTone: raw.emotional_tone,
                relationshipImpact: raw.relationship_impact, unresolvedThreadIds: raw.thread_ids,
                sourceEventIds: decisionEvent?.id ? [decisionEvent.id] : [], createdAt: nowMs
            }, nowMs);
        }
    });
    (Array.isArray(agency.thread_updates) ? agency.thread_updates : []).slice(0, 12).forEach((raw, index) => {
        const existing = runtime.openThreads.find(item => item.id === raw?.id)
            || runtime.openThreads.find(item => item.status !== 'resolved'
                && item.topic.toLowerCase() === String(raw?.topic || '').trim().toLowerCase());
        if (existing) {
            existing.status = raw.operation === 'resolve' ? 'resolved' : raw.operation === 'escalate' ? 'escalating'
                : raw.operation === 'dormant' ? 'dormant' : 'open';
            existing.summary = String(raw.summary || existing.summary).trim().slice(0, 700);
            existing.stakes = String(raw.stakes || existing.stakes).trim().slice(0, 500);
            existing.salience = livingClamp(Number.isFinite(Number(raw.salience)) ? Number(raw.salience) : existing.salience, 0, 100);
            existing.updatedAt = nowMs;
            if (existing.status === 'resolved') existing.resolvedAt = nowMs;
        } else if (raw?.operation === 'open' && String(raw?.topic || '').trim()) {
            runtime.openThreads.push(normalizeCompanionOpenThread({ ...raw, status: 'open', createdAt: nowMs, updatedAt: nowMs }, runtime.openThreads.length + index));
        }
    });
    runtime.beliefs = runtime.beliefs.slice(-120);
    runtime.intentions = runtime.intentions.slice(-100);
    runtime.openThreads = runtime.openThreads.slice(-80);
    runtime.episodes = runtime.episodes.slice(-120);
    runtime.playerModel = runtime.playerModel.slice(-160);
    runtime.boundaries = runtime.boundaries.slice(-100);
    runtime.truthLedger = runtime.truthLedger.slice(-100);
    runtime.milestones = runtime.milestones.slice(-120);
}

function applyCompanionTurnCommit(companion, commit, nowMs, source = 'turn', sourceMessageIds = []) {
    if (!isPlainObject(commit)) return;
    applyCompanionAgencyCommit(companion, commit.agency, nowMs, sourceMessageIds);
    if (sourceMessageIds.length) companionRecordMilestone(companion, {
        type: 'first_message', summary: `First active exchange between ${companion.name} and the player.`
    }, nowMs);
    const lifeEvent = String(commit.life_event || '').trim();
    if (lifeEvent) {
        companion.lifeEvents.push(normalizeCompanionLifeEvent({
            text: lifeEvent, createdAt: nowMs, source
        }));
        companionRecordContinuityEvent(companion, {
            type: 'life_event', summary: lifeEvent, certainty: 100,
            createdAt: nowMs, perceivedAt: nowMs,
            dedupeKey: `life:${source}:${nowMs}:${lifeEvent.slice(0, 80)}`
        });
    }
    companion.lifeEvents = companion.lifeEvents.slice(-200);
    const relationshipEvent = String(commit.relationship_event || '').trim();
    if (relationshipEvent && !(commit.agency?.episode_updates || []).some(item => item?.operation === 'remember')) {
        companionRecordEpisode(companion, {
            title: relationshipEvent.slice(0, 120), summary: relationshipEvent,
            emotionalMeaning: 'A relationship moment worth retaining beyond the recent transcript.',
            participants: ['player', companion.name], importance: 62,
            relationshipImpact: Number(commit.state?.relationship_change) || 0,
            emotionalTone: String(commit.state?.mood_label || ''), createdAt: nowMs
        }, nowMs);
    }
    if (isPlainObject(commit.life_state)) {
        if (String(commit.life_state.outfit || '').trim()) {
            companion.currentOutfit = String(commit.life_state.outfit).trim().slice(0, 400);
        }
        if (String(commit.life_state.location_detail || '').trim()) {
            companion.currentLocationDetail = String(commit.life_state.location_detail).trim().slice(0, 300);
        }
        if (isPlainObject(commit.life_state.temporary_situation)) {
            const temporary = commit.life_state.temporary_situation;
            const activity = String(temporary.activity || '').trim();
            const reason = String(temporary.reason || '').trim();
            const duration = livingClamp(Math.round(Number(temporary.duration_minutes) || 0), 15, 720);
            if (activity && reason) {
                companion.lifeRuntime.temporarySituation = normalizeCompanionLifeRuntime({
                    temporarySituation: {
                        activity,
                        placeLabel: temporary.place_label,
                        withNames: temporary.with_names,
                        availability: temporary.availability,
                        outfit: commit.life_state.outfit,
                        startedAt: nowMs,
                        endsAt: nowMs + duration * 60000,
                        reason
                    }
                }).temporarySituation;
            }
        }
    }
    (Array.isArray(commit.commitments) ? commit.commitments : []).slice(0, 20).forEach(raw => {
        const action = raw?.action;
        if (action === 'create' && String(raw.text || '').trim()) {
            const dueMinutes = livingClamp(Number(raw.due_in_minutes) || 0, 0, 60 * 24 * 90);
            companion.commitments.push(normalizeCompanionCommitment({
                text: raw.text,
                medium: raw.medium,
                dueAt: dueMinutes ? nowMs + dueMinutes * 60 * 1000 : 0,
                createdAt: nowMs
            }));
            companionRecordContinuityEvent(companion, {
                type: 'commitment', summary: `Made a commitment: ${String(raw.text).trim()}`,
                certainty: 100, createdAt: nowMs, perceivedAt: nowMs
            });
            return;
        }
        const existing = companion.commitments.find(item => item.id === raw?.id && item.status === 'pending');
        if (existing && ['fulfill', 'cancel'].includes(action)) {
            existing.status = action === 'fulfill' ? 'fulfilled' : 'cancelled';
            existing.resolvedAt = nowMs;
            companionRecordContinuityEvent(companion, {
                type: 'commitment',
                summary: `${action === 'fulfill' ? 'Fulfilled' : 'Cancelled'} commitment: ${existing.text}`,
                certainty: 100, createdAt: nowMs, perceivedAt: nowMs
            });
        }
    });
    if (commit.photo?.decision === 'postpone' && Number(commit.photo.due_in_minutes) > 0) {
        const text = String(commit.photo.reason || 'Send the promised photo').trim();
        companion.commitments.push(normalizeCompanionCommitment({
            text, medium: 'photo',
            dueAt: nowMs + livingClamp(Number(commit.photo.due_in_minutes), 1, 60 * 24 * 30) * 60 * 1000,
            createdAt: nowMs
        }));
    }
    const fulfillOldest = medium => {
        const pending = companion.commitments.find(item => item.status === 'pending' && item.medium === medium);
        if (pending) {
            pending.status = 'fulfilled';
            pending.resolvedAt = nowMs;
        }
    };
    if (commit.photo?.decision === 'send') {
        fulfillOldest('photo');
        companionRecordMilestone(companion, { type: 'first_photo', summary: `${companion.name} chose to send the player a photo.` }, nowMs);
    }
    if (commit.voice_note?.decision === 'send') {
        fulfillOldest('voice');
        companionRecordMilestone(companion, { type: 'first_voice_note', summary: `${companion.name} chose to send the player a voice note.` }, nowMs);
    }
    companion.commitments = companion.commitments.slice(-100);
    if (String(commit.persona_visual_memory || '').trim()) {
        const activePersona = state.personas.find(persona => persona.id === state.activePersonaId);
        if (activePersona?.avatar) {
            companion.personaVisualMemory = {
                personaId: activePersona.id,
                avatarFingerprint: companionMediaFingerprint(activePersona.avatar),
                description: String(commit.persona_visual_memory).trim().slice(0, 600),
                seenAt: nowMs
            };
        }
    }
    const video = commit.video_clip;
    if (isPlainObject(video) && video.decision && video.decision !== 'none') {
        const existing = [...companion.videoJobs].reverse().find(job =>
            job.status === 'requested' && (!video.request_id || job.id === video.request_id));
        if (existing) {
            existing.status = video.decision === 'accept' || video.decision === 'counter'
                ? 'accepted' : video.decision === 'refuse' ? 'refused' : 'requested';
            existing.concept = String(video.concept || existing.requestText).trim().slice(0, 1800);
            existing.caption = String(video.caption || '').trim().slice(0, 1200);
            existing.clipType = ['selfie', 'dance', 'outfit', 'storytime', 'day_in_life', 'comedy', 'trend', 'custom'].includes(video.clip_type)
                ? video.clip_type : existing.clipType;
            existing.cameraRig = ['selfie', 'handheld', 'fixed'].includes(video.camera_rig)
                ? video.camera_rig : existing.cameraRig;
            existing.reason = String(video.reason || '').trim().slice(0, 1000);
            existing.updatedAt = nowMs;
        }
    }
}

function applyCompanionSocialPostCommit(companion, commit, nowMs, source = 'turn') {
    const raw = commit?.social_post;
    if (!companion.socialFeedEnabled || raw?.decision !== 'post') return null;
    if (companion.socialPostFrequency === 'manual' && source !== 'manual') return null;
    // The feed is a life surface, not a second transcript. Even if a model
    // eagerly proposes a post on every turn, keep public activity human-scale.
    const lastPostAt = Number(companion.socialFeedRuntime?.lastPostAt) || 0;
    if (source !== 'manual' && lastPostAt && nowMs - lastPostAt < companionSocialMinimumGapMs(companion)) return null;
    const allowedTypes = companion.socialContentTypes?.length ? companion.socialContentTypes : ['everyday'];
    const category = allowedTypes.includes(raw.category) ? raw.category : allowedTypes[0];
    const monetized = companion.socialMonetization !== 'none';
    const visibility = monetized && ['public', 'followers', 'subscribers', 'paid'].includes(raw.visibility)
        ? raw.visibility : 'public';
    const text = String(raw.text || '').trim().slice(0, 1200);
    const wantsPhoto = raw.kind === 'photo' && companion.socialFeedImages && companion.allowPhotos
        && String(raw.scene || '').trim();
    if (!text && !wantsPhoto) return null;
    const post = normalizeCompanionSocialPost({
        text,
        kind: wantsPhoto ? 'photo' : 'status',
        scene: wantsPhoto ? String(raw.scene).trim() : '',
        category,
        visibility,
        unlockPrice: visibility === 'paid'
            ? livingClamp(Number(raw.unlock_price) || companion.socialSubscriptionPrice || 10, 0, 1000000) : 0,
        pending: wantsPhoto,
        createdAt: nowMs,
        lifeAnchor: String(raw.reason || '').trim(),
        source
    });
    companion.socialPosts.push(post);
    companion.socialPosts = companion.socialPosts.slice(-200);
    companion.socialFeedRuntime.lastPostAt = nowMs;
    companion.socialFeedRuntime.nextPostAt = companionNextSocialPostAt(companion, nowMs);
    companion.socialFeedRuntime.lastError = '';
    companion.socialFeedRuntime.lastErrorAt = 0;
    companion.socialFeedRuntime.consecutiveFailures = 0;
    companionRecordContinuityEvent(companion, {
        type: 'social_post',
        summary: `They posted ${wantsPhoto ? 'a photo' : 'a status'}: “${text || raw.scene}”`,
        interpretation: String(raw.reason || '').trim(), certainty: 100,
        createdAt: nowMs, perceivedAt: nowMs, dedupeKey: `social_post:${post.id}`
    });
    return wantsPhoto ? post : null;
}

function companionVideoReference(companion) {
    const latestGallery = [...(companion.socialPosts || [])].reverse().find(post => post.photo)?.photo || '';
    const choices = {
        generation: companion.basePhoto,
        profile: companion.profilePhoto,
        gallery: latestGallery,
        auto: companion.basePhoto || companion.profilePhoto || latestGallery
    };
    return normalizeGeneratedImageSource(choices[companion.videoReferencePolicy] || choices.auto);
}

function companionVideoPrompt(companion, job) {
    const life = companionLifeState(companion, Date.now());
    return [
        'Vertical 9:16 short-form social video recorded on a phone.',
        `Camera operation: ${job.cameraRig}; physically plausible framing and hand movement.`,
        'One continuous coherent scene, natural temporal motion, stable identity, realistic phone exposure and compression.',
        `Person: ${companion.appearance || companion.name}.`,
        `Current grounded situation: ${life.label || 'available'}; location: ${companion.currentLocationDetail || life.situation?.placeLabel || companion.locationLabel || 'not specified'}; outfit: ${companion.currentOutfit || life.situation?.outfit || 'use the reference image clothing'}.`,
        `Requested clip: ${job.concept || job.requestText}.`,
        companion.videoAudio ? 'Native audio may include only short natural room sound or the agreed spoken line.' : 'No dialogue; visual-only clip.',
        companion.videoStyleRules ? `Creator rules and boundaries: ${companion.videoStyleRules}` : '',
        'No cinematic crane shots, cuts to impossible viewpoints, captions, logos, watermarks or third-person camera unless fixed/handheld was explicitly selected.'
    ].filter(Boolean).join('\n');
}

async function submitCompanionVideoJob(companion, job) {
    const provider = normalizedVideoProviderId(job.provider || companion.videoProvider);
    if (!companion.allowVideoClips) throw new Error('Clips are disabled for this Virtual Human.');
    if (!videoProviderHasCredentials(provider)) throw new Error(`${videoProviderDisplayName(provider)} is not connected in Settings → Connections.`);
    const reference = companionVideoReference(companion);
    if (!reference) throw new Error('This reference-video model needs an identity image. Add a generation reference, profile image or gallery photo.');
    job.provider = provider;
    job.model = job.model || companion.videoModel || (await fetchVideoModels(provider))[0]?.id || '';
    job.prompt = companionVideoPrompt(companion, job);
    job.status = 'queued'; job.progress = 3; job.updatedAt = Date.now(); job.error = '';
    renderCompanionSocialPanel(companion); await saveState();
    if (provider === 'fal') {
        const fallback = String(companion.videoFallbackModel || '').trim();
        const fallback2 = String(companion.videoFallbackModel2 || '').trim();
        const models = [job.model, fallback, fallback2].filter((item, index, list) => item && list.indexOf(item) === index);
        const submitted = await mcpBridgeRequest('/fal/video/jobs', {
            method: 'POST', timeoutMs: 15000,
            body: {
                apiKey: state.falApiKey, models, prompt: job.prompt,
                duration: job.duration,
                resolution: job.resolution === '720p' ? '768P' : job.resolution.toUpperCase(),
                aspectRatio: '9:16', imageDataUrl: reference,
                enableSafetyChecker: state.globalSettings.falSafetyChecker !== false
            }
        });
        job.providerJobId = submitted.jobId;
        job.status = 'generating'; job.progress = 5; job.updatedAt = Date.now();
        await saveState(); renderCompanionSocialPanel(companion);
        return pollCompanionFalVideoJob(companion, job);
    }
    let endpoint = '';
    let body = {};
    if (provider === 'openrouter') {
        endpoint = `${videoProviderApiBase(provider)}/videos`;
        body = {
            model: job.model, prompt: job.prompt, duration: job.duration,
            resolution: job.resolution, aspect_ratio: '9:16', audio: companion.videoAudio,
            input_references: [{ type: 'image_url', image_url: { url: reference } }]
        };
    } else if (provider === 'evolink') {
        endpoint = `${videoProviderApiBase(provider)}/videos/generations`;
        body = {
            model: job.model, prompt: job.prompt, aspect_ratio: '9:16', duration: job.duration,
            quality: job.resolution, audio: companion.videoAudio, image_urls: [reference], reference_images: [reference]
        };
    } else {
        endpoint = `${videoProviderApiBase(provider)}/${String(job.model).replace(/^\/+/, '')}`;
        body = {
            prompt: job.prompt, image: reference, reference_images: [reference],
            aspect_ratio: '9:16', duration: job.duration, resolution: job.resolution,
            generate_audio: companion.videoAudio
        };
    }
    const response = await fetch(endpoint, { method: 'POST', headers: videoProviderHeaders(provider), body: JSON.stringify(body) });
    const payload = await response.json().catch(async () => ({ error: await response.text().catch(() => '') }));
    if (!response.ok) throw new Error(String(payload?.error?.message || payload?.error || payload?.message || `Video request failed (${response.status})`));
    const data = payload?.data || payload;
    job.providerJobId = String(data?.id || data?.task_id || data?.prediction_id || payload?.id || '').trim();
    const immediate = videoOutputFromPayload(payload);
    if (immediate) return completeCompanionVideoJob(companion, job, immediate);
    if (!job.providerJobId) throw new Error('The video provider accepted the request but returned no job ID.');
    job.status = 'generating'; job.progress = Math.max(5, Number(data?.progress) || 5); job.updatedAt = Date.now();
    await saveState(); renderCompanionSocialPanel(companion);
    return pollCompanionVideoJob(companion, job);
}

async function pollCompanionFalVideoJob(companion, job) {
    const startedAt = Date.now();
    while (Date.now() - startedAt < 20 * 60 * 1000 && ['queued', 'generating'].includes(job.status)) {
        await new Promise(resolve => setTimeout(resolve, 1500));
        const result = await mcpBridgeRequest(`/fal/video/jobs/${encodeURIComponent(job.providerJobId)}`, { timeoutMs: 15000 });
        job.model = result.currentModel || job.model;
        job.progress = Math.min(94, job.progress + (result.status === 'running' ? 3 : 1));
        job.updatedAt = Date.now();
        if (result.status === 'completed') {
            job.model = result.result?.model || job.model;
            job.duration = Number(result.result?.duration) || job.duration;
            return completeCompanionVideoJob(companion, job, `${mcpBridgeBase()}${result.result?.mediaUrl || ''}`);
        }
        if (['failed', 'cancelled'].includes(result.status)) {
            throw new Error(result.error || `Fal video generation ${result.status}.`);
        }
        renderCompanionSocialPanel(companion);
    }
    throw new Error('Fal video generation timed out. The bridge retained the job for recovery.');
}

async function completeCompanionVideoJob(companion, job, outputUrl) {
    job.status = 'downloading'; job.progress = 96; job.outputUrl = outputUrl; job.updatedAt = Date.now();
    renderCompanionSocialPanel(companion);
    await persistCompanionVideoAsset(job, outputUrl);
    job.status = 'ready'; job.progress = 100; job.updatedAt = Date.now(); job.error = '';
    companion.usage.videosGenerated = (Number(companion.usage.videosGenerated) || 0) + 1;
    await saveState(); renderCompanionSocialPanel(companion);
    return job;
}

async function completeCompanionVideoJobFromResponse(companion, job, response) {
    const blob = await response.blob();
    job.status = 'downloading'; job.progress = 96; job.updatedAt = Date.now();
    renderCompanionSocialPanel(companion);
    await persistCompanionVideoBlob(job, blob);
    job.status = 'ready'; job.progress = 100; job.updatedAt = Date.now(); job.error = '';
    companion.usage.videosGenerated = (Number(companion.usage.videosGenerated) || 0) + 1;
    await saveState(); renderCompanionSocialPanel(companion);
    return job;
}

async function pollCompanionVideoJob(companion, job) {
    const startedAt = Date.now();
    while (Date.now() - startedAt < 20 * 60 * 1000 && ['queued', 'generating'].includes(job.status)) {
        await new Promise(resolve => setTimeout(resolve, 3000));
        const provider = job.provider;
        const endpoint = provider === 'openrouter'
            ? `${videoProviderApiBase(provider)}/videos/${encodeURIComponent(job.providerJobId)}`
            : provider === 'evolink'
                ? `${videoProviderApiBase(provider)}/tasks/${encodeURIComponent(job.providerJobId)}`
                : `${videoProviderApiBase(provider)}/predictions/${encodeURIComponent(job.providerJobId)}/result`;
        const response = await fetch(endpoint, { headers: videoProviderHeaders(provider) });
        const payload = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(String(payload?.error?.message || payload?.error || payload?.message || `Video status failed (${response.status})`));
        const data = payload?.data || payload;
        const status = String(data?.status || data?.state || '').toLowerCase();
        const progress = Number(data?.progress ?? data?.percentage);
        job.progress = Number.isFinite(progress) ? livingClamp(progress <= 1 ? progress * 100 : progress, 5, 95)
            : Math.min(92, job.progress + 3);
        job.updatedAt = Date.now();
        const output = videoOutputFromPayload(payload);
        if (output) return completeCompanionVideoJob(companion, job, output);
        if (provider === 'openrouter' && /complete|succeed|ready/.test(status)) {
            const contentResponse = await fetch(
                `${videoProviderApiBase(provider)}/videos/${encodeURIComponent(job.providerJobId)}/content`,
                { headers: videoProviderHeaders(provider) }
            );
            if (!contentResponse.ok) throw new Error(`OpenRouter finished the clip, but download failed (${contentResponse.status}).`);
            return completeCompanionVideoJobFromResponse(companion, job, contentResponse);
        }
        if (/fail|error|cancel/.test(status)) throw new Error(String(data?.error?.message || data?.error || data?.message || `Video generation ${status}.`));
        renderCompanionSocialPanel(companion);
    }
    throw new Error('Video generation timed out. The provider job ID was preserved so a later build can resume it.');
}

async function runCompanionVideoJob(companion, job) {
    if (!job || !['accepted', 'failed'].includes(job.status)) return;
    try { await submitCompanionVideoJob(companion, job); }
    catch (error) {
        console.error('Virtual Human clip failed:', error);
        job.status = 'failed'; job.error = String(error.message || error).slice(0, 1600); job.updatedAt = Date.now();
        await saveState(); renderCompanionSocialPanel(companion);
        showToast('Clip failed: ' + job.error, 'error');
    }
}

async function requestCompanionClip(companion) {
    if (!companion.allowVideoClips) return showToast('Clips are off for this Virtual Human. Enable them in Studio → Video & Clips.', 'info');
    const request = await showCompanionClipRequestModal(companion);
    if (!request) return;
    const { concept, clipType, cameraRig } = request;
    const job = normalizeCompanionVideoJob({
        provider: companion.videoProvider, model: companion.videoModel, status: 'requested',
        requestText: String(concept).trim(), concept: '', clipType,
        cameraRig,
        duration: companion.videoDuration, resolution: companion.videoResolution
    });
    companion.videoJobs.push(job); companion.videoJobs = companion.videoJobs.slice(-100);
    companionSocialTab = 'clips';
    const requestText = `Could you make a ${clipType.replace('_', ' ')} video: ${job.requestText}?`;
    renderCompanionSocialPanel(companion);
    await queueCompanionUserMessage({
        type: 'clip_request', text: requestText, videoRequestId: job.id, clipType, cameraRig
    });
}

function showCompanionClipRequestModal(companion) {
    return new Promise(resolve => {
        document.querySelector('.companion-clip-request-overlay')?.remove();
        const overlay = document.createElement('div');
        overlay.className = 'modal-bg companion-clip-request-overlay';
        overlay.innerHTML = `<form class="modal companion-clip-request-modal">
            <div class="modal-hd"><div><span class="vh-eyebrow">Ask first</span><h2>Request a clip</h2><p>${escapeHTML(companion.name || 'They')} can accept, refuse, postpone or change the concept.</p></div><button type="button" class="modal-close" data-clip-cancel>×</button></div>
            <div class="companion-clip-request-body">
                <label class="form-field"><span>What do you want them to film?</span><textarea class="form-textarea" name="concept" required rows="4" maxlength="1200" placeholder="A quick outfit check before going out, saying hi to the camera…"></textarea></label>
                <fieldset class="companion-clip-type-picker"><legend>Format</legend>${[
                    ['selfie','Selfie','Front camera, direct and personal'],['dance','Dance','A short dance or trend'],['outfit','Outfit','Fit check or styling'],['storytime','Storytime','Talk directly to camera'],['day_in_life','Day in life','A grounded life moment'],['comedy','Comedy','Bit, reaction or situational joke'],['trend','Trend','A social trend in their own style'],['custom','Custom','Describe something else']
                ].map(([id,label,detail], index) => `<label><input type="radio" name="clipType" value="${id}" ${index === 0 ? 'checked' : ''}><span><strong>${label}</strong><small>${detail}</small></span></label>`).join('')}</fieldset>
                <label class="form-field"><span>Camera</span><select class="form-select" name="cameraRig"><option value="selfie">Selfie · they hold the phone</option><option value="fixed">Fixed · propped phone / tripod</option><option value="handheld">Handheld · someone present films</option></select></label>
                <div class="vh-video-safety-note"><strong>No charge yet</strong><span>This only sends a request through chat. Generation begins later, after they agree and you press Generate.</span></div>
            </div>
            <div class="modal-footer"><button type="button" class="btn btn-ghost" data-clip-cancel>Cancel</button><button type="submit" class="btn btn-primary">Send request</button></div>
        </form>`;
        const close = value => { document.removeEventListener('keydown', keydown); overlay.remove(); resolve(value); };
        const keydown = event => { if (event.key === 'Escape') close(null); };
        overlay.querySelectorAll('[data-clip-cancel]').forEach(button => button.onclick = () => close(null));
        overlay.onclick = event => { if (event.target === overlay) close(null); };
        overlay.querySelector('form').onsubmit = event => {
            event.preventDefault();
            const data = new FormData(event.currentTarget);
            const concept = String(data.get('concept') || '').trim();
            if (!concept) return;
            close({ concept, clipType: String(data.get('clipType') || 'custom'), cameraRig: String(data.get('cameraRig') || 'selfie') });
        };
        document.addEventListener('keydown', keydown);
        document.body.appendChild(overlay);
        overlay.querySelector('textarea').focus();
    });
}

/**
 * Send a text message to a companion and get their reply. Talks to the same
 * OpenRouter/local endpoint every other feature in this app uses, with the
 * emotional-engine tool attached so mood updates ride along with the reply
 * instead of needing a second call.
 */
async function sendCompanionMessage(companion, messages, userText, nowMs = Date.now(), options = {}) {
    const textProvider = companionTextProviderId(companion);
    const experience = normalizeCompanionChatExperience(options.experience || companionChatExperience(companion.id));
    const userMessage = options.initiative
        ? null
        : (options.existingUserMessage || normalizeCompanionMessage({
            role: 'user', type: 'text', text: userText, timestamp: nowMs
        }));
    if (userMessage && !messages.includes(userMessage)) messages.push(userMessage);
    const turnSnapshot = isPlainObject(options.turnSnapshot) ? safeJsonClone(options.turnSnapshot) : {
        runtime: captureCompanionRuntime(companion),
        messageCount: messages.length,
        initiative: options.initiative === true
    };
    const responseGroupId = String(options.responseGroupId
        || livingId('vh_response', `${companion.id}|${nowMs}|${messages.length}|${Math.random()}`));
    // OpenRouter's native web-search tool is not part of the OpenAI-compatible
    // contract used by GPTProto or local servers. All ordinary function tools
    // remain available everywhere.
    const tools = companionToolsFor(companion, textProvider !== 'openrouter');
    const pendingPersonaVision = !options.initiative ? companionPendingPersonaVision(companion) : null;
    const startingScenarioThisTurn = !options.initiative
        ? companionConsumeStartingScenario(companion, userMessage, nowMs) : '';
    const cognitionRuntime = companionContinuity(companion);
    const labsSocial = !options.initiative && userText ? await labsProposal('social_signal', {
        message: String(userText).slice(0, 1800),
        text: String(userText).slice(0, 1800),
        relationshipContext: `Virtual Human: ${companion.name}; relationship ${companion.mood?.relationship ?? 'unspecified'}; mood ${companion.mood?.label || 'unspecified'}; channel ${options.channel || 'text'}; connection ${companion.connectionType || 'stranger'}; motive ${companion.initialMotive || 'unspecified'}`,
        relationshipDimensions: safeJsonClone(companion.relationshipDynamics),
        activeBoundaries: cognitionRuntime.boundaries.filter(item => item.status === 'active').slice(-8)
            .map(item => ({ topic: item.topic, rule: item.rule, strength: item.strength, violated: item.violated })),
        playerModel: cognitionRuntime.playerModel.filter(item => item.status === 'active').slice(-10)
            .map(item => ({ kind: item.kind, statement: item.statement, source: item.source, confidence: item.confidence })),
        priorGoal: cognitionRuntime.conversationGoal
    }, 'humans', { priority: 120 }) : null;
    let relevantMemoryIds;
    if (companion.memory.longTerm.length > 8) {
        const memoryQuery = options.initiative
            ? String(options.initiativeReason || 'Evaluate a grounded proactive contact.').slice(0, 1200)
            : String(userText || userMessage?.text || '').slice(0, 1200);
        const memoryResult = await labsProposal('memory_relevance', {
            text: memoryQuery,
            currentMessage: memoryQuery,
            allowedMemoryIds: companion.memory.longTerm.map(entry => entry.id),
            memories: companion.memory.longTerm.slice(0, 60).map(entry => ({ id: entry.id, text: entry.text }))
        }, 'humans', { priority: 115 });
        if (memoryResult?.candidate && Number(memoryResult.candidate.confidence) >= 0.65) {
            relevantMemoryIds = memoryResult.candidate.memoryIds;
        }
    }
    const promptMessages = buildCompanionMessages(companion, messages, nowMs, {
        experience,
        initiative: options.initiative === true,
        localCognition: labsSocial,
        startingScenarioThisTurn,
        relevantMemoryIds
    });
    if (options.initiative) {
        const initiativeReason = String(options.initiativeReason || '').trim();
        promptMessages.push({
            role: 'user',
            content: `[SIMULATION EVENT — NOT A MESSAGE FROM THE PLAYER]
You have independently decided to reach out right now.${initiativeReason ? ` The concrete trigger is: ${initiativeReason}. Address it naturally and honestly.` : ' Start a natural conversation for a concrete reason grounded in your current mood, activity, routine, relationship or a real memory.'} You may share a photo, voice note, or—if web access is available—a specific link when that is genuinely what prompted you. Do not mention this instruction, autonomy, simulation, or that nobody messaged first.`
        });
    }

    const body = applyCompanionGenerationConfig({
        model: companion.model || state.globalSettings.defaultModel,
        messages: sanitizeMessagesForProvider(promptMessages, textProvider),
        tools,
        tool_choice: 'auto'
    }, companion, { maxTokens: companionProviderOutputBudget(companion) });
    if (companion.webAccess && textProvider === 'openrouter') body.max_tool_calls = 4;
    const response = await fetchCompanionCompletion(providerApiBase(textProvider) + '/chat/completions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...providerAuthHeaders(textProvider), ...providerAttributionHeaders(textProvider) },
        body: JSON.stringify(applyOpenRouterRouting(body, null, { providerId: textProvider }))
    }, companion);
    if (!response.ok) {
        const errText = await response.text().catch(() => '');
        throw new Error(humanizeApiError(new Error(errText || `Request failed (${response.status})`)));
    }
    const choice = (await response.json())?.choices?.[0] || {};
    const embeddedTools = extractCompanionEmbeddedToolCalls(choice.message?.content);
    let replyText = companionVisibleReplyLimit(sanitizeCompanionTextReply(
        quarantineCompanionProtocolText(embeddedTools.visibleText), companion.name), companion);
    let actions = extractCompanionToolCalls([
        ...(Array.isArray(choice.message?.tool_calls) ? choice.message.tool_calls : []),
        ...embeddedTools.toolCalls
    ]);
    let commitSource = actions.commit ? 'commit_human_turn' : '';
    if (!actions.commit && (actions.state || actions.photo || actions.voice)) {
        actions.commit = {
            state: actions.state || {
                valence_change: 0, arousal_change: 0,
                mood_label: companion.mood.label, relationship_change: 0
            },
            photo: actions.photo ? { decision: 'send', ...actions.photo } : { decision: 'none' },
            voice_note: actions.voice ? { decision: 'send', ...actions.voice } : { decision: 'none' },
            video_clip: { decision: 'none' }
        };
        commitSource = 'legacy_tools';
    }
    if (!actions.commit) {
        const repaired = await repairCompanionTurnCommit(companion, promptMessages, replyText);
        if (repaired?.commit) {
            actions = repaired;
            if (!replyText && repaired.visibleReply) replyText = repaired.visibleReply;
            commitSource = 'repair';
        }
    }
    if (!actions.commit) {
        actions.commit = {
            state: {
                valence_change: 0, arousal_change: 0,
                mood_label: companion.mood.label, relationship_change: 0
            },
            photo: { decision: 'none' },
            voice_note: { decision: 'none' },
            video_clip: { decision: 'none' }
        };
        actions.state = actions.commit.state;
        commitSource = 'frozen_no_receipt';
    }
    const annotationCanDeliver = (Array.isArray(choice.message?.annotations) ? choice.message.annotations : [])
        .some(annotation => annotation?.type === 'url_citation'
            && /^https?:\/\//i.test(String(annotation.url_citation?.url || '')));
    if (!companionHasDeliverableReply(replyText, actions, companion,
        annotationCanDeliver ? [{ mediaType: 'link' }] : [])) {
        const recovered = await repairCompanionTurnCommit(companion, promptMessages, '', {
            recoverVisible: true,
            preserveCommit: true
        });
        if (recovered?.visibleReply) replyText = recovered.visibleReply;
    }
    if (actions.photo) actions.commit.photo = { ...actions.commit.photo, ...actions.photo, decision: 'send' };
    if (actions.voice) actions.commit.voice_note = { ...actions.commit.voice_note, ...actions.voice, decision: 'send' };
    const rejectedActions = [];
    if (!isPlainObject(actions.commit.video_clip)) actions.commit.video_clip = { decision: 'none' };
    const pendingClipRequest = [...(companion.videoJobs || [])].reverse().find(job => job.status === 'requested');
    if (actions.commit.video_clip.decision !== 'none') {
        if (!companion.allowVideoClips || !pendingClipRequest) {
            rejectedActions.push(!companion.allowVideoClips ? 'video_permission_disabled' : 'video_request_missing');
            actions.commit.video_clip = { decision: 'none', reason: 'No permitted explicit player clip request is pending.' };
        } else if (!actions.commit.video_clip.request_id) {
            actions.commit.video_clip.request_id = pendingClipRequest.id;
        }
    }
    if (actions.commit.photo?.decision === 'send'
        && (!companion.allowPhotos || !String(actions.commit.photo.scene || '').trim())) {
        rejectedActions.push(!companion.allowPhotos ? 'photo_permission_disabled' : 'photo_scene_missing');
        actions.photo = null;
        actions.commit.photo = {
            decision: 'none',
            reason: !companion.allowPhotos ? 'Photos are disabled by the user.' : 'No generatable scene was supplied.'
        };
    }
    if (actions.commit.voice_note?.decision === 'send'
        && (!companion.allowVoiceNotes || !String(actions.commit.voice_note.text || '').trim())) {
        rejectedActions.push(!companion.allowVoiceNotes ? 'voice_permission_disabled' : 'voice_text_missing');
        actions.voice = null;
        actions.commit.voice_note = {
            decision: 'none',
            reason: !companion.allowVoiceNotes ? 'Voice notes are disabled by the user.' : 'No spoken text was supplied.'
        };
    }
    const alcoholEstablished = companionAlcoholContext(companion, nowMs)
        || /\b(?:drank|drinking|having (?:a )?(?:beer|wine|cocktail|drink)|at (?:a |the )?(?:bar|pub|club|party)|tipsy|drunk)\b/i
            .test(`${replyText} ${actions.commit?.life_event || ''}`);
    if (Number(actions.state?.intoxication_change) > 0
        && (companion.alcoholPattern === 'none' || !alcoholEstablished)) {
        actions.state.intoxication_change = 0;
        rejectedActions.push(companion.alcoholPattern === 'none'
            ? 'alcohol_pattern_none' : 'intoxication_not_established');
    }
    if (actions.state && !companionSexualSystemActive(companion)) {
        const attemptedDesireUpdate = ['desire_change', 'sexual_arousal_change', 'sexual_frustration_change', 'sexual_cooldown_minutes']
            .some(field => Number(actions.state[field]) !== 0)
            || (actions.state.intimacy_outcome && actions.state.intimacy_outcome !== 'none');
        ['desire_change', 'sexual_arousal_change', 'sexual_frustration_change', 'sexual_cooldown_minutes']
            .forEach(field => { actions.state[field] = 0; });
        actions.state.intimacy_outcome = 'none';
        if (attemptedDesireUpdate) rejectedActions.push('adult_desire_system_disabled');
    }
    const annotationLinks = (Array.isArray(choice.message?.annotations) ? choice.message.annotations : [])
        .filter(annotation => annotation?.type === 'url_citation' && /^https?:\/\//i.test(String(annotation.url_citation?.url || '')))
        .map(annotation => ({
            url: String(annotation.url_citation.url).slice(0, 2000),
            title: String(annotation.url_citation.title || '').slice(0, 200),
            mediaType: 'link'
        })).slice(0, 3);
    const sharedLink = actions.link && /^https?:\/\//i.test(String(actions.link.url || ''))
        ? [{
            url: String(actions.link.url).slice(0, 2000),
            title: String(actions.link.title || 'Shared link').slice(0, 200),
            mediaType: ['link', 'meme', 'video', 'article'].includes(actions.link.media_type)
                ? actions.link.media_type : 'link'
        }]
        : [];
    const links = sharedLink.length ? sharedLink : annotationLinks;

    if (!companionHasDeliverableReply(replyText, actions, companion, links)) {
        // Throw before applying the receipt. Deferred replies already restore a
        // retry gate in their caller, so a provider cannot silently consume the
        // inbox batch as answered when it returned no usable content.
        throw new Error('The conversation model returned no visible reply or deliverable media.');
    }

    const lastCompanionAt = messages.reduce((latest, message) =>
        message.role === 'companion' && !message.invalidated ? Math.max(latest, Number(message.timestamp) || 0) : latest, 0);
    const sourceMessageIds = messages.filter(message => message.role === 'user' && !message.invalidated
        && Number(message.timestamp) >= lastCompanionAt
        && (!experience.realTimeLife || (Number(message.readAt || 0) > 0 && Number(message.readAt) <= nowMs)))
        .map(message => message.id).slice(-20);
    if (!isPlainObject(actions.commit.agency)) {
        const perceivedMessages = messages.filter(message => sourceMessageIds.includes(message.id));
        actions.commit.agency = {
            perceived_event: options.initiative
                ? String(options.initiativeReason || 'A private reason prompted independent contact.').slice(0, 700)
                : perceivedMessages.map(message => message.text || message.mediaDescription || `[${message.type}]`).join(' / ').slice(0, 700),
            interpretation: '',
            confidence: 100,
            decision: replyText ? 'Reply now' : actions.photo ? 'Send a photo' : actions.voice ? 'Send a voice note' : 'No visible response',
            pressures: companionDecisionPressures(companion, nowMs),
            conversation_goal: {
                type: 'respond',
                objective: replyText ? 'Respond to the player’s actual message.' : 'Make the selected media decision honestly.',
                reason: 'The provider did not return a complete structured agency receipt.'
            }
        };
    }
    if (actions.state) applyCompanionMoodUpdate(companion, actions.state, nowMs);
    applyCompanionTurnCommit(companion, actions.commit, nowMs, options.initiative ? 'autonomy' : 'turn', sourceMessageIds);
    if (pendingPersonaVision && companion.personaVisualMemory?.avatarFingerprint !== pendingPersonaVision.fingerprint) {
        companion.personaVisualMemory = {
            personaId: pendingPersonaVision.persona.id,
            avatarFingerprint: pendingPersonaVision.fingerprint,
            description: 'Their current profile picture was shared and seen; no reliable visual summary was returned.',
            seenAt: nowMs
        };
    }
    const pendingSocialPhoto = applyCompanionSocialPostCommit(
        companion, actions.commit, nowMs, options.initiative ? 'autonomy' : 'turn');
    if (userMessage && ['photo', 'voice'].includes(userMessage.type)) {
        userMessage.mediaDescription = String(actions.commit?.player_media_memory || '').trim().slice(0, 600)
            || (userMessage.type === 'photo' ? 'A photo the player shared.' : 'A voice note the player shared.');
    }
    [
        ['memory_write', 'fact'],
        ['relationship_event', 'milestone'],
        ['life_event', 'milestone']
    ].forEach(([field, kind]) => {
        const text = String(actions.commit?.[field] || '').trim();
        if (!text) return;
        companion.memory.longTerm.push(normalizeCompanionMemoryEntry({
            text: text.slice(0, 500), kind, weight: field === 'relationship_event' ? 75 : 60,
            createdAt: nowMs
        }));
    });
    companion.memory.longTerm = companion.memory.longTerm.slice(-200);
    const turnAudit = {
        source: commitSource,
        photoDecision: actions.commit?.photo?.decision || (actions.photo ? 'send' : 'none'),
        photoReason: String(actions.commit?.photo?.reason || '').slice(0, 240),
        voiceDecision: actions.commit?.voice_note?.decision || (actions.voice ? 'send' : 'none'),
        voiceReason: String(actions.commit?.voice_note?.reason || '').slice(0, 240),
        videoDecision: actions.commit?.video_clip?.decision || 'none',
        videoReason: String(actions.commit?.video_clip?.reason || '').slice(0, 240),
        decision: companion.continuityRuntime?.lastDecision?.decision || '',
        interpretation: companion.continuityRuntime?.lastDecision?.interpretation || '',
        pressures: companion.continuityRuntime?.lastDecision?.pressures || [],
        rejectedActions,
        committedAt: nowMs
    };

    const newMessages = splitCompanionReplyIntoBubbles(replyText, experience.replyBursts).map((bubble, index) =>
        normalizeCompanionMessage({
            role: 'companion', type: 'text', text: bubble,
            timestamp: nowMs + (index + 1) * 400, moodLabel: companion.mood.label,
            links: index === 0 ? links : [],
            responseGroupId, turnAudit: index === 0 ? turnAudit : null,
            turnSnapshot: index === 0 ? turnSnapshot : null,
            autonomous: options.initiative === true
        }));
    if (!newMessages.length && links.length) {
        newMessages.push(normalizeCompanionMessage({
            role: 'companion', type: 'text', text: '',
            timestamp: nowMs + 400, moodLabel: companion.mood.label, links,
            responseGroupId, turnSnapshot, turnAudit,
            autonomous: options.initiative === true
        }));
    }

    // A voice note is its own bubble, spoken content rather than typed text.
    if (actions.voice && String(actions.voice.text || '').trim()) {
        newMessages.push(normalizeCompanionMessage({
            role: 'companion', type: 'voice', text: String(actions.voice.text).trim(),
            timestamp: nowMs + (newMessages.length + 1) * 400, moodLabel: companion.mood.label,
            responseGroupId, turnSnapshot: newMessages.length ? null : turnSnapshot,
            turnAudit: newMessages.length ? null : turnAudit,
            autonomous: options.initiative === true
        }));
    }

    // A photo starts as a pending placeholder — the caller generates the
    // actual image afterward and fills it in, so the thread does not stall
    // waiting on a second, slower network call before showing anything.
    let pendingPhoto = null;
    if (actions.photo && String(actions.photo.scene || '').trim()) {
        pendingPhoto = normalizeCompanionMessage({
            role: 'companion', type: 'photo', text: String(actions.photo.caption || '').trim(),
            scene: String(actions.photo.scene).trim(), pending: true,
            captureType: String(actions.photo.capture_type || 'auto'),
            photographer: String(actions.photo.photographer || '').trim(),
            timestamp: nowMs + (newMessages.length + 1) * 400, moodLabel: companion.mood.label,
            responseGroupId, turnSnapshot: newMessages.length ? null : turnSnapshot,
            turnAudit: newMessages.length ? null : turnAudit,
            autonomous: options.initiative === true
        });
        newMessages.push(pendingPhoto);
    }

    newMessages.forEach(m => messages.push(m));
    companion.usage.textTurns += 1;
    consolidateCompanionMemory(companion, messages);
    await applyCompanionLabsMemoryGate(companion, userMessage, newMessages, nowMs);
    return { userMessage, replyMessages: newMessages, mood: companion.mood, pendingPhoto, pendingSocialPhoto };
}

/** Tolerant JSON parse for a tool-call payload that came back slightly malformed. */
function safeParseJSONRepair(raw) {
    try { return JSON.parse(dirtyJSONRepair(String(raw || ''))); }
    catch (error) { return null; }
}

