function gptProtoImageReferenceProfile(model) {
    const id = String(model?.id || model || '').toLowerCase();
    const evidence = [
        model?.description,
        model?.task,
        model?.type,
        ...(Array.isArray(model?.tasks) ? model.tasks : []),
        ...(Array.isArray(model?.capabilities) ? model.capabilities : [])
    ].map(value => String(value || '').toLowerCase()).join(' ');
    if (/^gpt-image-(?:1|2)(?:[.-]|$)/.test(id)) return { max: 16, transport: 'openai-edit' };
    if (/^gpt-4o-image(?:-vip)?$/.test(id)) return { max: 1, transport: 'openai-edit' };
    if (id === 'grok-imagine-image' || /grok.*imagine.*image/.test(id)) return { max: 1, transport: 'openai-generation' };
    if (/^wan-2\.5(?:-preview)?$/.test(id)) return { max: 1, transport: 'seedream-async', vendor: 'alibaba' };
    if (/dola-seedream-5-0-pro/.test(id)) return { max: 10, transport: 'seedream-async', vendor: 'doubao' };
    if (/(?:doubao-)?seedream-5-0/.test(id)) return { max: 10, transport: 'seedream-async', vendor: 'bytedance' };
    if (/(?:doubao-)?seedream-(?:4|3)[-.]/.test(id) || /seededit/.test(id)) {
        return { max: 10, transport: 'seedream-v3' };
    }
    if (/gemini-3(?:\.1)?-.*image/.test(id)) return { max: 14, transport: 'gemini-native' };
    if (/gemini-2\.5-.*image/.test(id)) return { max: 3, transport: 'gemini-native' };
    if (/flux.*(?:kontext|fill|redux)/.test(id)) return { max: 1, transport: 'public-url-prompt' };
    if (/(?:image[-_ ]?edit|img2img|i2i)/.test(id)
        || /multi-reference|reference images?|image[- ]to[- ]image|image edit/.test(evidence)) {
        return { max: 1, transport: 'documented-edit' };
    }
    return null;
}

function enrichGptProtoImageModel(model) {
    const profile = gptProtoImageReferenceProfile(model);
    if (!profile) return model;
    const architecture = isPlainObject(model?.architecture) ? model.architecture : {};
    const inputs = Array.isArray(architecture.input_modalities)
        ? architecture.input_modalities.map(value => String(value).toLowerCase()) : ['text'];
    if (!inputs.includes('image')) inputs.push('image');
    const rawParameters = isPlainObject(model?.supported_parameters)
        ? model.supported_parameters : {};
    return {
        ...model,
        architecture: {
            ...architecture,
            input_modalities: inputs,
            output_modalities: Array.isArray(architecture.output_modalities)
                ? architecture.output_modalities : ['image']
        },
        supported_parameters: {
            ...rawParameters,
            input_references: { type: 'range', min: 0, max: profile.max }
        },
        gptproto_reference_profile: profile
    };
}

function gptProtoImageEndpoint(modelId, usedReference = false) {
    const profile = gptProtoImageReferenceProfile(modelId);
    if (profile?.transport === 'seedream-async') {
        return `https://gptproto.com/api/v3/${profile.vendor}/${encodeURIComponent(modelId)}/${usedReference ? 'image-edit' : 'text-to-image'}`;
    }
    if (profile?.transport === 'seedream-v3') return 'https://gptproto.com/api/v3/images/generations';
    if (profile?.transport === 'gemini-native') {
        return `https://gptproto.com/v1beta/models/${encodeURIComponent(modelId)}:generateContent`;
    }
    return '';
}

function companionImageModelFallback(providerId = state.globalSettings.apiProvider) {
    if (String(providerId || '').toLowerCase() === 'fal') return 'fal-ai/flux/schnell';
    const provider = normalizedProviderId(providerId);
    if (provider === 'gptproto') return GPTPROTO_IMAGE_MODELS[0].id;
    if (provider === 'nanogpt') return 'hidream';
    return COMPANION_IMAGE_MODEL_FALLBACK;
}

const NANOGPT_SINGLE_REFERENCE_MODELS = new Set([
    'flux-dev-image-to-image', 'ghiblify', 'gemini-flash-edit', 'hidream-edit',
    'bagel', 'sdxl-arlimix-v1', 'upscaler'
]);
const NANOGPT_MULTI_REFERENCE_MODELS = new Set([
    'flux-kontext', 'flux-kontext/dev', 'gpt-4o-image', 'gpt-image-1'
]);

function nanoGPTImageReferenceMode(modelId) {
    const id = String(modelId || '').toLowerCase();
    if (NANOGPT_MULTI_REFERENCE_MODELS.has(id)) return 'multiple';
    if (NANOGPT_SINGLE_REFERENCE_MODELS.has(id)) return 'single';
    return '';
}

function enrichNanoGPTImageModel(model) {
    const raw = isPlainObject(model?.supported_parameters) ? model.supported_parameters : {};
    const resolutions = Array.isArray(raw.resolutions) ? raw.resolutions
        : Array.isArray(raw.size) ? raw.size : [];
    const evidence = JSON.stringify({ raw, capabilities: model?.capabilities, task: model?.task }).toLowerCase();
    const referenceMode = nanoGPTImageReferenceMode(model?.id);
    const supportsReference = !!referenceMode
        || /im(?:age)?2im(?:age)?|image[-_ ]to[-_ ]image|imageDataUrl|input.image|reference/i.test(evidence)
        || (Array.isArray(model?.architecture?.input_modalities)
            && model.architecture.input_modalities.map(value => String(value).toLowerCase()).includes('image'));
    return {
        ...model,
        architecture: {
            ...(isPlainObject(model?.architecture) ? model.architecture : {}),
            input_modalities: supportsReference ? ['text', 'image'] : ['text'],
            output_modalities: ['image']
        },
        supported_parameters: {
            ...(resolutions.length ? { size: { type: 'enum', values: resolutions } } : {}),
            ...(supportsReference ? { input_references: { type: 'range', min: 0, max: 1 } } : {}),
            seed: { type: 'range', min: 0, max: 2147483647 },
            ...(Array.isArray(raw.output_formats) ? { output_format: { type: 'enum', values: raw.output_formats } } : {})
        },
        nanogpt_reference_capable: supportsReference,
        nanogpt_reference_mode: referenceMode || (supportsReference ? 'single' : '')
    };
}

const companionOutputModelCache = new Map();
const companionImageEndpointCache = new Map();
let companionImageModelCatalog = [];

const COMPANION_IMAGE_PARAMETER_DEFS = Object.freeze({
    resolution: { label: 'Resolution', kind: 'select' },
    aspect_ratio: { label: 'Aspect ratio', kind: 'select' },
    size: { label: 'Output size', kind: 'select-or-text' },
    quality: { label: 'Quality', kind: 'select' },
    output_format: { label: 'Format', kind: 'select' },
    background: { label: 'Background', kind: 'select' },
    output_compression: { label: 'Compression', kind: 'number' },
    seed: { label: 'Seed', kind: 'number' }
});

function normalizeCompanionImageParameters(raw) {
    const source = isPlainObject(raw) ? raw : {};
    const out = {};
    Object.keys(COMPANION_IMAGE_PARAMETER_DEFS).forEach(key => {
        const value = source[key];
        if (value === '' || value == null) return;
        if (['output_compression', 'seed'].includes(key)) {
            if (Number.isFinite(Number(value))) out[key] = Number(value);
            return;
        }
        if (['string', 'number', 'boolean'].includes(typeof value)) out[key] = value;
    });
    return out;
}

function normalizeCompanionImageProviderOptions(raw) {
    if (!isPlainObject(raw)) return {};
    const out = {};
    Object.entries(raw).slice(0, 40).forEach(([key, value]) => {
        if (!/^[a-zA-Z0-9_.-]{1,80}$/.test(key) || value === '' || value == null) return;
        const normalized = normalizeCompanionImageProviderOptionValue(value);
        if (normalized !== undefined) out[key] = normalized;
    });
    return out;
}

function normalizeCompanionImageProviderOptionValue(value, depth = 0) {
    if (depth > 4 || value == null) return undefined;
    if (typeof value === 'string') return value.slice(0, 2000);
    if (typeof value === 'number') return Number.isFinite(value) ? value : undefined;
    if (typeof value === 'boolean') return value;
    if (Array.isArray(value)) {
        return value.slice(0, 30)
            .map(item => normalizeCompanionImageProviderOptionValue(item, depth + 1))
            .filter(item => item !== undefined);
    }
    if (isPlainObject(value)) {
        const out = {};
        Object.entries(value).slice(0, 30).forEach(([key, item]) => {
            if (!/^[a-zA-Z0-9_.-]{1,80}$/.test(key)) return;
            const normalized = normalizeCompanionImageProviderOptionValue(item, depth + 1);
            if (normalized !== undefined) out[key] = normalized;
        });
        return out;
    }
    return undefined;
}

function imageCapabilityMap(raw) {
    if (!isPlainObject(raw)) return {};
    const out = {};
    Object.entries(raw).forEach(([key, descriptor]) => {
        if (!/^[a-zA-Z0-9_.-]{1,80}$/.test(key) || !isPlainObject(descriptor)) return;
        const type = ['enum', 'range', 'boolean'].includes(descriptor.type) ? descriptor.type : 'boolean';
        out[key] = {
            type,
            ...(Array.isArray(descriptor.values)
                ? { values: descriptor.values.filter(value => ['string', 'number', 'boolean'].includes(typeof value)).slice(0, 100) }
                : {}),
            ...(Number.isFinite(Number(descriptor.min)) ? { min: Number(descriptor.min) } : {}),
            ...(Number.isFinite(Number(descriptor.max)) ? { max: Number(descriptor.max) } : {})
        };
    });
    return out;
}

function imageParameterValueForDescriptor(key, value, descriptor) {
    if (value === '' || value == null || !descriptor) return undefined;
    if (descriptor.type === 'enum') {
        const match = (descriptor.values || []).find(option => String(option) === String(value));
        return match;
    }
    if (key === 'output_compression') {
        const number = Math.round(Number(value));
        if (!Number.isFinite(number)) return undefined;
        return livingClamp(number, descriptor.min ?? 0, descriptor.max ?? 100);
    }
    if (key === 'seed') {
        const number = Math.round(Number(value));
        return Number.isFinite(number) ? number : undefined;
    }
    if (descriptor.type === 'range') {
        const number = Number(value);
        if (!Number.isFinite(number)) return undefined;
        return livingClamp(number, descriptor.min ?? number, descriptor.max ?? number);
    }
    return ['string', 'number', 'boolean'].includes(typeof value) ? value : undefined;
}

async function getCompanionOutputModels(modality, force = false, providerId = state.globalSettings.apiProvider) {
    const provider = String(providerId || '').toLowerCase() === 'fal' ? 'fal' : normalizedProviderId(providerId);
    const base = provider === 'fal' ? 'fal://local-bridge' : providerApiBase(provider);
    const key = `${base}|${modality}`;
    if (force) companionOutputModelCache.delete(key);
    if (companionOutputModelCache.has(key)) return companionOutputModelCache.get(key);
    let models = [];
    if (provider === 'fal') {
        if (modality !== 'image') {
            companionOutputModelCache.set(key, []);
            return [];
        }
        // Live fal catalog through the loopback bridge: image-capable
        // endpoints only, so the pickers list every current fal image model
        // (FLUX 2 and friends) instead of a frozen curated set.
        try {
            const catalog = await mcpBridgeRequest('/fal/models', {
                method: 'POST', timeoutMs: 45000,
                body: { apiKey: state.falApiKey, categories: ['text-to-image', 'image-to-image'] }
            });
            const entries = Array.isArray(catalog?.models) ? catalog.models : [];
            models = entries.map(mapFalCatalogEntry).filter(Boolean);
        } catch (error) {
            console.warn('Could not load the live Fal image catalog:', error);
        }
        if (!models.length) models = FAL_IMAGE_MODELS.map(model => safeJsonClone(model));
        companionOutputModelCache.set(key, models);
        return models;
    }
    try {
        const queryModality = modality === 'audio' ? 'speech' : modality;
        const catalogPath = provider === 'nanogpt'
            ? (modality === 'text' ? '/models' : modality === 'image' ? '/image-models?detailed=true' : '/audio-models?detailed=true')
            : modality === 'text' ? '/models'
            : (modality === 'image' && provider === 'openrouter'
                ? '/images/models'
                : (provider === 'gptproto' ? '/models' : `/models?output_modalities=${encodeURIComponent(queryModality)}`));
        const response = await fetch(base + catalogPath, {
            headers: { ...providerAuthHeaders(provider), ...providerAttributionHeaders(provider) }
        });
        if (!response.ok) throw new Error(`Model catalog request failed (${response.status})`);
        const data = await response.json();
        const catalogEntries = Array.isArray(data) ? data
            : Array.isArray(data?.data) ? data.data
            : Array.isArray(data?.models) ? data.models : [];
        models = catalogEntries
            .filter(model => isPlainObject(model) && typeof model.id === 'string')
            .map(model => ({ ...model, name: typeof model.name === 'string' ? model.name : model.id }));
        if (provider === 'gptproto' && modality === 'image') {
            const byId = new Map(models.map(model => [model.id, model]));
            GPTPROTO_IMAGE_MODELS.forEach(curated => {
                const live = byId.get(curated.id) || {};
                byId.set(curated.id, {
                    ...curated,
                    ...live,
                    architecture: { ...(curated.architecture || {}), ...(live.architecture || {}) },
                    supported_parameters: {
                        ...(curated.supported_parameters || {}),
                        ...(isPlainObject(live.supported_parameters) ? live.supported_parameters : {})
                    }
                });
            });
            models = [...byId.values()].map(enrichGptProtoImageModel);
        }
        if (provider === 'nanogpt' && modality === 'image') {
            models = models.map(enrichNanoGPTImageModel);
        }
        if (provider === 'nanogpt' && modality === 'audio') {
            // Every entry came from NanoGPT's audio-only catalog. Normalize
            // the varied catalog shapes into the same descriptors used by the
            // voice picker instead of guessing from model-name substrings.
            models = models.filter(model => {
                const evidence = `${model.id || ''} ${model.name || ''} ${model.description || ''} ${model.task || ''}`.toLowerCase();
                return !/\b(?:music|transcrib|transcription|speech[-_ ]to[-_ ]text|stt|whisper)\b/.test(evidence);
            }).map(model => ({
                ...model,
                architecture: {
                    ...(isPlainObject(model.architecture) ? model.architecture : {}),
                    input_modalities: ['text'],
                    output_modalities: ['speech']
                },
                supported_voices: Array.isArray(model.supported_voices) ? model.supported_voices
                    : Array.isArray(model.voices) ? model.voices : [],
                supported_parameters: Array.isArray(model.supported_parameters) ? model.supported_parameters
                    : Object.keys(isPlainObject(model.supported_parameters) ? model.supported_parameters : {})
            }));
        }
        if (provider === 'gptproto' && modality === 'audio') {
            const existing = models.find(model => model.id === 'gpt-4o-mini-tts') || {};
            models = [{
                ...existing,
                id: 'gpt-4o-mini-tts',
                name: existing.name || 'GPT-4o Mini TTS',
                architecture: { input_modalities: ['text'], output_modalities: ['speech'] },
                supported_voices: ['alloy'],
                supported_parameters: ['voice']
            }];
        }
    } catch (error) {
        console.warn(`Could not load ${modality}-output models:`, error);
    }
    companionOutputModelCache.set(key, models);
    return models;
}

function modelOutputModalities(model) {
    const architecture = isPlainObject(model?.architecture) ? model.architecture : {};
    if (Array.isArray(architecture.output_modalities)) {
        return architecture.output_modalities.map(value => String(value).toLowerCase());
    }
    const modality = String(architecture.modality || '').toLowerCase();
    const outputSide = modality.includes('->') ? modality.split('->').pop() : '';
    return outputSide ? outputSide.split(/[+,/]/).map(value => value.trim()).filter(Boolean) : [];
}

function isImageCapableModel(model) {
    if (!model || typeof model.id !== 'string') return false;
    const id = model.id.toLowerCase();
    const outputs = modelOutputModalities(model);
    if (outputs.length) return outputs.includes('image');
    const pricing = model.pricing || {};
    if (pricing.image_output || pricing.output_image) return true;
    return /seedream|flux(?:[.-]|$)|dall-e|gpt-(?:5-)?image|recraft|stable-diffusion|sdxl|imagen|ideogram|gemini-[^/]*-image/i.test(id);
}

function rankCompanionImageModels(models, providerId = state.globalSettings.apiProvider) {
    const provider = String(providerId || '').toLowerCase() === 'fal' ? 'fal' : normalizedProviderId(providerId);
    const source = provider === 'gptproto'
        ? (Array.isArray(models) ? models : []).map(enrichGptProtoImageModel)
        : provider === 'nanogpt'
            ? (Array.isArray(models) ? models : []).map(enrichNanoGPTImageModel)
        : (Array.isArray(models) ? models : []);
    const list = source.filter(isImageCapableModel);
    if (!list.length) {
        const fallbacks = provider === 'gptproto' ? GPTPROTO_IMAGE_MODELS
            : provider === 'nanogpt'
                ? [{ id: 'hidream', name: 'HiDream', architecture: { output_modalities: ['image'] } }]
                : COMPANION_IMAGE_MODEL_FALLBACKS;
        fallbacks.forEach(fb =>
            list.push({ ...fb, architecture: fb.architecture || { output_modalities: ['image'] }, pricing: {} }));
    }
    return list.map(model => ({
        id: model.id,
        name: model.name || model.id,
        description: String(model.description || '').slice(0, 1200),
        supportsReference: modelSupportsImageReferences(model),
        referenceTransport: model?.gptproto_reference_profile?.transport || '',
        supportedParameters: imageCapabilityMap(model.supported_parameters),
        endpointsPath: typeof model.endpoints === 'string' ? model.endpoints : '',
        supportsStreaming: model.supports_streaming === true,
        price: Array.isArray(model.pricing)
            ? (Number(model.pricing.find(line => line?.billable === 'output_image' && line?.unit === 'image')?.cost_usd) || null)
            : null
    })).sort((a, b) =>
        Number(b.supportsReference === true) - Number(a.supportsReference === true)
        || (a.price ?? 999) - (b.price ?? 999));
}

function modelSupportsImageReferences(model) {
    const params = model?.supported_parameters;
    if (Array.isArray(params)) return params.includes('input_references');
    if (isPlainObject(params) && Object.prototype.hasOwnProperty.call(params, 'input_references')) {
        const descriptor = params.input_references;
        return !isPlainObject(descriptor) || descriptor.type !== 'range' || Number(descriptor.max) > 0;
    }
    const inputs = model?.architecture?.input_modalities;
    if (Array.isArray(inputs)) return inputs.map(value => String(value).toLowerCase()).includes('image');
    return null;
}

function companionImageModelInfo(modelId) {
    return companionImageModelCatalog.find(model => model.id === modelId) || null;
}

async function getCompanionImageEndpoints(modelId, force = false, providerId = state.globalSettings.apiProvider) {
    if (String(providerId || '').toLowerCase() === 'fal') return [];
    const provider = normalizedProviderId(providerId);
    const id = String(modelId || '').trim();
    if (!id || provider !== 'openrouter') return [];
    const base = providerApiBase(provider);
    const key = `${base}|${id}`;
    if (force) companionImageEndpointCache.delete(key);
    if (companionImageEndpointCache.has(key)) return companionImageEndpointCache.get(key);
    const encodedId = id.split('/').map(encodeURIComponent).join('/');
    try {
        const response = await fetch(`${base}/images/models/${encodedId}/endpoints`, {
            headers: { ...providerAuthHeaders(provider), ...providerAttributionHeaders(provider) }
        });
        if (!response.ok) throw new Error(`Endpoint catalog request failed (${response.status})`);
        const data = await response.json();
        const endpoints = (Array.isArray(data?.endpoints) ? data.endpoints : []).map(endpoint => ({
            providerName: String(endpoint?.provider_name || endpoint?.provider_slug || 'Provider').slice(0, 120),
            providerSlug: String(endpoint?.provider_slug || '').slice(0, 120),
            providerTag: String(endpoint?.provider_tag || '').slice(0, 160),
            supportedParameters: imageCapabilityMap(endpoint?.supported_parameters),
            allowedPassthroughParameters: (Array.isArray(endpoint?.allowed_passthrough_parameters)
                ? endpoint.allowed_passthrough_parameters : [])
                .map(value => String(value)).filter(value => /^[a-zA-Z0-9_.-]{1,80}$/.test(value)).slice(0, 40),
            supportsStreaming: endpoint?.supports_streaming === true,
            pricing: Array.isArray(endpoint?.pricing) ? endpoint.pricing : []
        }));
        companionImageEndpointCache.set(key, endpoints);
        return endpoints;
    } catch (error) {
        console.warn(`Could not load endpoints for ${id}:`, error);
        companionImageEndpointCache.set(key, []);
        return [];
    }
}

function chooseCompanionImageEndpoint(endpoints, companion, includeReference) {
    const list = Array.isArray(endpoints) ? endpoints : [];
    if (!list.length) return null;
    const preferred = list.find(endpoint =>
        companion.imageProviderTag
        && [endpoint.providerTag, endpoint.providerSlug].includes(companion.imageProviderTag));
    const referenceReady = endpoint => {
        if (!includeReference) return true;
        const descriptor = endpoint.supportedParameters?.input_references;
        return !!descriptor && (descriptor.type !== 'range' || Number(descriptor.max) > 0);
    };
    if (preferred && referenceReady(preferred)) return preferred;
    return list.find(referenceReady) || preferred || list[0];
}

function companionImageCapabilities(modelInfo, endpoint) {
    return isPlainObject(endpoint?.supportedParameters)
        ? endpoint.supportedParameters
        : (isPlainObject(modelInfo?.supportedParameters) ? modelInfo.supportedParameters : {});
}

function applyCompanionImageParameters(body, companion, capabilities, endpoint) {
    const configured = normalizeCompanionImageParameters(companion.imageParameters);
    Object.entries(configured).forEach(([key, value]) => {
        const normalized = imageParameterValueForDescriptor(key, value, capabilities[key]);
        if (normalized !== undefined) body[key] = normalized;
    });
    // OpenRouter rejects explicit pixel size combined with independent
    // resolution/aspect-ratio values because the concrete size is authoritative.
    if (body.size && /^\d+x\d+$/i.test(String(body.size))) {
        delete body.resolution;
        delete body.aspect_ratio;
    }
    // Alpha cannot exist in JPEG. Prefer a successful opaque JPEG to a
    // provider-side parameter-combination rejection.
    if (body.output_format === 'jpeg' && body.background === 'transparent') {
        body.background = 'opaque';
    }
    if (endpoint?.providerTag) {
        body.provider = { only: [endpoint.providerTag], allow_fallbacks: false };
        const allowed = new Set(endpoint.allowedPassthroughParameters || []);
        const passthrough = {};
        Object.entries(normalizeCompanionImageProviderOptions(companion.imageProviderOptions)).forEach(([key, value]) => {
            if (allowed.has(key)) passthrough[key] = value;
        });
        if (Object.keys(passthrough).length && endpoint.providerSlug) {
            body.provider.options = { [endpoint.providerSlug]: passthrough };
        }
    }
    return body;
}

const COMPANION_PHOTO_CAPTURE_TYPES = Object.freeze([
    'auto', 'front_camera_selfie', 'mirror_selfie', 'group_selfie',
    'timer_or_propped', 'taken_by_someone'
]);

function companionPhotoCapturePlan(companion, sceneDescription, atMs = Date.now(), options = {}) {
    const scene = String(sceneDescription || '');
    const lower = scene.toLowerCase();
    const situation = companionSituationAt(companion, atMs);
    const policy = normalizeCompanionPhotoCapturePolicy(companion.photoCapturePolicy);
    const withNames = (Array.isArray(situation.withNames) ? situation.withNames : [])
        .map(name => String(name).trim()).filter(Boolean);
    const situationText = `${situation.activity || ''} ${situation.label || ''} ${situation.placeLabel || ''}`.toLowerCase();
    const socialSituation = withNames.length > 0
        || /\b(with (?:a |my |some )?(?:friend|friends|family|coworkers?|colleagues?|partner|date)|party|gathering|group|wedding|dinner with|out with)\b/.test(situationText);
    const mirrorRequested = /\b(mirror|reflection|outfit check|bathroom mirror|elevator mirror|dressing room)\b/.test(lower);
    const timerRequested = /\b(self[- ]?timer|timer shot|propped (?:up )?(?:phone|camera)|phone (?:on|against) (?:a |the )|tripod)\b/.test(lower);
    const groupRequested = /\b(group (?:photo|pic|picture|selfie)|everyone (?:in|together)|all of us|with (?:my |some )?(?:friends|family|coworkers?|colleagues?))\b/.test(lower);
    const frontRequested = /\b(front[- ]?camera|selfie|arm'?s[- ]length|holding (?:my|the|her|his|their) phone)\b/.test(lower);
    const otherPhotographerRequested = /\b(taken by|photo by|friend took|someone (?:else )?(?:took|taking)|photographer|candid (?:of|shot)|shot (?:by|of (?:her|him|them)))\b/.test(lower);
    const distantFraming = /\b(full[- ]body|head[- ]to[- ]toe|from across|wide shot|walking away|candid|both hands|whole outfit)\b/.test(lower);
    const outfitFraming = /\b(outfit|fit check|what (?:i(?:'m| am)|she(?:'s| is)|he(?:'s| is)|they(?:'re| are)) wearing)\b/.test(lower);
    const mirrorPlausible = mirrorRequested
        || /\b(home|bedroom|bathroom|hallway|elevator|gym|studio|shop|store|dressing|restroom|hotel|apartment)\b/.test(situationText);
    const requestedType = COMPANION_PHOTO_CAPTURE_TYPES.includes(options.captureType)
        ? options.captureType : 'auto';
    const requestedPhotographer = String(options.photographer || '').trim();
    const namedPhotographer = requestedPhotographer
        && withNames.find(name => name.toLowerCase() === requestedPhotographer.toLowerCase());
    const plausiblePhotographer = namedPhotographer || withNames[0]
        || (socialSituation ? 'someone already there' : '');
    const canUseOtherPhotographer = policy !== 'self_capture' && !!plausiblePhotographer;

    const plan = (type, reason, photographer = '') => {
        const details = {
            front_camera_selfie: {
                label: 'Front-camera selfie',
                instruction: `The subject is physically holding the phone at arm's length and using its front camera. Use close selfie geometry, slight wide-angle perspective and a naturally imperfect crop. At least one arm must plausibly operate the phone. Do not use a distant, observer-like or full-body camera angle; there is no invisible photographer.`
            },
            mirror_selfie: {
                label: 'Mirror selfie',
                instruction: `The subject takes the photo into a real nearby mirror. The phone is visible in the reflection and is held by the subject; preserve believable reflection, hand and phone geometry. There is no external camera operator or observer viewpoint.`
            },
            group_selfie: {
                label: 'Group selfie',
                instruction: `This is a front-camera group selfie held at arm's length by the subject or one of the people already present. Keep selfie geometry and include only people established by the current situation; do not invent extra friends or a separate photographer.`
            },
            timer_or_propped: {
                label: 'Timer / propped phone',
                instruction: `The subject has propped their own phone on a plausible stable surface and used a timer. The fixed viewpoint, distance and camera height must make physical sense for that surface. No person is behind the camera and no unseen photographer is implied.`
            },
            taken_by_someone: {
                label: `Taken by ${photographer || 'someone present'}`,
                instruction: `The camera is physically held by ${photographer || 'a person already present in the established situation'}. The viewpoint belongs to that person, so the subject is not holding the camera. This third-person framing is permitted only because the photographer is already present; do not add any other unseen people.`
            }
        };
        return { type, reason, photographer, situation, ...details[type] };
    };

    // Explicit structured choices are respected only when the simulated
    // situation can physically support them.
    if (requestedType === 'mirror_selfie' && mirrorPlausible) {
        return plan('mirror_selfie', 'The turn explicitly selected a mirror selfie.');
    }
    if (requestedType === 'timer_or_propped') {
        return plan('timer_or_propped', 'The turn explicitly selected a timer or propped phone.');
    }
    if (requestedType === 'group_selfie' && socialSituation) {
        return plan('group_selfie', 'The turn selected a group selfie and company is present.');
    }
    if (requestedType === 'taken_by_someone' && canUseOtherPhotographer) {
        return plan('taken_by_someone', 'The turn named a physically plausible photographer.', plausiblePhotographer);
    }
    if (requestedType === 'front_camera_selfie') {
        return plan('front_camera_selfie', 'The turn explicitly selected the front camera.');
    }

    if (policy === 'self_capture') {
        if (mirrorRequested && mirrorPlausible) return plan('mirror_selfie', 'Self-capture policy and a mirror are established.');
        if (groupRequested && socialSituation) return plan('group_selfie', 'Self-capture policy allows an arm’s-length group selfie.');
        if (timerRequested || distantFraming) return plan('timer_or_propped', 'Self-capture policy requires a timer for this wider framing.');
        if (outfitFraming && mirrorPlausible) return plan('mirror_selfie', 'An outfit photo is plausible in a nearby mirror.');
        return plan('front_camera_selfie', 'Self-capture policy forbids a separate photographer.');
    }

    if (mirrorRequested && mirrorPlausible) return plan('mirror_selfie', 'The scene establishes a nearby mirror.');
    if (timerRequested) return plan('timer_or_propped', 'The scene establishes a timer or propped phone.');
    if (groupRequested && socialSituation) return plan('group_selfie', 'The requested group and current company support a group selfie.');
    if (otherPhotographerRequested && canUseOtherPhotographer) {
        return plan('taken_by_someone', 'The scene asks for a photographer who is already present.', plausiblePhotographer);
    }
    if (frontRequested) return plan('front_camera_selfie', 'The scene asks for a selfie.');
    if (outfitFraming && mirrorPlausible) return plan('mirror_selfie', 'A mirror is the natural self-captured setup for this outfit photo.');
    if ((policy === 'social' || policy === 'scene') && distantFraming && canUseOtherPhotographer) {
        return plan('taken_by_someone', 'Wider candid framing is plausible because company is present.', plausiblePhotographer);
    }
    if (distantFraming) return plan('timer_or_propped', 'Wider framing while no photographer is established requires a propped phone.');
    return plan('front_camera_selfie', socialSituation
        ? 'No different camera setup was requested, so the subject takes an ordinary selfie.'
        : 'The subject is alone and no mirror or timer was established.');
}

function buildCompanionPhotoPrompt(companion, sceneDescription, options = {}) {
    const style = COMPANION_PHOTO_STYLES[normalizeCompanionPhotoStyle(companion.photoStyle)];
    const atMs = Number(options.atMs) || Date.now();
    const capture = companionPhotoCapturePlan(companion, sceneDescription, atMs, options);
    const situation = capture.situation;
    const environment = companionWeatherLabel(situation.environment);
    const hasReference = options.hasReference !== false;
    const subject = companion.appearance
        || (hasReference
            ? 'the adult person in the identity reference image'
            : 'an adult matching this virtual human; no identity reference is available, so create a consistent natural-looking person');
    return `Create an image sent by this virtual human during a private chat.

Subject: ${subject}.
Scene: ${sceneDescription}.
Authoritative current continuity: ${situation.outfit ? `wearing ${situation.outfit}` : companion.currentOutfit ? `wearing ${companion.currentOutfit}` : 'outfit not otherwise established'}; ${situation.placeLabel || companion.currentLocationDetail || companion.locationLabel || 'specific surroundings not otherwise established'}${environment ? `; local conditions are ${environment}` : ''}.
People actually present: ${situation.withNames?.length ? situation.withNames.join(', ') : 'none established'}.
Do not silently relocate, restyle, redress or change the time of day to make a prettier image. If the requested scene conflicts with this situation, treat the current situation as ground truth. Never invent an unseen friend, photographer or group.

Camera provenance — ${capture.label}:
${capture.instruction}
Reason: ${capture.reason}
This camera provenance overrides any generic camera-angle wording in the visual style below.

Visual treatment — ${style.label}:
${style.appendix}

The result should feel like something this person genuinely chose to send in the conversation. Keep the requested scene clear, the character consistent, and the moment personal and believable.`;
}

/**
 * Generate a photo. Image-to-image against the companion's base photo when
 * one has been uploaded, so the same face persists across every photo they
 * ever send; text-to-image from the appearance description otherwise.
 */
function buildCompanionImageRequest(companion, sceneDescription, options = {}) {
    const provider = normalizedProviderId(options.providerId || companionImageProviderId(companion));
    const model = companion.imageModel || companionImageModelFallback(provider);
    const includeReference = !!companion.basePhoto && options.includeReference !== false;
    const body = {
        model,
        prompt: buildCompanionPhotoPrompt(companion, sceneDescription, { ...options, hasReference: includeReference })
    };
    if (includeReference) {
        if (provider === 'fal') {
            body.imageDataUrl = companion.basePhoto;
        } else if (provider === 'nanogpt') {
            // NanoGPT accepts browser-local identity references directly as a
            // data URL. This avoids a public image host and keeps the photo on
            // the user's device until the generation request is submitted.
            if (nanoGPTImageReferenceMode(model) === 'multiple') body.imageDataUrls = [companion.basePhoto];
            else body.imageDataUrl = companion.basePhoto;
        } else if (provider === 'gptproto') {
            // GPTProto's OpenAI-compatible image endpoint accepts the identity
            // reference as a base64 data string or public URL in `image`.
            body.image = companion.basePhoto;
        } else {
            body.input_references = [{
                type: 'image_url',
                image_url: { url: companion.basePhoto }
            }];
        }
    }
    return applyCompanionImageParameters(
        body, companion, isPlainObject(options.capabilities) ? options.capabilities : {}, options.endpoint || null);
}

function companionImageErrorMessage(message, model, usedReference, providerId = state.globalSettings.apiProvider) {
    const text = String(message || 'Image generation failed.');
    if (/input image may contain sensitive information|InputImageSensitiveContentDetected/i.test(text)) {
        return `The selected image provider rejected the generation reference with its mandatory privacy filter. Horde Studio did not apply this filter. Try another image model${usedReference ? ' or test once with “Use generation reference” off' : ''}. Provider message: ${text}`;
    }
    if (/content[_ -]?policy|safety filter|sensitive content/i.test(text)) {
        return `${text} This restriction came from ${providerDisplayName(providerId)}, an account guardrail, or the selected upstream model—not Horde Studio’s Mature Immersion setting.`;
    }
    return text;
}

function isCompanionReferencePrivacyError(message) {
    return /input image may contain sensitive information|InputImageSensitiveContentDetected/i.test(String(message || ''));
}

function generatedImageMimeFromBase64(encoded, fallback = 'image/png') {
    const value = String(encoded || '').replace(/\s+/g, '');
    if (value.startsWith('/9j/')) return 'image/jpeg';
    if (value.startsWith('iVBORw0KGgo')) return 'image/png';
    if (value.startsWith('UklGR')) return 'image/webp';
    if (value.startsWith('R0lGOD')) return 'image/gif';
    if (value.startsWith('PHN2Zy')) return 'image/svg+xml';
    return fallback;
}

function isRecognizableImageBase64(value) {
    const encoded = String(value || '').replace(/\s+/g, '');
    // JPEG is especially important here: its base64 signature begins with a
    // slash (`/9j/`). It must be identified before root-relative URL handling
    // or the browser will request a bogus https://gptproto.com/9j/... asset.
    return encoded.startsWith('/9j/')
        || encoded.startsWith('iVBORw0KGgo')
        || encoded.startsWith('UklGR')
        || encoded.startsWith('R0lGOD')
        || encoded.startsWith('PHN2Zy');
}

function normalizeGeneratedImageSource(value, requestedMediaType = 'image/png', depth = 0) {
    if (depth > 4 || value == null) return '';
    if (Array.isArray(value)) {
        for (const item of value) {
            const normalized = normalizeGeneratedImageSource(item, requestedMediaType, depth + 1);
            if (normalized) return normalized;
        }
        return '';
    }
    if (isPlainObject(value)) {
        const mime = value.media_type || value.mime_type || value.mimeType || requestedMediaType;
        // Prefer an inline result when the provider supplies both inline data
        // and a temporary URL. The embedded result cannot expire, reject a
        // file:// origin, or be blocked by a CDN hotlink policy.
        for (const key of ['b64_json', 'base64', 'base64_data']) {
            const encoded = String(value[key] || '').trim();
            if (!encoded) continue;
            const normalized = normalizeGeneratedImageSource(encoded, mime, depth + 1);
            if (normalized) return normalized;
            const compact = encoded.replace(/\s+/g, '');
            return `data:${generatedImageMimeFromBase64(compact, mime)};base64,${compact}`;
        }
        // Dedicated image endpoints commonly return data[].b64_json, while
        // multimodal/chat routes may nest images under message.images,
        // content parts, output arrays or inlineData. Walk all documented
        // containers before deciding that a paid generation returned nothing.
        for (const key of ['url', 'image_url', 'imageUrl', 'image', 'images',
            'output', 'outputs', 'content', 'parts', 'inlineData', 'inline_data']) {
            const normalized = normalizeGeneratedImageSource(value[key], mime, depth + 1);
            if (normalized) return normalized;
        }
        return '';
    }
    let source = String(value || '').trim();
    if (!source) return '';
    if ((source.startsWith('"') && source.endsWith('"')) || (source.startsWith('{') && source.endsWith('}'))) {
        try {
            const normalized = normalizeGeneratedImageSource(JSON.parse(source), requestedMediaType, depth + 1);
            if (normalized) return normalized;
        } catch (error) { /* continue with the literal */ }
    }
    if (/^data:image\/[a-z0-9.+-]+(?:;[^,]*)?,/i.test(source) || /^blob:/i.test(source)) return source;
    const compact = source.replace(/\s+/g, '');
    if (isRecognizableImageBase64(compact) && /^[a-z0-9+/]+={0,2}$/i.test(compact)) {
        const padded = compact.padEnd(Math.ceil(compact.length / 4) * 4, '=');
        return `data:${generatedImageMimeFromBase64(compact, requestedMediaType)};base64,${padded}`;
    }
    // Bundled showcase media is deliberately kept as small project assets
    // instead of duplicating megabytes of base64 in every installed record.
    if (/^(?:\.\/)?assets\/bundled\/[a-z0-9_./-]+$/i.test(source)) {
        return source.replace(/^(?:\.\/)?assets\/bundled\/ashlyn-social\//i, 'assets/bundled/ashlyn-media/');
    }
    if (/^\/\//.test(source)) return `https:${source}`;
    if (/^http:\/\//i.test(source)) return source.replace(/^http:/i, 'https:');
    if (/^https:\/\//i.test(source)) return source;
    if (/^\//.test(source)) return `https://gptproto.com${source}`;
    if (/^[a-z0-9.-]+\.[a-z]{2,}\/\S+$/i.test(source)) return `https://${source}`;
    if (compact.length >= 64 && /^[a-z0-9+/]+={0,2}$/i.test(compact) && compact.length % 4 !== 1) {
        return `data:${generatedImageMimeFromBase64(compact, requestedMediaType)};base64,${compact.padEnd(Math.ceil(compact.length / 4) * 4, '=')}`;
    }
    return '';
}

function gptProtoImageFromResponse(data, requestedMediaType = 'image/png') {
    const direct = Array.isArray(data?.data) ? data.data[0] : data?.data;
    const output = Array.isArray(direct?.outputs) ? direct.outputs[0]
        : Array.isArray(data?.outputs) ? data.outputs[0] : '';
    const item = isPlainObject(direct) ? direct : {};
    const part = data?.candidates?.[0]?.content?.parts?.find(candidate =>
        candidate?.inlineData?.data || candidate?.inline_data?.data);
    const inline = part?.inlineData || part?.inline_data;
    const message = data?.choices?.[0]?.message;
    const markdown = String(message?.content || '')
        .match(/!\[[^\]]*\]\((data:image\/[^)]+|https?:\/\/[^)]+)\)/i)?.[1] || '';
    const normalized = normalizeGeneratedImageSource(
        [output, direct, item, message?.images, message?.content, data?.images,
            data?.output, data?.result, markdown], requestedMediaType);
    if (normalized) return normalized;
    if (inline?.data) return `data:${inline.mimeType || inline.mime_type || requestedMediaType};base64,${inline.data}`;
    return '';
}

function loadGeneratedImageOnce(image, source, timeoutMs = 30000) {
    return new Promise((resolve, reject) => {
        const timeout = setTimeout(() => {
            cleanup();
            reject(new Error('The generated image URL timed out while the browser was loading it.'));
        }, timeoutMs);
        const cleanup = () => {
            clearTimeout(timeout);
            image.onload = null;
            image.onerror = null;
        };
        image.onload = () => {
            cleanup();
            if (image.naturalWidth > 0 && image.naturalHeight > 0) resolve(source);
            else reject(new Error('The provider returned an empty image.'));
        };
        image.onerror = () => {
            cleanup();
            reject(new Error('The image was generated, but its returned URL or base64 data could not be loaded by this browser.'));
        };
        image.src = source;
        if (image.complete && image.naturalWidth > 0) {
            cleanup();
            resolve(source);
        }
    });
}

async function stabilizeGeneratedImageSource(source) {
    const normalized = normalizeGeneratedImageSource(source);
    if (!normalized) throw new Error('The provider returned an invalid image value instead of a URL or base64 image.');
    if (!/^https:\/\//i.test(normalized)) return normalized;
    try {
        const result = await mcpBridgeRequest('/media/fetch', {
            method: 'POST', body: { url: normalized }, timeoutMs: 135000
        });
        const embedded = normalizeGeneratedImageSource(result.image);
        return embedded || normalized;
    } catch (error) {
        // The bridge is optional for cloud-only use. The caller still gets one
        // direct browser attempt; GPTProto is also asked for b64_json first.
        console.warn('Could not stabilize generated image through the local bridge:', error.message || error);
        return normalized;
    }
}

async function loadGeneratedImage(image, source, timeoutMs = 30000) {
    const normalized = normalizeGeneratedImageSource(source);
    if (!normalized) throw new Error('The provider returned an invalid image value instead of a URL or base64 image.');
    try {
        return await loadGeneratedImageOnce(image, normalized, timeoutMs);
    } catch (directError) {
        if (!/^https:\/\//i.test(normalized)) throw directError;
        const stable = await stabilizeGeneratedImageSource(normalized);
        if (stable === normalized) throw directError;
        return loadGeneratedImageOnce(image, stable, timeoutMs);
    }
}

async function pollGptProtoImagePrediction(data, headers, signal, requestedMediaType) {
    let current = data;
    for (let attempt = 0; attempt < 120; attempt++) {
        const image = gptProtoImageFromResponse(current, requestedMediaType);
        if (image) return image;
        const record = isPlainObject(current?.data) ? current.data : current;
        const status = String(record?.status || '').toLowerCase();
        if (['failed', 'error', 'cancelled', 'canceled'].includes(status)) {
            throw new Error(record?.error || 'GPTProto image task failed.');
        }
        const id = record?.id || record?.result_id || current?.result_id;
        const getUrl = typeof record?.urls?.get === 'string' ? record.urls.get : '';
        if (!id && !getUrl) return '';
        await new Promise(resolve => setTimeout(resolve, 1000));
        const response = await fetch(
            getUrl || `https://gptproto.com/api/v3/predictions/${encodeURIComponent(id)}/result`,
            { headers, signal }
        );
        const raw = await response.text();
        let next = {};
        try { next = raw ? JSON.parse(raw) : {}; } catch (error) { next = {}; }
        if (!response.ok) {
            throw new Error(next?.error?.message || next?.message || `GPTProto result polling failed (${response.status})`);
        }
        current = next;
    }
    throw new Error('GPTProto image generation timed out while waiting for the completed task.');
}

async function requestCompanionPhoto(body, providerId = state.globalSettings.apiProvider) {
    const provider = String(providerId || '').toLowerCase() === 'fal' ? 'fal' : normalizedProviderId(providerId);
    const catalogModel = companionImageModelCatalog.find(item => item.id === body.model);
    const usedReference = !!body.input_references?.length || !!body.image
        || !!body.imageDataUrl || !!body.imageDataUrls?.length;
    if (usedReference && catalogModel?.supportsReference === false) {
        if (provider !== 'fal') throw new Error(`${catalogModel.name} does not advertise reference-image input. Choose a model marked “reference ready” in Virtual Human Studio.`);
    }
    if (provider === 'fal') {
        if (!state.falApiKey) throw new Error('Add a Fal API key in Settings before generating images.');
        const result = await mcpBridgeRequest('/fal/image/generate', {
            method: 'POST', timeoutMs: 210000,
            body: {
                apiKey: state.falApiKey, model: body.model, prompt: body.prompt,
                imageDataUrl: body.imageDataUrl || '',
                aspectRatio: body.aspect_ratio || (String(body.size || '').includes('16_9') ? '16:9' : '1:1'),
                fiboStructuredPrompt: isPlainObject(body.fiboStructuredPrompt) ? body.fiboStructuredPrompt : null,
                fiboResolution: String(body.fiboResolution || ''),
                fiboRevisionInstruction: String(body.fiboRevisionInstruction || ''),
                fiboCombinedRevision: body.fiboCombinedRevision === true,
                fiboNativeCompile: body.fiboNativeCompile === true,
                syncMode: typeof body.syncMode === 'boolean' ? body.syncMode : undefined,
                ...falAdvancedRequestFieldsFromBody(body)
            }
        });
        if (!result.image) throw new Error('Fal completed without returning an image.');
        requestCompanionPhoto.lastResult = result;
        return normalizeGeneratedImageSource(result.image);
    }
    const gptprotoProfile = provider === 'gptproto'
        ? gptProtoImageReferenceProfile({ id: body.model, ...(catalogModel || {}) }) : null;
    const gptprotoMultipartEdit = provider === 'gptproto'
        && usedReference
        && (!gptprotoProfile || gptprotoProfile.transport === 'openai-edit');
    let requestBody;
    let headers;
    let imagePath;
    let absoluteImageUrl = '';
    let pollsPrediction = false;
    if (provider === 'gptproto' && usedReference && gptprotoProfile?.transport === 'public-url-prompt') {
        if (!/^https?:\/\//i.test(String(body.image || ''))) {
            const error = new Error(`${body.model} supports references through GPTProto, but this route requires a public image URL rather than an uploaded local file.`);
            error.referenceTransportRejected = true;
            throw error;
        }
        body.prompt += `\nReference image URL: ${body.image}`;
        delete body.image;
    }
    if (provider === 'gptproto' && usedReference && gptprotoProfile?.transport === 'documented-edit') {
        const error = new Error(`${body.model} advertises image editing, but GPTProto does not expose a safely discoverable edit route for this catalog entry.`);
        error.referenceTransportRejected = true;
        throw error;
    }
    if (provider === 'nanogpt') {
        // NanoGPT's OpenAI-compatible image route deliberately lives outside
        // /api/v1. Prefer inline base64 so expiring signed URLs and browser
        // cross-origin image policies cannot turn a paid result into a blank.
        absoluteImageUrl = 'https://nano-gpt.com/v1/images/generations';
        const nanoBody = {
            ...body,
            n: Number.isFinite(Number(body.n)) ? Number(body.n) : 1,
            response_format: 'b64_json'
        };
        delete nanoBody.input_references;
        requestBody = JSON.stringify(nanoBody);
        headers = { 'Content-Type': 'application/json', ...providerAuthHeaders(provider) };
    } else if (provider === 'gptproto' && gptprotoProfile?.transport === 'seedream-async') {
        absoluteImageUrl = gptProtoImageEndpoint(body.model, usedReference);
        requestBody = JSON.stringify({
            prompt: body.prompt,
            ...(usedReference ? { images: [body.image] } : {}),
            ...(body.size ? { size: body.size } : {}),
            enable_base64_output: true,
            enable_sync_mode: false
        });
        headers = { 'Content-Type': 'application/json', ...providerAuthHeaders(provider) };
        pollsPrediction = true;
    } else if (provider === 'gptproto' && gptprotoProfile?.transport === 'seedream-v3') {
        absoluteImageUrl = gptProtoImageEndpoint(body.model, usedReference);
        requestBody = JSON.stringify({ ...body, response_format: body.response_format || 'b64_json' });
        headers = { 'Content-Type': 'application/json', ...providerAuthHeaders(provider) };
    } else if (provider === 'gptproto' && gptprotoProfile?.transport === 'gemini-native') {
        const match = String(body.image || '').match(/^data:([^;,]+);base64,([\s\S]+)$/i);
        const imagePart = match
            ? { inlineData: { mimeType: match[1], data: match[2] } }
            : { fileData: { mimeType: 'image/jpeg', fileUri: body.image } };
        absoluteImageUrl = gptProtoImageEndpoint(body.model, usedReference);
        requestBody = JSON.stringify({
            contents: [{ role: 'user', parts: [{ text: body.prompt }, ...(usedReference ? [imagePart] : [])] }],
            generationConfig: {
                responseModalities: ['TEXT', 'IMAGE'],
                imageConfig: {
                    ...(body.aspect_ratio ? { aspectRatio: body.aspect_ratio } : {}),
                    ...(body.size ? { imageSize: body.size } : {})
                }
            }
        });
        headers = { 'Content-Type': 'application/json', ...providerAuthHeaders(provider) };
    } else if (gptprotoMultipartEdit) {
        imagePath = '/images/edits';
        const form = new FormData();
        if (!body.response_format) body.response_format = 'b64_json';
        Object.entries(body).forEach(([key, value]) => {
            if (key === 'image' || value == null || typeof value === 'object') return;
            form.append(key, String(value));
        });
        const reference = String(body.image || '');
        const dataMatch = reference.match(/^data:([^;,]+);base64,([\s\S]+)$/i);
        if (dataMatch) {
            const binary = atob(dataMatch[2]);
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
            const mime = dataMatch[1].toLowerCase();
            const extension = mime.includes('png') ? 'png' : mime.includes('webp') ? 'webp' : 'jpg';
            form.append('image[]', new Blob([bytes], { type: mime }), `identity-reference.${extension}`);
        } else {
            // GPTProto documents `image` as either a file or a public URL.
            form.append('image', reference);
        }
        requestBody = form;
        headers = { ...providerAuthHeaders(provider), ...providerAttributionHeaders(provider) };
    } else {
        imagePath = provider === 'gptproto' ? '/images/generations' : '/images';
        requestBody = JSON.stringify(provider === 'gptproto'
            ? { ...body, response_format: body.response_format || 'b64_json' }
            : body);
        headers = { 'Content-Type': 'application/json', ...providerAuthHeaders(provider), ...providerAttributionHeaders(provider) };
    }
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 120000);
    let response;
    try {
        response = await fetch(absoluteImageUrl || (providerApiBase(provider) + imagePath), {
            // Some GPTProto image families use provider-native v3/v1beta
            // routes instead of the OpenAI-compatible /v1 image routes.
            method: 'POST',
            headers,
            body: requestBody,
            signal: controller.signal
        });
    } catch (error) {
        if (controller.signal.aborted) {
            throw new Error('Image generation timed out after 120 seconds. Retry the photo or choose a faster image model.');
        }
        throw error;
    } finally {
        clearTimeout(timeout);
    }
    let rawResponse = await response.text();
    let data = {};
    try { data = rawResponse ? JSON.parse(rawResponse) : {}; }
    catch (error) { data = {}; }
    const firstFailure = data?.error?.message || data?.message || rawResponse;
    if (!response.ok && provider === 'gptproto'
        && /response[_ ]format/i.test(String(firstFailure || ''))
        && /unsupported|not supported|unknown|unrecognized|invalid parameter/i.test(String(firstFailure || ''))) {
        // GPTProto's model families are not uniform: prefer portable base64,
        // but retry once without the hint when that exact route rejects it.
        if (requestBody instanceof FormData) requestBody.delete('response_format');
        else {
            try {
                const retryBody = JSON.parse(requestBody);
                delete retryBody.response_format;
                requestBody = JSON.stringify(retryBody);
            } catch (error) { /* provider-native payload; nothing to remove */ }
        }
        const retryController = new AbortController();
        const retryTimeout = setTimeout(() => retryController.abort(), 120000);
        try {
            response = await fetch(absoluteImageUrl || (providerApiBase(provider) + imagePath), {
                method: 'POST', headers, body: requestBody, signal: retryController.signal
            });
            rawResponse = await response.text();
            try { data = rawResponse ? JSON.parse(rawResponse) : {}; }
            catch (error) { data = {}; }
        } finally {
            clearTimeout(retryTimeout);
        }
    }
    if (!response.ok) {
        const errorData = data;
        const message = errorData?.error?.message || errorData?.message || `Image request failed (${response.status})`;
        const providerMessage = message === `Image request failed (${response.status})` && rawResponse
            ? rawResponse.slice(0, 2000) : message;
        const error = new Error(humanizeApiError(new Error(companionImageErrorMessage(providerMessage, body.model, usedReference, provider))));
        error.referencePrivacyRejected = usedReference && isCompanionReferencePrivacyError(providerMessage);
        throw error;
    }
    const requestedMediaType = {
        png: 'image/png', jpeg: 'image/jpeg', webp: 'image/webp', svg: 'image/svg+xml'
    }[body.output_format] || 'image/png';
    const url = pollsPrediction
        ? await pollGptProtoImagePrediction(data, headers, controller.signal, requestedMediaType)
        : gptProtoImageFromResponse(data, requestedMediaType);
    if (!url) throw new Error('The model replied without an image. Try a different image model in Virtual Human Studio.');
    const normalized = await stabilizeGeneratedImageSource(url);
    requestCompanionPhoto.lastResult = { image: normalized, provider, model: body.model, seed: body.seed || null };
    return normalized;
}

function companionMcpGenerationArguments(companion, sceneDescription, options = {}) {
    const tool = companionMcpTool(companion);
    if (!tool) throw new Error(`Choose a ${HORDE_MCP_PROVIDERS[companion.imageSource]?.label || 'MCP'} image tool in Photos & Voice.`);
    const schema = isPlainObject(tool.inputSchema) ? tool.inputSchema : {};
    const properties = isPlainObject(schema.properties) ? schema.properties : {};
    const required = new Set(Array.isArray(schema.required) ? schema.required : []);
    const includeReference = !!companion.basePhoto && options.includeReference !== false;
    const prompt = buildCompanionPhotoPrompt(companion, sceneDescription, {
        ...options, hasReference: includeReference
    });
    const args = safeJsonClone(isPlainObject(companion.mcpImageArguments) ? companion.mcpImageArguments : {});
    const promptKey = COMPANION_MCP_PROMPT_KEYS.find(key => properties[key])
        || (Object.keys(properties).length ? '' : 'prompt');
    if (!promptKey) {
        throw new Error(`${tool.name} does not advertise a recognizable prompt field. Choose another generation tool.`);
    }
    args[promptKey] = prompt;
    const referenceKey = COMPANION_MCP_REFERENCE_KEYS.find(key => properties[key]);
    if (includeReference && referenceKey) {
        const descriptor = properties[referenceKey] || {};
        args[referenceKey] = descriptor.type === 'array' ? [companion.basePhoto] : companion.basePhoto;
    }
    Object.entries(properties).forEach(([key, descriptor]) => {
        if (args[key] !== undefined || !isPlainObject(descriptor)) return;
        if (descriptor.default !== undefined) args[key] = safeJsonClone(descriptor.default);
        else if (key === 'action' && descriptor.enum?.includes('create')) args[key] = 'create';
        else if (['type', 'media_type', 'mediaType'].includes(key) && descriptor.enum?.includes('image')) args[key] = 'image';
        else if (['count', 'n', 'limit', 'num_images', 'numImages'].includes(key)) args[key] = 1;
        else if (required.has(key) && Array.isArray(descriptor.enum) && descriptor.enum.length) {
            args[key] = safeJsonClone(descriptor.enum[0]);
        }
    });
    const missing = [...required].filter(key => args[key] === undefined || args[key] === '');
    if (missing.length) {
        throw new Error(`${tool.name} still needs: ${missing.join(', ')}. Configure these fields under the MCP tool.`);
    }
    return { tool, args, includeReference, referenceKey };
}

async function generateCompanionMcpPhoto(companion, sceneDescription, options = {}) {
    const request = companionMcpGenerationArguments(companion, sceneDescription, options);
    try {
        const response = await mcpBridgeRequest(`/providers/${companion.imageSource}/generate`, {
            method: 'POST',
            body: { tool: request.tool.name, arguments: request.args },
            timeoutMs: 330000
        });
        if (!response.image) throw new Error('The MCP bridge returned no image.');
        return response.image;
    } catch (error) {
        const referenceRejected = request.includeReference && request.referenceKey
            && /reference|input image|source image|sensitive|privacy|unsupported image/i.test(String(error.message || error));
        const mayFallback = referenceRejected
            && options.fallbackWithoutReference !== false
            && companion.photoReferenceFallback !== false;
        if (!mayFallback) throw error;
        if (typeof options.onReferenceFallback === 'function') options.onReferenceFallback(error);
        const fallback = companionMcpGenerationArguments(companion, sceneDescription, {
            ...options, includeReference: false
        });
        const response = await mcpBridgeRequest(`/providers/${companion.imageSource}/generate`, {
            method: 'POST',
            body: { tool: fallback.tool.name, arguments: fallback.args },
            timeoutMs: 330000
        });
        if (!response.image) throw new Error('The MCP bridge returned no image.');
        return response.image;
    }
}

async function generateCompanionLocalPhoto(companion, sceneDescription, options = {}) {
    const includeReference = !!companion.basePhoto && options.includeReference !== false;
    const prompt = buildCompanionPhotoPrompt(companion, sceneDescription, {
        ...options, hasReference: includeReference
    });
    const settings = state.globalSettings;
    const comfyProfile = activeComfyWorkflowProfile(settings);
    const request = companion.imageSource === 'comfyui'
        ? {
            path: '/local-image/comfy/generate',
            body: {
                baseUrl: settings.comfyUiBaseUrl,
                workflow: comfyProfile.workflow,
                prompt,
                reference: includeReference ? companion.basePhoto : '',
                mapping: {
                    promptNode: comfyProfile.promptNode,
                    promptInput: comfyProfile.promptInput || 'text',
                    referenceNode: comfyProfile.referenceNode,
                    referenceInput: 'image'
                }
            }
        }
        : {
            path: '/local-image/openai/generate',
            body: {
                baseUrl: settings.localImageBaseUrl,
                path: settings.localImagePath,
                apiKey: settings.localImageApiKey,
                payload: {
                    model: companion.imageModel || 'local-image',
                    prompt,
                    ...(includeReference ? { image: companion.basePhoto } : {}),
                    ...normalizeCompanionImageParameters(companion.imageParameters)
                }
            }
        };
    try {
        const result = await mcpBridgeRequest(request.path, {
            method: 'POST', body: request.body, timeoutMs: 360000
        });
        if (!result.image) throw new Error('The local image engine returned no image.');
        return result.image;
    } catch (error) {
        const mayFallback = includeReference
            && options.fallbackWithoutReference !== false
            && companion.photoReferenceFallback !== false
            && /image|reference|upload|input|workflow/i.test(String(error.message || error));
        if (!mayFallback) throw error;
        if (typeof options.onReferenceFallback === 'function') options.onReferenceFallback(error);
        return generateCompanionLocalPhoto(companion, sceneDescription, {
            ...options, includeReference: false, fallbackWithoutReference: false
        });
    }
}

async function generateCompanionPhoto(companion, sceneDescription, options = {}) {
    if (['higgsfield', 'magnific'].includes(companion.imageSource)) {
        return generateCompanionMcpPhoto(companion, sceneDescription, options);
    }
    if (['local_image', 'comfyui'].includes(companion.imageSource)) {
        return generateCompanionLocalPhoto(companion, sceneDescription, options);
    }
    const imageProvider = companionImageProviderId(companion);
    if (!providerHasCredentials(imageProvider)) {
        throw new Error(`Add a ${providerDisplayName(imageProvider)} API key in Settings before generating photos.`);
    }
    const modelId = companion.imageModel || companionImageModelFallback(imageProvider);
    let modelInfo = companionImageModelInfo(modelId);
    if (!modelInfo && imageProvider !== 'local') {
        const ranked = rankCompanionImageModels(
            await getCompanionOutputModels('image', false, imageProvider), imageProvider);
        companionImageModelCatalog = ranked;
        modelInfo = ranked.find(model => model.id === modelId) || null;
    }
    const endpoints = await getCompanionImageEndpoints(modelId, false, imageProvider);
    const endpoint = chooseCompanionImageEndpoint(endpoints, companion, !!companion.basePhoto && options.includeReference !== false);
    const capabilities = companionImageCapabilities(modelInfo, endpoint);
    const body = buildCompanionImageRequest(companion, sceneDescription, {
        ...options, endpoint, capabilities, providerId: imageProvider
    });
    try {
        return await requestCompanionPhoto(body, imageProvider);
    } catch (error) {
        const mayFallback = (error?.referencePrivacyRejected || error?.referenceTransportRejected)
            && options.fallbackWithoutReference !== false
            && companion.photoReferenceFallback !== false;
        if (!mayFallback) throw error;
        if (typeof options.onReferenceFallback === 'function') options.onReferenceFallback(error);
        const fallbackEndpoint = chooseCompanionImageEndpoint(endpoints, companion, false);
        return requestCompanionPhoto(buildCompanionImageRequest(companion, sceneDescription, {
            ...options, includeReference: false, endpoint: fallbackEndpoint,
            capabilities: companionImageCapabilities(modelInfo, fallbackEndpoint),
            providerId: imageProvider
        }), imageProvider);
    }
}

// --- Voice notes and calls: OpenRouter Neural TTS & Browser text-to-speech ---

const COMPANION_TTS_MODEL_FALLBACK = 'mistralai/voxtral-mini-tts-2603';
const COMPANION_TTS_MODEL_FALLBACKS = [
    { id: 'mistralai/voxtral-mini-tts-2603', name: 'Mistral Voxtral Mini TTS' },
    { id: 'openai/gpt-4o-mini-tts-2025-12-15', name: 'OpenAI GPT-4o Mini TTS' }
];
const GPTPROTO_TTS_MODEL_FALLBACK = Object.freeze({
    id: 'gpt-4o-mini-tts',
    name: 'GPT-4o Mini TTS',
    architecture: { input_modalities: ['text'], output_modalities: ['speech'] },
    supported_voices: ['alloy'],
    supported_parameters: ['voice']
});
const NANOGPT_TTS_MODEL_FALLBACK = Object.freeze({
    id: 'Kokoro-82m',
    name: 'Kokoro 82M',
    architecture: { input_modalities: ['text'], output_modalities: ['speech'] },
    supported_voices: ['af_bella'],
    supported_parameters: ['voice', 'response_format', 'speed']
});
const LOCAL_TTS_MODEL_FALLBACK = Object.freeze({
    id: 'tts-1',
    name: 'Local TTS (default)',
    architecture: { input_modalities: ['text'], output_modalities: ['speech'] },
    supported_voices: ['alloy'],
    supported_parameters: ['voice', 'response_format', 'speed']
});
let localTTSModelCache = null;

function companionTTSModelFallback(mode = '') {
    if (mode === 'local') return LOCAL_TTS_MODEL_FALLBACK.id;
    if (isGPTProtoProvider()) return GPTPROTO_TTS_MODEL_FALLBACK.id;
    if (isNanoGPTProvider()) return NANOGPT_TTS_MODEL_FALLBACK.id;
    return COMPANION_TTS_MODEL_FALLBACK;
}

async function getLocalTTSModels(force = false) {
    if (force) localTTSModelCache = null;
    if (localTTSModelCache) return localTTSModelCache;
    const response = await fetch(localTTSApiBase() + '/models', { headers: localTTSAuthHeaders() });
    if (!response.ok) throw new Error(`Local TTS model catalog failed (${response.status})`);
    const data = await response.json();
    const catalog = Array.isArray(data) ? data : Array.isArray(data?.data) ? data.data : Array.isArray(data?.models) ? data.models : [];
    localTTSModelCache = catalog.filter(model => isPlainObject(model) && typeof model.id === 'string')
        .map(model => ({
            ...model,
            name: typeof model.name === 'string' ? model.name : model.id,
            architecture: isPlainObject(model.architecture)
                ? { ...model.architecture, output_modalities: ['speech'] }
                : { input_modalities: ['text'], output_modalities: ['speech'] }
        }));
    if (!localTTSModelCache.length) localTTSModelCache = [LOCAL_TTS_MODEL_FALLBACK];
    return localTTSModelCache;
}

function isTTSCapableModel(model) {
    if (!model || typeof model.id !== 'string') return false;
    const id = model.id.toLowerCase();
    const outputs = modelOutputModalities(model);
    if (outputs.includes('speech')) return true;
    if (outputs.includes('audio')) return /(?:^|[/.-])tts(?:$|[/.-])|voice(?:$|[/.-])|speech(?:$|[/.-])/i.test(id);
    if (outputs.length) return false;
    return /(?:^|[/.-])tts(?:$|[/.-])|voxtral[^/]*tts|mai-voice/i.test(id);
}

function rankCompanionTTSModels(models) {
    const list = (Array.isArray(models) ? models : []).filter(isTTSCapableModel);
    if (!list.length) {
        const fallbacks = isGPTProtoProvider() ? [GPTPROTO_TTS_MODEL_FALLBACK]
            : isNanoGPTProvider() ? [NANOGPT_TTS_MODEL_FALLBACK]
            : COMPANION_TTS_MODEL_FALLBACKS;
        fallbacks.forEach(fb =>
            list.push({ ...fb, architecture: fb.architecture || { output_modalities: ['speech'] } }));
    }
    return list.map(model => ({
        id: model.id,
        name: model.name || model.id,
        description: String(model.description || '').slice(0, 2000),
        supportedVoices: Array.isArray(model.supported_voices) ? model.supported_voices : [],
        supportedParameters: Array.isArray(model.supported_parameters)
            ? model.supported_parameters.map(value => String(value)) : [],
        pricing: isPlainObject(model.pricing) ? model.pricing : {}
    }));
}

const COMPANION_TTS_PROVIDER_OPTION_DEFS = Object.freeze({
    openai: {
        instructions: { label: 'Delivery instructions', kind: 'text', placeholder: 'Warm, intimate, slightly tired…' }
    },
    azure: {
        style: { label: 'Speaking style', kind: 'text', placeholder: 'cheerful, sad, excited…' },
        styledegree: { label: 'Style intensity', kind: 'number', min: 0.01, max: 2, step: 0.05 }
    }
});

let companionTTSModelCatalog = [];

function normalizeCompanionTTSProviderOptions(raw) {
    if (!isPlainObject(raw)) return {};
    const out = {};
    Object.entries(raw).slice(0, 20).forEach(([key, value]) => {
        if (!/^[a-zA-Z0-9_.-]{1,80}$/.test(key) || value == null || value === '') return;
        if (typeof value === 'string') out[key] = value.slice(0, 1000);
        else if (typeof value === 'boolean') out[key] = value;
        else if (typeof value === 'number' && Number.isFinite(value)) out[key] = value;
    });
    return out;
}

function companionTTSCapabilities(modelId, modelInfo = null, ttsMode = '') {
    const id = String(modelId || '').toLowerCase();
    const description = String(modelInfo?.description || '').toLowerCase();
    const supportedParameters = new Set(modelInfo?.supportedParameters || []);
    const gptprotoSpeech = isGPTProtoProvider();
    const nanoGPTSpeech = isNanoGPTProvider();
    const googlePCMOnly = id.startsWith('google/') && /tts|speech/.test(id);
    const localSpeech = ttsMode === 'local';
    const formats = localSpeech ? ['mp3', 'wav', 'pcm', 'ogg', 'opus', 'aac', 'flac']
        : gptprotoSpeech ? ['mp3']
        : nanoGPTSpeech ? ['mp3', 'wav', 'ogg', 'opus', 'aac', 'flac']
        : (googlePCMOnly ? ['pcm'] : ['mp3', 'pcm']);
    let providerSlug = '';
    if (id.startsWith('openai/')) providerSlug = 'openai';
    else if (id.startsWith('microsoft/')) providerSlug = 'azure';
    else if (id.startsWith('x-ai/')) providerSlug = 'x-ai';
    else if (id.startsWith('mistralai/')) providerSlug = 'mistral';
    else if (id.startsWith('hexgrad/')) providerSlug = 'deepinfra';
    else if (id.startsWith('google/')) providerSlug = 'google';
    const supportsSpeed = !gptprotoSpeech && (localSpeech || nanoGPTSpeech || supportedParameters.has('speed')
        || id.startsWith('openai/')
        || id.startsWith('microsoft/')
        || /\bspeed (?:control|multiplier)\b/.test(description));
    return {
        formats,
        preferredFormat: googlePCMOnly ? 'pcm' : 'mp3',
        sendsResponseFormat: !gptprotoSpeech,
        sampleRate: /\b48\s*khz\b/.test(description) ? 48000 : 24000,
        channels: 1,
        pcmEncoding: id.startsWith('mistralai/') ? 'float32le' : 's16le',
        supportsSpeed,
        providerSlug,
        providerOptionDefs: COMPANION_TTS_PROVIDER_OPTION_DEFS[providerSlug] || {}
    };
}

function fallbackTTSVoicesForModel(modelId) {
    const id = String(modelId || '').toLowerCase();
    if (isNanoGPTProvider() && id === 'kokoro-82m') return ['af_bella'];
    if (isNanoGPTProvider() && ['tts-1', 'tts-1-hd', 'gpt-4o-mini-tts'].includes(id)) {
        return ['alloy', 'ash', 'ballad', 'coral', 'echo', 'fable', 'nova', 'onyx', 'sage', 'shimmer'];
    }
    if (id.startsWith('x-ai/')) return ['eve', 'ara', 'rex', 'sal', 'leo'];
    if (id.startsWith('microsoft/mai-voice')) return ['en-US-Harper:MAI-Voice-2'];
    if (id.startsWith('google/') && /tts|speech/.test(id)) {
        return [
            'Kore', 'Puck', 'Charon', 'Aoede', 'Leda', 'Fenrir', 'Orus', 'Zephyr',
            'Callirrhoe', 'Autonoe', 'Enceladus', 'Iapetus', 'Umbriel', 'Algieba',
            'Despina', 'Erinome', 'Algenib', 'Rasalgethi', 'Laomedeia', 'Achernar',
            'Alnilam', 'Schedar', 'Gacrux', 'Pulcherrima', 'Achird',
            'Zubenelgenubi', 'Vindemiatrix', 'Sadachbia', 'Sadaltager', 'Sulafat'
        ];
    }
    if (id === 'gpt-4o-mini-tts') return ['alloy'];
    if (id.startsWith('openai/')) {
        return ['alloy', 'ash', 'ballad', 'coral', 'echo', 'fable', 'nova', 'onyx', 'sage', 'shimmer'];
    }
    // OpenRouter's TTS contract uses `alloy` as its portable baseline, and
    // model metadata replaces this fallback whenever it advertises voices.
    return ['alloy'];
}

function normalizeTTSVoiceOptions(rawVoices, modelId) {
    const source = Array.isArray(rawVoices) && rawVoices.length
        ? rawVoices
        : fallbackTTSVoicesForModel(modelId);
    const seen = new Set();
    return source.map(raw => {
        const value = typeof raw === 'string'
            ? raw
            : String(raw?.id || raw?.voice || raw?.value || raw?.name || '').trim();
        const label = typeof raw === 'string'
            ? raw.replace(/[-_]/g, ' ').replace(/\b\w/g, char => char.toUpperCase())
            : String(raw?.label || raw?.name || value);
        return { value, label };
    }).filter(voice => voice.value && !seen.has(voice.value) && seen.add(voice.value));
}

function populateCompanionTTSVoicePicker(companion, modelId, resetVoice = false) {
    const select = document.getElementById('cs-tts-voice');
    const custom = document.getElementById('cs-tts-voice-custom');
    const status = document.getElementById('cs-tts-voice-status');
    if (!select) return;
    const model = companionTTSModelCatalog.find(item => item.id === modelId);
    const voices = normalizeTTSVoiceOptions(model?.supportedVoices, modelId);
    const current = resetVoice ? '' : String(companion?.ttsVoice || '');
    const selected = voices.some(voice => voice.value === current) ? current : (voices[0]?.value || '');
    select.innerHTML = voices.map(voice =>
        `<option value="${escapeHTML(voice.value)}" ${voice.value === selected ? 'selected' : ''}>${escapeHTML(voice.label)}</option>`
    ).join('') || '<option value="">Enter a custom voice ID below</option>';
    if (companion && selected) companion.ttsVoice = selected;
    if (custom) custom.value = current && !voices.some(voice => voice.value === current) ? current : '';
    if (status) {
        const modelName = model?.name || modelId || 'custom model';
        const voiceSummary = model?.supportedVoices?.length
            ? `${voices.length} voices advertised by ${modelName}.`
            : `${modelName} does not advertise a voice catalog; using the portable default. You can enter a provider voice ID below.`;
        const capabilities = companionTTSCapabilities(modelId, model, companion?.ttsMode);
        const format = companion.ttsResponseFormat === 'auto'
            ? capabilities.preferredFormat : companion.ttsResponseFormat;
        status.textContent = `${voiceSummary} Preferred audio: ${format === 'pcm' ? `PCM ${capabilities.sampleRate / 1000} kHz → WAV` : 'MP3'}.`;
    }
    renderCompanionTTSAudioControls(companion, modelId);
}

/**
 * OpenRouter exposes mp3 and pcm through one speech endpoint, but upstream
 * models do not all accept both. Gemini TTS is PCM-only; other current
 * providers are safest as MP3 (Mistral's raw PCM is float32, unlike Gemini's
 * signed 16-bit stream).
 */
function ttsResponseFormatForModel(modelId) {
    return companionTTSCapabilities(modelId,
        companionTTSModelCatalog.find(model => model.id === modelId)).preferredFormat;
}

function buildCompanionTTSRequest(companion, text, modelInfo = null, formatOverride = '') {
    const model = companion.ttsModel || companionTTSModelFallback(companion.ttsMode);
    const capabilities = companionTTSCapabilities(model, modelInfo, companion.ttsMode);
    const requested = formatOverride
        || (companion.ttsResponseFormat && companion.ttsResponseFormat !== 'auto'
            ? companion.ttsResponseFormat : capabilities.preferredFormat);
    const responseFormat = capabilities.formats.includes(requested)
        ? requested : capabilities.preferredFormat;
    const body = {
        model,
        input: String(text || ''),
        voice: String(companion.ttsVoice || '').trim()
    };
    if (capabilities.sendsResponseFormat) body.response_format = responseFormat;
    if (capabilities.supportsSpeed) {
        body.speed = livingClamp(Number(companion.ttsSpeed) || 1, 0.5, 2);
    }
    const allowedOptions = capabilities.providerOptionDefs || {};
    const providerOptions = {};
    Object.entries(normalizeCompanionTTSProviderOptions(companion.ttsProviderOptions)).forEach(([key, value]) => {
        if (allowedOptions[key]) providerOptions[key] = value;
    });
    if (capabilities.providerSlug && Object.keys(providerOptions).length) {
        body.provider = { options: { [capabilities.providerSlug]: providerOptions } };
    }
    return { body, capabilities, responseFormat };
}

function updateCompanionTTSRequestPreview(companion, modelInfo = null) {
    const preview = document.getElementById('cs-tts-request-preview');
    if (!preview) return;
    const { body } = buildCompanionTTSRequest(companion, '(sample text)', modelInfo);
    const visible = Object.entries(body)
        .filter(([key]) => key !== 'input')
        .map(([key, value]) => `${key}=${typeof value === 'object' ? JSON.stringify(value) : value}`);
    preview.textContent = `Request: ${visible.join(' · ')} · input`;
}

function renderCompanionTTSAudioControls(companion, modelId) {
    const formatSelect = document.getElementById('cs-tts-response-format');
    const speedInput = document.getElementById('cs-tts-speed');
    const speedWrap = document.getElementById('cs-tts-speed-wrap');
    const speedValue = document.getElementById('cs-tts-speed-value');
    const providerOptions = document.getElementById('cs-tts-provider-options');
    if (!formatSelect || !speedInput || !speedWrap || !providerOptions) return;
    const model = companionTTSModelCatalog.find(item => item.id === modelId) || null;
    const capabilities = companionTTSCapabilities(modelId, model, companion?.ttsMode);
    const selectedFormat = capabilities.formats.includes(companion.ttsResponseFormat)
        ? companion.ttsResponseFormat : 'auto';
    formatSelect.innerHTML = [
        `<option value="auto" ${selectedFormat === 'auto' ? 'selected' : ''}>Automatic (${capabilities.preferredFormat.toUpperCase()})</option>`,
        ...capabilities.formats.map(format =>
            `<option value="${format}" ${selectedFormat === format ? 'selected' : ''}>${format === 'pcm' ? `PCM ${capabilities.sampleRate / 1000} kHz → WAV` : format.toUpperCase()}</option>`)
    ].join('');
    speedWrap.classList.toggle('hidden', !capabilities.supportsSpeed);
    speedInput.value = String(companion.ttsSpeed || 1);
    if (speedValue) speedValue.textContent = `${Number(companion.ttsSpeed || 1).toFixed(2)}×`;

    const optionDefs = capabilities.providerOptionDefs || {};
    providerOptions.classList.toggle('hidden', !Object.keys(optionDefs).length);
    providerOptions.innerHTML = Object.entries(optionDefs).length
        ? `<div class="vh-image-provider-heading">${escapeHTML(capabilities.providerSlug)} voice controls</div>`
            + Object.entries(optionDefs).map(([key, definition]) => `<div class="vh-image-parameter-field">
                <label class="form-label" for="cs-tts-provider-${escapeHTML(key)}">${escapeHTML(definition.label)}<small>provider-specific</small></label>
                <input id="cs-tts-provider-${escapeHTML(key)}" class="form-input"
                    data-tts-provider-option="${escapeHTML(key)}"
                    type="${definition.kind === 'number' ? 'number' : 'text'}"
                    ${definition.min != null ? `min="${definition.min}"` : ''}
                    ${definition.max != null ? `max="${definition.max}"` : ''}
                    ${definition.step != null ? `step="${definition.step}"` : ''}
                    value="${companion.ttsProviderOptions[key] == null ? '' : escapeHTML(String(companion.ttsProviderOptions[key]))}"
                    placeholder="${escapeHTML(definition.placeholder || 'Provider default')}">
            </div>`).join('')
        : '';

    formatSelect.onchange = () => {
        companion.ttsResponseFormat = formatSelect.value;
        updateCompanionTTSRequestPreview(companion, model);
        populateCompanionTTSVoicePicker(companion, modelId);
    };
    speedInput.oninput = () => {
        companion.ttsSpeed = livingClamp(Number(speedInput.value) || 1, 0.5, 2);
        if (speedValue) speedValue.textContent = `${companion.ttsSpeed.toFixed(2)}×`;
        updateCompanionTTSRequestPreview(companion, model);
    };
    providerOptions.querySelectorAll('[data-tts-provider-option]').forEach(input => {
        input.oninput = () => {
            const key = input.dataset.ttsProviderOption;
            const definition = optionDefs[key];
            let value = input.value.trim();
            if (definition?.kind === 'number') {
                const number = Number(value);
                value = Number.isFinite(number)
                    ? livingClamp(number, definition.min ?? number, definition.max ?? number)
                    : '';
            }
            if (value === '') delete companion.ttsProviderOptions[key];
            else companion.ttsProviderOptions[key] = value;
            updateCompanionTTSRequestPreview(companion, model);
        };
    });
    updateCompanionTTSRequestPreview(companion, model);
}

function pcmToWavArrayBuffer(pcmBuffer, sampleRate = 24000, channels = 1, bitsPerSample = 16, audioFormat = 1) {
    const pcm = pcmBuffer instanceof Uint8Array ? pcmBuffer : new Uint8Array(pcmBuffer);
    if (pcm.length >= 12
        && String.fromCharCode(...pcm.slice(0, 4)) === 'RIFF'
        && String.fromCharCode(...pcm.slice(8, 12)) === 'WAVE') {
        return pcm.buffer.slice(pcm.byteOffset, pcm.byteOffset + pcm.byteLength);
    }
    const headerSize = 44;
    const output = new ArrayBuffer(headerSize + pcm.byteLength);
    const view = new DataView(output);
    const bytes = new Uint8Array(output);
    const writeASCII = (offset, value) => {
        for (let i = 0; i < value.length; i++) bytes[offset + i] = value.charCodeAt(i);
    };
    const blockAlign = channels * bitsPerSample / 8;
    writeASCII(0, 'RIFF');
    view.setUint32(4, 36 + pcm.byteLength, true);
    writeASCII(8, 'WAVE');
    writeASCII(12, 'fmt ');
    view.setUint32(16, 16, true);
    view.setUint16(20, audioFormat, true);
    view.setUint16(22, channels, true);
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * blockAlign, true);
    view.setUint16(32, blockAlign, true);
    view.setUint16(34, bitsPerSample, true);
    writeASCII(36, 'data');
    view.setUint32(40, pcm.byteLength, true);
    bytes.set(pcm, headerSize);
    return output;
}

function pcm16ToWavArrayBuffer(pcmBuffer, sampleRate = 24000, channels = 1) {
    return pcmToWavArrayBuffer(pcmBuffer, sampleRate, channels, 16, 1);
}

function sniffTTSAudioFormat(audioBuffer, contentType = '', requestedFormat = '') {
    const bytes = audioBuffer instanceof Uint8Array ? audioBuffer : new Uint8Array(audioBuffer);
    const ascii = (start, length) => String.fromCharCode(...bytes.slice(start, start + length));
    if (bytes.length >= 12 && ascii(0, 4) === 'RIFF' && ascii(8, 4) === 'WAVE') {
        return { format: 'wav', mime: 'audio/wav', container: true };
    }
    if (bytes.length >= 12 && ascii(0, 4) === 'FORM' && ['AIFF', 'AIFC'].includes(ascii(8, 4))) {
        return { format: 'aiff', mime: 'audio/aiff', container: true };
    }
    if (bytes.length >= 4 && ascii(0, 4) === 'OggS') {
        return { format: 'ogg', mime: 'audio/ogg', container: true };
    }
    if (bytes.length >= 4 && ascii(0, 4) === 'fLaC') {
        return { format: 'flac', mime: 'audio/flac', container: true };
    }
    if (bytes.length >= 4 && bytes[0] === 0x1a && bytes[1] === 0x45 && bytes[2] === 0xdf && bytes[3] === 0xa3) {
        return { format: 'webm', mime: 'audio/webm', container: true };
    }
    if (bytes.length >= 12 && ascii(4, 4) === 'ftyp') {
        return { format: 'mp4', mime: 'audio/mp4', container: true };
    }
    if (bytes.length >= 2 && bytes[0] === 0xff && (bytes[1] & 0xf6) === 0xf0) {
        return { format: 'aac', mime: 'audio/aac', container: true };
    }
    if (bytes.length >= 3 && ascii(0, 3) === 'ID3') {
        return { format: 'mp3', mime: 'audio/mpeg', container: true };
    }
    if (requestedFormat === 'mp3' || /audio\/(?:mpeg|mp3)/i.test(String(contentType))) {
        for (let offset = 0; offset < Math.min(bytes.length - 1, 4096); offset++) {
            if (bytes[offset] === 0xff && (bytes[offset + 1] & 0xe0) === 0xe0) {
                return { format: 'mp3', mime: 'audio/mpeg', container: true };
            }
        }
    }
    const trimmedStart = ascii(0, Math.min(bytes.length, 80)).trimStart();
    if (/^[{[]/.test(trimmedStart)) return { format: 'json', mime: 'application/json', container: false };
    if (/^<!doctype|^<html/i.test(trimmedStart)) return { format: 'html', mime: 'text/html', container: false };
    if (/\bpcm\b|audio\/(l16|l24|raw)/i.test(String(contentType))) {
        return { format: 'pcm', mime: 'audio/pcm', container: false };
    }
    return { format: 'unknown', mime: String(contentType || '').split(';')[0] || 'application/octet-stream', container: false };
}

function prepareTTSAudioBlob(audioBuffer, options = {}) {
    const bytes = audioBuffer instanceof Uint8Array ? audioBuffer : new Uint8Array(audioBuffer);
    const detected = sniffTTSAudioFormat(bytes, options.contentType, options.requestedFormat);
    if (['json', 'html'].includes(detected.format)) {
        const text = new TextDecoder().decode(bytes).slice(0, 2000);
        throw new Error(ttsErrorMessageFromText(text, options.status || 200));
    }
    if (detected.container) {
        return {
            blob: new Blob([bytes], { type: detected.mime }),
            format: detected.format,
            mime: detected.mime,
            converted: false
        };
    }
    const treatAsPCM = detected.format === 'pcm'
        || options.requestedFormat === 'pcm'
        || options.allowUnknownPCM === true;
    if (!treatAsPCM) {
        const head = Array.from(bytes.slice(0, 12), byte => byte.toString(16).padStart(2, '0')).join(' ');
        throw new Error(`The provider returned ${bytes.length} bytes that are not a recognizable ${String(options.requestedFormat || 'audio').toUpperCase()} stream (Content-Type: ${options.contentType || 'missing'}, header: ${head || 'empty'}).`);
    }
    const profile = options.capabilities || { sampleRate: 24000, channels: 1, pcmEncoding: 's16le' };
    const floatPCM = profile.pcmEncoding === 'float32le';
    const wav = pcmToWavArrayBuffer(
        bytes, profile.sampleRate || 24000, profile.channels || 1,
        floatPCM ? 32 : 16, floatPCM ? 3 : 1);
    return {
        blob: new Blob([wav], { type: 'audio/wav' }),
        format: floatPCM ? 'pcm-f32le→wav' : 'pcm-s16le→wav',
        mime: 'audio/wav',
        converted: true
    };
}

function ttsErrorMessageFromText(raw, status) {
    const text = String(raw || '').trim();
    if (text) {
        try {
            const data = JSON.parse(text);
            return data?.error?.message || data?.message || text;
        } catch (error) {
            return text;
        }
    }
    return `TTS request failed (${status})`;
}

function requiredTTSFormatFromError(message) {
    const match = String(message || '').match(/(?:only supports?\s+(?:response_format\s*=\s*)?|accepted:\s*)["']?(mp3|pcm)["']?/i);
    return match ? match[1].toLowerCase() : '';
}

/**
 * Generate audio speech via OpenRouter TTS / Audio endpoints.
 */
async function generateOpenRouterSpeech(companion, text, options = {}) {
    const useLocalTTS = companion.ttsMode === 'local';
    if (!useLocalTTS && !hasApiCredentials()) {
        throw new Error(`${cloudProviderName()} API Key is missing. Please enter it in Settings.`);
    }
    const model = companion.ttsModel || companionTTSModelFallback(companion.ttsMode);
    const voice = String(companion.ttsVoice || '').trim();
    if (!voice) throw new Error('Choose a neural voice before generating a preview.');
    const modelInfo = companionTTSModelCatalog.find(item => item.id === model) || null;
    const initial = buildCompanionTTSRequest(companion, text, modelInfo, options.responseFormat || '');
    const attempts = [initial.responseFormat, ...initial.capabilities.formats.filter(format => format !== initial.responseFormat)];
    const attempted = new Set();
    let lastError = null;
    while (attempts.length) {
        const responseFormat = attempts.shift();
        if (attempted.has(responseFormat)) continue;
        attempted.add(responseFormat);
        const request = buildCompanionTTSRequest(companion, text, modelInfo, responseFormat);
        const response = await fetch((useLocalTTS ? localTTSApiBase() : apiBase()) + '/audio/speech', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                ...(useLocalTTS ? localTTSAuthHeaders() : authHeaders()),
                ...(useLocalTTS ? {} : providerAttributionHeaders(state.globalSettings.apiProvider))
            },
            body: JSON.stringify(request.body)
        });
        if (!response.ok) {
            const rawError = await response.text().catch(() => '');
            const message = ttsErrorMessageFromText(rawError, response.status);
            const requiredFormat = requiredTTSFormatFromError(message);
            if (requiredFormat && !attempted.has(requiredFormat)) {
                attempts.unshift(requiredFormat);
                lastError = new Error(message);
                continue;
            }
            throw new Error(humanizeApiError(new Error(message), useLocalTTS ? 'local' : state.globalSettings.apiProvider));
        }
        const contentType = String(response.headers.get('content-type') || '');
        const audioBytes = await response.arrayBuffer();
        if (!audioBytes.byteLength) {
            lastError = new Error(`The model (${model}) returned an empty audio file.`);
            continue;
        }
        try {
            const prepared = prepareTTSAudioBlob(audioBytes, {
                contentType,
                requestedFormat: responseFormat,
                capabilities: request.capabilities,
                status: response.status
            });
            if (!prepared.blob?.size) throw new Error(`The model (${model}) returned an empty audio file.`);
            let persistentDataUrl = '';
            if (options.persist === true && prepared.blob.size <= 6 * 1024 * 1024) {
                persistentDataUrl = await new Promise((resolve, reject) => {
                    const reader = new FileReader();
                    reader.onload = () => resolve(String(reader.result || ''));
                    reader.onerror = () => reject(reader.error || new Error('Could not cache voice note audio.'));
                    reader.readAsDataURL(prepared.blob);
                });
            }
            return {
                url: persistentDataUrl || URL.createObjectURL(prepared.blob),
                persistentDataUrl,
                format: prepared.format,
                mime: prepared.mime,
                converted: prepared.converted,
                requestedFormat: responseFormat,
                contentType: contentType || '(missing)',
                byteLength: audioBytes.byteLength,
                generationId: String(response.headers.get('x-generation-id') || '')
            };
        } catch (error) {
            lastError = error;
            if (/not a recognizable/i.test(error.message) && attempts.length) continue;
            throw error;
        }
    }
    throw lastError || new Error(`The model (${model}) did not return playable audio.`);
}

/** Deterministic voice choice, so the same companion always sounds the same. */
function pickCompanionVoice(companion) {
    if (companion.ttsVoiceURI) {
        const remembered = speechSynthesis.getVoices().find(v => v.voiceURI === companion.ttsVoiceURI);
        if (remembered) return remembered;
    }
    const voices = speechSynthesis.getVoices();
    if (!voices.length) return null;
    const byGender = voices.filter(v => {
        if (companion.voiceGender === 'neutral') return true;
        const name = v.name.toLowerCase();
        return companion.voiceGender === 'female' ? /female|samantha|victoria|karen|zira|allison/.test(name)
            : /male|daniel|fred|alex|david/.test(name);
    });
    const pool = byGender.length ? byGender : voices;
    return pool[Math.floor(companionSeededRoll(companion.id + '|voice') * pool.length)];
}

function speakBrowserLine(companion, text, onEnd) {
    if (!('speechSynthesis' in window)) { if (onEnd) onEnd(); return null; }
    speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    const voice = pickCompanionVoice(companion);
    if (voice) utterance.voice = voice;
    utterance.rate = 1.0;
    if (onEnd) utterance.onend = onEnd;
    speechSynthesis.speak(utterance);
    return utterance;
}

let companionActiveAudio = null;

function speakCompanionLine(companion, text, onEnd) {
    // Read live UI settings directly when previewing in Virtual Human Studio
    const modeEl = document.getElementById('cs-tts-mode');
    const modelEl = document.getElementById('cs-tts-model');
    const customModelEl = document.getElementById('cs-tts-model-custom');
    const voiceEl = document.getElementById('cs-tts-voice');
    const customVoiceEl = document.getElementById('cs-tts-voice-custom');

    const studioVisible = !!(modeEl && modeEl.offsetParent !== null);
    const effectiveMode = studioVisible ? modeEl.value : (companion?.ttsMode || 'browser');
    const effectiveModel = (studioVisible && customModelEl && customModelEl.value.trim())
        ? customModelEl.value.trim()
        : ((studioVisible && modelEl?.value) ? modelEl.value : (companion?.ttsModel || companionTTSModelFallback(effectiveMode)));
    const effectiveVoice = (studioVisible && customVoiceEl?.value.trim())
        ? customVoiceEl.value.trim()
        : ((studioVisible && voiceEl?.value) ? voiceEl.value : (companion?.ttsVoice || 'alloy'));

    const activeCompanion = {
        ...companion,
        ttsMode: effectiveMode,
        ttsModel: effectiveModel,
        ttsVoice: effectiveVoice
    };

    if (effectiveMode === 'openrouter' || effectiveMode === 'local') {
        const useLocalTTS = effectiveMode === 'local';
        const speechProvider = useLocalTTS ? 'Local TTS' : cloudProviderName();
        if (!useLocalTTS && !hasApiCredentials()) {
            showToast(`API Key missing in Settings. ${cloudProviderName()} neural speech requires an API Key.`, 'error');
            const status = document.getElementById('cs-voice-preview-status');
            if (studioVisible && status) status.textContent = `${cloudProviderName()} API key missing. Add it in Settings.`;
            if (onEnd) onEnd();
            return null;
        }

        showToast(`Generating ${speechProvider} Neural Speech...`, 'info');

        generateOpenRouterSpeech(activeCompanion, text).then(audioResult => {
            const audioSrc = audioResult.url;
            const previewPlayer = studioVisible ? document.getElementById('cs-voice-preview-player') : null;
            const audio = previewPlayer || new Audio();
            let playbackSettled = false;
            if (!previewPlayer) companionActiveAudio = audio;
            if (previewPlayer?.src?.startsWith('blob:')) URL.revokeObjectURL(previewPlayer.src);
            audio.src = audioSrc;
            if (previewPlayer) previewPlayer.classList.remove('hidden');
            audio.onended = () => {
                playbackSettled = true;
                if (companionActiveAudio === audio) companionActiveAudio = null;
                if (!previewPlayer) URL.revokeObjectURL(audioSrc);
                if (onEnd) onEnd();
            };
            audio.onerror = () => {
                if (playbackSettled) return;
                playbackSettled = true;
                if (companionActiveAudio === audio) companionActiveAudio = null;
                if (!previewPlayer) URL.revokeObjectURL(audioSrc);
                const status = document.getElementById('cs-voice-preview-status');
                const detail = `${audioResult.format} · ${audioResult.mime} · ${Math.round(audioResult.byteLength / 1024)} KB`;
                if (studioVisible && status) status.textContent = `Playback failed after validating ${detail}. Try PCM/WAV or another model.`;
                showToast(`Voice playback failed (${audioResult.format}). Try PCM/WAV or another model.`, 'error');
                if (onEnd) onEnd();
            };
            audio.play().then(() => {
                const status = document.getElementById('cs-voice-preview-status');
                const conversion = audioResult.converted ? ' · converted to browser-ready WAV' : '';
                if (studioVisible && status) {
                    status.textContent = `Playing ${audioResult.format.toUpperCase()} · ${Math.round(audioResult.byteLength / 1024)} KB${conversion}.`;
                }
                showToast(`Playing ${speechProvider} Neural Speech`, 'success');
            }).catch(err => {
                if (playbackSettled) return;
                console.warn('Audio autoplay was blocked:', err);
                const status = document.getElementById('cs-voice-preview-status');
                if (err?.name === 'NotSupportedError') {
                    playbackSettled = true;
                    if (studioVisible && status) status.textContent = `Browser rejected validated ${audioResult.format} audio. Select PCM/WAV or another model.`;
                    showToast(`Browser rejected ${audioResult.format} audio. Try PCM/WAV.`, 'error');
                } else {
                    if (studioVisible && status) status.textContent = `Voice generated as ${audioResult.format}. Press play in the audio player.`;
                    showToast('Voice generated — press play in the audio player.', 'info');
                }
                if (onEnd) onEnd();
            });
        }).catch(err => {
            console.warn(`${speechProvider} error:`, err);
            const status = document.getElementById('cs-voice-preview-status');
            if (studioVisible && status) status.textContent = `Generation failed: ${err.message}`;
            showToast(`${speechProvider} Error: ` + err.message, 'error');
            if (onEnd) onEnd();
        });
        return null;
    }
    return speakBrowserLine(activeCompanion, text, onEnd);
}

async function playCompanionVoiceMessage(companion, message) {
    if (!companion || !message) return;
    if (message.audio) {
        if (companionActiveAudio) companionActiveAudio.pause();
        const audio = new Audio(message.audio);
        companionActiveAudio = audio;
        audio.onended = () => { if (companionActiveAudio === audio) companionActiveAudio = null; };
        audio.onerror = () => showToast('The saved voice note could not be decoded by this browser.', 'error');
        await audio.play().catch(error => {
            showToast('Voice playback was blocked: ' + error.message, 'error');
        });
        return;
    }
    if (!['openrouter', 'local'].includes(companion.ttsMode)) {
        speakCompanionLine(companion, message.text);
        return;
    }
    try {
        const speechProvider = companion.ttsMode === 'local' ? 'Local TTS' : cloudProviderName();
        showToast(`Generating ${speechProvider} voice note once…`, 'info');
        const result = await generateOpenRouterSpeech(companion, message.text, { persist: true });
        if (result.persistentDataUrl) {
            message.audio = result.persistentDataUrl;
            companion.usage.voiceNotesGenerated += 1;
            await saveState();
        }
        const audio = new Audio(result.url);
        companionActiveAudio = audio;
        audio.onended = () => {
            if (companionActiveAudio === audio) companionActiveAudio = null;
            if (!result.persistentDataUrl && result.url.startsWith('blob:')) URL.revokeObjectURL(result.url);
        };
        await audio.play();
    } catch (error) {
        showToast(`${companion.ttsMode === 'local' ? 'Local TTS' : cloudProviderName()} Error: ${error.message}`, 'error');
    }
}

function companionCallPlan(companion, nowMs = Date.now(), rawExperience = null) {
    const experience = normalizeCompanionChatExperience(rawExperience);
    const dynamics = advanceCompanionHumanDynamics(companion, nowMs);
    const emotions = advanceCompanionEmotionState(companion, nowMs);
    const life = experience.realTimeLife
        ? companionLifeState(companion, nowMs)
        : { activity: 'available', label: 'available to chat', availability: 'available' };
    if (!experience.allowNoReply) return { picksUp: true, reason: '', life };
    if (life.availability === 'asleep') {
        return { picksUp: false, reason: `${companion.name} is asleep right now.`, life };
    }
    const window = Math.floor(nowMs / (5 * 60 * 1000));
    const roll = companionSeededRoll(`${companion.id}|call|${window}`);
    const refusalChance = life.availability === 'busy' ? 0.48 : 0.06;
    const moodPenalty = {
        angry: 0.48, hurt: 0.35, numb: 0.3, overwhelmed: 0.32,
        sad: 0.14, tired: 0.1
    }[companion.mood.label] || 0;
    const regulationPenalty = dynamics.anger * 0.005
        + emotions.towardPlayer.disgust * 0.0035
        + emotions.towardPlayer.anger * 0.0025
        + Math.max(0, emotions.felt.fear - 75) * 0.002
        + Math.max(0, dynamics.stress - 70) * 0.003
        + (dynamics.cooldownUntil > nowMs ? 0.2 : 0);
    const picksUp = roll >= Math.min(0.94, refusalChance + moodPenalty + regulationPenalty);
    return {
        picksUp,
        reason: picksUp ? '' : `${companion.name} didn’t answer${life.availability === 'busy' ? ` — ${life.label}` : ''}.`,
        life
    };
}

async function requestCompanionCallTurn(companion, chatMessages, callTranscript, nowMs = Date.now(), answering = false) {
    const textProvider = companionTextProviderId(companion);
    const prompt = buildCompanionSystemPrompt(companion, chatMessages, nowMs, {
        channel: 'call',
        experience: companionChatExperience(companion.id)
    }) +
        `\n\nCALL STATE:
This is an active, synchronous phone call. You hear the caller in real time and they hear your generated voice. The transcript below contains only turns that actually happened. Never invent, summarize or perform the caller's lines. Reply with 1–3 short spoken sentences and no narration.${answering ? ' You have just chosen to answer; say the first thing you naturally say when picking up.' : ''}`;
    const callMessages = (Array.isArray(callTranscript) ? callTranscript : []).map(turn => ({
        role: turn.speaker === 'companion' ? 'assistant' : 'user',
        content: turn.line
    }));
    if (answering && !callMessages.length) {
        callMessages.push({ role: 'user', content: '[The phone is ringing. You answer the live call now.]' });
    }
    const response = await fetch(providerApiBase(textProvider) + '/chat/completions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...providerAuthHeaders(textProvider), ...providerAttributionHeaders(textProvider) },
        body: JSON.stringify(applyOpenRouterRouting(applyCompanionGenerationConfig({
            model: companion.model || state.globalSettings.defaultModel,
            messages: sanitizeMessagesForProvider(
                [{ role: 'system', content: prompt }, ...callMessages], textProvider),
            tools: [COMPANION_TURN_COMMIT_TOOL, COMPANION_STATE_TOOL],
            tool_choice: 'auto'
        }, companion, { maxTokens: companion.reasoning ? Math.max(600, companion.maxTokens) : Math.min(600, companion.maxTokens) }), null, { providerId: textProvider }))
    });
    if (!response.ok) throw new Error(`Call failed (${response.status})`);
    const choice = (await response.json())?.choices?.[0] || {};
    const embeddedTools = extractCompanionEmbeddedToolCalls(choice.message?.content);
    const actions = extractCompanionToolCalls([
        ...(Array.isArray(choice.message?.tool_calls) ? choice.message.tool_calls : []),
        ...embeddedTools.toolCalls
    ]);
    if (actions.state) applyCompanionMoodUpdate(companion, actions.state, nowMs);
    const line = sanitizeCompanionTextReply(embeddedTools.visibleText, companion.name).slice(0, 600);
    if (!line) throw new Error('The call model returned no spoken reply.');
    return line;
}

// --- UI: Virtual Human library -----------------------------------------------

function companionInitials(name) {
    return String(name || '?').trim().split(/\s+/).slice(0, 2).map(w => w[0]?.toUpperCase() || '').join('') || '?';
}

function companionAvatarStyle(companion) {
    const photo = cssUrl(companion.profilePhoto);
    return photo ? `background-image:url('${photo}')` : '';
}

function companionReadinessIssues(companion) {
    const issues = [];
    if (!String(companion?.name || '').trim() || companion.name === 'New Virtual Human') {
        issues.push('give them a real name');
    }
    if (![companion?.personality, companion?.backstory, companion?.occupation, companion?.values]
        .some(value => String(value || '').trim().length >= 20)) {
        issues.push('author some identity or inner-life detail');
    }
    return issues;
}

function companionLocationOptions() {
    return [
        ['Karachi, Pakistan', 'Asia/Karachi'], ['Lahore, Pakistan', 'Asia/Karachi'],
        ['Islamabad, Pakistan', 'Asia/Karachi'], ['London, UK', 'Europe/London'],
        ['Manchester, UK', 'Europe/London'], ['Birmingham, UK', 'Europe/London'],
        ['Glasgow, UK', 'Europe/London'], ['Dublin, Ireland', 'Europe/Dublin'],
        ['Paris, France', 'Europe/Paris'], ['Berlin, Germany', 'Europe/Berlin'],
        ['Amsterdam, Netherlands', 'Europe/Amsterdam'], ['Brussels, Belgium', 'Europe/Brussels'],
        ['Madrid, Spain', 'Europe/Madrid'], ['Barcelona, Spain', 'Europe/Madrid'],
        ['Lisbon, Portugal', 'Europe/Lisbon'], ['Rome, Italy', 'Europe/Rome'],
        ['Milan, Italy', 'Europe/Rome'], ['Vienna, Austria', 'Europe/Vienna'],
        ['Prague, Czechia', 'Europe/Prague'], ['Warsaw, Poland', 'Europe/Warsaw'],
        ['Athens, Greece', 'Europe/Athens'], ['Istanbul, Türkiye', 'Europe/Istanbul'],
        ['Kyiv, Ukraine', 'Europe/Kyiv'], ['Dubai, UAE', 'Asia/Dubai'],
        ['Abu Dhabi, UAE', 'Asia/Dubai'], ['Riyadh, Saudi Arabia', 'Asia/Riyadh'],
        ['Jeddah, Saudi Arabia', 'Asia/Riyadh'], ['Doha, Qatar', 'Asia/Qatar'],
        ['Cairo, Egypt', 'Africa/Cairo'], ['Cape Town, South Africa', 'Africa/Johannesburg'],
        ['Johannesburg, South Africa', 'Africa/Johannesburg'], ['Lagos, Nigeria', 'Africa/Lagos'],
        ['Nairobi, Kenya', 'Africa/Nairobi'], ['Delhi, India', 'Asia/Kolkata'],
        ['Mumbai, India', 'Asia/Kolkata'], ['Bengaluru, India', 'Asia/Kolkata'],
        ['Dhaka, Bangladesh', 'Asia/Dhaka'], ['Bangkok, Thailand', 'Asia/Bangkok'],
        ['Singapore', 'Asia/Singapore'], ['Kuala Lumpur, Malaysia', 'Asia/Kuala_Lumpur'],
        ['Jakarta, Indonesia', 'Asia/Jakarta'], ['Manila, Philippines', 'Asia/Manila'],
        ['Hong Kong', 'Asia/Hong_Kong'], ['Shanghai, China', 'Asia/Shanghai'],
        ['Beijing, China', 'Asia/Shanghai'], ['Tokyo, Japan', 'Asia/Tokyo'],
        ['Seoul, South Korea', 'Asia/Seoul'], ['Sydney, Australia', 'Australia/Sydney'],
        ['Melbourne, Australia', 'Australia/Melbourne'], ['Auckland, New Zealand', 'Pacific/Auckland'],
        ['New York, USA', 'America/New_York'], ['Los Angeles, USA', 'America/Los_Angeles'],
        ['Chicago, USA', 'America/Chicago'], ['Denver, USA', 'America/Denver'],
        ['Toronto, Canada', 'America/Toronto'], ['Vancouver, Canada', 'America/Vancouver'],
        ['Mexico City, Mexico', 'America/Mexico_City'], ['São Paulo, Brazil', 'America/Sao_Paulo'],
        ['Buenos Aires, Argentina', 'America/Argentina/Buenos_Aires']
    ].map(([label, timezone]) => ({ label, timezone }));
}

function companionGeocodingUrl(query, count = 40) {
    const params = new URLSearchParams({
        name: String(query || '').trim(),
        count: String(livingClamp(parseInt(count) || 40, 1, 100)),
        language: String(navigator.language || 'en').split('-')[0].toLowerCase(),
        format: 'json'
    });
    return `https://geocoding-api.open-meteo.com/v1/search?${params}`;
}

async function searchCompanionRealLocations(query, options = {}) {
    const term = String(query || '').trim();
    if (term.length < 2) return [];
    const response = await fetch(companionGeocodingUrl(term, options.count), {
        signal: options.signal
    });
    if (!response.ok) throw new Error(`Place search failed (${response.status})`);
    const data = await response.json();
    const seen = new Set();
    return (Array.isArray(data?.results) ? data.results : []).map(place => {
        const parts = [place.name, place.admin1, place.admin2, place.country]
            .map(value => String(value || '').trim()).filter((value, index, all) =>
                value && all.findIndex(other => other.toLowerCase() === value.toLowerCase()) === index);
        const label = parts.join(', ');
        const timezone = String(place.timezone || '').trim();
        const coordinates = Number.isFinite(Number(place.latitude)) && Number.isFinite(Number(place.longitude))
            ? `${Number(place.latitude).toFixed(3)}, ${Number(place.longitude).toFixed(3)}` : '';
        return {
            id: String(place.id || `${label}|${timezone}`),
            label,
            timezone,
            latitude: Number(place.latitude),
            longitude: Number(place.longitude),
            countryCode: String(place.country_code || '').toUpperCase(),
            meta: [timezone, coordinates].filter(Boolean).join(' · ')
        };
    }).filter(place => {
        const key = `${place.label.toLowerCase()}|${place.timezone}`;
        if (!place.label || !place.timezone || seen.has(key)) return false;
        seen.add(key);
        return true;
    });
}

function companionTimeZoneOptions() {
    let zones = [];
    try {
        zones = typeof Intl.supportedValuesOf === 'function'
            ? Intl.supportedValuesOf('timeZone') : [];
    } catch (error) {
        zones = [];
    }
    if (!zones.length) {
        zones = [...new Set(companionLocationOptions().map(option => option.timezone))];
    }
    return ['UTC', ...zones.filter(zone => zone !== 'UTC')].map(value => {
        const parts = value.split('/');
        const city = (parts[parts.length - 1] || value).replace(/_/g, ' ');
        const region = parts.length > 1 ? parts.slice(0, -1).join(' / ') : 'Universal';
        return { value, label: city, meta: `${region} · ${value}` };
    });
}

function isValidCompanionTimeZone(value) {
    const zone = String(value || '').trim();
    if (!zone) return false;
    try {
        new Intl.DateTimeFormat('en', { timeZone: zone }).format();
        return true;
    } catch (error) {
        return false;
    }
}

function shuffledCompanionClips() {
    const clips = state.companions.flatMap(companion => (companion.videoJobs || [])
        .filter(job => job.status === 'ready' && (job.assetId || job.bundledSrc || job.outputUrl))
        .map(job => ({ companion, job })));
    for (let index = clips.length - 1; index > 0; index -= 1) {
        const swap = Math.floor(Math.random() * (index + 1));
        [clips[index], clips[swap]] = [clips[swap], clips[index]];
    }
    return clips;
}

function closeCompanionDiscoveryClips() {
    const backdrop = document.getElementById('vh-clips-discovery-backdrop');
    backdrop?.querySelectorAll('video').forEach(video => video.pause());
    backdrop?.classList.add('hidden');
}

function bindCompanionDiscoveryClipViewer(root, items) {
    const feed = root.querySelector('.vh-clips-feed');
    const cards = [...root.querySelectorAll('.vh-discovery-clip')];
    if (!feed || !cards.length) return;
    let activeCard = cards[0];
    let soundOn = false;
    const activate = async card => {
        if (!card) return;
        activeCard = card;
        cards.forEach(item => {
            const video = item.querySelector('video');
            item.classList.toggle('is-active', item === card);
            if (video && item !== card) video.pause();
        });
        const video = card.querySelector('video');
        if (!video) return;
        video.muted = !soundOn;
        const sound = card.querySelector('[data-discovery-sound]');
        if (sound) {
            sound.textContent = soundOn ? '🔊' : '🔇';
            sound.setAttribute('aria-label', soundOn ? 'Mute clip' : 'Unmute clip');
        }
        if (video.paused) {
            try { await video.play(); } catch (_) { card.classList.add('needs-play'); }
        }
    };
    const observer = typeof IntersectionObserver === 'function' ? new IntersectionObserver(entries => {
        const visible = entries.filter(entry => entry.isIntersecting)
            .sort((left, right) => right.intersectionRatio - left.intersectionRatio)[0];
        if (visible?.intersectionRatio >= .62) activate(visible.target);
    }, { root: feed, threshold: [.2, .62, .9] }) : null;
    cards.forEach(card => observer?.observe(card));
    cards.forEach((card, index) => {
        const item = items[index];
        const video = card.querySelector('video');
        if (!item || !video) return;
        video.addEventListener('timeupdate', () => {
            const progress = card.querySelector('[data-discovery-progress]');
            if (progress) progress.style.width = `${video.duration ? livingClamp(video.currentTime / video.duration * 100, 0, 100) : 0}%`;
        });
        video.addEventListener('playing', () => card.classList.remove('needs-play', 'is-buffering'));
        video.addEventListener('waiting', () => card.classList.add('is-buffering'));
        video.addEventListener('canplay', () => card.classList.remove('is-buffering'));
        video.addEventListener('error', () => {
            card.classList.remove('is-buffering', 'needs-play');
            card.classList.add('media-unavailable');
            card.querySelector('.vh-discovery-video-slot')?.insertAdjacentHTML('beforeend', '<div class="companion-media-error"><strong>Clip unavailable</strong><span>This bundled file could not be loaded. Reload after starting Horde Studio locally.</span></div>');
        }, { once: true });
        video.addEventListener('pause', () => { if (!video.ended) card.classList.add('needs-play'); });
        video.addEventListener('ended', () => { video.currentTime = 0; if (card === activeCard) activate(card); });
        card.querySelector('[data-discovery-play]')?.addEventListener('click', () => {
            if (video.paused) activate(card); else video.pause();
        });
        card.querySelector('[data-discovery-sound]')?.addEventListener('click', event => {
            event.stopPropagation(); soundOn = !soundOn; activate(card);
        });
        card.querySelector('[data-discovery-like]')?.addEventListener('click', async event => {
            event.stopPropagation();
            item.job.likedByPlayer = !item.job.likedByPlayer;
            const button = event.currentTarget;
            button.classList.toggle('liked', item.job.likedByPlayer);
            button.setAttribute('aria-label', item.job.likedByPlayer ? 'Unlike clip' : 'Like clip');
            button.querySelector('b').textContent = item.job.likedByPlayer ? '♥' : '♡';
            button.querySelector('span').textContent = companionClipCountLabel(item.job.likeCount + (item.job.likedByPlayer ? 1 : 0));
            item.companion.socialRelationship.engagement = livingClamp(item.companion.socialRelationship.engagement + (item.job.likedByPlayer ? 1 : -1), 0, 100);
            recordCompanionSocialInteraction(item.companion, {
                id: item.job.id, text: item.job.caption || item.job.concept || 'video clip'
            }, item.job.likedByPlayer ? 'liked' : 'unliked');
            persistCompanionRuntime(item.companion); await saveState();
        });
        card.querySelector('[data-discovery-open-human]')?.addEventListener('click', event => {
            event.stopPropagation();
            state.activeCompanionId = item.companion.id;
            saveState(); closeCompanionDiscoveryClips(); switchView('companionChat');
        });
        card.querySelector('[data-discovery-prev]')?.addEventListener('click', () => cards[Math.max(0, index - 1)]?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
        card.querySelector('[data-discovery-next]')?.addEventListener('click', () => cards[Math.min(cards.length - 1, index + 1)]?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
    });
    feed.addEventListener('keydown', event => {
        const index = Math.max(0, cards.indexOf(activeCard));
        if (event.key === 'ArrowDown') { event.preventDefault(); cards[Math.min(cards.length - 1, index + 1)]?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
        if (event.key === 'ArrowUp') { event.preventDefault(); cards[Math.max(0, index - 1)]?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
        if (event.key === ' ') { event.preventDefault(); const video = activeCard?.querySelector('video'); if (video?.paused) activate(activeCard); else video?.pause(); }
    });
    activate(cards[0]);
}

function renderCompanionDiscoveryClips() {
    const content = document.getElementById('vh-clips-discovery-content');
    if (!content) return;
    const items = shuffledCompanionClips();
    if (!items.length) {
        content.innerHTML = '<div class="vh-clips-empty"><span>▶</span><strong>No clips yet</strong><p>Clips generated or bundled for any Virtual Human will appear here.</p></div>';
        return;
    }
    content.innerHTML = `<div class="vh-clips-feed" tabindex="0" aria-label="Clips from all Virtual Humans">${items.map(({ companion, job }, index) => {
        const avatarStyle = companion.profilePhoto ? `background-image:url(&quot;${escapeHTML(companion.profilePhoto)}&quot;)` : '';
        return `<article class="vh-discovery-clip" data-discovery-clip="${escapeHTML(companion.id)}:${escapeHTML(job.id)}">
            <div class="vh-discovery-video-slot"></div>
            <button type="button" class="vh-discovery-play" data-discovery-play aria-label="Play or pause clip"><span>▶</span></button>
            <div class="companion-clip-shade"></div>
            <div class="vh-discovery-creator"><button type="button" data-discovery-open-human aria-label="Open ${escapeHTML(companion.name || 'Virtual Human')}'s chat"><span style="${avatarStyle}">${companion.profilePhoto ? '' : escapeHTML(companionInitials(companion.name))}</span></button><div><strong>${escapeHTML(companion.name || 'Virtual Human')}</strong><p>${escapeHTML(job.caption || job.concept || job.requestText || 'A new moment.')}</p><small>♫ original sound</small></div></div>
            <div class="vh-discovery-actions"><button type="button" data-discovery-like class="${job.likedByPlayer ? 'liked' : ''}" aria-label="${job.likedByPlayer ? 'Unlike' : 'Like'} clip"><b>${job.likedByPlayer ? '♥' : '♡'}</b><span>${escapeHTML(companionClipCountLabel(job.likeCount + (job.likedByPlayer ? 1 : 0)))}</span></button><button type="button" data-discovery-sound aria-label="Unmute clip">🔇</button></div>
            <div class="vh-discovery-nav"><button type="button" data-discovery-prev ${index === 0 ? 'disabled' : ''} aria-label="Previous clip">⌃</button><button type="button" data-discovery-next ${index === items.length - 1 ? 'disabled' : ''} aria-label="Next clip">⌄</button></div>
            <div class="vh-discovery-progress"><i data-discovery-progress></i></div>
        </article>`;
    }).join('')}</div>`;
    Promise.all(items.map(async ({ job }, index) => {
        const slot = content.querySelectorAll('.vh-discovery-video-slot')[index];
        const src = await companionVideoJobSource(job);
        if (src && slot?.isConnected) slot.innerHTML = `<video playsinline muted preload="auto" src="${escapeHTML(src)}"${job.poster ? ` poster="${escapeHTML(job.poster)}"` : ''}></video>`;
        else if (slot?.isConnected) slot.innerHTML = '<div class="companion-media-error"><strong>Clip unavailable</strong><span>No playable media source was found.</span></div>';
    })).then(() => { if (content.isConnected) bindCompanionDiscoveryClipViewer(content, items); });
}

function openCompanionDiscoveryClips() {
    const backdrop = document.getElementById('vh-clips-discovery-backdrop');
    if (!backdrop) return;
    backdrop.classList.remove('hidden');
    renderCompanionDiscoveryClips();
}

function renderCompanionSearchResults(results, items, onSelect, emptyText) {
    if (!results) return;
    results.innerHTML = '';
    if (!items.length) {
        const empty = document.createElement('div');
        empty.className = 'vh-search-empty';
        empty.textContent = emptyText;
        results.appendChild(empty);
    } else {
        items.forEach(item => {
            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'searchable-dropdown-item';
            button.setAttribute('role', 'option');
            const label = document.createElement('span');
            label.className = 'model-display-name';
            label.textContent = item.label;
            const meta = document.createElement('span');
            meta.className = 'model-display-id';
            meta.textContent = item.meta || item.value || '';
            button.append(label, meta);
            // Keep the associated search input focused while a pointer picks
            // an option. Its blur handler otherwise races this click and can
            // hide/rebuild the list before the model ID is committed.
            // Keyboard activation still reaches onclick normally.
            button.onmousedown = event => event.preventDefault();
            button.onclick = () => onSelect(item);
            results.appendChild(button);
        });
    }
    results.classList.remove('hidden');
}

function setCompanionSearchOpen(input, results, open) {
    if (!input || !results) return;
    results.classList.toggle('hidden', !open);
    input.setAttribute('aria-expanded', String(open));
}

function companionEffectiveLifeBuilderModel(companion) {
    return String(
        companion?.lifeBuilderModel
        || companion?.model
        || state.globalSettings.defaultModel
        || ''
    ).trim();
}

function updateCompanionLifeBuilderModelStatus(companion) {
    const status = document.getElementById('cs-life-builder-model-status');
    if (!status) return;
    const dedicated = String(companion?.lifeBuilderModel || '').trim();
    const conversation = String(companion?.model || state.globalSettings.defaultModel || '').trim();
    const effective = companionEffectiveLifeBuilderModel(companion);
    status.textContent = dedicated
        ? `Active Life will use ${effective}. This selection is saved only for this human.`
        : conversation
            ? `Using the conversation model · ${conversation}. Choose another model here without changing chat.`
            : 'No effective model is configured. Choose one here or configure a conversation/global default model.';
    status.classList.toggle('invalid-field-hint', !effective);
}

function updateCompanionTimezoneFieldStatus() {
    const input = document.getElementById('cs-timezone');
    const status = document.getElementById('cs-timezone-status');
    if (!input || !status) return;
    const value = input.value.trim();
    const custom = document.getElementById('cs-custom-location-mode')?.checked === true;
    if (custom) {
        const offset = Number(document.getElementById('cs-timezone-offset')?.value || 0);
        status.textContent = value
            ? `${value} · simulated clock uses ${formatCompanionUtcOffset(offset)}`
            : `Enter a fictional timezone name · simulated clock uses ${formatCompanionUtcOffset(offset)}`;
        status.classList.remove('invalid-field-hint');
        return;
    }
    const valid = isValidCompanionTimeZone(value);
    status.textContent = !value
        ? 'Choose a timezone so their clock, sleep and routines use the correct local time.'
        : valid
            ? `Valid timezone · current local time ${new Date().toLocaleTimeString([], { timeZone: value, hour: 'numeric', minute: '2-digit' })}`
            : 'Unknown timezone. Search and select a listed IANA timezone, or correct the custom value.';
    status.classList.toggle('invalid-field-hint', !!value && !valid);
}

function setupCompanionSearchableFields() {
    const locationInput = document.getElementById('cs-location-label');
    const locationResults = document.getElementById('cs-location-results');
    const locationStatus = document.getElementById('cs-location-status');
    const timezoneInput = document.getElementById('cs-timezone');
    const timezoneResults = document.getElementById('cs-timezone-results');
    const customLocationMode = document.getElementById('cs-custom-location-mode');
    const customOffsetWrap = document.getElementById('cs-custom-timezone-offset-wrap');
    const customOffset = document.getElementById('cs-timezone-offset');
    const attribution = document.getElementById('cs-location-attribution');
    const builderInput = document.getElementById('cs-builder-model');
    const builderResults = document.getElementById('cs-builder-model-results');
    const builderStatus = document.getElementById('cs-builder-model-status');
    const lifeBuilderInput = document.getElementById('cs-life-builder-model');
    const lifeBuilderResults = document.getElementById('cs-life-builder-model-results');
    const timezones = companionTimeZoneOptions();
    let locationTimer = null;
    let locationController = null;

    if (customOffset) {
        customOffset.innerHTML = '';
        for (let minutes = -720; minutes <= 840; minutes += 15) {
            const option = document.createElement('option');
            option.value = String(minutes);
            option.textContent = formatCompanionUtcOffset(minutes);
            customOffset.appendChild(option);
        }
    }

    const applyLocationModeUI = () => {
        const custom = customLocationMode?.checked === true;
        locationInput.placeholder = custom
            ? 'Enter a fictional or custom place…'
            : 'Search worldwide places or postal codes…';
        timezoneInput.placeholder = custom
            ? 'Enter a fictional timezone name…'
            : 'Search city, region or IANA timezone…';
        customOffsetWrap?.classList.toggle('hidden', !custom);
        attribution?.classList.toggle('hidden', custom);
        if (locationStatus) {
            locationStatus.textContent = custom
                ? 'Custom mode: enter any invented place. No online lookup is performed.'
                : 'Search the worldwide place database by city, town, village, district, or postal code.';
        }
        if (custom) {
            locationController?.abort();
            setCompanionSearchOpen(locationInput, locationResults, false);
            setCompanionSearchOpen(timezoneInput, timezoneResults, false);
        }
        updateCompanionTimezoneFieldStatus();
    };
    const showLocationMatches = matches => {
        renderCompanionSearchResults(locationResults, matches, option => {
            const companion = getCompanion(state.editingCompanionId);
            locationInput.value = option.label;
            timezoneInput.value = option.timezone;
            if (companion) {
                companion.locationLabel = option.label;
                companion.timezone = option.timezone;
                companion.locationMode = 'real';
                companion.locationLatitude = Number.isFinite(option.latitude) ? option.latitude : null;
                companion.locationLongitude = Number.isFinite(option.longitude) ? option.longitude : null;
                companion.locationCountryCode = option.countryCode || '';
            }
            setCompanionSearchOpen(locationInput, locationResults, false);
            if (locationStatus) locationStatus.textContent =
                `Selected real location · ${option.meta || option.timezone}`;
            updateCompanionTimezoneFieldStatus();
        }, 'No worldwide place matches. Check the spelling or enable fictional/custom location.');
        locationInput.setAttribute('aria-expanded', 'true');
    };
    const searchLocations = async () => {
        if (customLocationMode?.checked) return;
        const query = String(locationInput?.value || '').trim();
        if (query.length < 2) {
            setCompanionSearchOpen(locationInput, locationResults, false);
            if (locationStatus) locationStatus.textContent =
                'Type at least 2 characters. Three or more enables fuzzy worldwide matching.';
            return;
        }
        locationController?.abort();
        locationController = new AbortController();
        if (locationStatus) locationStatus.textContent = 'Searching worldwide places…';
        try {
            const matches = await searchCompanionRealLocations(query, {
                count: 50, signal: locationController.signal
            });
            showLocationMatches(matches);
            if (locationStatus) locationStatus.textContent = matches.length
                ? `${matches.length} worldwide result${matches.length === 1 ? '' : 's'} · select one to set its timezone automatically.`
                : 'No worldwide place matched. Check the spelling or enable fictional/custom location.';
        } catch (error) {
            if (error.name === 'AbortError') return;
            console.warn('Worldwide place search failed:', error);
            const fallback = companionLocationOptions().filter(option =>
                `${option.label} ${option.timezone}`.toLowerCase().includes(query.toLowerCase())).map(option => ({
                    ...option, meta: `${option.timezone} · offline fallback`
                })).slice(0, 20);
            showLocationMatches(fallback);
            if (locationStatus) locationStatus.textContent = fallback.length
                ? 'Worldwide search is unavailable; showing a small offline fallback list.'
                : 'Worldwide place search is unavailable. Check your connection or use fictional/custom mode.';
        }
    };
    const scheduleLocationSearch = () => {
        clearTimeout(locationTimer);
        locationTimer = setTimeout(searchLocations, 320);
    };
    const renderTimezones = () => {
        if (customLocationMode?.checked) {
            setCompanionSearchOpen(timezoneInput, timezoneResults, false);
            return;
        }
        const query = String(timezoneInput?.value || '').trim().toLowerCase().replace(/\s+/g, '_');
        const matches = timezones.filter(option =>
            !query || `${option.label} ${option.meta} ${option.value}`.toLowerCase().replace(/\s+/g, '_').includes(query))
            .slice(0, 60);
        renderCompanionSearchResults(timezoneResults, matches, option => {
            const companion = getCompanion(state.editingCompanionId);
            timezoneInput.value = option.value;
            if (companion) companion.timezone = option.value;
            setCompanionSearchOpen(timezoneInput, timezoneResults, false);
            updateCompanionTimezoneFieldStatus();
        }, 'No timezone matches. Try a city, region, or exact IANA name.');
        timezoneInput.setAttribute('aria-expanded', 'true');
    };
    const renderBuilderModels = async () => {
        if (!builderInput || !builderResults) return;
        if (!companionTextModelCatalog.length) {
            try { companionTextModelCatalog = rankCompanionTextModels(await getOpenRouterModels()); }
            catch (error) { console.warn('Could not load builder model suggestions:', error); }
        }
        const query = builderInput.value.trim().toLowerCase();
        const effectiveDefault = state.globalSettings.defaultModel || '';
        const options = [{
            value: '', label: 'Use global default',
            meta: effectiveDefault || 'No global default configured'
        }, ...companionTextModelCatalog.map(model => ({
            value: model.id,
            label: model.name,
            meta: `${model.id}${model.supportsTools ? ' · tools' : ''}`
        }))].filter(option =>
            !query || `${option.label} ${option.meta}`.toLowerCase().includes(query)).slice(0, 60);
        renderCompanionSearchResults(builderResults, options, option => {
            builderInput.value = option.value;
            setCompanionSearchOpen(builderInput, builderResults, false);
            if (builderStatus) {
                builderStatus.textContent = option.value
                    ? `Builder will use ${option.label} · ${option.value}`
                    : `Builder will use the global default${effectiveDefault ? ` · ${effectiveDefault}` : ''}.`;
            }
        }, 'No text model matches. A custom provider model ID can still be entered.');
        builderInput.setAttribute('aria-expanded', 'true');
        if (builderStatus) builderStatus.textContent =
            `${companionTextModelCatalog.length} text models available from ${isLocalProvider() ? 'your local server' : cloudProviderName()}.`;
    };
    const renderLifeBuilderModels = async () => {
        if (!lifeBuilderInput || !lifeBuilderResults) return;
        const companion = getCompanion(state.editingCompanionId);
        if (!companionTextModelCatalog.length) {
            try {
                companionTextModelCatalog = rankCompanionTextModels(
                    await getCompanionOutputModels('text', false, companionTextProviderId(companion)));
            }
            catch (error) { console.warn('Could not load Active Life model suggestions:', error); }
        }
        const query = lifeBuilderInput.value.trim().toLowerCase();
        const conversationModel = String(companion?.model || state.globalSettings.defaultModel || '').trim();
        const options = [{
            value: '',
            label: 'Use conversation model',
            meta: conversationModel || 'No conversation or global model configured'
        }, ...companionTextModelCatalog.map(model => ({
            value: model.id,
            label: model.name,
            meta: `${model.id}${model.supportsJSON ? ' · structured output' : ''}`
        }))].filter(option =>
            !query || `${option.label} ${option.meta}`.toLowerCase().includes(query)
        ).slice(0, 60);
        renderCompanionSearchResults(lifeBuilderResults, options, option => {
            lifeBuilderInput.value = option.value;
            if (companion) companion.lifeBuilderModel = option.value;
            setCompanionSearchOpen(lifeBuilderInput, lifeBuilderResults, false);
            updateCompanionLifeBuilderModelStatus(companion);
        }, 'No text model matches. You can still enter an exact custom model ID.');
        lifeBuilderInput.setAttribute('aria-expanded', 'true');
        updateCompanionLifeBuilderModelStatus(companion);
    };

    if (locationInput && locationResults) {
        locationInput.onfocus = scheduleLocationSearch;
        locationInput.addEventListener('input', () => {
            const companion = getCompanion(state.editingCompanionId);
            if (companion && companion.locationMode !== 'custom') {
                companion.locationLatitude = null;
                companion.locationLongitude = null;
                companion.locationCountryCode = '';
            }
            scheduleLocationSearch();
        });
        locationInput.addEventListener('keydown', event => {
            if (event.key === 'Escape') setCompanionSearchOpen(locationInput, locationResults, false);
        });
    }
    if (timezoneInput && timezoneResults) {
        timezoneInput.onfocus = renderTimezones;
        timezoneInput.addEventListener('input', () => {
            renderTimezones();
            updateCompanionTimezoneFieldStatus();
        });
        timezoneInput.addEventListener('keydown', event => {
            if (event.key === 'Escape') setCompanionSearchOpen(timezoneInput, timezoneResults, false);
        });
    }
    if (builderInput && builderResults) {
        builderInput.onfocus = renderBuilderModels;
        builderInput.addEventListener('input', renderBuilderModels);
        builderInput.addEventListener('keydown', event => {
            if (event.key === 'Escape') setCompanionSearchOpen(builderInput, builderResults, false);
        });
    }
    if (lifeBuilderInput && lifeBuilderResults) {
        lifeBuilderInput.onfocus = renderLifeBuilderModels;
        lifeBuilderInput.addEventListener('input', () => {
            const companion = getCompanion(state.editingCompanionId);
            if (companion) companion.lifeBuilderModel = lifeBuilderInput.value.trim();
            renderLifeBuilderModels();
        });
        lifeBuilderInput.addEventListener('keydown', event => {
            if (event.key === 'Escape') setCompanionSearchOpen(lifeBuilderInput, lifeBuilderResults, false);
        });
    }
    if (customLocationMode) {
        customLocationMode.onchange = () => {
            const companion = getCompanion(state.editingCompanionId);
            if (companion) {
                companion.locationMode = customLocationMode.checked ? 'custom' : 'real';
                if (customLocationMode.checked) {
                    companion.locationLatitude = null;
                    companion.locationLongitude = null;
                    companion.locationCountryCode = '';
                }
            }
            applyLocationModeUI();
        };
    }
    if (customOffset) {
        customOffset.onchange = () => {
            const companion = getCompanion(state.editingCompanionId);
            if (companion) companion.timezoneOffsetMinutes =
                livingClamp(parseInt(customOffset.value) || 0, -720, 840);
            updateCompanionTimezoneFieldStatus();
        };
    }
    document.addEventListener('click', event => {
        [
            [locationInput, locationResults],
            [timezoneInput, timezoneResults],
            [builderInput, builderResults],
            [lifeBuilderInput, lifeBuilderResults]
        ].forEach(([input, results]) => {
            if (input && results && !input.contains(event.target) && !results.contains(event.target)) {
                setCompanionSearchOpen(input, results, false);
            }
        });
    });
    applyLocationModeUI();
    updateCompanionTimezoneFieldStatus();
    updateCompanionLifeBuilderModelStatus(getCompanion(state.editingCompanionId));
}

async function getSettingsProviderCatalog() {
    const provider = document.getElementById('global-api-provider')?.value || state.globalSettings.apiProvider;
    const value = id => document.getElementById(id)?.value.trim() || '';
    let base = '';
    let headers = {};
    if (provider === 'local') {
        base = normalizeRemoteApiBase(value('global-local-url'), 'http://localhost:11434/v1');
        if (value('global-local-key')) headers.Authorization = `Bearer ${value('global-local-key')}`;
    } else if (provider === 'gptproto') {
        base = 'https://gptproto.com/v1'; headers.Authorization = `Bearer ${value('global-gptproto-key')}`;
    } else if (provider === 'nanogpt') {
        base = 'https://nano-gpt.com/api/v1'; headers.Authorization = `Bearer ${value('global-nanogpt-key')}`;
    } else if (provider === 'nvidia') {
        base = 'https://integrate.api.nvidia.com/v1'; headers.Authorization = `Bearer ${value('global-nvidia-key')}`;
    } else if (provider === 'bedrock') {
        base = normalizeRemoteApiBase(value('global-bedrock-base-url'))
            || `https://bedrock-mantle.${normalizedBedrockRegion(value('global-bedrock-region'))}.api.aws/v1`;
        headers.Authorization = `Bearer ${value('global-bedrock-key')}`;
    } else if (provider === 'custom') {
        base = normalizeRemoteApiBase(value('global-custom-base-url'));
        if (!base) return [];
        if (value('global-custom-api-key')) headers.Authorization = `Bearer ${value('global-custom-api-key')}`;
        headers = { ...headers, ...parseCustomHeaders(document.getElementById('global-custom-headers')?.value.trim()) };
    } else {
        base = 'https://openrouter.ai/api/v1';
        headers = { Authorization: `Bearer ${value('global-api-key')}`, 'HTTP-Referer': 'https://horde-studio.ai', 'X-Title': 'Horde Studio' };
    }
    const response = await fetch(base.replace(/\/+$/, '') + '/models', { headers });
    if (!response.ok) throw new Error(`Model catalog request failed (${response.status})`);
    const data = await response.json();
    const catalog = Array.isArray(data) ? data : Array.isArray(data?.data) ? data.data : Array.isArray(data?.models) ? data.models : [];
    return catalog.filter(model => isPlainObject(model) && typeof model.id === 'string')
        .map(model => ({ ...model, name: typeof model.name === 'string' ? model.name : model.id }));
}

async function getSettingsEmbeddingCatalog() {
    const explicitBase = normalizeOpenAICompatibleBase(
        document.getElementById('global-embedding-url')?.value.trim() || '');
    if (!explicitBase) return getSettingsProviderCatalog();
    const key = document.getElementById('global-embedding-key')?.value.trim() || '';
    const response = await fetch(explicitBase + '/models', {
        headers: key ? { Authorization: `Bearer ${key}` } : {}
    });
    if (!response.ok) throw new Error(`Embedding catalog request failed (${response.status})`);
    const data = await response.json();
    const catalog = Array.isArray(data) ? data : Array.isArray(data?.data) ? data.data : Array.isArray(data?.models) ? data.models : [];
    return catalog.filter(model => isPlainObject(model) && typeof model.id === 'string')
        .map(model => ({ ...model, name: typeof model.name === 'string' ? model.name : model.id }));
}

function setupCatalogModelSearchFields() {
    const definitions = [
        { inputId: 'w-agent-model', resultsId: 'w-agent-model-results', blankLabel: 'Use this world’s DM model', kind: 'text' },
        { inputId: 'video-world-director-model', resultsId: 'video-world-director-model-results', kind: 'text', providerAware: true },
        { inputId: 'global-default-model', resultsId: 'global-default-model-results', kind: 'text' },
        { inputId: 'global-consolidation-model', resultsId: 'global-consolidation-model-results', kind: 'text' },
        { inputId: 'global-embedding-model', resultsId: 'global-embedding-model-results', kind: 'embedding' },
        { inputId: 'room-model', resultsId: 'room-model-results', kind: 'text' }
    ];
    definitions.forEach(definition => {
        const input = document.getElementById(definition.inputId);
        const results = document.getElementById(definition.resultsId);
        if (!input || !results) return;
        const render = async () => {
            let rawModels = [];
            try {
                rawModels = definition.inputId === 'global-default-model' || definition.providerAware
                    ? await getSettingsProviderCatalog()
                    : definition.kind === 'embedding'
                        ? await getSettingsEmbeddingCatalog()
                        : await getOpenRouterModels();
            }
            catch (error) { console.warn(`Could not load models for ${definition.inputId}:`, error); }
            const models = definition.kind === 'embedding'
                ? rawModels.filter(model => {
                    const outputs = modelOutputModalities(model);
                    return outputs.some(output => /embed/.test(output))
                        || /(?:^|[/._-])embed(?:ding)?(?:$|[/._-])/i.test(model.id);
                }).map(model => ({ id: model.id, name: model.name || model.id }))
                : rankCompanionTextModels(rawModels);
            const query = input.value.trim().toLowerCase();
            const options = [
                ...(definition.blankLabel ? [{ value: '', label: definition.blankLabel, meta: 'Automatic' }] : []),
                ...models.map(model => ({
                    value: model.id,
                    label: model.name || model.id,
                    meta: model.id
                }))
            ].filter(option =>
                !query || `${option.label} ${option.meta}`.toLowerCase().includes(query)).slice(0, 60);
            renderCompanionSearchResults(results, options, option => {
                input.value = option.value;
                setCompanionSearchOpen(input, results, false);
            }, definition.kind === 'embedding'
                ? 'No embedding model matches. You can still enter an exact custom model ID.'
                : 'No text model matches. You can still enter an exact custom model ID.');
            input.setAttribute('aria-expanded', 'true');
        };
        input.addEventListener('focus', render);
        input.addEventListener('input', render);
        input.addEventListener('keydown', event => {
            if (event.key === 'Escape') setCompanionSearchOpen(input, results, false);
        });
        document.addEventListener('click', event => {
            if (!input.contains(event.target) && !results.contains(event.target)) {
                setCompanionSearchOpen(input, results, false);
            }
        });
    });
}

function renderCompanionsGrid() {
    const grid = document.getElementById('companions-grid');
    if (!grid) return;
    renderIncludedHumansCatalog();
    grid.innerHTML = '';
    const query = String(document.getElementById('vh-search')?.value || '').trim().toLowerCase();
    const now = Date.now();
    const availableCount = state.companions.filter(companion =>
        companionLifeState(companion, now).availability === 'available').length;
    const totalEl = document.getElementById('vh-total-count');
    const totalUnitEl = document.getElementById('vh-human-unit');
    const availableEl = document.getElementById('vh-available-count');
    if (totalEl) totalEl.textContent = state.companions.length;
    if (totalUnitEl) totalUnitEl.textContent = state.companions.length === 1 ? 'human' : 'humans';
    if (availableEl) availableEl.textContent = availableCount;

    const companions = state.companions.filter(companion => {
        if (!query) return true;
        return [companion.name, companion.occupation, companion.personality, companion.socialWorld]
            .some(value => String(value || '').toLowerCase().includes(query));
    });
    if (!companions.length) {
        grid.innerHTML = query
            ? `<div class="vh-empty"><strong>No matching virtual humans</strong><span>Try a name, occupation, personality trait or social detail.</span></div>`
            : `<div class="vh-empty"><strong>Your human library is empty</strong><span>Create one from rough notes with the AI Human Builder, or author every detail yourself.</span></div>`;
        return;
    }
    companions.forEach(companion => {
        const thread = getCompanionThread(companion.id);
        const timeline = getActiveCompanionTimeline(companion.id);
        const unreadCount = thread.filter(message =>
            message.role === 'companion' && message.timestamp > (timeline?.lastViewedAt || 0)).length;
        const last = thread[thread.length - 1];
        const life = companionLifeState(companion, now);
        const unanswered = companionUnansweredState(thread, now);
        const card = document.createElement('article');
        card.className = 'vh-card';
        const meta = [companion.age ? `${companion.age}` : '', companion.pronouns].filter(Boolean).join(' · ');
        const role = companion.occupation || companion.personality || 'A persistent virtual human with a life beyond the conversation.';
        const lastText = last
            ? `${last.role === 'user' ? 'You: ' : ''}${last.type === 'photo' ? '📷 Photo' : last.type === 'voice' ? '🎙 Voice note' : last.text}`
            : 'No conversation yet';
        card.innerHTML = `
            <div class="vh-card-head">
                <div class="vh-card-avatar" style="${companionAvatarStyle(companion)}">
                    ${companion.profilePhoto ? '' : escapeHTML(companionInitials(companion.name))}
                </div>
                <div class="vh-card-identity">
                    <div class="vh-card-name">${escapeHTML(companion.name || 'Unnamed')}</div>
                    <div class="vh-card-meta">${escapeHTML(meta || 'Identity details not set')}</div>
                </div>
                <span class="vh-status ${escapeHTML(life.availability)}">${escapeHTML(life.availability)}</span>
            </div>
            <div class="vh-card-role">${escapeHTML(role)}</div>
            <div class="vh-card-state">
                <span class="vh-chip">${escapeHTML(life.label)}</span>
                <span class="vh-chip">Mood: ${escapeHTML(companion.mood?.label || 'content')}</span>
                ${unanswered.shouldAcknowledgeSilence ? '<span class="vh-chip">Awaiting your reply</span>' : ''}
            </div>
            <div class="vh-card-last">${escapeHTML(lastText.slice(0, 120))}</div>
            ${unreadCount ? `<div class="vh-card-state"><span class="vh-chip">${unreadCount} unread</span></div>` : ''}
            <div class="vh-card-actions">
                <button class="btn btn-primary" type="button" data-vh-chat>Open chat</button>
                <button class="btn btn-ghost" type="button" data-vh-edit title="Edit in Virtual Human Studio">Edit</button>
                <button class="btn btn-ghost" type="button" data-vh-export title="Export a clean template or complete portable human">Export</button>
            </div>`;
        card.querySelector('[data-vh-chat]').onclick = () => {
            const issues = companionReadinessIssues(companion);
            if (issues.length) {
                showToast(`Finish this human first: ${issues.join(' and ')}.`, 'info');
                openCompanionStudio(companion.id);
                switchView('companionStudio');
                activateCompanionStudioTab('cs-identity');
                return;
            }
            state.activeCompanionId = companion.id;
            saveState();
            switchView('companionChat');
        };
        card.querySelector('[data-vh-edit]').onclick = () => {
            openCompanionStudio(companion.id);
            switchView('companionStudio');
        };
        card.querySelector('[data-vh-export]').onclick = () => exportCompanionArchive(companion.id);
        grid.appendChild(card);
    });
}

function includedHumanCandidates() {
    return (Array.isArray(globalThis.HORDE_INCLUDED_HUMANS) ? globalThis.HORDE_INCLUDED_HUMANS : [])
        .filter(candidate => candidate?.bundledId && candidate?.companion?.name);
}

async function installIncludedHuman(bundleId) {
    const candidate = includedHumanCandidates().find(item => item.bundledId === bundleId);
    if (!candidate) return showToast('That built-in human is unavailable in this package.', 'error');
    try {
        const companion = restoreCompanionArchive(candidate);
        companion.bundledId = candidate.bundledId;
        const receipts = Array.isArray(state.globalSettings.includedHumanReceipts)
            ? state.globalSettings.includedHumanReceipts : [];
        state.globalSettings.includedHumanReceipts = [...new Set([...receipts, candidate.bundledId])];
        await saveState();
        renderCompanionsGrid();
        showToast(`${companion.name} was added as a fresh built-in copy.`, 'success');
    } catch (error) {
        console.error('Could not restore included Virtual Human:', error);
        showToast(`Could not add the built-in human: ${error.message}`, 'error');
    }
}

function renderIncludedHumansCatalog() {
    const section = document.getElementById('included-humans-section');
    const grid = document.getElementById('included-humans-grid');
    if (!section || !grid) return;
    const included = includedHumanCandidates();
    // Never turn a packaging failure into a blank, apparently legitimate
    // library. Portable releases inline these definitions; seeing this state
    // means the package is incomplete or an old index was copied alone.
    section.classList.remove('hidden');
    grid.innerHTML = '';
    if (!included.length) {
        grid.innerHTML = `<article class="vh-included-card vh-included-error" role="alert">
            <div class="vh-included-copy">
                <strong>Built-in humans did not load</strong>
                <span>This copy of Horde Studio is incomplete. Use the portable release rather than copying index.html by itself.</span>
            </div>
        </article>`;
        return;
    }
    included.forEach(candidate => {
        const authored = normalizeCompanion(candidate.companion);
        const installed = state.companions.some(companion =>
            companion?.bundledId === candidate.bundledId
            || companion?.name === authored.name);
        const card = document.createElement('article');
        card.className = 'vh-included-card';
        card.innerHTML = `
            <div class="vh-included-avatar" style="${companionAvatarStyle(authored)}"></div>
            <div class="vh-included-copy">
                <strong>${escapeHTML(authored.name)}</strong>
                <span>${escapeHTML(authored.occupation || authored.personality || 'Included Virtual Human')}</span>
            </div>
            <button class="btn ${installed ? 'btn-ghost' : 'btn-primary'}" type="button">
                ${installed ? 'Add fresh copy' : 'Add to library'}
            </button>`;
        card.querySelector('button').onclick = () => installIncludedHuman(candidate.bundledId);
        grid.appendChild(card);
    });
}

// --- UI: Virtual Human Studio -------------------------------------------------

function openCompanionStudio(id) {
    state.editingCompanionId = id;
    persistWorkspaceSoon();
    renderCompanionStudioForm();
    activateCompanionStudioTab((workspaceRestoring && state.lastCompanionStudioTab) || 'cs-overview');
}

function resetNewCompanionStudioState() {
    const builderInput = document.getElementById('cs-builder-input');
    const builderStatus = document.getElementById('cs-builder-status');
    const builderResult = document.getElementById('cs-builder-result');
    const builderSummary = document.getElementById('cs-builder-summary');
    const photoPrompt = document.getElementById('cs-photo-test-prompt');
    const voiceSample = document.getElementById('cs-voice-sample-text');
    const voiceStatus = document.getElementById('cs-voice-preview-status');
    const voicePlayer = document.getElementById('cs-voice-preview-player');
    const photoResult = document.getElementById('cs-photo-test-result');
    const photoImage = document.getElementById('cs-photo-test-image');
    if (builderInput) builderInput.value = '';
    if (builderStatus) builderStatus.textContent = 'Nothing is sent until you press Build.';
    if (builderResult) builderResult.classList.add('hidden');
    if (builderSummary) builderSummary.textContent = '—';
    if (photoPrompt) photoPrompt.value = '';
    if (voiceSample) voiceSample.value = 'Hey, it’s me. This is what I sound like.';
    if (voiceStatus) voiceStatus.textContent = 'Ready.';
    if (voicePlayer) {
        voicePlayer.pause();
        voicePlayer.classList.add('hidden');
        voicePlayer.removeAttribute('src');
    }
    if (photoResult) photoResult.classList.add('hidden');
    if (photoImage) photoImage.removeAttribute('src');
    ['cs-photo-input', 'cs-reference-input'].forEach(id => {
        const input = document.getElementById(id);
        if (input) input.value = '';
    });
}

function setupCompanionStudioTabs() {
    document.querySelectorAll('.companion-studio-tab').forEach(tab => {
        tab.onclick = () => {
            commitCompanionStudioForm();
            activateCompanionStudioTab(tab.dataset.tab);
        };
    });
    document.querySelectorAll('[data-companion-studio-target]').forEach(button => {
        button.onclick = () => {
            commitCompanionStudioForm();
            activateCompanionStudioTab(button.dataset.companionStudioTarget);
        };
    });
    const videoToggle = document.getElementById('cs-video-enabled');
    if (videoToggle) videoToggle.onclick = () => {
        const companion = getCompanion(state.editingCompanionId);
        if (!companion) return;
        companion.allowVideoClips = !companion.allowVideoClips;
        renderCompanionVideoStudio(companion);
    };
    const videoProvider = document.getElementById('cs-video-provider');
    if (videoProvider) videoProvider.onchange = () => {
        const companion = getCompanion(state.editingCompanionId);
        if (!companion) return;
        companion.videoProvider = normalizedVideoProviderId(videoProvider.value);
        companion.videoModel = '';
        companion.videoFallbackModel = companion.videoProvider === 'fal' ? 'alibaba/wan-3.0' : '';
        companion.videoFallbackModel2 = '';
        renderCompanionVideoStudio(companion, true);
    };
    const videoModel = document.getElementById('cs-video-model');
    if (videoModel) videoModel.onchange = () => {
        const companion = getCompanion(state.editingCompanionId);
        if (!companion) return;
        companion.videoModel = videoModel.value;
        renderCompanionVideoStudio(companion);
    };
    const videoFallbackModel = document.getElementById('cs-video-fallback-model');
    if (videoFallbackModel) videoFallbackModel.onchange = () => {
        const companion = getCompanion(state.editingCompanionId);
        if (!companion) return;
        companion.videoFallbackModel = videoFallbackModel.value;
        renderCompanionVideoStudio(companion);
    };
    const videoFallbackModel2 = document.getElementById('cs-video-fallback-model-2');
    if (videoFallbackModel2) videoFallbackModel2.onchange = () => {
        const companion = getCompanion(state.editingCompanionId);
        if (companion) companion.videoFallbackModel2 = videoFallbackModel2.value;
    };
}

function activateCompanionStudioTab(tabName) {
    state.lastCompanionStudioTab = tabName || null;
    persistWorkspaceSoon();
    document.querySelectorAll('.companion-studio-tab').forEach(tab => {
        tab.classList.toggle('active', tab.dataset.tab === tabName);
    });
    document.querySelectorAll('#companion-studio-view .studio-panel').forEach(panel => panel.classList.add('hidden'));
    document.getElementById(`tab-${tabName}`)?.classList.remove('hidden');
    if (tabName === 'cs-life') {
        updateCompanionLifeBuilderModelStatus(getCompanion(state.editingCompanionId));
    }
    if (tabName === 'cs-social') renderCompanionSocialStudio(getCompanion(state.editingCompanionId));
    if (tabName === 'cs-video') renderCompanionVideoStudio(getCompanion(state.editingCompanionId), true);
    const content = document.querySelector('#companion-studio-view .studio-content-wrap');
    if (content) content.scrollTop = 0;
}

async function renderCompanionVideoStudio(companion, refreshModels = false) {
    if (!companion) return;
    const toggle = document.getElementById('cs-video-enabled');
    const provider = document.getElementById('cs-video-provider');
    const model = document.getElementById('cs-video-model');
    const fallbackModel = document.getElementById('cs-video-fallback-model');
    const fallbackModel2 = document.getElementById('cs-video-fallback-model-2');
    const status = document.getElementById('cs-video-model-status');
    if (!toggle || !provider || !model) return;
    toggle.setAttribute('aria-pressed', String(companion.allowVideoClips));
    toggle.classList.toggle('active', companion.allowVideoClips);
    document.getElementById('cs-video-enabled-label').textContent = companion.allowVideoClips ? 'Clips on' : 'Clips off';
    provider.value = normalizedVideoProviderId(companion.videoProvider);
    const falFallbacksEnabled = provider.value === 'fal';
    if (fallbackModel) fallbackModel.disabled = !falFallbacksEnabled;
    if (fallbackModel2) fallbackModel2.disabled = !falFallbacksEnabled;
    document.getElementById('cs-video-resolution').value = companion.videoResolution;
    document.getElementById('cs-video-duration').value = String(companion.videoDuration);
    document.getElementById('cs-video-reference').value = companion.videoReferencePolicy;
    document.getElementById('cs-video-audio').checked = companion.videoAudio;
    document.getElementById('cs-video-style-rules').value = companion.videoStyleRules;
    status.textContent = videoProviderHasCredentials(provider.value)
        ? `Loading ${videoProviderDisplayName(provider.value)} reference-video models…`
        : `${videoProviderDisplayName(provider.value)} is not connected in Settings → Connections.`;
    const models = await fetchVideoModels(provider.value, refreshModels);
    model.innerHTML = models.map(item => `<option value="${escapeHTML(item.id)}">${escapeHTML(item.name || item.id)}</option>`).join('');
    if (companion.videoModel && !models.some(item => item.id === companion.videoModel)) {
        model.insertAdjacentHTML('afterbegin', `<option value="${escapeHTML(companion.videoModel)}">${escapeHTML(companion.videoModel)} · custom</option>`);
    }
    model.value = companion.videoModel || models[0]?.id || '';
    if (!companion.videoModel && model.value) companion.videoModel = model.value;
    if (fallbackModel) {
        fallbackModel.innerHTML = '<option value="">No automatic fallback</option>' + models
            .filter(item => item.id !== model.value)
            .map(item => `<option value="${escapeHTML(item.id)}">${escapeHTML(item.name || item.id)}</option>`).join('');
        fallbackModel.value = models.some(item => item.id === companion.videoFallbackModel)
            ? companion.videoFallbackModel : '';
        companion.videoFallbackModel = fallbackModel.value;
    }
    if (fallbackModel2) {
        fallbackModel2.innerHTML = '<option value="">None</option>' + models
            .filter(item => ![model.value, fallbackModel?.value].includes(item.id))
            .map(item => `<option value="${escapeHTML(item.id)}">${escapeHTML(item.name || item.id)}</option>`).join('');
        fallbackModel2.value = models.some(item => item.id === companion.videoFallbackModel2)
            ? companion.videoFallbackModel2 : '';
        companion.videoFallbackModel2 = fallbackModel2.value;
    }
    status.textContent = `${models.length} reference-capable model${models.length === 1 ? '' : 's'} · ${videoProviderDisplayName(provider.value)}${videoProviderHasCredentials(provider.value) ? ' connected' : ' key required before generation'}.`;
}

function updateCompanionPhotoStyleDescription(styleId) {
    const description = document.getElementById('cs-photo-style-description');
    const style = COMPANION_PHOTO_STYLES[normalizeCompanionPhotoStyle(styleId)];
    if (description) description.textContent = style.description;
}

function updateCompanionPhotoCaptureDescription(policyId) {
    const description = document.getElementById('cs-photo-capture-description');
    const policy = COMPANION_PHOTO_CAPTURE_POLICIES[normalizeCompanionPhotoCapturePolicy(policyId)];
    if (description) description.textContent = policy.description;
}

function formatCompanionScheduleMinute(minute) {
    const normalized = livingClamp(Math.round(Number(minute) || 0), 0, 1440);
    const hour = Math.floor(normalized / 60) % 24;
    const mins = normalized % 60;
    const suffix = hour >= 12 ? 'PM' : 'AM';
    return `${hour % 12 || 12}:${String(mins).padStart(2, '0')} ${suffix}`;
}

function companionScheduleTimeValue(minute) {
    const value = livingClamp(Math.round(Number(minute) || 0), 0, 1439);
    return `${String(Math.floor(value / 60)).padStart(2, '0')}:${String(value % 60).padStart(2, '0')}`;
}

function companionScheduleMinuteFromInput(value) {
    const match = /^(\d{1,2}):(\d{2})$/.exec(String(value || ''));
    if (!match) return 0;
    return livingClamp((parseInt(match[1]) || 0) * 60 + (parseInt(match[2]) || 0), 0, 1439);
}

function companionLifeEditorRowActions(type) {
    return `<button class="tool-btn tool-btn-danger" type="button" data-life-remove="${escapeHTML(type)}" title="Remove">×</button>`;
}

function collectCompanionLifeEditorValues(editor, life) {
    editor.querySelectorAll('[data-life-texture]').forEach(input => {
        life[input.dataset.lifeTexture] = input.value.trim();
    });
    editor.querySelectorAll('[data-life-place]').forEach(row => {
        const place = life.places[Number(row.dataset.lifePlace)];
        if (!place) return;
        place.label = row.querySelector('[data-field="label"]').value.trim();
        place.kind = row.querySelector('[data-field="kind"]').value;
        place.detail = row.querySelector('[data-field="detail"]').value.trim();
        place.travelMinutesFromHome = livingClamp(Number(row.querySelector('[data-field="travelMinutesFromHome"]').value) || 0, 0, 360);
    });
    editor.querySelectorAll('[data-life-person]').forEach(row => {
        const person = life.socialCircle[Number(row.dataset.lifePerson)];
        if (!person) return;
        ['name','relationship','role','contactFrequency','description','currentTension','playerContext'].forEach(field => {
            person[field] = row.querySelector(`[data-field="${field}"]`).value.trim();
        });
        person.closeness = livingClamp(Number(row.querySelector('[data-field="closeness"]').value) || 0, -100, 100);
        person.trust = livingClamp(Number(row.querySelector('[data-field="trust"]').value) || 0, -100, 100);
        person.tension = livingClamp(Number(row.querySelector('[data-field="tension"]').value) || 0, 0, 100);
        person.influence = livingClamp(Number(row.querySelector('[data-field="influence"]').value) || 0, 0, 100);
        person.knowsPlayer = row.querySelector('[data-field="knowsPlayer"]').checked;
    });
    editor.querySelectorAll('[data-life-schedule]').forEach(row => {
        const block = life.weeklySchedule[Number(row.dataset.lifeSchedule)];
        if (!block) return;
        block.days = [...row.querySelectorAll('[data-life-day]:checked')].map(input => Number(input.dataset.lifeDay));
        block.startMinute = companionScheduleMinuteFromInput(row.querySelector('[data-field="startMinute"]').value);
        block.endMinute = companionScheduleMinuteFromInput(row.querySelector('[data-field="endMinute"]').value);
        ['activity','placeId','availability','flexibility','outfitContext'].forEach(field => {
            block[field] = row.querySelector(`[data-field="${field}"]`).value.trim();
        });
    });
    editor.querySelectorAll('[data-life-look]').forEach(row => {
        const look = life.wardrobe[Number(row.dataset.lifeLook)];
        if (!look) return;
        ['label','context','items','notes'].forEach(field => {
            look[field] = row.querySelector(`[data-field="${field}"]`).value.trim();
        });
    });
    editor.querySelectorAll('[data-life-wildcard]').forEach(row => {
        const event = life.wildcardDeck[Number(row.dataset.lifeWildcard)];
        if (!event) return;
        ['label','category','availability','initiativeHook','consequences'].forEach(field => {
            event[field] = row.querySelector(`[data-field="${field}"]`).value.trim();
        });
        event.minGapDays = livingClamp(Number(row.querySelector('[data-field="minGapDays"]').value) || 1, 1, 90);
        event.durationMinutes = livingClamp(Number(row.querySelector('[data-field="durationMinutes"]').value) || 60, 15, 1440);
    });
    return life;
}

