    document.getElementById('cs-test-photo-btn').onclick = async () => {
        const companion = getCompanion(state.editingCompanionId);
        const scene = document.getElementById('cs-photo-test-prompt').value.trim();
        const button = document.getElementById('cs-test-photo-btn');
        const status = document.getElementById('cs-photo-test-status');
        const result = document.getElementById('cs-photo-test-result');
        const image = document.getElementById('cs-photo-test-image');
        const includeReference = !!document.getElementById('cs-photo-test-use-reference')?.checked;
        if (!companion) return;
        if (!scene) {
            if (status) status.textContent = 'Describe the test photo first.';
            return showToast('Describe the test photo first.', 'info');
        }
        button.disabled = true;
        button.textContent = 'Generating test photo…';
        result.classList.add('hidden');
        image.removeAttribute('src');
        const capture = companionPhotoCapturePlan(companion, scene, Date.now());
        const imageTarget = ['higgsfield', 'magnific'].includes(companion.imageSource)
            ? `${HORDE_MCP_PROVIDERS[companion.imageSource].label} · ${companion.mcpImageTool || 'no tool selected'}`
            : companion.imageSource === 'comfyui'
                ? 'ComfyUI workflow'
                : companion.imageSource === 'local_image'
                    ? `Local image server · ${companion.imageModel || 'local-image'}`
                    : `${providerDisplayName(companionImageProviderId(companion))} · ${companion.imageModel || companionImageModelFallback(companionImageProviderId(companion))}`;
        if (status) {
            status.textContent = `${capture.label}: ${capture.reason} Sending the production photo request to ${imageTarget}${includeReference ? ' with the identity reference…' : ' without a reference…'}`;
        }
        let referenceFallbackUsed = false;
        try {
            const photo = await generateCompanionPhoto(companion, scene, {
                includeReference,
                onReferenceFallback: () => {
                    referenceFallbackUsed = true;
                    if (status) status.textContent = 'The provider blocked the identity reference. Retrying safely from the written appearance…';
                }
            });
            await loadGeneratedImage(image, photo);
            result.classList.remove('hidden');
            if (status) status.textContent = referenceFallbackUsed
                ? `${capture.label}. Generated without the blocked reference. Chat photos will recover the same way, but identity fidelity may be lower.`
                : `Success — ${capture.label}. Chat photos use this exact situation-aware camera plan, model and reference-image path.`;
            showToast(referenceFallbackUsed
                ? 'Reference was blocked; generated from the written appearance instead.'
                : 'Test photo generated successfully.', referenceFallbackUsed ? 'info' : 'success');
        } catch (error) {
            console.warn('Test photo generation failed:', error);
            image.removeAttribute('src');
            result.classList.add('hidden');
            if (status) status.textContent = `Generation failed: ${error.message}`;
            showToast('Photo test failed: ' + error.message, 'error');
        } finally {
            button.disabled = false;
            button.textContent = 'Generate test photo';
        }
    };
